[745] = {
    en = "Marshal McBride's Documents",
    T  = "Документи маршала Макбрайда",
    pages = {
        [1] = "ЗВІТ: Кобольди$B$BУ околицях Долини Нортшир посилилася активність кобольдів. Вони розбили табори на північ від абатства та в шахті «Ехо-Рідж» у тривожно великій кількості.  Я зібрав паладинів, воїнів та інших місцевих мешканців, щоб вони допомогли мені позбутися цієї нечисті.$B$BСправа йде добре.  Я буду повідомляти про хід подій у міру необхідності.",
        [2] = "ЗВІТ: Злодії$B$BУ долині з’явилася банда людських злодіїв, яка викликає ще більше занепокоєння, ніж кобольди. Вони носять червоні бандани й називають себе «братством».  Такий рівень організації може призвести до неприємностей як тут, так і в усьому Лісі Елвін.$B$BМи встановили особу одного з їхніх ватажків — Гарріка Падфута — і сподіваємося незабаром притягнути його до відповідальності.",
        [3] = "ЗВІТ: Вовки$B$BУ Нортширі спостерігається зростання кількості зареєстрованих випадків нападів тварин.  Іган вважає, що  вовки в долині перебралися сюди з Дусквуда.$B$BХоча вовки рідко полюють на людей, сама їхня чисельність стала причиною низки інцидентів із фермерами.  Крім того, зникла значна кількість худоби.",
        [4] = "ПОДЯКА:$B$BВласнику цих документів присвоюється звання заступника в Армії Штормовію за сумлінну та зразкову службу в Нортширі.  Я впевнений, що ця особа стане вам у нагоді в Елвінському лісі.$B$BПідпис:$B-Маршал Дуглас Макбрайд, $BАрмія Штормовію, Нортшир",
    },
},

