[889] = {
    en = "A Dusty Unsent Letter",
    T  = "Запилений лист, що так і не був відправлений",
    pages = {
        [1] = "Шановний директоре Крілліане,$B$Bмій колишній наставнику, я пишу вам, щоб ви знали, чим останнім часом займався ваш учень.  Дотримуючись вашої поради, я прагнув розширити свої знання та мудрість, подорожуючи за межами нашого улюбленого Штормовію.  Мої мандри привели мене до багатьох місць, але я вирішив оселитися тут, у чарівному містечку Мунбрук.  Навколишні поля Вестфолла надзвичайно красиві напередодні жнив.",
        [2] = "Вже через кілька днів після мого приїзду я почав давати приватні уроки місцевим дітям із сусідніх ферм.  Заняття пройшли настільки успішно, що мер міста доручив мені очолити школу, і вже розпочалося будівництво нової шкільної будівлі!  Від Сільверпайна до Штормовію, а тепер і до Мунбрука — хто б міг подумати, що я побачу стільки місць в Азероті!$B$BЗ повагою,$B$BСталван Містмантл",
    },
},

[910] = {
    en = "An Undelivered Letter",
    T  = "Лист, що не був доставлений",
    pages = {
        [1] = "Шановний благородний пане,$B$BДо мене, що перебуваю тут, у Голдширі, де я тимчасово мешкаю в готелі «Лев’яча гордість», дійшла звістка про те, що вам потрібен репетитор для ваших дітей.  Через несприятливий розвиток подій у регіоні я був змушений залишити посаду директора школи «Мунбрук».  Прошу прийняти мою заявку на посаду репетитора для Ваших дітей.  У разі потреби директор Академії Крілліан може надати Вам рекомендації щодо моїх здібностей.",
        [2] = "Я вирушу до вас, щоб зустрітися особисто, коли вщухнуть зимові дощі і дороги знову стануть придатними для подорожей.$B$BДо того часу,$B$BСталван Містмантл із Срібної Сосни",
    },
},

[916] = {
    en = "A Torn Journal Page",
    T  = "Розірвана сторінка щоденника",
    pages = {
        [1] = ". . .Хлопчик Гайлз здається дещо неспокійним, і його виховання стане справжнім викликом.  Однак старша дочка, Тіллоа, видається надзвичайно розумною.  Я також не міг не помітити її чарівну красу.  Вона зараз на порозі дорослого життя.  Кажуть, що лорд домовився про її одруження на наступний рік.  Але я відволікся від теми.  Цього тижня я супроводжуватиму родину до їхньої літньої дачі поблизу лісозаготівельного табору Іствейл в Елвінні, недалеко від гір Ред-Рідж.  Сподіваюся, що там я зможу написати більше.",
    },
},

