[1208] = {
    en = "Maybell's Love Letter",
    T  = "Любовний лист Мейбелл",
    pages = {
        [1] = "Томмі Джо — З кожною годиною моє серце в’яне від твоєї відсутності.  О, якби тільки наші рідні змогли поглянути далі тих дурних провин, які вони скоїли одне проти одного, і зрозуміти, що єдиний справжній злочин — це ненависть.  Ненависть пожирає, і я боюся, що в ці похмурі часи вона охопить не лише наші родини. Якби вони це усвідомили, ми нарешті змогли б бути разом.  Саме на цей день я сподіваюся, і заради нього я живу. З любов’ю, Мейбел",
    },
},

[1252] = {
    en = "Gramma Stonefield's Note",
    T  = "Записка бабусі Стоунфілд",
    pages = {
        [1] = "Привіт, Вільяме,$B$B$BMи не спілкувалися вже багато років, але сподіваюся, що ти та твій брат почуваєтеся добре, а твоя аптека процвітає.$B$B$BЯ мушу попросити тебе про послугу, Вільяме.  Коротко кажучи, мій онук Томмі Джо закохався в юну Мейбел Маклюр.  І хоча вони обожнюють одне одного... наші родини, ну, наші родини вже роками ворогують між собою.",
        [2] = "Я боюся, що війна між родинами Стоунфілд і Маклюр покладе кінець романтичним стосункам Томмі Джо та Мейбел, які тільки-но зароджуються, а в такі часи — коли над нами нависають похмурі новини та чутки про війну — молодість і кохання потрібно плекати. Тож ось прохання: я прошу тебе використати свої вміння й приготувати зілля або еліксир, щоб допомогти цим молодим закоханим у їхніх пошуках одне одного. Дякую, Вільяме. І, будь ласка, коли у тебе з’явиться трохи вільного часу від роботи, завітай до нас. Ми трохи посміємося, згадуючи минуле. — Мілдред",
    },
},

[1283] = {
    en = "Verner's Note",
    T  = "Примітка Вернера",
    pages = {
        [1] = "Аргус, $B$BЯк ти знаєш, я по вуха завалений заявками на ремонт від армії.  Я не можу скаржитися на таку кількість роботи, але це вичерпує мої запаси заліза.$B$BУ мене не вистачає заліза навіть на підкови.  Я знаю, що ти завжди тримаєш великий запас — я хотів би позичити 50 пар підків, поки не отримаю наступну партію заліза.$B$BЯ тобі дуже вдячний,$B-Вернер",
    },
