    pages = {
        [1] = "ДЕНЬ ПЕРШИЙ$B$B$BСьогодні ми з учнем прибули до Долини Колдрідж. Подорож через печеру пройшла в основному без пригод. Ми розбили табір на значній відстані від печери, де, як нам сказали, зібралися тролі.$B$B$BДЕНЬ ДРУГИЙ$B$B$BВиття клятого вовка майже не дало мені заснути всю ніч.$B$B$BЗа кілька днів я отримаю новий одяг із вовчої шкури.$B$B$BСьогодні хлопець зіткнувся з троггом, вступив у бій і",
        [2] = "йому вдалося взяти гору над потворним звіром, але тепер він лікує глибокий поріз на руці. Схоже, мені доведеться деякий час виконувати хатні справи. ТРЕТІЙ ДЕНЬ Холодно. Близько полудня трохи посніжило. ЧЕТВЕРТИЙ ДЕНЬ Хлопець сьогодні повернувся й був у гарному настрої, тож ми вперше поглянули на тролів. Я б сказав, що це «Морозногриві», судячи з візерунків на їхній шкірі та різних прикрас, які вони носили на собі.",
        [3] = "П'ЯТИЙ ДЕНЬ Попросив хлопця приглянути за табором, а сам потайки підкрався до печери й оглянув її. Кількість тролів дещо турбує. Можливо, доведеться викликати на допомогу весь загін «Гірських стрільців», щоб очистити печеру від навали тролів. Я усвідомив, що останнім часом не згадував про трогів. Вони з’являються в цій місцевості дедалі частіше, але вони настільки примітивні, що не становлять особливої загрози. Час покаже, чи це справді так.",
        [4] = "І вже майже тиждень — ні краплі елю. ДЕНЬ ШОСТИЙ Знову холодно. Сніг. Тролі. Елю немає. СЬОМИЙ ДЕНЬ Сніг внизу такий білий, Небо вгорі таке блакитне, Вовки витимуть всю ніч, А елю — ні краплі. ВОСЬМИЙ ДЕНЬ Тролі, мабуть, не така вже й велика проблема, як ми спочатку думали. У них є деякі",
