[2007] = {
    en = "The Third Troll Legend",
    T  = "Третя легенда про тролів",
    pages = {
        [1] = "Піднявшись з океану, як водяна вежа, Нептулон послав великого Краккена до приреченого І’лалаї. Їхні тіла були настільки величезними, що джунглі водоростей колихалися між їхніми кінцівками, а левіафани плавали крізь їхні тіла.$B$BТоді найбільший кракен високо підняв руки й з силою опустив їх у море, піднявши навколо себе хвилі. І вони з люттю поринули в бік І'лалаї.",
        [2] = "Кракен заревів, і їхні голоси прогриміли, наче океанська буря:$B$B\"Ми йдемо.\"$B$BМін’лот, твердо стоячи на місці, закликав свою магію. Хвилі, спрямовані на І’лалію, розступилися й розійшлися в обидва боки, затопивши джунглі за ними. Тоді Мін’лот наказав своїм підлеглим промовляти заклинання зв’язування, і пролунав галас, коли піднялися десятки голосів тролів.$B$BІ один голос піднявся над усіма іншими.",
        [3] = "Мін'лот прогримів, і його магія зібрала силу заклинань його слуг, після чого він спрямував її на наближаючогося краккена.$B$BМоре розступилося, і заклинання Мін'лота помчало на слуг Нептулона. Блискавки розірвали небо, і заклинання влучило в них; тисячі блискавок впали, кип’ятячи воду та випалюючи кратери в землі.$B$BMін’лот тріумфально вигукнув, знаючи, що його заклинання повалить цих величезних звірів.",
        [4] = "Але кракени старі, дуже старі. Вони пам’ятають, як земля вперше з’явилася з моря.$B$BВони пам’ятають, як правили Стародавні, і як прийшли Мандрівники та повалили їх. Вони пам’ятають, як магія була ще новою.$B$BВони старі й зберігають багато таємниць. І хоча заклинання Мін'лота було сильним, воно, як і троль, було смертним.$B$BІ тому воно зазнало поразки.",
        [5] = "Їм не вдалося приборкати Краккена, але це лише розлютило їх. Вже віки жоден смертний не завдавав їм болю, а заклинання троля було болісним.$B$BТож вони скинули пута заклинання Мінлота, але потім заревіли й кинулися вперед у люті.$B$BПролунав гуркіт, коли величезні хвилі піднялися з глибин і помчали до суші. Добравшись до І’лалаї, вони затьмарили місто своєю тінню.$B$BАле перш ніж знищити його, Краккен зупинився, застигши в напрузі.",
        [6] = "Трольські знахарі затремтіли й закликали свого господаря. Мін’лот дивився на морські гори — приречений і непокірний. Він повернувся до своїх послідовників і прошепотів, а тролі викарбували його останні слова на камені.  Потім Мін'лот обернувся до грізного Кракена.$B$BВін скривився і кинув свій посох — це був його останній сміливий вчинок.$B$BТоді Кракен спрямував свою лють на Мін'лота, і на І'лалай обрушився океан.$B$BІ все скінчилося.",
        [7] = "Трольські знахарі затремтіли й закликали свого господаря. Мін’лот дивився на морські гори — приречений і непокірний. Він повернувся до своїх послідовників і прошепотів, а тролі викарбували його останні слова на камені.  Потім Мін'лот обернувся до грізного Кракена.$B$BВін скривився і кинув свій посох — це був його останній сміливий вчинок.$B$BТоді Кракен спрямував свою лють на Мін'лота, і на І'лалай обрушився океан.$B$BІ її більше не стало.",
        [8] = "Трольські знахарі затремтіли й закликали свого господаря. Мін’лот дивився на морські гори — приречений і непокірний. Він повернувся до своїх послідовників і прошепотів, а тролі викарбували його останні слова на камені.  Потім Мін'лот обернувся до грізного Кракена.$B$BВін скривився і кинув свій посох — це був його останній сміливий вчинок.$B$BТоді Кракен спрямував свою лють на Мін'лота, і на І'лалай обрушився океан.$B$BІ все зникло.",
    },
},

