[2154] = {
    en = "The Story of Morgan Ladimore",
    T  = "Історія Моргана Ладімора",
    pages = {
        [1] = "Морган Ладімор був великим і благородним лицарем, який боровся на захист невинних, бідних та страждаючих. Протягом багатьох років він старанно працював у віддалених куточках Азероту, приносячи полегшення страждаючим і швидко караючи злочинців.$B$BВлітку, коли йому виповнилося вісімнадцять, він одружився з молодою дівчиною на ім’я Ліс. Вони дуже кохали одне одного і з часом мали трьох дітей — сина та двох дочок.$B$BMоргану було тридцять два, коли спалахнула війна в",
        [2] = "Лордаерон. Моргана було покликано до лав легендарного паладина Утера Світлоносного, щоб воювати проти орків та нежиті. Залишивши дружину та дітей у безпеці свого дому, Морган вирушив на війну.$B$BМинали роки, війна затягувалася, і Морган став свідком багатьох жахливих подій, зокрема розформування Паладинів Срібної Руки, смерті Утера та поширення чуми. Єдине, що утримувало його від краю божевілля, — це усвідомлення того, що він",
        [3] = "колись знову побачитися зі своєю дружиною та дітьми.$B$BЗрештою Морган повернувся на батьківщину, але виявив, що вона зовсім не така, якою він її запам’ятав. Колись зелений ліс був спотворений і кишів нежиттю та іншими темними силами. Скрізь можна було побачити зруйновані будинки та ферми, а кладовище біля Равенс-Гілл тепер займало більшу частину цієї місцевості. Вражений і збентежений Морган зрештою дістався до свого дому, але виявив, що той лежить у руїнах. Не знаючи, що сталося з його батьківщиною, він",
        [4] = "попрямував до села, щоб знайти відповіді і, як він сподівався, свою дружину та дітей.$B$BMорган розпитував про свою родину, але не зміг дізнатися нічого. Священик у Даркширі, як тепер називалося це місце, сказав, що йому варто пошукати надгробку на кладовищі на Равен-Гілл. Морган відмовлявся вірити, що його родина загинула, і продовжував обшукувати кожну ферму та кожен будинок у Дасквуді, але марно.$B$BMорган поїхав з Даркширу до сусіднього Лейкширу, думаючи, що, можливо, його родина втекла. По дорозі",
        [5] = "Там він, всупереч здоровому глузду, вирішив зайти на кладовище «Рейвен-Хілл». Морган годинами блукав серед надгробків. Він впізнав багато імен знайомих людей і ставав дедалі більш розгубленим. І раптом він їх побачив: невеличку, занедбану ділянку серед безлічі інших, на якій стояли три маленькі надгробки. Коли він наблизився, його охопило відчуття жаху. Морган змахнув пил з найпомітнішого надгробка, щоб розгледіти ім’я, викарбуване на ньому. На могилі були просто викарбувані літери, що складалися в слово",
        [6] = "його найгірший страх:$B$BLис Ладімор$BBулюблена дружина та мати$B$BMорганове занепокоєння переросло у відчай, а потім — у горе, і він, ридаючи, впав на коліна. Годинами він дивився на ту єдину могилу, благаючи холодний камінь про прощення та ридаючи від вини. Потім, через кілька годин, щось у ньому зламалося, і він почав розмахувати мечем. Він витягнув меч із піхов і почав сипати ударами по надгробках, кричачи від люті. Засліплений гнівом, він розмахував мечем і бив ним наосліп, привернувши увагу",
        [7] = "тріо працівників кладовища. Коли вони спробували його стримати, він переніс свою увагу на них, обсипаючи невинних доглядачів звинуваченнями у провині, а потім убив їх усіх.$B$BПізніше, коли лють минула, до свідомості Моргана прокралася усвідомленість, і він побачив, як його закривавлений меч встромлений у груди одного з доглядачів. Доведений емоціями до межі, він дістав ніж з-за пояса й встромив його собі в серце.$B$BТіло Моргана Ладімора та тіла трьох його жертв було знайдено",
        [8] = "Наступного дня його швидко поховали, без церемонії, у поспіхом викопаній могилі на околиці кладовища. Оскільки Морган вчинив вбивство невинних людей — що повністю суперечило його переконанням і природі — а також через горе, яке він відчував через те, що не зміг врятувати свою родину, Морган не зміг померти спокійною смертю і продовжив існувати як один із неспокійних померлих.$B$BЛише через кілька днів його могилу розрили, а тіло не вдалося знайти. Істота, якою тепер став Морган,",
        [9] = "блукає Сутінковим лісом, охоплений горем через втрату дружини та дітей, а також ненавистю до самого себе. Мор’Ладім, як він тепер називає себе, мандрує Сутінковим лісом, сповнений сліпої помсти та ненависті, і, як відомо, без розбору вчиняє вбивства.",
    },
},

[2161] = {
    en = "Book from Sven's Farm",
    T  = "Замовлення з ферми Свена",
    pages = {
        [1] = "Жах останніх кількох тижнів — це майже більше, ніж я можу витримати; проте я відчуваю, що, записавши те, що я бачила, я якось знайду розраду. Тож я це роблю, і це — єдина розрада, яка у мене є в ці похмурі дні.",
        [2] = "Все почалося з того, як я знайшов ту прокляту косу в «Долі Роланда».  До появи Коси жахи цього місця здавалися такими ж нешкідливими, як і в Долині Нортшир.$B$BАле відтоді, як я знайшов рукоятку Коси, що стирчала з тієї купи уламків у шахті, і, хай мене проклянуть, витягнув її, «Роландс Дум» перетворився на місце огидної смерті!",
        [3] = "Після того, як «Коса» була звільнена, вони накинулися на нас з усіх боків: виривалися з прихованих нір біля наших ніг і накидалися на нас з безшумних схованок зверху.  Половина наших людей загинула в ті перші хвилини паніки.  Решта, включаючи мене, намагалася втекти.  Під час втечі я бачив, як багатьох моїх побратимів забирали зубами й кігтями, чув, як безліч криків обірвалися або перейшли у булькання, що стихло.",
        [4] = "Я можу лише здогадуватися, чому я вижив тієї ночі. Я завжди був обережним, завжди встигав ухилитися від ударів і вистрибувати з пасток. Моє прізвисько походить саме від цієї риси. Тож, можливо, саме ця схильність до обережності й врятувала мене...$B$BАбо, можливо, це була Коса, яку я витягнув із-під уламків.  Це не може бути сама Коса, адже я загубив її під час шаленої втечі.  Але якщо саме я привів воргенів до Сутінкового лісу, то, можливо, воргени проявили до мене рідкісну ввічливість.  Хай їм буде ганьба.",
        [5] = "Переживши втечу з «Роланд’с Дум», я сховався у сараї, що належав чоловікові на ім’я Свен. Я провів у сараї кілька днів, і той жах так сильно мене переслідував, що я жодного разу не наважився показатися Свену чи його родині. Але з того, що я бачив зі своєї схованки, я зрозумів, що ці фермери — цілком порядні люди.  Якби я вийшов зі своєї схованки, думаю, вони б мене прийняли, але мені важко довіряти людям.  А після того шоку в шахті це стало ще важче.$B$BТож я й далі залишався в схованці.",
        [6] = "<Решта книги — порожня>",
    },
},

