[2223] = {
    en = "The Collector's Schedule",
    T  = "Графік роботи «Колекціонера»",
    pages = {
        [1] = "Нижче наведено порядок дій та графік доставки золота Дефіасів із копалень Елвіна до нашого штабу у Вестфолі.$B$BГрафік доставки:$B$BNеділя: 12:30$BСереда: 12:30$B$BУ кожен зазначений день золото, видобуте в шахтах Елвіна, збиратиметься на гарбузовому полі Браквелла.  Агента, відповідального за ці збори, — «Збирача» — можна буде впізнати за перснем з гравіюванням, який він носить.  Це перстень, який я йому подарував.",
        [2] = "Представник штабу «Братства Дефіас» зв’яжеться зі Збирачем, після чого той передасть зібране золото.$B$BПереконайтеся, що цей процес буде виконано безвідмовно та з максимальною обережністю.  Збирач несе відповідальність за передачу золота, але в кінцевому рахунку кожен член Братства Дефіас зобов’язаний дбати про те, щоб виконувати свої обов’язки уважно та дисципліновано.",
        [3] = "Пам’ятайте, брати мої, колись ми були гордими майстрами. Ми виконуватимемо свої нинішні обов’язки з тією ж точністю, яку проявляли у своїй колишній справі.$B$B-EVC",
    },
},

[2560] = {
    en = "Jitters' Completed Journal",
    T  = "Завершений щоденник «Джитерса»",
    pages = {
        [1] = "Мій щоденник$B$BЖах останніх кількох тижнів майже нестерпний для мене; чому ж, записуючи слова в цю книгу, я якось можу тримати божевілля на відстані?  Можливо, це ніби я сповідаюся у своїх гріхах мовчазному супутнику або звільняю свій розум від цих мучливих думок, ув’язнюючи їх на папері.  $B$BЯ вже вів щоденник до цього, але він залишився в місці, куди я не можу повернутися.  Тож я почну все спочатку.  Але цього разу я почну з самого початку.",
        [2] = "Все почалося з того, як у шахті, яку називають «Роландська загибель», знайшли ту прокляту косу. Так, саме з цього все й почалося. До цього «Братство Дефіас» було задоволене нашими успіхами в Сутінковому лісі.  До появи коси жахи цього місця здавалися такими ж помірними, як у Долині Нортшир.$B$BАле відтоді, як я знайшов рукоятку коси, що стирчала з тієї купи уламків у шахті, і, хай мене проклянуть, витягнув її, «Роландська загибель» перетворилася на місце огидної смерті!",
        [3] = "Якби я знав, що станеться, я б відрізав собі руку, аби тільки не взяти в руки той дерев’яний предмет з викарбуваними рунами.  Скільки ж жалю!  Я завжди думав, що це привілей старих.  Тепер я знаю, що не літні люди — а безнадійні — накидають на себе плащ жалю, не маючи змоги й не бажаючи скинути його з плечей, згорблених від страждань.$B$BАле досить вже роздумувати, наче поет, що збожеволів від куріння трубки.  Я мушу продовжувати свою хроніку...",
        [4] = "Після того, як «Коса» була звільнена, у шахті прокотилася хвиля змін. Світло від наших мерехтливих смолоскипів спотворилося, а сила наших голосів, здавалося, вийшла з-під нашого контролю.  Іноді шепіт людини гуркотів тунелями так, що доводилося затуляти вуха, а іноді наші крики ледь долітали на кілька кроків, перш ніж згасали, перетворюючись на ледь чутний шепіт на вітрі.$B$BЦе, звісно, було тривожно, але у нас не було часу довго дивуватися цій дивацтві.  Це було лише передвісником того, що насправді змусило нас покинути шахту.  Воргени.",
        [5] = "Вони накинулися на нас звідусіль: виривалися з прихованих нір біля наших ніг і накидалися на нас з безшумних схованок зверху.  Половина наших людей загинула в ті перші хвилини паніки.  Решта, включаючи мене, намагалася втекти.  Під час втечі я бачив, як багатьох моїх побратимів забирали зубами й кігтями, чув, як безліч криків обривалися або переходили у булькання, що стихало.$B$BНаскільки мені відомо, я — єдина людина, яка втекла з того місця.",
        [6] = "Я можу лише здогадуватися, чому я вижив тієї ночі. Я завжди був обережним, завжди встигав ухилитися від ударів і вистрибувати з пасток. Моє прізвисько, «Джитерс», походить саме від цієї риси. Тож, можливо, саме ця схильність до обережності й врятувала мене...$B$BА може, це була Коса, яку я витягнув із-під уламків.  Сама Коса це не могла бути, адже я загубив її під час шаленої втечі.  Але якщо саме я привів воргенів до Сутінкового лісу, то, можливо, воргени проявили до мене рідкісну ввічливість.  Нехай їх проклянуть.",
        [7] = "А може, я приречений стати свідком тих змін, які сам спричинив у Сутінковому лісі.  Можливо, моя доля — спостерігати, як воргени навалюються на цю землю, заплямовуючи її своєю мерзенністю дедалі темнішими плямами.$B$BЯкщо це справді моя доля, то вона має два аспекти.  Адже воргени — не єдина сила, що прагне заволодіти Сутінковим лісом — свої права на нього також заявляють демони з Перевалу Мертвого Вітру.$B$BЦе — наступний розділ моєї історії, і я молюся, щоб він став останнім...",
        [8] = "Переживши втечу з «Роланд’с Дуум», я сховався у сараї, що належав чоловікові на ім’я Свен. Я провів у сараї кілька днів, і той жах настільки глибоко закарбувався в моїй душі, що я жодного разу не наважився показатися Свену чи його родині. Але з того, що я бачив зі своєї схованки, я зрозумів, що ці фермери — цілком порядні люди.  Якби я вийшов зі своєї схованки, думаю, вони б мене прийняли, але мені важко довіряти людям.  А після того шоку в шахті це стало ще важче.$B$BТож я залишався в схованці.  І це врятувало мені життя.",
        [9] = "Через кілька днів після того, як я прибув до комори, Свен вирушив зі своєї ферми до Даркширу. Він поцілував дружину, посміхнувся дітям і пообіцяв незабаром повернутися з іграшками та солодощами. Бідолаха. Це був останній раз, коли він бачив свою родину цілою й неушкодженою.  $B$BПринаймні вони розлучилися щасливо.  І принаймні його дружина померла першою, тож їй не довелося бачити, як вбивають її дітей.  Але ці невеликі втіхи мені нічим не допомагають.  Я бачив, що сталося, і це назавжди буде переслідувати мене у снах.",
        [10] = "Моя рука тремтить, коли я згадую подробиці тієї ночі, коли Свена не було поруч, а його родина була приречена самотужки протистояти Чорним Вершникам. Знову мене охоплює жаль, адже я був там і міг би виступити проти тих нечистей з Перевалу Мертвого Вітру. Але це помилковий жаль.  Це те саме почуття, яке мучить кожного, хто пережив трагедію.  Я знаю: якби я вийшов зі своєї схованки, мене теж убили б, моє тіло розірвали б на шматки, а його уламки розкидали б так далеко, що мене б не впізнали.",
        [11] = "Але, хоча я й розумію, що не міг нічого вдіяти, аби запобігти цьому жахливому вбивству, у мене все ж залишається одне справжнє жаль: саме я привів Чорних Вершників на ферму Свена.  Моє відкриття Коси не лише випустило воргенів на Сутінковий ліс — воно також привернуло Вершників із Перевалу Мертвого Вітру.$B$BЯ знаю це, бо безпосередньо перед тим, як вони почали свою різанину, вони поставили одне запитання дружині Свена, яка міцно обіймала своїх дітей, намагаючись заспокоїти їх, як тільки могла, хоча була впевнена, що смерть вже близько.",
        [12] = "«Коса Елуни», — провищав один із Вершників голосом, що був водночас грубим і пронизливим, наче скрегіт сокири об камінь.  А останнє слово — «Елуна» — воно прохрипіло, ніби задихаючись від самого звуку.$B$BКоли я почув цей голос, мене охопив жах — і через його огидний тембр, і тому що...Я знав, про яку Косу говорив Вершник.  Це мала бути та сама проклята річ, яку я витягнув із скель «Роландської загибелі» кілька днів тому.  Саме її шукали Чорні Вершники!$B$BІ саме вона вб’є родину Свена.",
        [13] = "Я так і не дізнався імені дружини Свена, адже її чоловік і діти завжди називали її лише «найдорожча», «моє кохання» та «мамочко». Але якби ж я знав це ім’я.  Я — єдиний живий свідок її вчинку того дня, і хоча вона була лише дружиною фермера, я ніколи не бачив, щоб хтось — чоловік чи жінка — діяв з такою хоробрістю.$B$BЗвісно, вона не знала про Косу, але коли дізналася, що Вершники її шукають, у її голові миттєво сформувався план.$B$BІ він був сміливим та кмітливим.  Якби ж тільки він спрацював.",
        [14] = "«Коса?» — сказала вона спокійним голосом. «Звісно, що знаю. Хто з тут присутніх не знає?» Вона дивилася на Вершників твердим поглядом, і я б присягнувся, що вона говорить правду, якби не знав, що це не так. Вона ніяк не могла знати про Косу.$B$BЇї хід спрацював.  Той самий Вершник, що й раніше поставив це запитання, злегка нахилив голову до неї й викрикнув: «Де?»$B$B«Я відведу вас.  Усіх вас», — сказала вона, і я побачив, як у її очах промайнула крихітна іскра надії.",
        [15] = "«Але шлях довгий, і мої діти нас затримають. Ми мусимо їх залишити».$B$BЇї хитрість була простою, але саме прості хитрощі мають найбільші шанси на успіх. Якщо це спрацює, це відведе Вершників подалі від ферми. Вона загине, але її діти будуть у безпеці.  І це спрацювало б, якби тільки Вершники повірили її благородним брехням.$B$BХоча я ніколи не був учнем Світла, я палко молився за дружину Свена, коли вона протистояла тим жахливим Вершникам.$B$B«Будь ласка, — молився я. — Нехай вони повірять».",
        [16] = "Вони стояли, заціпенілі, а вона спокійно зустріла їхні погляди.  Тоді один з вершників підвів голову, ніби почувши віддалений поклик.  Він дістав зі свого одягу невеликий самоцвіт і втупився в нього.  Потім він жестом вказав цією прикрасою на дружину Свена.  Від Вершника до жінки поповзло світло, яке прийняло форму похмурої білої руки.  Вона дивилася на світло, не змигнувши оком, але я бачив невпевненість за її маскою впевненості.  Коли рука досягла її, вона розчепірила пальці над її головою.  $B$BІ стиснула.",
        [17] = "Дружина Свена стояла нерухомо, як дошка, а її очі широко розширилися. І хоча її губи розтягнулися, ніби готуючись вигукнути крик, жодного звуку не пролунало. Після кількох миттєвостей цієї муки рука відпустила її, і вона впала на коліна.  Вершник, який тримав прикрасу, випрямився в сідлі, і звідти пролунав гучний голос.$B$B\"Ця жінка бреше,\" — пролунало голосом, що назавжди закарбувався в моїх снах.  \"Вона не бачила Коси.\"",
        [18] = "Після цього плечі Вершника трохи згорбилися, ніби дух, що був у ньому, втік.  І тоді тим самим старим, пронизливим голосом, яким він говорив раніше, пролунали ці останні слова:$B$B\"Господь вимовив.  Вбийте їх.\"",
        [19] = "Я не можу описати, що сталося далі. У моїй свідомості все ясно, але навіть моя знедолена душа не здатна викласти на папері події тих наступних кількох моторошних хвилин.$B$BI можу лише написати, що родину Свена вбили. А незабаром після цього Свен повернувся на це похмуре, смертоносне місце.  У ньому було стільки горя, що я боявся показатися на очі.  І так боявся, що він мене знайде, що втік зі своєї схованки в сараї.  Я не знаю, де зараз Свен, але молюся, щоб він колись знайшов спокій.",
        [20] = "Наступні кілька тижнів я провів, переїжджаючи з місця на місце, ніде не затримуючись через страх перед Вершниками. Зараз я перебуваю в покинутому містечку Рейвенс-Гілл, як завжди, ховаючись. Я не можу протистояти тій силі, яку вони застосували проти дружини Свена, і знаю, що вона й досі шукає Косу в Сутінковому лісі.  Я її втратив, і дякую Світлу за це, бо якби я її зберіг, то, як мені відомо, мене б знайшли.  Навіть зараз я в глибині душі знаю, що мене знайдуть.$B$BIЯ так втомився.",
    },
},

[2619] = {
    en = "Grelin's Report",
    T  = "Звіт Греліна",
    pages = {
        [1] = "Звіт про стан справ із тролями Морозної Гриви в районі Долини Колдрідж$B$BПідготовлено Греліном Білобородим, спеціальним посланцем Сенату$B$BЗа результатами спостережень за переміщеннями тролів Морозної Гриви в районі Долини Колдрідж, я дійшов висновку, що вони не становлять значної загрози для поселень гномів у цьому районі. Більше того, цю загрозу можна усунути, не потребуючи значної додаткової підтримки з боку армії. За допомогою альпіністів, які вже дислокуються в",
        [2] = "Долина Колдрідж та найманці (оплата яких здійснюється за рахунок коштів, виділених Сенатом до мого відправлення), я впевнений, що проблема буде вирішена найближчим часом. $B$BЦя операція була санкціонована королем Бронзобородим.",
    },
},

[2628] = {
    en = "Senir's Report",
    T  = "Звіт Сеніра",
    pages = {
        [1] = "Звіт про стан тролів Фростмейн у районі Дун-Морога. Тролі, що мешкають у Дун-Морозі, здебільшого зосереджені у фортеці Фростмейн — гірській печері на західному кордоні. Їхня чисельність достатня, щоб викликати певне занепокоєння, проте вони, здається, цілком задоволені тим, що залишаються у своїй печері. Це, без сумніву, пов’язано з тим, що вони не бажають знову накликати на себе гнів гномів і ризикувати повним винищенням. Їхні дії, якщо вже й можна так сказати, можна вважати територіальними, і це",
        [2] = "я переконаний, що вони не становлять для нас реальної загрози, доки ми не втручаємося на їхню територію. Ця ситуація може здатися непривабливою для населення гномів, але з огляду на розподіл військових ресурсів, можливо, розумніше буде віднести знищення тролів до менш пріоритетних завдань і продовжувати зосереджуватися на загрозі, яку становлять троги та Темні Залізні. У додатку ви також знайдете копію звіту мого брата Греліна про Анвілмар. Підпис: Сенір Білобородий",
        [3] = "Звіт про стан тролів Морозної Гриви в районі Долини Колдрідж, підготовлений Греліном Білобородим, спеціальним посланцем Сенату. За час спостереження за переміщеннями тролів Морозної Гриви в районі Долини Колдрідж я дійшов висновку, що вони не становлять серйозної загрози для поселень гномів у цьому районі. Більше того, цю загрозу можна усунути, не потребуючи значної додаткової підтримки з боку армії. Завдяки допомозі альпіністів, які вже дислокуються в",
        [4] = "Долина Колдрідж та найманці (оплата яких здійснюється за рахунок коштів, виділених Сенатом до мого відправлення), я впевнений, що проблема буде вирішена найближчим часом. Ця операція була санкціонована королем Бронзобородим.",
    },
},

[2637] = {
    en = "Ironband's Progress Report",
    T  = "Звіт про хід робіт компанії «Айронбенд»",
    pages = {
        [1] = "Шановні колеги та шукачі істини$B$BРозкопки на цьому місці тривають, але їх хід уповільнюють троги, про яких я згадував у своєму останньому звіті.  Я впевнений, що з ними можна впоратися, навіть якщо деякі з цих трогів виявляють більшу агресивність, ніж зазвичай.$B$BНещодавно було знайдено ще більше артефактів, хоча в усіх випадках, крім одного (про який я розповім нижче), останні знахідки мають той самий рівень, що й попередні — цікаві, хоча й не надто просвітницькі.",
        [2] = "Був лише один виняток. Нещодавно знайдені ідоли з дивними різьбленнями (короткий опис яких містився в моєму останньому звіті), судячи з усього, впливають на трогов у цьому місці.  Їх приваблюють ці кам’яні різьблення, а деяких трогогів вони доводили до несамовитості!$B$BЩоб зробити якісь висновки щодо цих ідолів, потрібні додаткові дослідження, але я сподіваюся, що вони проллють світло на зв’язок між трогогами та титанами.",
        [3] = "Наостанок я мушу ще раз нагадати про своє прохання щодо вибухового порошку. Мої запаси майже вичерпалися, що суттєво заважає успішному проведенню розкопок.  Мені повідомили, що поповнення запасів вибухового порошку має надійти найближчим часом, проте я його ще не отримав.$B$BДозвольте запитати, у чому причина затримки?$B$BЗ повагою,$BЗолотошукач Дартеус Айронбенд",
    },
},

[2639] = {
    en = "Merrin's Letter",
    T  = "Лист Меррін",
    pages = {
        [1] = "Мій найдорожчий Таррел —$B$BВибач за поспіх, з яким було написано цей лист, але час — це не та розкіш, якою ми можемо собі дозволити.  $B$BЕкспедиція досягла значного прогресу у розкопках важливих артефактів Титану.  Але ми почали виявляти й інші стародавні предмети, а саме великі кістки.",
        [2] = "Незабаром після того, як кістки були викопані, ми стали жертвами нападу рапторів.  Батальйон бійців із полку Лонгбрейда бився відважно.  Але зрештою їх перевершили чисельністю.  Майже всі загинули.  Вижили лише троє з нас.  Найбільш героїчним виявився робітник на ім’я Ормер Айронбрейд, який забезпечив безпеку мені та золотошукачеві Велгару.",
        [3] = "Зараз ми сховалися в захищеній печері, де, здавалося б, нам нічого не загрожує.  Але насправді ми опинилися в пастці, доки не буде надіслано підкріплення, здатне дати відсіч Рапторам.  Велгар намагається продовжувати роботу, але я підозрюю, що він досі дуже наляканий.  Ось така у нас ситуація, Таррел.  Будь ласка, попроси Лонгбрейда негайно зібрати рятувальний загін.$B$BМоя любов до тебе залишається сильною, навіть у ці страшні часи.$B$B—Меррін",
    },
},

[2720] = {
    en = "Muddy Note",
    T  = "Замітка про багнюку",
    pages = {
        [1] = "1-й день: з 6:00 до 11:00 — верхній табір; з 11:00 до 11:30 — перерва, обід; з 11:30 до 16:00 — перевал у каньйоні; з 16:00 до 19:30 — верхній табір. 2-й день: Такий самий розклад, як і в 1-й день. 3-й день: Такий самий розклад. 4-й день: Такий самий розклад, за одним винятком.  Незадовго до заходу сонця Торсен попросив мене прикрити його, поки він спускався до перевала в каньйоні.  Я припустив, що він пішов на зустріч із нашими агентами. Але він повернувся через годину.  Це мене здивувало.  Я сподівався, що він зустрівся з нашими агентами і знову приєднається до Курзена.  Щось не так.",
        [2] = "5-й день: Сьогодні Торсен був дуже схвильований.  Мабуть, те, що він побачив, або ті, кого він зустрів під час вчорашньої вилазки, налякали його. Я припустив, що з ним розмовляли наші агенти, але коли я запитав Торсена, куди він ходив, поки я його прикривав, він промовчав.  Він вважає мене своїм другом і вірить, що захищає мене від небезпечної таємниці. Його лояльність спрямована не туди, але вона дуже сильна.  Коли він знову приєднається до нас, він стане цінним поповненням для військ Курзена.",
        [3] = "6-й день: Рано вранці Торсен довго розмовляв із сержантом Йова.  Мені довелося вдавати, що я ще сплю, тому я не міг наблизитися на відстань, з якої можна було б почути їхню розмову.  Але я припускаю, що вони говорили про недавню подорож Торсена. Під час обіду я пильно спостерігав за ним і помітив, що Йова робить те саме.  Пізніше Дорен викликав Торсена.  У них трьох є спільна таємниця.  Дорен і Йова, мабуть, знають, що Торсен зустрічається з вашими агентами. Він шпигує на користь повстанців.",
        [4] = "Ми не повинні більше надавати Торсену жодної інформації, і ми повинні його вбити. Він більше не потрібен нашому полковнику. Я покінчу з Торсеном, якщо випаде нагода, але якщо ви отримаєте цей лист, то знатимете, що у мене ще не було такої можливості. У такому разі я пропоную, щоб наступна зустріч Торсена з нашими агентами стала для нього фатальною. Хай живе Курзен, — М",
    },
},

[2724] = {
    en = "Cloth Request",
    T  = "Запит на тканину",
    pages = {
        [1] = "Шановні Шнайдери.$b$bДоброго дня. Сподіваюся, справи в районі каналу йдуть добре.$b$bУ нас на Торговій площі справді процвітає торгівля. Нам потрібні трикотажні вироби, оскільки наші запаси майже вичерпалися. Будь ласка, надішліть стандартну партію товару, як тільки зможете.$b$bБажаю вам успіхів, і сподіваюся, що навчання вашого сина Термана просувається добре.$b$b— Гарлан Бейглі",
    },
},

[2725] = {
    en = "Green Hills of Stranglethorn - Page 1",
    T  = "Зелені пагорби Стренглторна — Сторінка 1",
    pages = {
        [1] = "Зелені пагорби Стренглторна$B$BНаш перший день пройшов так добре, як і слід було очікувати від першого дня.  Більшу частину часу ми присвятили підготовці до облаштування базового табору.  Я знайшов ідеальне місце біля притоки прісноводної річки.  Судячи зі старих, занедбаних причалів поблизу, колись тут хтось мешкав.  А що стосується перших мешканців, то про це може розповісти лише час.",
    },
},

[2728] = {
    en = "Green Hills of Stranglethorn - Page 4",
    T  = "Зелені пагорби Стренглторна — Сторінка 4",
    pages = {
        [1] = "У наступні роки, після того як Штормовій зрадив Гільдію каменярів, сер Ерлгадін став з гіркотою ставитися до ролі дворян у Королівстві. Він більше не бажав обіймати посаду, яку родовід його батька забезпечив йому в Палаті дворян.$B$BАле я відволікся від теми.  Мета цієї розповіді — не стати політичним трактатом чи біографією.  Це розповідь про мої враження від полювання на велику дичину серед зелених пагорбів Странглторна??",
    },
},

[2730] = {
    en = "Green Hills of Stranglethorn - Page 6",
    T  = "Зелені пагорби Стренглторна — Сторінка 6",
    pages = {
        [1] = "Якраз коли я збирався запитати Аджек, чому вона не цікавиться стратегією сьогоднішнього полювання, вона потягнулася до свого колчана, витягла стрілу й випустила її прямо в бік бідолашного Барніла.  Але Аджек стріляла не в Барніла.  Бо коли Барніл відступив убік із роззявленим ротом, на поверхню сплив великий річковий кроколіск, у якого стріла Аджек ідеально влучила між двома великими очима.",
    },
},

[2732] = {
    en = "Green Hills of Stranglethorn - Page 8",
    T  = "Зелені пагорби Стренглторна — Сторінка 8",
    pages = {
        [1] = "Під час однієї з таких помилок Ерлгадін важко поклав руку на плече Барніла.  Аджек і я кинули побіжний погляд, припускаючи, що чоловік просто робить Барнілу так необхідне зауваження за його необережність. Однак Ерлгадін повільно кивнув головою у бік поваленого поблизу дерева. На нас дивилися дві пронизливі чорні очі, розташовані трохи вище рота, повного гострих, як бритва, іклів.",
    },
},

[2734] = {
    en = "Green Hills of Stranglethorn - Page 10",
    T  = "Зелені пагорби Стренглторна — Сторінка 10",
    pages = {
        [1] = "Це вбивство створило святкову атмосферу серед учасників експедиції. Барніл налив медовухи, щоб усі могли насолодитися нею. Але наше святкування тривало недовго. Коли ми готували труп до транспортування назад до базового табору, нас усіх застало зненацька жахливе гарчання. За все своє життя я ніколи не чув нічого настільки моторошного.",
    },
},

[2735] = {
    en = "Green Hills of Stranglethorn - Page 11",
    T  = "Зелені пагорби Стренглторна — Сторінка 11",
    pages = {
        [1] = "На скелястому обриві вгорі, на тлі заходу сонця, я розгледів найбільшого хижого кота, якого коли-небудь бачив. Мені вдалося випустити одну невмілу серію пострілів зі своєї рушниці, але кіт не поступився. Він ще раз заричав, цього разу голосніше, ніж попереднього разу, і зник.$B$BМи зібрали свої речі й урочисто вирушили назад до табору.",
    },
},

[2738] = {
    en = "Green Hills of Stranglethorn - Page 14",
    T  = "Зелені пагорби Стренглторна — Сторінка 14",
    pages = {
        [1] = "Цього дня ми вирушили на південь, слідуючи за свіжими слідами пантери.  Незабаром ми дісталися до ущелини, через яку пролягав величезний мост із мотузок.  Побачивши це диво інженерної думки, я не міг не згадати описи цього краю, зроблені Бранном.  Так часто вважалося, що місцеві тролі — це примітивна й неосвічена раса, проте, споглядаючи майстерну роботу над мостом, я зміг оцінити, з якою вправністю тролі-будівельники впоралися з цим, здавалося б, неможливим завданням.",
    },
},

[2740] = {
    en = "Green Hills of Stranglethorn - Page 16",
    T  = "Зелені пагорби Стренглторна — Сторінка 16",
    pages = {
        [1] = "І Аджек, і сер Ерлгадін стояли, тримаючи зброю на мушці, спрямовану на густі зарості біля підніжжя колихаючихся дерев. Полуденне сонце пекло нас немилосердно. Повільна цівка поту стікала з скроні Ерлгадіна, коли він відтягнув запобіжник.  Звуком клацання густа рослинність розступилася, і велика чорна пантера — прекрасний екземпляр — вискочила на рівнину.",
    },
},

[2742] = {
    en = "Green Hills of Stranglethorn - Page 18",
    T  = "Зелені пагорби Стренглторна — Сторінка 18",
    pages = {
        [1] = "Його рушниця різко відкинулася назад у його руках.  Ствол змахнув убік і опинився під гвинтівкою Аджек.  Саме в цей момент Аджек натиснула на спусковий гачок.  Гвинтівка, приціл якої тепер незграбно був спрямований у бік лісосмуги, пролунала гучним пострілом.  З крони з криком вилетіла зграя птахів, розлетівшись у всі боки.  З дерева піднявся стовп диму.  Ми з подивом спостерігали, як величезна гілка впала прямо на пантеру, що тікала, зламавши їй спину.",
    },
},

[2744] = {
    en = "Green Hills of Stranglethorn - Page 20",
    T  = "Зелені пагорби Стренглторна — Сторінка 20",
    pages = {
        [1] = "Ми вирушили з першими променями світанку, прямуючи на південь повз руїни Ткаші. Барніл висловив побоювання, що ми можемо натрапити на представників племені «Криваві скальпи». Я нагадав Барнілу, що «Криваві скальпи» більше зацікавлені у знищенні свого племінного ворога — «Розколювачів черепів».  Зрозуміло, що це анітрохи не заспокоїло Барніла.  Однак у мене була заряджена рушниця, сумка, повна пороху, та троє вправних мисливців, що розвіювали будь-які побоювання щодо ворожої засідки.",
    },
},

[2745] = {
    en = "Green Hills of Stranglethorn - Page 21",
    T  = "Зелені пагорби Стренглторна — Сторінка 21",
    pages = {
        [1] = "Я стояв на полі бою перед грізним Пекельним, а армія Палаючого Легіону наступала з усіх боків.  Недисциплінована зграя тролів здається такою ж нешкідливою, як заєць у пагорбах Дун-Морога.$B$B$BМи без пригод минули Руїни Ткаші, на велике полегшення Барніла.  Група рушила на захід, у бік Великого моря, оминаючи руїни Зул’Кунди, що лежали трохи південніше.  Піднімаючись на високі морські скелі, ми помітили нашого першого раптора.",
    },
},

[2748] = {
    en = "Green Hills of Stranglethorn - Page 24",
    T  = "Зелені пагорби Стренглторна — Сторінка 24",
    pages = {
        [1] = "Наших поспішно випущених пострілів вистачило, щоб дати Барнілу можливість втекти. Барніл з галасом збіг униз зі схилу й знову приєднався до нашої групи. Ми кинулися в джунглі; зграя лютих «Лаштейл-рапторів» стежила за кожним нашим рухом. Тепер мисливці стали здобиччю.",
    },
},

[2749] = {
    en = "Green Hills of Stranglethorn - Page 25",
    T  = "Зелені пагорби Стренглторна — Сторінка 25",
    pages = {
        [1] = "Я повів загін у бік моря, сподіваючись, що берегова лінія стане для нас притулком від Рапторів. У поспіху ми занадто далеко відхилилися на північ, опинившись на небезпечно високій висоті. Ми припустилися помилки. Це моя провина. Ми зупинилися впритул до стрімкої скелі, а Раптори були всього за кілька кроків від нас.",
    },
},

[2750] = {
    en = "Green Hills of Stranglethorn - Page 26",
    T  = "Зелені пагорби Стренглторна — Сторінка 26",
    pages = {
        [1] = "Я повільно рушив уперед, піднявши зброю.  Я привів цих хоробрих мисливців на смерть. Я загину, захищаючи їх. Раптори «Лаштейл» — особливо люті, відомі своєю невгамовною жадобою крові. Їх було набагато більше, ніж нас. Але хай мене чорт забере, якщо я дозволю їм убити мене та моїх товаришів, не проливши спочатку трохи їхньої крові.",
    },
},

[2751] = {
    en = "Green Hills of Stranglethorn - Page 27",
    T  = "Зелені пагорби Стренглторна — Сторінка 27",
    pages = {
        [1] = "Аджек і сер Ерлгадін приготували зброю, ставши по обидва боки від мене, спиною до моря. Барніл зітхнув з відчаєм і витягнув сокиру. Лаштейли вже майже наздогнали нас. Їхній рівний крок сповільнився. Тепер вони підкрадалися до своєї здобичі, бо знали, що загнали нас у пастку.",
    },
},

[2756] = {
    en = "Green Hills of Stranglethorn - Chapter I",
    T  = "«Зелені пагорби Стренглторна» — Розділ I",
    pages = {
        [1] = "Наш перший день пройшов так добре, як і слід було очікувати від першого дня.  Більшу частину часу ми присвятили підготовці до облаштування базового табору. Я знайшов ідеальне місце біля притоки прісноводної річки. Судячи зі старих, занедбаних причалів поблизу, колись тут хтось мешкав. Щодо перших мешканців цього місця — про це може розповісти лише час.",
        [2] = "Для цієї експедиції я зібрав Аджека Руака та сера С. Дж. Ерлгадіна, а також мого вірного слугу Барніла Стоунпота. Я воював пліч-о-пліч з батьком Аджека у багатьох битвах на захист Альянсу.  Бачити, як вона виросла, — це щось особливе.  Її батько добре навчив її володінню зброєю.  Її майстерність у стрільбі з лука змушує мене замислитися, чи не тече в її жилах ельфійська кров.",
        [3] = "Сер С. Дж. Ерлгадін походить із людської аристократії.  Його батько, граф Ерлгадін, славився своєю щедрістю.  Саме граф доклав зусиль для поліпшення умов праці членів Гільдії каменярів під час відновлення Штормовію після Другої Великої війни.",
        [4] = "У наступні роки, після того як Штормовій зрадив Гільдію каменярів, сер Ерлгадін став з гіркотою ставитися до ролі дворян у Королівстві. Він більше не бажав обіймати посаду, яку родовід його батька забезпечив йому в Палаті дворян. Але я відволікся від теми.  Мета цієї розповіді — не стати політичним трактатом чи біографією.  Це розповідь про мої пригоди під час полювання на велику дичину серед зелених пагорбів Странглторна?.",
        [5] = "Ми прокинулися разом із сонцем.  Барніл почав готувати сніданок. Я помітила, що Аджек була дещо розсіяна.  Сьогоднішній похід мав бути довгим, а полювання наблизило б нас до небезпеки.  Відсутність зосередженості могла легко призвести до несподіваної прикрості.  Проте Аджек, здавалося, не могла відвести погляду від Барніла, який стояв на березі річки й ополіскував свою польову посуд.",
        [6] = "Якраз коли я збирався запитати Аджек, чому вона не цікавиться стратегією сьогоднішнього полювання, вона потягнулася до свого колчана, витягла стрілу й випустила її прямо в бік бідолашного Барніла.  Але Аджек стріляла не в Барніла.  Бо коли Барніл відступив убік із роззявленим ротом, на поверхню виплив великий річковий кроколіск, у якого стріла Аджек ідеально влучила між двома великими очима.",
        [7] = "Ми вирушили на захід, крізь густі зарості заплутаних джунглів. Рухаючись повільними, обережними кроками, ми пробиралися крізь густе листя у пошуках здобичі. Ранок минув у розчарованій тиші.  У Долині нічого не ворушилося, навіть вітерець не подув.  До полудня учасники експедиції стали нетерплячими: Барніл уже не крокував обережними кроками хижака, що вистежує здобич.  Натомість він незграбно тупотів стежкою, часто гучно наступаючи на сухе листя чи повалені гілки.",
        [8] = "Під час однієї з таких помилок Ерлгадін важко поклав руку на плече Барніла.  Аджек і я кинули побіжний погляд, припускаючи, що чоловік просто робить Барнілу вкрай необхідне зауваження за його необережність. Однак Ерлгадін повільно кивнув головою у бік поваленого поблизу дерева. На нас дивилися дві пронизливі чорні очі, розташовані трохи вище рота, повного гострих як бритва іклів.",
    },
},

[2757] = {
    en = "Green Hills of Stranglethorn - Chapter II",
    T  = "Зелені пагорби Стренглторна — Розділ II",
    pages = {
        [1] = "Звір виявився самцем тигра зі Странглторна. Не встиг я навіть зарядити гвинтівку, як Ерлгадін підняв арбалет і вистрілив у звіра. Стріла не влучила в ціль, але важко поранила звіра в лівий бік. Тигр зробив марну спробу втекти, але його рана була занадто серйозною. Звір ще кілька трагічних секунд спотикався, поки Барніл не довершив його, кинувши сокиру.",
        [2] = "Ця вполювання викликало святковий настрій серед учасників експедиції. Барніл налив медовуху, щоб усі могли насолодитися нею. Але наше святкування тривало недовго. Коли ми готували труп до транспортування назад до базового табору, нас усіх застало зненацька жахливе гарчання. За все своє життя я ніколи не чув нічого настільки моторошного.",
        [3] = "На скелястому обриві вгорі, на тлі заходу сонця, я розгледів найбільшого хижого кота, якого коли-небудь бачив. Мені вдалося випустити одну невмілу серію пострілів зі своєї рушниці, але кіт не поступився. Він ще раз заричав, цього разу голосніше, ніж попереднього разу, і зник.$B$BМи зібрали свої речі й урочисто вирушили назад до табору.",
        [4] = "Я пообіцяв учасникам експедиції, що наступного дня ми будемо полювати на пантер, оскільки їхнє хутро користується великим попитом по всьому Азероту. І це цілком логічно, адже всі працездатні мисливці, трапери та торговці хутром віддали свої життя, так відважно борючись за справу Альянсу.",
        [5] = "Аджек і сер Ерлгадін дуже хотіли навчитися ефективно полювати з гномівською гвинтівкою. Я попросив цих двох людей залишити свою примітивну зброю для стрільби на великі відстані в базовому таборі. Барніл і я оснастили їх найкращою вогнепальною зброєю з Айронфорджа.",
        [6] = "Цього дня ми вирушили на південь, слідуючи за свіжими слідами пантери. Незабаром ми дісталися до ущелини, через яку пролягав величезний мост із мотузок. Побачивши це диво інженерної думки, я не міг не згадати описи цього краю, зроблені Бранном. Так часто вважалося, що місцеві тролі — це примітивна й неосвічена раса, проте, споглядаючи майстерну роботу над мостом, я зміг оцінити ту вправність, з якою тролі-будівельники подолали, здавалося б, неможливе завдання.",
        [7] = "Незабаром Аджек вистежив пантеру на південному заході. Ми йшли тихо, тримаючи зброю напоготові, в очікуванні здобичі. Тріск гілочок із сусіднього гаю одразу привернув нашу увагу. Там щось було. Одного суворого погляду на Барніла вистачило, щоб передати мої думки. Барніл повільно опустив свою гвинтівку. Ця здобич була не для нас; вона була для наших людських супутників. Незліченна кількість пантер загинула під нашими димлячими стволами. Ця здобич буде для людей.",
        [8] = "І Аджек, і сер Ерлгадін стояли, тримаючи зброю на мушці, спрямовану на густі зарості біля підніжжя колихаючихся дерев. Полуденне сонце пекло нас немилосердно. Повільна цівка поту стікала з скроні Ерлгадіна, коли він відтягнув запобіжник. Звуком клацання густа рослинність розступилася, і велика чорна пантера — прекрасний екземпляр — вискочила на рівнину.",
    },
},

[2758] = {
    en = "Green Hills of Stranglethorn - Chapter III",
    T  = "«Зелені пагорби Стренглторна» — Розділ III",
    pages = {
        [1] = "Люди навели приціли на пантеру, яка бігла вздовж краю лісосмуги.  Стволи їхніх рушниць рухалися ідеально паралельно один одному. Барніл кинув на мене наполегливий погляд, але я похитав головою. Це полювання було для людей, а не для Барніла чи для мене. Ерлгадін вистрілив гучним пострілом, але повністю промахнувся повз пантеру. Мабуть, він не був готовий до сильної віддачі від пострілу.",
        [2] = "Його рушниця різко відкинулася назад у його руках.  Ствол змахнув убік і опинився під гвинтівкою Аджек.  Саме в цей момент Аджек натиснула на спусковий гачок.  Гвинтівка, приціл якої тепер незграбно був спрямований у бік лісосмуги, пролунала гучним пострілом.  З крони з криком вилетіла зграя птахів, розлетівшись у всі боки.  З дерева піднявся стовп диму.  Ми з подивом спостерігали, як величезна гілка впала прямо на пантеру, що тікала, зламавши їй спину.",
        [3] = "З кожним тижнем наші запаси шкур пантер і тигрів ставали все більшими. Я вирішив, що настав час експедиції перенести свою увагу на нове завдання: хижих птахів. Люди, хоча й цінували навчання, яке ми з Барнілом їм надавали, вирішили утриматися від полювання з вогнепальною зброєю.  Аджек набагато впевненіше почувався з добре натягнутим луком, а сер Ерлгадін ніколи не залишав табору без свого міцного арбалета.",
        [4] = "Ми вирушили з першими променями світанку, прямуючи на південь повз руїни Ткаші. Барніл висловив побоювання, що ми можемо натрапити на представників племені «Криваві скальпи». Я нагадав Барнілу, що «Криваві скальпи» більше зацікавлені у знищенні свого племінного ворога — «Розколювачів черепів».  Зрозуміло, що це анітрохи не заспокоїло Барніла.  Однак у мене була заряджена рушниця, сумка, повна пороху, та троє вправних мисливців, що розвіювали будь-які побоювання щодо ворожої засідки.",
        [5] = "Я стояв на полі бою перед грізним Пекельним, а армія Палаючого Легіону наступала з усіх боків.  Недисциплінована зграя тролів здається такою ж нешкідливою, як заєць у горах Дун-Морога. Ми без пригод минули Руїни Ткаші, на велике полегшення Барніла.  Наша група рушила на захід, у бік Великого моря, оминаючи Руїни Зул’Кунди, що лежали трохи південніше.  Піднімаючись на високі морські скелі, ми помітили нашого першого раптора.",
        [6] = "Звір навіть не помітив нашої присутності.  Насправді, єдиним привітанням, яке він отримав від експедиції, була куля між очей.  Сер Ерлгадін вигукнув сердечне «ура», а Аджек кивнув мені головою, висловлюючи щире схвалення.  Я перерив свій рюкзак у пошуках люльки, сподіваючись насолодитися святковою куренням.  Барніл почав метушитися вгору по схилу, щоб дістати тушу Раптора.  Я дивився на вбиту тварину з тим задоволенням, яке супроводжує кожне велике полювання.",
        [7] = "Але я не міг довго насолоджуватися славою перемоги. Адже коли я звернув погляд на горизонт, на вершині пагорба, прямо над бідним Барнілом, з’явилося кілька силуетів. *Тікай, Барніле!* — крикнув я.  Аджек, сер Ерлгадін і я випустили шквал куль, стріл і болтів над Барнілом у бік хижаків, що переслідували його.  Одному з нас вдалося вбити одного з них у цій метушні.",
        [8] = "Наших поспішно випущених пострілів вистачило, щоб дати Барнілу можливість втекти. Барніл з галасом збіг униз зі схилу й знову приєднався до нашої групи. Ми кинулися в джунглі; зграя лютих «Лаштейл-рапторів» стежила за кожним нашим рухом. Тепер мисливці стали здобиччю.",
    },
},

[2759] = {
    en = "Green Hills of Stranglethorn - Chapter IV",
    T  = "Зелені пагорби Стренглторна — Розділ IV",
    pages = {
        [1] = "Я повів загін у бік моря, сподіваючись, що берегова лінія стане для нас притулком від Рапторів. У поспіху ми занадто далеко відхилилися на північ, опинившись на небезпечно високій висоті. Ми припустилися помилки. Це моя провина. Ми зупинилися впритул до стрімкої скелі, а Раптори були всього за кілька кроків від нас.",
        [2] = "Я повільно рушив уперед, піднявши зброю.  Я привів цих хоробрих мисливців на смерть. Я загину, захищаючи їх. Раптори «Лаштейл» — особливо люті, відомі своєю невгамовною жадобою крові. Їх було набагато більше, ніж нас. Але хай мене чорт забере, якщо я дозволю їм убити мене та моїх товаришів, не проливши спочатку трохи їхньої крові.",
        [3] = "Аджек і сер Ерлгадін приготували зброю, ставши по обидва боки від мене, спиною до моря. Барніл зітхнув з відчаєм і витягнув сокиру. Лаштейли вже майже наздогнали нас. Їхній рівний крок сповільнився. Тепер вони підкрадалися до своєї здобичі, бо знали, що загнали нас у пастку.",
        [4] = "І тоді сталося щось дивовижне. З боку до нас долинув чіткий і жахливий рик великого білого тигра.  Незважаючи на свою чисельність, раптори розвернулися й розбіглися в усі боки.  Ми побачили лише короткий білий спалах, коли тигр промчав повз нас і накинувся на одного з рапторів.  Не було потреби давати жодної команди.  Усі четверо членів нашої групи розуміли, що настав час тікати.",
        [5] = "Ми мчали назад до базового табору, не зменшуючи швидкості. Пізніше тієї ночі ми тихо сиділи біля багаття, розуміючи, що наші життя врятував дивний поворот долі.  Такі ось ризики мисливця на велику дичину.  Ми граємо з долею, доставляючи їй здобич.  Проте кожен із нас рано чи пізно зіткнеться з гострими як бритва зубами долі.  Цей карлик просто радий, що той момент не настав на зелених пагорбах Странглторна.",
    },
},

