[2837] = {
    en = "Thurman's Letter",
    T  = "Лист Турмана",
    pages = {
        [1] = "Найдорожча Іветто,$B$B$BЯ доручу цей лист нашому найшвидшому бігуну.  Я молюся, щоб він зміг пробратися крізь війська, що оточують нас.  І я молюся, щоб ти прочитала ці слова, бо це останнє, що ти почуєш від мене.$B$B$BЄдиною втіхою для мене в ці темні дні є полегшення, яке я відчуваю, знаючи, що ти уникнула моєї долі.",
        [2] = "Боюся, що мій батько припустився серйозної помилки, вирішивши залишитися й захищати наш дім. Війська Плетіння лютують у Полях Тірісфал, і хоча ми добре укріплені та забезпечені провіантом, після зради мого брата Девліна нам бракує сил і чисельності, щоб протистояти їхнім безперервним атакам. Якщо ти отримаєш цей лист, Іветто, то знай: Девлін — зрадник.",
        [3] = "Девін, зневірившись, шукав способу врятуватися від наших нещасть, і в результаті уклав угоду з «Скорб’ю». Я не знаю, яку винагороду йому обіцяли за зраду, але впевнений, що вона була просякнута брехнею. Якщо побачите мого брата, то тікайте від нього.  Він — нечисть.  Кілька ночей тому він вбив двох наших вартових і пропустив невелику групу «Покарання» крізь пролом, привівши їх туди, де спало ще багато наших.",
        [4] = "Їхня засідка була жорстокою. Вони вбили третину наших, перш ніж ми змогли їх знищити. Зараз у нас ледь вистачає людей, щоб охороняти наші кордони. Це лише питання часу, коли наша виснажена варта втратить пильність і «Скорб» атакує. І хоча тієї проклятої ночі я побачив обличчя Девліна серед зневірених бійців та виснажених воїнів «Покарання», він втік, перш ніж я встиг його спіймати.  Можливо, він загинув, а може, досі живе як агент «Покарання». У будь-якому разі, він — монстр.",
        [5] = "Девлін попередив нас, що якщо ми спробуємо протистояти Плети, то нас чекає загибель. Він сказав нам це, коли вони вперше увійшли до Полян Тірісфал, задовго до того, як оточили наш дім.  Можливо, він благав нас піти, а може, просто зловтішався. Завжди було важко зрозуміти мотиви Девліна.  Ще з дитинства він був для нас загадкою.",
        [6] = "Але він мав рацію.  Ми приречені.  Рід Агамандів вимре.  Хоча я ще жива, я знаю, що незабаром помру. Я не боюся і не шкодую, що залишилася зі своєю родиною.  Але мої останні думки будуть про тебе. Живи далі, моя кохана Іветто, а я знайду спокій, — Турман",
    },
},

[2885] = {
    en = "Scarlet Crusade Documents",
    T  = "Документи «Скарлетного хрестового походу»",
    pages = {
        [1] = "Поширюйте інформацію так, як вважаєте за необхідне.$B$BРегіональне командування Тірісфал$BCапітан Мелроуз$BCапітан Вашон$BCапітан Перрін$B$BНакази за розпорядженням Верховного лорда.$B$BCапітан Перрін, додатково укріпіть свою позицію на південно-західній вежі (як зазначено). Додаткові припаси будуть відправлені пізніше. Тим часом матеріали можна буде отримати з навколишніх ферм. Також слід проводити подальшу розвідку та збір інформації",
        [2] = "Слід зібрати інформацію про організацію нежиті в Бріллі.$B$BКапітане Вашон, судячи з усього, поблизу північної вежі спостерігається посилення активності нежиті. З цим повстанням треба швидко й рішуче розібратися.$B$BКапітане Мелроуз, є занепокоєння щодо рівня організації нежиті поблизу кордонів Заражених земель. У найближчі тижні до вашої позиції буде відправлено свіжу групу бійців.$B$BСлава під Світлом",
    },
},

[2956] = {
    en = "Report on the Defias Brotherhood",
    T  = "Звіт про Братство Дефіаса",
    pages = {
        [1] = "Від Бароса Алексстона, Управління міського архітектора Штормовію. Ваша Величносте, існує чимало причин, через які я вважаю за необхідне підготувати та представити звіт щодо останніх подій, пов’язаних із «Братством Дефіаса», та їхньої діяльності по всьому королівству. Для кращого розуміння ситуації я почну з короткого історичного екскурсу. Як Ви, можливо, знаєте, а може й ні, моя служба на благо міста Штормовію розпочалася з членства в Гільдії каменярів. За роки роботи ми завершили відбудову",
        [2] = "У Штормовій на той час рахунки, збори та зарплати Гільдії каменярів залишалися неоплаченими й без уваги. Тоді Едвін ВанКліф був обраний головою Гільдії каменярів і виступив із вимогою відшкодування за наші роботи. У відповідь Палата дворян Штормовію наказала розпустити Гільдію каменярів, що, зрозуміло, розлютило ВанКліфа. Очоливши заворушення, ВанКліф вивів каменярів за межі міста. Перш ніж продовжувати, слід згадати ще кілька подій, що відбулися під час",
        [3] = "Цей період я хотів би особливо висвітлити. По-перше, саме тоді мені запропонували посаду міського архітектора, якщо я не приєднаюся до ВанКліфа. Через певні ідеологічні розбіжності я вирішив залишитися у Штормовій. Під час заворушень заступник ВанКліфа та його найнадійніший помічник, Базіл Тредд, був захоплений у полон і ув’язнений. Очікуючи на суд і допит, Тредд майже забувся у в’язниці «Стокейд». Повернувшись до ВанКліфа після того, як той очолив залишки",
        [4] = "Каменярі зі Штормовію скористалися тим, що Вестфолл перебував у відносно незахищеному стані, і, задіювавши свої чималі людські ресурси, вигнали звідти багатьох селян та захопили кілька золотих копалень. Використавши наявні в його розпорядженні ресурси, ВанКліф розробив план помсти уряду Штормовію. Ця інформація стала відома нещодавно завдяки допомозі носія цього документа, який відіграв ключову роль у розкритті цієї масштабної змови.",
    },
},

