[3117] = {
    en = "Hildelve's Journal",
    T  = "Щоденник Хільдельве",
    pages = {
        [1] = "День 1$B$BМій танк зламався, але я знаю, що руда хірону десь тут, у цих пагорбах.  Я сказав Хаммерфуту залишитися й пильнувати наші танки.$B$BЯ продовжую пошуки сам. Якщо я не повернуся, то цей щоденник буде моїм останнім заповітом.$B$B—Бурон Хільдельве, пілот$BПарова бригада Айронфорджа",
        [2] = "День 2$B$BМої пошуки тривають, але руди ніде не видно.  Мені цікаво, чи, може, Стоунгір просто вигадав цю чутку про руду як жарт.  Ну, якщо так, то я йому череп розтрощу, коли повернуся до складу Стілгрілла!$B$BSьогодні ввечері, коли я розкладав табір, я почув гарчання, що лунало каньйонами.  $B$BЦе не вовк.  Можливо, це ведмідь.",
        [3] = "3-й день$B$BЦе гарчання тривало всю ніч і супроводжувало мене весь сьогоднішній день, відволікаючи від пошуків руди.  Мені здається, за мною стежить ведмідь!$B$BСподіваюся, він підійде ближче.  Я вб’ю йому киркою по голові!",
        [4] = "4-й день$B$BУ мене закінчуються запаси.  Їжі в мене ще вдосталь, але я не розраховував на таке тривале перебування в дикій місцевості поза межами мого резервуара, і взяв із собою лише два бочки елю.$B$BОстанні дві ночі я не спав, прислухаючись до того проклятого гарчання, і майже повністю випив свої бочки!$B$BЗавтра мені доведеться повертатися до Хаммерфута та наших Парових Резервуарів.  Я не хочу заблукати тут, залишившись без випивки.",
        [5] = "5-й день$B$BЦей проклятий ведмідь мене доконав!  Він напав на мене опівдні, ревучи й кинувшись на мене ззаду.$B$BЯ б відчув його запах, якби він кинувся з навітряного боку — його сморід був просто жахливий!  Один лише сморід його паршивої шерсті та гнилого подиху ледь не збив мене з ніг!$B$BЯ відбився від нього, але він добряче покусав мені ногу.  Тепер я не можу рухатися, моє пиво закінчилося, а ту руду я так і не знайшов.  Чорт забирай!",
        [6] = "6-й день$B$BВедмідь ще не повернувся — мабуть, я його добряче побив!  Але я все ще чую його гарчання.  Гадаю, він чекає, поки я помру!$B$BТому, хто знайде цю книгу, я маю для тебе завдання.  Вбий того паршивого ведмедя.  Вбий його і віднеси цю книгу моєму другові Хаммерфуту.  Він захоче дізнатися, що сталося.$B$BІ візьми мою броню.  Вона тобі знадобиться у боротьбі зі старим Мангеклоу!",
    },
},

[3248] = {
    en = "Translated Letter from The Embalmer",
    T  = "Переклад листа від бальзаматора",
    pages = {
        [1] = "Вітаю, Елло Ебонлок, мер Даркшира.  Боюся, що маю новини для вашого міста.  Тяжкі новини.$B$BРозумієте, я — творець.  Я обдурив того, хто приніс цю записку, щоб він допоміг мені у створенні мого останнього, найжахливішого творіння — демона з плоті, кісток та покрученого металу!  Поки ви це читаєте, він, ймовірно, стоїть біля моєї скромної оселі, скрегочучи зубами й чекаючи на мій наказ, щоб вийти й вчинити різанину.$B$BАле ви про це незабаром дізнаєтеся.$B$B — Бальзамувальник",
    },
},

[3252] = {
    en = "Deathstalker Report",
    T  = "Звіт «Deathstalker»",
    pages = {
        [1] = "Звіт про місію «Дестстокер»$B$BAгенти: Рейн Йорік, Квінн Йорік, Ерланд МакКрі$B$BОсновне завдання: провести розвідку на півночі Сільверпайн та визначити рівень загрози з боку диких тварин і Плеті.",
        [2] = "Агенти розпочали обшук і виявили значну кількість воргів. Рекомендується відправити мисливські загони для нейтралізації цієї загрози.$B$На фермерському подвір’ї, яке отримало назву «Мертве поле», було виявлено неживих гнолів. Мета їхнього перебування на фермі невідома, хоча їхні пересування та рівень готовності вказують на неминучі військові дії.  За час спостереження серед гнолів не було виявлено жодних помітних ватажків.  Припускається, що вони очікують на прибуття керівництва або підкріплення.",
        [3] = "Продовжуючи операцію, наші агенти потрапили в пастку на фермі Івара. Івар, більшість членів його родини та його робітники піддалися впливу «Порази» і стали її слугами.$B$BAгенти зазнали нападу і, хоча їм вдалося відбити нападників, вони отримали серйозні поранення, особливо агент Квінн.",
        [4] = "У колишньому будинку Івара було зайнято оборонну позицію, і поки Ране пильнував на випадок майбутніх атак, Ерланд продовжував розвідувальну місію.$B$BПотім Ерланд опинився в оточенні воргів у північному саду і зміг врятуватися лише завдяки допомозі іншого агента «Покинутих». Саме цей агент і є носієм даного звіту.",
        [5] = "Слід зазначити, що цей носій звіту відіграв вирішальну роль не лише в успіху нашої місії, а й у розгромі Івара Брутального, порятунку Ерланда та доставці цього звіту.$B$BМи висловлюємо йому свою вдячність і рекомендуємо командуванню нагородити цю особу нагородами, гідними таких заслуг, які він проявив у бою.$B$B — Дестстокер Рейн Йорік,$Bкерівник місії",
    },
},

[3255] = {
    en = "Berard's Journal",
    T  = "Щоденник Берара",
    pages = {
        [1] = "Вивчаючи різні скам’янілості, я дійшов висновку, що в давні часи у водах озера Лордамере прокотилася велика епідемія.  Що стало причиною цього?  Можливо, ми ніколи цього не дізнаємося.  Однак, судячи з високої щільності скупчення решток, розкиданих по всьому дну озера, рівень зараження, судячи з усього, був надзвичайно високим.",
        [2] = "У спробі розкрити таємниці минулого я почав досліджувати істот сьогодення, сподіваючись знайти відсутню зачіпку для розгадки цієї загадки. «Озерні причаї» та «озерні повзуни» — це стародавні звірі, що мешкають на островах у центрі озера Лордамере. На них росте мох, який нагадує мікроелементи, виявлені на деяких скам’янілостях.  Потрібно провести додаткові дослідження, перш ніж я зможу висунути припущення щодо значення цього зв’язку.",
        [3] = "Під час збору зразків моху я натрапив на місце кривавої битви. Плем’я мурлоків «Підлі Плавники» опинилося в облозі з боку розбійницької банди гнолів. Поле бою було усіяне трупами як гнолів, так і мурлоків.  Проходячи повз понівечене тіло мурлока, я помітив дивну затверділу пухлину, що стирчала з рани.  Коли я почав вивчати цю пухлину, стало зрозуміло, що вона має властивості, схожі на ті, що й мох, який я збирав.  На жаль, крім цієї однієї, я не зміг знайти жодної іншої пухлини.",
    },
},

[3518] = {
    en = "Decrypted Letter",
    T  = "Розшифрований лист",
    pages = {
        [1] = "Вітаю, Майстре,$B$Bпробачте мені за спосіб надсилання цього повідомлення.  Мої маги тіні в Альтераку зосереджені на виконанні своїх завдань, що змушує мене скористатися послугами чужого посланця — призваного з-поміж наших нових «союзників» — щоб передати вам цей звіт.  Але я зашифрував цей лист одним із наших найтаємничіших шифрів.  Його зміст у безпеці від цих селюків.",
        [2] = "Наші плани успішно реалізуються; як уже згадувалося, ми уклали союз із групою людей, які називають себе «Синдикатом».  Їхні лідери колись були дворянами Альтерака, і вони прагнуть знову панувати тут.$B$BТому вони уклали з нами угоду.  Угоду, про яку вони ще пошкодують.",
        [3] = "Сьогодні Синдикат має незначну владу на цих землях, але його члени добре знають цю місцевість і зібрали достатню кількість людей для виконання майбутніх завдань.  Я впевнений, що за умови правильного керівництва Синдикат незабаром знову запанує над Альтераком.$B$BКрім того, ми закликали Синдикат націлитися на місто Стромгард у сусідніх Аратських височинах.  Це місто є полем бою між нашими військами, ограми та людьми Стромгарда, але ми вважаємо, що завдяки продуманій тактиці ми зможемо заволодіти цим колись величним містом.",
        [4] = "І коли це буде зроблено, можна буде розпочати наступний етап нашого плану. Маючи власну державу та опорний пункт у цьому регіоні, ми зможемо підготувати шлях для Третього Воїнства.$B$BНезабаром Володарі Легіону винагородять наші зусилля, знову обрушивши на землю вогняний дощ з небес!",
        [5] = "Рада мудро вчинила, призначивши вас головою «Аргус-Вейк» — керівником їхніх стратегічних операцій на землях людей і гномів.  І для мене велика честь виконувати вашу волю в Альтераку.$B$BВ ім’я Саргераса,$B $BNагаз, $BІєрофант Аргуса",
    },
},

