[3657] = {
    en = "Hillsbrad Town Registry",
    T  = "Реєстр міста Хіллсбрад",
    pages = {
        [1] = "Реєстр міста Хіллсбрад Ми, жителі Хіллсбрада, урочисто присягаємо у своїй вірності та відданості Альянсу, очолюваному великими монархами — королем Магні Бронзобородим із Айронфорджа та королем Андуїном Райном зі Штормовію. Цей міський реєстр призначений для управління цим прекрасним містом, розташованим у передгір’ях величних Альтеракських гір, а також слугує записом про тих, хто сплатив податки своїм королям та великому всемогутньому Альянсу.",
        [2] = "Магістрат Ратерфорд Бернсайд. Усі борги погашені. Коваль Ейвері Веррінгтан. Усі борги погашені. Клерк Горас Уайтстід. Усі борги погашені. Член ради Гілліс. Усі борги погашені. Член ради Хукс. Усі борги погашені. Фермер Гетц. Усі борги погашені. Фермер Рей. Борг не погашений. Обіцяно розрахунок сільськогосподарською продукцією під час жнив. Фермер Лайон. Борг не погашений. Виселений з землі.",
        [3] = "Фермер Калаба — борг залишається непогашеним.  Оплата сільськогосподарською продукцією обіцяна під час збору врожаю. Громадянин Вілкс — усі борги погашені. Громадянин Боноан — усі борги погашені. Шахтар Велті — борг залишається непогашеним.  Оплата має бути здійснена під час наступної поставки руди з «Азурлоуд». Шахтар Сідні — борг залишається непогашеним.  Оплата має бути здійснена під час наступної поставки руди з Азурлоуда. Гірник Хакетт: борг залишається непогашеним.  Оплата має бути здійснена під час наступної поставки руди з Азурлоуда.",
    },
},

[3711] = {
    en = "Belamoore's Research Journal",
    T  = "Науковий журнал Беламура",
    pages = {
        [1] = "Кеган Даркмар, ватажок невеликої групи неживих, які прийшли до нас у пошуках притулку від своїх «побратимів», суперечить нашим загальноприйнятим уявленням про представників його виду.  Може, його шкіра й гниє, а кров уже давно перестала текти в його жилах, але він поводиться дуже благородно і, здається, більше дбає про безпеку своїх співвітчизників, ніж про власну.$B$BСправді, в ньому є така людяність, якої, зізнаюся, мені іноді бракує в людях, що мене оточують.",
        [2] = "Але чому я про це згадую?  Я роблю це, щоб надати ваги тому, що збираюся написати, адже ці слова прозвучали з вуст Кегана, і я сподіваюся, що мої колеги, прочитавши цей щоденник, зрозуміють, чому я вірю в те, що він сказав:$B$B\"Залишки Старих Богів досі причаїлися в глибоких ущелинах світу.  Нові сили прагнуть приборкати цю древню міць, і ті, кому це вдасться, отримають страшну зброю проти своїх ворогів.\"",
        [3] = "Саме це промовив Кеган, передаючи мені свій кулон із гематиту, і в його очах, коли він це робив, відбивалися страх і, можливо, благоговіння.  А коли його руки торкнулися моїх, вони затрималися, ніби не бажаючи віддавати кулон.  Мене охопила огида, та й досі я не знаю, чи то мене відштовхувало його мертве тіло, що притискалося до мого, чи то сам кулон викликав у мене мурашки по шкірі.$B$BБо я відчувала в ньому силу.  Глибоку, приховану, голодну силу.  І таку, що прагнула вирватися назовні.",
        [4] = "Хоча мої колеги в Даларані вирішили не поспішати з дослідженням кривавих каменів, які привезли з собою Кеган та його послідовники, а замість цього помістили чотирьох біженців у карантин, залишивши криваві камені при них, щирість Кегана змусила мене дослідити його кулон із кривавим каменем.",
        [5] = "Я сподівався довести своїм колегам, що цей вид каменю справді має магічні властивості, і що, навіть якщо ми, чарівники Даларана, не бажаємо використовувати силу кровокаменів, нам слід принаймні вивчити їхні властивості, оскільки наші вороги одного дня можуть застосувати їх проти нас.$B$BІ так розпочалися мої дослідження.",
        [6] = "Я розпочав свої дослідження, виходячи з припущення, що гематит — це різновид гірської породи, подібний до кварцу чи обсидіану.  Тож я розпочав серію дослідів, щоб з’ясувати: які мінерали містяться в гематиті, які сили вплинули на формування його кольору та твердості, а також інші властивості, характерні для гірських порід і руд.  Але, на моє розчарування, кулон із гематиту не реагував на мої досліди так, як це робила б звичайна руда.",
        [7] = "Насправді він часто поводився саме так, як не очікувалося!  Складалося враження, ніби кулон навмисно заважав моїм експериментам.$B$BНіби він думав і був живим.$B$BРозлючений, але не зневірений, я перестав вважати кулон неживим шматком каменю і почав сприймати його як живу істоту.  $B$BАле знову я зазнав невдачі.",
        [8] = "Жоден із моїх нових експериментів не дав жодних відповідей щодо походження гематиту.  На той час єдиною загадкою, яку я розгадав, було те, що гематит не був ані живим, ані мертвим!$B$BАле саме тоді, на межі провалу, стався прорив.  У моєму останньому експерименті я використовував скляну колбу, край якої був відколотий, утворивши невеликий нерівний проміжок уздовж краю.  Коли експеримент закінчився, знову не давши жодних результатів, я пішов прибирати робочий стіл і порізався об цю колбу.",
        [9] = "Поріз був неглибоким, але, попри це, кров текла рясно. Ще до того, як я встиг перев’язати поранений палець бинтом, на мій робочий стіл вилилася чимала кількість моєї крові.$B$BІ коли я прибирав цей новий безлад, я помітив щось дуже дивне...",
        [10] = "Кров, що пролилася поруч із кулоном із гематиту, повільно рухалася до прикраси, ніби сила тяжіння якимось чином спрямувалася до гематиту. Кров, що торкалася кулона, ніби зникала, а червоний колір каменю ставав все насиченішим, коли він вбирав у себе все більше моєї крові.",
        [11] = "Побачивши це, у мене запаморочилося в голові — можливо, через нещодавню травму (хоча я не вважав, що втратив аж стільки крові), а може, тому, що я нарешті, після стількох розчарувань, розкрив одну з властивостей кровокам’яну.  Я потягнувся за робочим табуретом, що стояв позаду, сів і замислився.  Думки й запитання проносилися в моїй голові, викликаючи запаморочення й загрожуючи звалити мене з ніг.  $B$BЧи п’є гематит кров?  Чи жадає він крові?  Чи притягує він кров?",
        [12] = "Або, може, гематит зроблений із крові?  І якщо так, то чиєї крові?  Моєї?  Крові будь-якої людини?  Будь-якої тварини?  $B$BА може, гематит — це кров якоїсь невідомої істоти, тієї самої, яку Кеган і боявся, і шанував, коли вручав мені свій кулон.$B$BОсь на це питання треба знайти відповідь.  Це і є ключ.",
        [13] = "У мені знову розгорівся вогонь, і я знову поринув у свої експерименти. Цього разу я не робив жодних припущень, методично проводячи всі доступні мені випробування. Це значно збільшило обсяг необхідних зусиль, але й підвищило ймовірність відкриттів.  $B$BІ хоча моя лабораторія тут невелика і в мене немає підлеглих, яких я міг би залучити до допомоги, я все ж виявив ще одну цікаву властивість гематиту...",
        [14] = "Окрім крові, у камені поєднані стихійні сили. Вогонь, вода, грім і камінь змішані з кров’ю (але знову ж таки, чиєю саме кров’ю?), і хоча зовні ця суміш здається інертною, всередині всі ці сили, здається, бурхливо борються одна з одною.  Тож з’явилося ще безліч запитань щодо цього дивовижного й таємничого матеріалу.",
        [15] = "Однак щоб відповісти на ці питання, необхідно провести додаткові дослідження та експерименти з кулоном, і я побоююся, що табір для ув’язнених «Лордамере» не зможе залучити для цього ані необхідних кадрів, ані обладнання. Тому я відправив кулон із гематитом кур’єром до Даларана, додавши до нього чіткі інструкції щодо того, як його перевірити, щоб вони змогли уникнути тих труднощів, з якими я зіткнувся раніше.",
        [16] = "Поки я чекав на результати цих аналізів, я проводив час, розмовляючи з Кеганом.  Хоча я постійно допитував його про те, що він знає про кровокамені, він ніколи не розповідав мені нічого більше, ніж те, що сказав того дня, коли подарував мені свій кулон.  І він не часто згадував про час, проведений у лавах тих, кого він називав «Покинутими» — так він називає свій клан неживих.",
        [17] = "Але Кеган дуже хотів поговорити на інші теми, зокрема про те, як він ріс у Лордаероні до його падіння.  $B$BВін досі дуже любить це втрачене королівство, хоч воно й лежить у руїнах, і вже не існує.$B$BМоя дедалі більша симпатія до Кегана додавала мені терпіння, поки я чекала на результати аналізів.",
        [18] = "Але після кількох тижнів мовчання моє терпіння вичерпалося, і, звернувшись із додатковим запитом до Даларана, я дізнався, що кривавий камінь так і не дійшов до моїх колег.  Мій кур'єр якимось чином загубився по дорозі, і кулон із кровокаменем зник разом із ним!$B$BЦе дуже серйозна новина, адже хоча Кеган і його послідовники все ще мають зразки кровокаменю, з якими ми можемо проводити експерименти, я побоююся, що кулон може потрапити в небажані руки.",
        [19] = "Я відправив ще одного посланця до Даларана і дізнався, що навіть зараз вони шукають кулон у руїнах за межами нашої захисної сфери.$B$BI Сподіваюся лише, що ми не запізнилися.",
    },
},

