[3899] = {
    en = "Legends of the Gurubashi, Volume 3",
    T  = "«Легенди Гурубаші», том 3",
    pages = {
        [1] = "ЛЕГЕНДИ ПРО ТРОЛІВ, ТОМ III «Камінь припливів» Автор: Архімаг Ансірем Руневівер, Даларан ВСТУП Стародавня Імперія Гурубаші була джерелом багатьох захоплюючих та інтригуючих легенд, які, без сумніву, пов’язані з її околицями, оскільки дослідження їхніх вірувань та суспільних звичаїв вказують на велику повагу до навколишнього природного середовища. Хоча я докладно вивчав багато",
        [2] = "Оскільки в попередніх томах цього дослідження я вже розглядав окремі аспекти їхнього поклоніння зміям, тут я пропоную проаналізувати цікаві та унікальні стосунки тролів з морем. ВЕЛИКЕ МОРЕ Імперія Гурубаші з трьох боків була оточена морем, тож не дивно, що вода відігравала важливу роль у їхньому суспільстві. Хоча тролі могли вільно пересуватися та контролювати великі території своєї джунгляної імперії, море залишалося для них недосяжним. Воно було безмежним і незмірним, ні",
        [3] = "Безсумнівно, це був неприємний сусід для могутніх тролів. Тут слід зазначити, що останні відкриття, здається, свідчать про те, що тролі майже не виявляли інтересу до дослідження земель за Великим морем. Хоча представники виду тролів зустрічалися по всій території Азерота, Хаз-Модана та Лордаерона, у нещодавно відкритих землях Калімдора чи на островах Південних морів було знайдено мало свідчень про їхню цивілізацію. Чи свідчить це про небажання",
        [4] = "Те, чи наважуються тролі залишати свої наземні володіння, або ж їхня нездатність розробити технології, необхідні для такої подорожі, вимагатиме подальших досліджень та аналізу, що виходить за межі моїх роздумів у цій статті. Але навряд чи можна ігнорувати таку значну присутність, а нові знахідки у величезних руїнах тролів у Долині Странглторн розкривають раніше невідомий і не задокументований аспект їхніх стосунків з морем. КАМІНЬ ПРИПЛИВІВ Нещодавні відкриття під час досліджень",
        [5] = "У руїнах тролів у Долині Странглторн були виявлені згадки про предмет, відомий як «Камінь Припливів». Зібравши воєдино різні уривки з легенд тролів, можна скласти досить повну картину про цей Камінь та його значення для стародавньої Імперії Гурубаші. Схоже, що Камінь Припливів дозволяв своєму володареві керувати водою в її різних проявах — річками, дощем та припливами. З огляду на розповіді про використання Каменя Припливів, я припустив, що він є",
        [6] = "насправді є фізичним втіленням сил Володаря Води — могутнього елементаля морів. Як і чому такий предмет міг вийти з-під контролю Володаря Води та потрапити до рук тролів — це вже інше питання, яке виходить за межі моїх знань. «НОСІЙ ПРИПЛИВІВ» Подібно до рухів однойменних припливів, Камінь Припливів з’являвся у світі тролів і зникав з нього, ніколи не залишаючись у руках тролів довше, ніж на одне покоління.",
        [7] = "У легендах тролів розповідається, що коли «Камінь Припливів» вперше потрапив до Імперії Гурубаші, його знайшов воїн-троль, який блукав узбережжям Странглторна. Він натрапив на таємничий блакитний камінь, усередині якого плавали й текли молочно-білі нитки. Заінтригований каменем, воїн взяв його з собою і продовжив свою подорож. З плином тижнів і місяців воїн виявив, що камінь наділив його здатністю керувати водою. Він міг викликати",
        [8] = "водяні елементалі — істоти, повністю утворені з води, — повторивши подвиг, на який здатні лише могутні маги Кірін-Тор. Воїн вирушив до Зул’Гуруба, у саме серце імперії, щоб продемонструвати імператору свої новонабуті здібності. Він без труднощів отримав аудієнцію при дворі, продемонструвавши свої сили в центрі імперської столиці. Його сили вразили імператора Гурубаші, який негайно надав йому почесне місце при дворі, назвавши воїна «Носієм Припливу», залишивши його",
        [9] = "залишивши колишнє ім’я позаду. Протягом багатьох років Носій Припливів служив Імперії Гурубаші, викликаючи у бою своїх підлеглих — водяних елементалів — та керуючи потоками води в Долині Странглторн на благо Імперії. Але з плином років Носій Припливів став все більш відлюдним, часто надовго залишаючись подалі від двору. Носій Припливів приховував таємницю від цікавих очей придворних. Здібності, надані йому Каменем Припливів, супроводжувалися також прокляттям. З роками",
        [10] = "Минуло, і Носій Припливів поступово зникав. З кожним припливом і відпливом Носій Припливів дедалі більше втрачав себе, позбавляючись матеріальної форми — то з’являючись, то зникаючи — аж поки в останні дні свого життя він не вирушив на той самий пляж, де вперше знайшов Камінь, і не увійшов у море, зникнувши востаннє. Через кілька поколінь Камінь Припливів винесло на береги Странглторна, і було обрано іншого Носія Припливів, коли троль приніс Камінь до",
        [11] = "Зул’Гуруб. Так тривало протягом багатьох поколінь: Камінь з’являвся разом із припливом, а Носій Припливу зникав у хвилях. У наші дні з’являються різні розповіді про Камінь Припливів у різних куточках світу, але все ж виникає питання: чому об’єкт такої сили з’являється з такою регулярністю і за чиїм задумом?",
    },
},

[3921] = {
    en = "Bloodsail Orders",
    T  = "Ордени «Кривавого вітрила»",
    pages = {
        [1] = "Накази «Кривавого вітрила»$B$BУважно слухайте ці слова, друзі мої, бо у нас є лише один шанс у Буті-Бей.$B$BЯ відправив Старого Данкена на розвідку на північ і наказав йому чекати сигналу.$B$B«Щастя діви» кине якір біля південного мису для поповнення запасів. Капітан Стілвотер, той маленький карлик, має наказати своїй команді підготуватися до вивантаження всього награбованого.  Я впевнений, що той тупиця Брут все триматиме під контролем.",
        [2] = "Я хочу, щоб капітан Кілхол підвів «Ріптайд» до берега з південного сходу.  Коли пролунає сигнал, ми відправимо його екіпаж пішки.  $B$BТой великий дурень, Солтхуф, може доправити хлопців на канатах.  Я хочу, щоб на Ревілгаза та Сіхорна наклали «чорну мітку».  З мого боку — відправте їх прямо на дно моря.$B$BВи, хлопці, відповідаєте за вилучення всього, що може стати в нагоді для нашого маленького проєкту з ВанКліфом у Мертвих копальнях.",
        [3] = "Я віддам наказ «Айронпатчу» відкрити вогонь.  Артилерійський залп  не дозволить жодному кораблю «Блеквотер» покинути або увійти в порт.$B$BПісля того, як «Кримсон Вейл» вистрілить усі свої гармати, я підведу її до «Ріптайд» для надання підтримки та забезпечу резерви за потреби.$B$BЯк тільки «Солтхуф» і його хлопці підпалять місто, а весь екіпаж вийде на палубу, ми піднімемо вітрила і для впевненості ще раз обстріляємо затоку з «Дикого узбережжя».$B$B—Командувач флоту Фіралон",
    },
},

