[4432] = {
    en = "Sully Balloo's Letter",
    T  = "Лист Саллі Баллу",
    pages = {
        [1] = "Дун Модр із Болот$B$BМоя дорога Саро,$B$BУсе вказує на те, що вже за кілька днів ми вирушимо охороняти Тандольський міст. Бо, можливо, я більше не зможу написати тобі. Я відчуваю необхідність написати кілька рядків, які, можливо, потраплять тобі на очі, коли мене вже не стане.",
        [2] = "Наше завдання може тривати лише кілька днів і бути сповненим радості, а може виявитися суворим випробуванням, що загрожує мені смертю. Якщо доведеться загинути на полі бою за Альянс, я готовий.$B$BI не маю жодних сумнівів чи браку впевненості щодо справи, якій присвятив себе, і моя мужність не згасає й не хитається.",
        [3] = "Я знаю, наскільки сильно Королівство Айронфордж залежить від перемоги Альянсу, і наскільки великий борг ми маємо перед тими, хто пройшов перед нами крізь кров і страждання Великих воєн, і я готовий, цілком готовий пожертвувати всіма своїми радощами в цьому житті, аби допомогти зберегти цей Альянс і сплатити цей борг.",
        [4] = "Саро, моя любов до тебе безсмертна; вона, здається, сковує мене могутніми ланцюгами, які може розірвати лише Всемогутність, а моя любов до Царства накриває мене, немов сильний вітер, і непереборно несе мене разом з усіма цими ланцюгами на поле бою.",
        [5] = "Спогади про всі ті блаженні миті, які я провів із тобою, поволі наповнюють мене, і я відчуваю глибоку вдячність Світлу та тобі за те, що я так довго насолоджувався ними, і за те, як важко мені відмовитися від них та спалити на попіл надії на майбутні роки, коли ми ще могли б жити й кохати разом та бачити, як наші сини виростають у поважних карликівнавколо нас.",
        [6] = "Я знаю, що маю лише кілька незначних прохань до Божественного Провидіння, але щось шепоче мені — можливо, це молитва мого маленького Едгара, що долинула до мене, — що я повернуся до своїх близьких неушкодженим. Якщо ж цього не станеться, моя дорога Саро, ніколи не забувай, як сильно я тебе кохаю, і коли мій останній подих покине мене на полі бою, я прошепочу твоє ім’я.$B$BПробач мені мої численні провини та той біль, який я тобі заподіяв, — який же я був бездумний, який дурний я часто бував.",
        [7] = "Як би я хотів змити своїми сльозами кожну найменшу пляму на твоєму щасті та боротися з усіма нещастями цього світу, щоб захистити тебе й моїх дорогих дітей від лиха.$B$BАле я не можу.$B$BЯ мушу спостерігати за тобою з похмурої безодні й кружляти поруч, поки ти борешся з бурями, несучи свій дорогоцінний маленький вантаж, і з сумним терпінням чекати, поки ми зустрінемося, щоб більше не розлучатися.",
        [8] = "Але, о Саро, якщо померлі можуть повернутися до Азероту й непомітно кружляти поруч із тими, кого вони кохають, я завжди буду поруч із тобою — і в найрадісніший день, і в найтемнішу ніч, серед твоїх найщасливіших миттєвостей і найпохмуріших годин, завжди, завжди; і якщо на твої щоки повіє легкий вітерець — це буде мій подих, а коли прохолодне повітря обдує твою пульсуючу скроню — це буде мій дух, що пролітає повз.$B$BSара, не оплакуй моєї смерті, думай, що я пішов і чекаю на тебе, бо ми знову зустрінемося.$B$B—Саллі",
    },
},

