[5505] = {
    en = "Teronis' Journal",
    T  = "Щоденник Тероніса",
    pages = {
        [1] = "Я завів цей щоденник, щоб вести записи про свої зусилля, спрямовані на допомогу Ашенвейлу. Деякі події, що відбулися не так давно, оповиті таємницею, і, сподіваюся, мені вдасться розгадати хоча б частину з них, щоб допомогти своєму народу.$B$BПочну з того, що запишу факти, щоб вони не випали з пам’яті згодом.$B$BNещодавно я переконався у правдивості чуток про діяльність чарівника Дартола.",
        [2] = "Колись мені здавалося абсурдним, що людина могла б прибути на наші землі й опанувати наші звичаї, але цей чарівник, цей злий чоловік, приїхав сюди й не лише вижив, а й опанував частину наших знань. Я досі не впевнений, як...$B$BI під час мого розслідування так і не вдалося з'ясувати його цілі, але його план здавався простим: за допомогою магії друїдів він хотів подружитися з фурболгами, а потім підкорити їх. Чи це була спроба нашкодити моїм родичам, чи якась інша злісна мета — сподіваюся з'ясувати це, перш ніж мій шлях завершиться.",
        [3] = "У будь-якому разі, судячи з усього, йому вдалося хоча б частково втілити свої плани. Чи хотів він спочатку випробувати свої інтриги на фурболгах, перш ніж перейти до мого народу? Чи було у фурболгів щось, чого він прагнув? Хто знає?$B$BВикористовуючи створений ним предмет (якись жезл чи посох), він спробував проникнути до племен фурболгів у Попеліній долині. У якийсь момент — і саме тут багато деталей досі залишаються незрозумілими — фурболги виявили його, коли він намагався схилити їх до дій проти",
        [4] = "один одного. Як, без сумніву, і ельфи, фурболги розлютилися, але вони відреагували набагато різкіше і вбили Дартола.$B$BФурболги, принаймні на той час, ще не були тими зіпсованими істотами, якими стали згодом. Вони все ще були розсудливими й розумними — їхні стосунки з нашим народом були дружніми.$B$BЯ сподіваюся, що якщо мені вдасться відтворити жезл за допомогою дріади на ім’я Шаел’дрин, я зможу використати його силу, щоб допомогти нашому народу… і фурболгам.",
        [5] = "Не всі фурболи зазнали спотворення. Деякі з них досі живуть і намагаються захищати ліс. Під час спотворення частина фурболгів втекла, багато хто загинув, а інших вигнали з племен.$B$BЯ знайшов поважного фурболга з племені Фоулвелд, що мешкає над озером Містрал — його звати Кролг.$B$BI спостерігав за ним кілька днів і вважаю, що якби я підійшов до нього під виглядом фурболга, то міг би допомогти йому та знайти спосіб відновити зв’язок між нашими народами.",
        [6] = "Окрім вбивства Дартола, фурболги розбили жезл на три частини, щоб його більше не можна було використати проти них. Це було нелегко, але я маю гарне уявлення про те, де саме були розміщені всі три частини.$B$BСамоцвіт$BПерша частина жезла — сяючий самоцвіт — була захована у святилищі на північному заході Ашенвейлу. Я вважаю, що зараз ця святиня — це руїни в центрі озера Фалатім. Вартові кажуть мені, що зараз там мешкають мурлоки.",
        [7] = "Якщо я не зможу знайти самоцвіт, захований у святилищі, можливо, він опинився у володінні одного з мурлоків.$B$BЧастина стрижня$BЦю частину жезла було передано трентам поблизу того місця, яке зараз називається Фелвуд. Ні фурболги, ні мій народ не могли й уявити, що такі величні істоти колись піддадуться розтління, яке охопило цю землю.$B$BЗгідно з моїми дослідженнями, охоронці зберігали цей фрагмент у невеликій галявині, замкненому в скрині. Щоб дізнатися більше, мені доведеться поговорити з Шаел'дрином.",
        [8] = "Шаел'дрин — дріада, яка охороняє місячний колодязь на північний схід від озера Ірис. Вона відмовляється покинути ліс або залишити його на милість розтління. Я знаю, що вона має силу й знання, щоб відремонтувати жезл або, принаймні, підказати мені, як я можу це зробити самостійно.$B$BНаконечник$BНаконечник жезла було передано друїдам Дор’даніла. Однак є одна серйозна проблема: друїди мертві.$B$BЇхні духи тепер мешкають у цій місцевості й більше не є гостинними.",
        [9] = "Можливо, це потребує додаткового розслідування. Я не впевнений, чи маю я достатньо сили, щоб боротися з духами моїх померлих родичів... не кажучи вже про те, щоб заглибитися в глибини Дор’даніла й знайти рукоятку меча.$B$B(Примітка: Під час моїх приготувань в Астранаарі я нещодавно зустрів карликового мисливця, який провів чималу частину свого часу в Ешенвейлі, намагаючись допомогти моєму народу. Він приїхав із місця під назвою Штормовій.$B$BОдного вечора ми поспілкувалися за кількома кухлями елю, і його розповіді дали мені нову надію на те, що я знайду навершя...",
        [10] = "Він розповідає мені, що обійшов усю Дорданіл, але ніколи не бачив скрині чи будь-якої іншої ємності, в якій міг би зберігатися навершя. $B$BВін також каже, що в цій місцевості мешкають гнилі слизові істоти, які пожирають майже все, що менші за них. Він бачив, як вони «з’їдали» столи, скульптури, ведмедів і навіть гномів!$B$BСлайми, здається, отримують чимало поживних речовин із магічних предметів. Якщо скриня, в якій зберігався навершя, була хоч трохи зачарована, слайми, можливо, з’їли її.",
        [11] = "Це ризикований крок, але наразі у мене немає інших підказок...$B$BЯк тільки я дізнаюся більше, я опублікую тут подробиці; а до того часу я займуся пошуком частин жердини та допомогою Ашенвейлу.",
    },
},

[5520] = {
    en = "Velinde's Journal",
    T  = "Щоденник Велінде",
    pages = {
        [1] = "Елуна виконала мої бажання. Життя моїх полеглих товаришів не буде марним, і я помщуся за їхню смерть за допомогою Коси Елуни. Це стародавня річ — покручена й вузлувата гілка, яка, можливо, старша навіть за калдореїв. Багато годин я вивчав знаряддя, яке подарувала мені богиня. Це, безперечно, не звичайна зброя, і не простий магічний предмет. З нею... здається, ніби бар'єри часу й простору слабшають. Тримаючи Косу...",
        [2] = "У моїх руках з’явилося бачення хаосу. Люди-вовки… воргени… билися з неймовірним ворогом. Воргени билися запекло, як і личить їхній примітивній расі, але їхній ворог був непохитним: Володарі Смарагдового Полум’я. І саме тоді я усвідомив справжню силу Коси. Зосередившись на ній, я зміг налагодити зв’язок із воргенами. Однак для спілкування з ними я використовував не мову. Це було щось інше… Я не міг цього описати. Головне було те, що воргени почули",
        [3] = "і зрозуміла мене. Продовжуючи направляти енергію в Косу, бар’єри ще більше ослабли, і мені вдалося привести воргенів у наш світ. З першої ж спроби мені вдалося викликати двадцять п’ять воргенів. Вони пішли за мною в бій, і, маючи під своїм командуванням їхню брутальну силу, ми накинулися на демонів Фелвуда. Елуна виконала мої бажання. Ліс буде очищений. Нехай благословення Елуни супроводжують мене, доки моя справа не буде завершена.",
        [4] = "Усе йде добре. Я скликав чималу кількість воргенів, щоб вони билися разом зі мною. Хоча вони не надто кмітливі, вони продемонстрували вражаючу здатність координувати свої атаки та діяти злагоджено. Я визначив лідерів у їхніх зграях. Їм я доручив командування невеликими групами воїнів. Ми наносимо удари одночасно з багатьох місць у лісі, і моя кампанія проти демонів є плідною. Нехай благословення Елуни супроводжують мене, доки моя справа не буде завершена.",
        [5] = "Зникла зграя. Я відправив воргенів обстежити ліс і виявити місця, уражені демонами, але вони не повернулися. Я починаю турбуватися про ватажків, яким довірив управління. Вони недалекі, і ту невелику владу, яку я їм надав, вони розтягують до межі. Чи не втрачаю я контроль? Можливо, мені слід на якийсь час припинити прикликати нових воргенів. Нехай благословення Елуни супроводжують мене, доки моя справа не буде завершена.",
        [6] = "Хоча я й не викликав додаткових воргенів, їхня кількість продовжує зростати. Складається враження, ніби «Коса» більше не потребує мого втручання для процесу виклику. Це викликає занепокоєння. Я зібрав усі зграї, які зміг знайти, і наказав їм залишатися біля Святилища Мел’Тандріса. Тим часом я обшукав бібліотеки в Дарнасусі та проконсультувався з Колом Стародавніх у Темному Березі. Я не знайшов жодної інформації про цих воргенів. Я чув повідомлення,",
        [7] = "ходять чутки про чарівника з Кірін-Тор на ім’я Аругал. З того, що я чув, цілком можливо, що він також викликав воргенів. Я б порадився з цим чарівником — хоч як це мені й не до вподоби — і дізнався, що йому відомо. Воргени небезпечні, і я хочу зупинити їхнє насування. Завтра я вирушу до порту в Пустках і забронюю квиток до Нового Світу. Нехай благословення Елуни супроводжують мене, доки я не завершу свою справу.",
    },
},

[5535] = {
    en = "Compendium of the Fallen",
    T  = "Збірник померлих",
    pages = {
        [1] = "З огляду на успіхи Кел'Тузада в Лордаероні, Король Ліч завершив останні приготування до наступу на людську цивілізацію. Вклавши свою енергію чуми в низку переносних артефактів, званих «казанами чуми», Нер'жул наказав Кель'Тузаду перевезти ці казани до Лордаерону, де їх мали сховати в різних селах, контрольованих культом.",
        [2] = "Котли, охоронювані відданими культистами, мали стати джерелами чуми, розносячи її по нічого не підозрюючих сільських місцевостях і містах північного Лордаерону. План Короля Ліча спрацював бездоганно. Багато північних сіл Лордаерона були заражені майже миттєво. Так само, як і в Нортренді, мешканці, які заразилися чумою, помирали й воскресали як покірні раби Короля Ліча.",
        [3] = "Послідовники Кель'Тузада прагнули померти, щоб потім воскреснути на службу своєму темному володареві. Вони раділи перспективі безсмертя через нежить. У міру поширення чуми на північних землях з'являлося дедалі більше диких зомбі. Кел'Тузад, споглядаючи на зростаючу армію Короля Ліча, назвав її «Покаранням» — адже незабаром вона рушить до воріт Лордаерона... і винищить людство з лиця землі.",
    },
},

[5536] = {
    en = "Mythology of the Titans",
    T  = "Міфологія титанів",
    pages = {
        [1] = "Ніхто точно не знає, як виник Всесвіт. Одні висувають гіпотезу, що катастрофічний космічний вибух розкидав нескінченні світи у безмежну Велику Темряву — світи, які одного дня стануть домівкою для форм життя дивовижної й жахливої різноманітності. Інші вважають, що Всесвіт у його нинішньому вигляді був створений як єдине ціле єдиною, всемогутньою істотою.",
        [2] = "Хоча точне походження хаотичного Всесвіту залишається нез’ясованим, очевидно, що з’явилася раса могутніх істот, покликана навести лад у різних світах і забезпечити безпечне майбутнє для тих, хто піде їхніми слідами. Титани — колосальні боги з металевою шкірою, що прибули з далеких куточків космосу, — вийшли на сцену і взялися за роботу над світами, які траплялися їм на шляху. Вони формували обриси своїх світів, піднімаючи могутні гори та вириваючи безкрайні моря.",
        [3] = "Вони породили небеса та бурхливі атмосфери — все це було частиною їхнього незбагненного, далекоглядного плану щодо встановлення порядку з хаосу. Вони навіть наділили первісні раси повноваженнями, щоб ті дбали про їхні творіння та підтримували цілісність своїх світів. Титани, якими керувала елітна секта, відома як Пантеон, у перші століття творіння навели лад у ста мільйонах світів, розкиданих по всій Великій Темній Далечі.",
        [4] = "Доброзичливий Пантеон, прагнучи захистити свої впорядковані світи, завжди пильно стежив за загрозою нападу з боку підлих позавимірних істот із «Крученого Нетера». Нетер — ефірний вимір хаотичної магії, що з'єднував між собою незліченні світи Всесвіту, — був притулком для нескінченної кількості злісних, демонічних істот, які прагнули лише знищити життя та поглинути енергію живого Всесвіту.",
    },
},

[5594] = {
    en = "Letter to Jin'Zil",
    T  = "Лист до Джин'Зіла",
    pages = {
        [1] = "Джин'Зіл,$B$BДавно не бачилися, але я подумав, що тобі буде цікаво дізнатися, що останніх представників роду «Криваве Перо» було вбито. Тільки не дякуй мені — вбивця — це та людина, яка доставляє цей лист. Якщо хочеш, я можу наказати доставити тобі її голову після того, як караван проїде через Пустощі. Я знаю, що тобі подобаються такі речі для твоїх вуду-чарів.$B$BБережи себе, старий друже.$B$B$B—Дарсок Швидкий Кинджал",
    },
},

[5628] = {
    en = "Zamah's Note",
    T  = "Примітка Замаха",
    pages = {
        [1] = "Аптекар Лайдон, сподіваюся, цей лист швидко дійде до вас, а його носій — у доброму стані. У далекому Калімдорі виникла потреба, для вирішення якої, як я вважаю, знадобляться ваші вміння. Буду коротким. У Горах Кам’яного Кігтя, неподалік від Мулгора — батьківщини наших союзників-тауренів, — розгортається криза.  Керована гоблінами компанія «Венчур» веде інтенсивну гірничодобувну та лісозаготівельну діяльність у цих горах, розлючуючи гірських духів.",
        [2] = "Я мушу припустити, що галас, який ці духи піднімають через канали під егідою шаманів і друїдів тауренів, відволікає їхню увагу.  Адже таурени вважають «Компанію «Венчур» у Горах Кам’яного Копита» серйозною загрозою. Загроза це чи ні, ми мусимо допомогти нашим союзникам. Лайдоне, ти маєш глибокі знання про отрути. Чи зможеш ти створити таку, яку ми могли б використати для поширення епідемії серед гоблінів у Кам’яному Копиті? З повагою, П. Замах",
    },
},

[5737] = {
    en = "Covert Ops Plans: Alpha & Beta",
    T  = "Плани таємних операцій: «Альфа» та «Бета»",
    pages = {
        [1] = "Гаразд, у вас мають бути готові заряди NG-5 та детонатори. Я їх для вас позначив… Синій — для лісопилки. Червоні — для шахти «Віндшир».$B$BЯ провів розвідку, і в усьому районі Віндшир-Крег вистачить вибухівки, тож вам не складе жодних проблем проникнути туди, встановити заряди, а потім вибратися звідти до їх підриву.$B$BПам’ятайте, це відволікаючий маневр. Відійдіть подалі від возів, перш ніж гобліни прибіжать перевірити, що сталося, а потім прокрадіться за їхніми спинами.",
        [2] = "До речі, будьте з ними обережні. Один лише нітроміргліцероній може перетворити вас на пил. Я помістив частину рідини в мідні трубки, що має забезпечити її стабільність і безпеку.$B$BСвиток, який ви отримали від Коліна, я використав для детонаторних блоків. Тепер, після того як ви їх встановите, вони надсилатимуть безшумний сигнал до зарядів NG-5. Я використав простий механізм «Сталтваргон», щоб забезпечити оптимальну провідність дроту та кращий, ніж у середньому, потік нітрогліцеронію між диференціальною рідиною.",
        [3] = "Перш ніж перейти до деталей мого плану, дозвольте пояснити, де саме слід розмістити вибухівку.$B$BPлан «Альфа» — лісопильня:$BПеред лісопильнею стоїть візок (це на північний схід від їхньої споруди для вирубки лісу та збору деревини). Я підозрюю, що інженерні креслення знаходяться всередині лісопилки.$B$BЩоб встановити заряд, підійдіть до задньої частини воза. Як тільки заряд буде встановлено, поспішіть відійти на безпечну відстань.",
        [4] = "Коли будете готові, натисніть на детонатор.$B$BЯ забезпечив потужний сигнал, проклавши мідні та срібні дроти разом із масивом антен Мелтуса всередині корпусу коробки. Це має забезпечити вам хороший радіус дії. Тільки будьте обережні з гоблінами поблизу. Вони не оцінять моє творіння, якщо помітять вас у полі зору.$B$BО, і на всяк випадок, якщо це не було очевидно, не стойте поруч із возом, коли він вибухне... це буде боляче.",
        [5] = "План «Бета» — Шахта «Віндшир»:$B$BЯ бачив, як гобліни використовували ще один візок з вибухівкою на північ від входу в шахту. Гадаю, це має бути досить вдале місце для встановлення заряду NG-5 (червоного). Після того як ви встановите заряд у задній частині воза, відійдіть на деяку відстань і натисніть кнопку.$B$BЯкщо гобліни не прибіжать перевірити, що сталося, то, ймовірно, це тому, що гора обвалилася їм прямо на голови.",
        [6] = "Листи від «The Venture Co.» знаходяться за межами шахти... Гадаю, на якихось ящиках на нижньому рівні.$B$BУдачі, і пам’ятайте...$B$BСиній заряд: лісопильня$BЧервоний заряд: шахта$B$BА, і знищіть цей лист після виконання місії. Хм, може, мені варто подумати над тим, як зробити так, щоб ці листи самознищувалися після прочитання. Непогана ідея...",
    },
},

[5790] = {
    en = "Lonebrow's Journal",
    T  = "Щоденник Lonebrow",
    pages = {
        [1] = "--День перший--$B$BМоя подорож з Айронфорджа нарешті привела мене до Калімдору!$B$BЗолотошукач Хазгорм із Бел-Модана досягає значних успіхів. Сьогодні він виявив скам’янілість, яку місцеві вчені вважають фрагментом кістки стародавнього бога. Хазгорм переконаний, що ця скам’янілість є частиною великої таємниці. Поки він керує розкопками, він доручив мені знайти більше скам’янілостей, щоб скласти повну картину подій. $B$BМоє завдання: вирушити на південь у пошуках нових підказок.",
        [2] = "--Другий день--$B$BЗемлі Барренс безмежні й розлогі. Моя подорож була довгою й виснажливою, і поки що не принесла нічого цікавого для архівів Ліги Дослідників. $B$BЄдиний випадок, вартий уваги, стався поблизу «золотої дороги». Вдалині я помітив дивних істот. Здавалося, вони були наполовину свинями, наполовину людьми. Я швидко сховався й дав цим огидним тварюкам пройти. Боже, який огидний сморід вони залишили після себе!",
        [3] = "--Третій день--$B$BO, яке величне й дивовижне відкриття!$B$BСьогодні під час досліджень я натрапив на грандіозну знахідку: величезні останки істоти, схожої на кабана. Її череп височів на кілька довжин вище за мене. Кожен зуб цієї тварини міг би затьмарити навіть... ну, навіть карлика. З огляду на величезні розміри знахідки, я схильний вважати, що це останки одного з тих Старих Богів, про яких ходять чутки.",
        [4] = "Якось давно, у штаб-квартирі Ліги Дослідників в Айронфорзі, я пригадую лекцію, яку читав головний археолог Грейвіскер. Старий згадав про такого бога, якого шанували дивні ельфи Дарнассуса через його, як кажуть, альтруїстичну природу — $B$BBах! Хвилинку. Я чую хрюкання за межами намету. Напевно, це просто якісь чортополохові кабани, що намагаються дістатися до мого запасу яблук...",
        [5] = "--4-й день--$B$BЗахоплений!$B$BТреба... написати... швидко. $B$BНа мене напали люди-кабани з племені Разорфен. Я думав, що вони ведуть мене до величезних останків кабана — поваленого бога. Натомість вони обійшли великі скам’янілості й попрямували прямо на захід від гігантського черепа, через Золоту дорогу.",
        [6] = "Мене грубо затягли всередину смердючого, зарослого колючками чагарнику під назвою Разорфен Краул. Мене закинули в грубо збиту хатину й утримували в полоні разом із вмираючим нічним ельфом.$B$BУ мене з собою немає нічого, крім цього щоденника, пера та кишенькового годинника... $B$BХтось наближається...",
        [7] = "--5-й день--$B$BMій сусід по камері, нічний ельф, отримав тяжкі поранення. Люди-кабани неодноразово били його батогом, і я вважаю, що він незабаром загине, якщо тільки якимось дивом рятувальна група не наважиться пробратися крізь це підступне місце. Він то втрачає, то відновлює свідомість. Коли він прокидається, я намагаюся дати йому ту невелику кількість води, що в мене є.",
        [8] = "Вчора ввечері він вперше зміг заговорити. Це друїд на ім’я Гералат, якого відправили сюди, щоб перевірити чутки про полеглого бога-кабана. $B$BСлабким голосом він розповів мені, що, на його думку, череп великого вепра — це місце, де великий бог-кабан Агамагган загинув у бою з Палким Легіоном близько 10 000 років тому під час Війни Древніх. Його масивне тіло розплющило землю, а його кров просочилася в ґрунт. Там, де пролилася його кров, ростуть покручені шпилі з колючок...",
        [9] = "Гералат і його люди прагнуть виявити джерело розтління на цій місцевості. Він розповів мені, що Агамагган вважався чистим богом. Чому ці огидні істоти та злоякісні колючки спотворюють цю землю — це справді загадка.$B$BНе встиг я ще наполягти на додатковій інформації, як Гералат знову занурився в неспокійний сон...",
        [10] = "--6-й день--$B$Стан Гералата погіршується.$B$BСьогодні він розплющив очі лише раз. Він говорив з болісним стражданням, але його повідомлення було чітким. Якщо мені вдасться врятуватися від неминучої загибелі тут, у Разорфен-Краулі, треба повідомити Фальфінделу Вейвардеру в Таланаарі, що Чарлга Разорфланк збирає поплічників у південних Барренах. Її сила зростає з кожним днем. Стару потрібно зупинити, перш ніж чума розтління пошириться з Краула.",
        [11] = "Бідний Гералат зблід, як кістка. Його лихоманка з кожною хвилиною посилюється. А тим часом люди-кабани готуються до якоїсь великої військової операції. Боюся, що якщо я не спробую втекти найближчим часом, мене чекає доля, подібна до долі мого ельфійського сусіда по камері. $B$BМій план — вислизнути, коли люди-кабани вирушать на чергове полювання. Мої охоронці ліниві й часто просинають свої зміни.",
        [12] = "Як тільки я звільнюся від Краула, я вирушу до Тисячі Голків, а потім на захід — до Таланаара, що на кордоні таємничого лісу Фералас. Там я шукатиму друїда на ім’я Фальфіндель Вейвордер.$B$BТе, що почалося як спроба дослідити минуле мого народу, перетворилося на щось набагато масштабніше. Доля Альянсу лежить у моїх руках....",
    },
},

