[5807] = {
    en = "Fool's Stout Report",
    T  = "Звіт «Fool's Stout»",
    pages = {
        [1] = "Пане Фізлбаб, напій, який ви подарували моєму партнеру, мав величезний успіх. Він не тільки міцний і значно притуплює розум, але, здається, ще й викликає залежність. Я впевнений, що ті, хто його скуштував, будуть прагнути ще. Ми у боргу перед вами, Кранк. І я запрошую вас приїхати до «Шіммерінг Флетс» або надіслати свого довіреного представника, щоб скористатися новими можливостями для азартних ігор, які ми тут пропонуємо. — Кравел",
    },
},

[5826] = {
    en = "Kravel's Scheme",
    T  = "Схема Кравеля",
    pages = {
        [1] = "Пане Фізлбаб,$B$BЯ разом із носієм цього листа розробляємо бізнес-проект, до якого ми запрошуємо вас долучитися.  $B$BЯк вам відомо, я проводжу значну частину свого часу на Мерехтливих рівнинах — згаданий бізнес-проект пов’язаний саме з перегонами на цих рівнинах.$B$BЯкщо вас цікавлять перегони, а точніше — ставки на перегони, то, будь ласка, читайте далі, адже я вважаю, що ваші знання про Странглторн стануть у нагоді в нашому проекті.",
        [2] = "Ракетоподібні автомобілі, що беруть участь у гонках на рівнинах, мають надзвичайно досконалу настройку і вимагають ретельного технічного обслуговування.  Тож не дивно, що бригади піт-стопів постійно перебувають на місці подій.  $B$BЦі бригади постійно тестують автомобілі та за потреби вносять виправлення й модифікації.  Це єдиний спосіб підтримувати автомобілі в стані максимальної працездатності.$B$BОтже... ми шукаємо спосіб змусити одну з піт-команд допустити помилку в роботі, оскільки будь-яка така помилка призведе до того, що автомобіль цієї команди швидко прийде в непридатність.",
        [3] = "Якщо ми зможемо контролювати, яка машина в ідеальному стані, а яка — ні, то... Мені не треба тобі пояснювати, яку перевагу це нам дає в азартних іграх.$B$BОтже, добрий Фізлбаб, нам потрібні засоби, за допомогою яких ми зможемо змусити піт-екіпажі припуститися помилки.$B$BЧи є у Стренглторні якась рослина, трава чи напій, які ми могли б використати, щоб затуманити розум гномів і гоблінів?$B$B—К. Коалбеард",
    },
},

[5827] = {
    en = "Fizzle Brassbolts' Letter",
    T  = "Лист від Фіззла Брассболтса",
    pages = {
        [1] = "Привіт, Мартек, я в скрутному становищі і мені потрібна твоя допомога. Ми з братом будуємо гоночний автомобіль, і нам потрібні міцні поршні.  Ніщо з того, що я пробую, не виявляється достатньо міцним.  Ніщо не витримує швидкості нашого нового автомобіля.  І тому двигун постійно ламається! Ти ж експерт у роботі з металом.  Ти мусиш допомогти.  Ти єдиний, хто може це зробити.",
        [2] = "Ось технічні характеристики поршня: Довжина: 32 WW Ширина: 12 WW Вага: від 23,5 IBG до 25,5 IBG Теплопровідність: 70 TC Міцність на зсув: 98 або вище Рейтинг комбобуля: «суперміцний» або вище На випадок, якщо ви забули гномські одиниці виміру: WW = «ширина вуса» IGB = «крихітні грами» (Itty-Bitty Grams) TC = «згинання пальців» (Toe Curls)",
    },
},

