    pages = {
        [1] = "Щоб зіткнутися з Фростмоу, вам потрібно привабити його м’ясом його улюбленої здобичі.$B$BВідправляйтеся в гори Альтерак в Азероті та вполюйте величезного гірського пуму.  Вбийте його, а потім віднесіть тушу до Печери Гроулес — місця, яке звіроподібні вендіго вважають священним.$B$BПокладіть тушу на Полум'я Узеля, і запах палаючого м'яса пошириться з печери.$B$BІ тоді, з часом, з'явиться Фростмоу.",
