[5839] = {
    en = "Journal Page",
    T  = "Сторінка журналу",
    pages = {
        [1] = "Мене ніколи не перестає дивувати, як легко ненависть можна використати, щоб підкорити людей своїй волі. З орками та тролями було найпростіше: їхня ненависть до Альянсу зробила їх охочими підданими, готовими прислухатися до послання «Темної Нитки». Чи мають вони хоч якесь уявлення про ту велику силу, якій служать? Той дратівливий паладин, Делгрен Очисник, втручається в наші справи в Лісі Ешенвейл, а його лакей, Балтуле, шпигує за моєю вежею, думаючи, що я не знаю про його присутність. Делгрен вважає нас незначними",
        [2] = "загроза, можливо, просто ще один культ смерті. Він навіть не підозрює, що ми — лише одна з… гілок Ради Тіней. У дитинстві мені колись розповідали про комаху, укус якої міг легко вбити, хоча зовні вона виглядала не більше ніж муха, цятка, яку ледь можна було помітити. Саме ті речі, які ти ігноруєш, завдадуть тобі найбільшої шкоди, якщо їх залишити гнити.",
    },
},

[5860] = {
    en = "Legacy of the Aspects",
    T  = "Спадщина Аспектів",
    pages = {
        [1] = "Я провів величезну роботу з дослідження Аспектів та їхніх творців-титанів — стільки, скільки тільки може зробити людина за все своє життя. Коли титани покинули цей світ, існувало п’ять Аспектів; це були могутні дракони, яким було доручено захищати світ Азерота. Історії про них безмежні й різноманітні, і навіть зараз, попри всю інформацію, яку я зібрав, я розумію, що про цих величних істот ще багато чого належить дізнатися.",
        [2] = "Більшу частину тих знань, якими я володію зараз, я нізащо не зміг би здобути самостійно. Тому я надзвичайно вдячний нічним ельфам. Лише завдяки їхній допомозі я маю стільки деталей, скільки маю. В результаті наших зустрічей у мене склалося враження, що їхні витоки набагато тісніше пов’язані з Аспектами, ніж я спочатку думав. Однак вони настільки ретельно оберігають свої таємниці, що навіть я не можу знати цього напевно.",
        [3] = "Інформацію про Аспекти, яку я дізнався, я розміщую тут, щоб інші могли скористатися нею в майбутньому. Я впевнений, що вона виявиться корисною, оскільки відчуваю, що з плином часу ці дракони матимуть набагато більший вплив на наш світ.",
        [4] = "Алексстраза: Алексстраза, древня й могутня Королева Драконів, отримала від титанів ім’я «Ті, хто пов’язує життя». Вона була першою, кого створили титани для захисту світу після того, як вони пішли. Кажуть, що вона була свідком народження всіх сучасних рас на землі Азерота. Її червоний драконячий полк, відомий своєю гордою поведінкою, колись панував над усіма іншими драконами.",
        [5] = "Серед нічних ельфів ходять чутки, що Алексстраза та напівбог Сенаріус були близькими друзями і що саме він покликав її під час першого вторгнення Палаючого Легіону.",
        [6] = "Ісера: Ісера Мрійниця уособлює підсвідомість смертних. Вона є втіленням Смарагдової Мрії. Хоча вона цінує уяву та творчість і схвалює амбіції смертних рас, вона та її драконячий полк вважають реальний світ лише ілюзією. Ісера — одна з найвитонченіших і наймогутніших істот, яких тільки може побачити смертний.",
        [7] = "Малігос: Малігос відомий як «Хранитель магії» або «Ткач заклинань». Його природна форма не схожа на типового дракона, і кажуть, що він може змінювати її за власним бажанням. Після відходу на далеку північ його рідко бачать, і він майже завжди перебуває у вигляді істоти, схожої на комаху, але в драконячій формі він та його драконячий зграя мають різні відтінки синього кольору.",
        [8] = "Ноздорму: Ноздорму відомий як Володар Часу та Позачасовий. Він і його драконячий полк мають бронзовий колір і виявляють велику хитрість у всьому. Увага Ноздорму завжди була зосереджена на зборі артефактів минулого, оскільки він мало переймається поточними справами смертних рас чи навіть діями своїх колег-Аспектів. Однак його байдужість до політики інших не означає, що він спокійно ставиться до подій, які відбуваються у світі.",
        [9] = "Бронзовий драконячий полк, який вважається захисниками, відчуває сильний потяг до областей цивілізації. Дракон та його полк за своєю природою дуже терплячі, завжди покладаються на спостереження та діють за заздалегідь розробленим планом, не поспішаючи. Ноздорму завжди намагатиметься захистити потік часу та смертні раси, коли їм загрожують сильніші вороги.",
        [10] = "Нелтаріон: Нелтаріон, якого після створення називали «Хранителем Землі», був більш відданим Азероту й дбайливо ставився до нього, ніж будь-який інший Аспект. Його чорний драконячий полк був відповідальним за створення гір та інших ландшафтних утворень, включаючи кордони між смертними расами. Що саме спричинило його спотворення, досі залишається загадкою: чи то зовнішній вплив, чи щось, що роз’їдало його зсередини. Цікаво, чи, можливо, Старі Боги не причетні до спотворення Великого Чорного.",
        [11] = "Чорний дракон зазнав повного перетворення",
    },
},

[5861] = {
    en = "Beginnings of the Undead Threat",
    T  = "Початок загрози з боку нежиті",
    pages = {
        [1] = "Історія нежиті в Азероті насправді почалася не з того, як принц Артас піддався спокусі — вона почалася задовго до цієї події. Події, що призвели до падіння Лордаерона, були запущені ще задовго до того; все почалося з приходу кланів орків та Палаючого Легіону.",
        [2] = "Орки Дренора (світу, звідки вони походили) були благородними і сповідували шаманізм. Вони були могутніми воїнами, сильними тілом і волею. Саме з цих причин «Палаюча Легіон» звернула на них свою увагу. Кіл'яеден, один із наймогутніших демонів Легіону, прагнув поневолити клани орків і використати їх як свою армію проти світів, які «Палаюча Легіон» ще не підкорила.",
        [3] = "Кіл'яеден звернувся до вождя кланів — могутнього шамана на ім'я Нер'жул. Він пообіцяв Нер'жулу незліченні містичні сили та знання, якщо той укладе угоду з демоном, яка зведе клани в рабство до Палаючого Легіону. Ця угода назавжди визначила не лише їхню долю, а й долю їхнього світу.",
        [4] = "З плином часу Нер'жул усвідомив, яка доля чекає на клани з боку Палаючого Легіону, і шаман орків почав чинити опір Кіл'ядену. Демон, розлючений поведінкою Нер'жула, звернувся до власного учня шамана — Гул'дана, який виявився набагато більш схильним до спокуси, ніж Нер'жул.",
        [5] = "Саме Гул'дан був винуватцем занепаду шаманізму серед кланів. Обіцянка влади та контролю над ворогами робила його пропозиції ще більш привабливими. За допомогою Кіл'яедена Гул'дан розпочав маніпулювати кланами. Орки, колись благородні, перетворилися на зіпсованих, бездумних дикунів. З введенням демонічної крові в їхні тіла орки стали ще більш безжалісними та варварськими.",
        [6] = "Хоча Кіл'яеден і спокусив Гул'дана після його провалу з Нер'жулом, він ненавидів шамана і пообіцяв домогтися виконання їхнього первісного пакту. Кіл'яеден захопив Нер'жула і розпочав неймовірно повільні фізичні тортури над шаманом. Поки Нер'жул благав про смерть, Кіл'яеден нагадав йому, що їхній первісний пакт досі залишається чинним. Кіл'яеден вбив орка, але лише фізично. Кіл'яеден міцно утримав дух орка-шамана, не давши йому дістатися до Викривленого Ефіру.",
        [7] = "Кіл'яеден помістив дух Нер'жула в крижаний брусок, взятий із Викрученого Потойбіччя. Поки дух був ув'язнений у льоді, він наповнив його ще більшою силою. Втрата тіла та набуття такої неймовірної сили стали вирішальним моментом у перетворенні Нер'жула.",
        [8] = "Кіл'яеден кинув крижаний блок крізь виміри назад до Азероту, де той впав на континенті Нортренд, принісши це велике зло у наш світ. Нер'жул зник назавжди; на його місці залишився трон із льоду та ненависті. Колись шанований вождь шаманів перетворився на неймовірно могутнього Короля Ліча.",
        [9] = "Оскільки Кіл'яеден не довіряв Королю Лічу, він відправив своїх жахливих лордів, щоб ті стежили за духом і гарантували, що Король Ліч виконуватиме його накази. Ці вампірські слуги прибули до Азероту добровільно, приваблені руйнуванням і силою Короля Ліча, а також можливістю геноциду цілої раси на планеті.",
        [10] = "Минуло понад десятиліття. За цей час Король Ліч використовував свої величезні сили, щоб підкорити розуми істот Нортренда, яким він наказав звести величну цитадель над своїм замерзлим троном. Тепер, коли весь Нортренд опинився під його пануванням, Король Ліч усвідомив, що йому потрібно розпочати проникнення в Лордаерон. Замкнений у льоді, колишній шаман орків почав шукати нові уми, якими міг би маніпулювати та керувати. Його заклик пролунав по всіх континентах.",
        [11] = "Заклик Короля Ліча не залишився непоміченим, особливо для невеликої групи впливових осіб. Серед них був архімаг Кел’Тузад, який був впливовим членом керівного органу Даларана — Кірін-Тор. Його захоплення всіма видами магії суперечило політиці Кірін-Тор, що забороняла вивчення темної магії. Кел'Тузад покинув Кірін-Тор і відмовився від усіх зв'язків із традиційним мисленням, пообіцявши навчитися у Короля Ліча якомога більше.",
        [12] = "Між ними було укладено угоду. Кел’Тузад мав отримати безсмертя та величезну силу в обмін на служіння Королю Лічу. Першим завданням Кел’Тузада було використати свої багатства та вплив у Лордаероні для заснування «Культу Проклятих». Культ обіцяв рівність і вічне життя всім своїм членам, якщо вони присягнуть на вірність Нер'жулу, богу «Культу Проклятих».",
        [13] = "Потім Нер'жул створив артефакти, призначені для поширення чуми серед людських цивілізацій Лордаерона. Він передав їх Кель'Тузаду і наказав чарівнику розповсюдити їх по всій країні. Послідовники його культу мали захищати артефакти за будь-яку ціну.",
        [14] = "Опинившись на місці, чума почала проникати в країну й вражати її необізнаних мешканців. На очах у Кел’Тузада армія Короля Ліча швидко зростала, і незабаром він здобув контроль над значними територіями. Ця армія стала відомою як «Покарання», адже її єдиною метою було знищити людство на всій території Азерота.",
    },
},

[5882] = {
    en = "Captain's Documents",
    T  = "Документи капітана",
    pages = {
        [1] = "--13-й день. Рух військ поблизу Терамора посилився.  Велика кількість людей покинула місто й поспіхом рухається на захід. --14-й день. З міста виходить ще більше військ.  Я прослідкував за невеликою групою й побачив, як вони зняли форму, щойно опинилися поза межами досяжності стріл Терамора.  Можливо, це дезертири? --15-й день. Сьогодні я підслухав розмову деяких солдатів з Терамора про те, що вартові покидають свої пости.  Мої підозри щодо дезертирів, мабуть, виправдані",
        [2] = "--16-й день$B$BУлег і Таргіл повернулися з місії до доків Терамора.  У порту вони побачили новий корабель: «Кривавий Горобчик».  Корабель прибув із гавані Менетіл в Азероті.$B$B$BЗавтра Улег і Таргіл повернуться до доків і проникнуть на борт корабля.  Вони сподіваються знайти політичні документи, які розкриють відносини між Терамором та Альянсом.",
        [3] = "--17-й день. Улег повернувся з місії.  Йому не вдалося виконати завдання, і Таргіла взяли в полон.  Я відправив Улега передати цей звіт Назіру. Я залишуся тут.  Я помітив посилення судноплавства біля узбережжя Терамора.  Я продовжуватиму спостереження та особисто повідомлятиму про будь-які важливі події.",
    },
},

[5897] = {
    en = "Snufflenose Owner's Manual",
    T  = "Інструкція з експлуатації Snufflenose",
    pages = {
        [1] = "ВІТАЄМО!$B$BВи стали щасливим новим власником дивовижного гофера з плоским носом!  Хоча це сором’язлива тваринка, ми впевнені, що пухнаста милість та неймовірні нюхові здібності вашого нового улюбленця підкорять ваше серце.$B$BНа наступних сторінках ви знайдете інформацію про:$B$B1. Годування та догляд$B2. Ексцентричну (і чарівну) поведінку$B3. Використання запатентованої палички для команд «Снуффленоз» (Snufflenose Command Stick™)$B$BЩе раз вітаємо.  Ви не будете розчаровані,$B$B—Марвіг Растболт$BВласник компанії «Snuff Inc.»",
        [2] = "ХАРЧУВАННЯ ТА ДОГЛЯД:$B$BМи прагнемо забезпечити вас усім необхідним для догляду за вашим улюбленцем.  Наші клієнти вже звикли очікувати такого рівня обслуговування від компанії Snuff Inc, і ми повністю з ними згодні!$B$BЗ цією метою ми розробили міцні клітки для гоферів з невеликими отворами, які ідеально підходять для того, щоб забезпечити вашому улюбленцю безпеку, захист та захист від світла.$B$BДля вашої зручності всередині кожної клітки є ємність для кормових гранул, просочена привабливим ароматом бульб блакитного листя (улюбленого ласоща гофера-снуффленоза)!",
        [3] = "ПРОГУЛЯНКА З ГОФЕРОМ$B$BГофер-рильцелюб любить маленькі темні місця.  І він дуже боязкий.$B$BЯкщо ви хочете прогулятися з гофером, то повинні відвести його туди, де він почуватиметься як вдома.  І ви ОБОВ'ЯЗКОВО повинні відвести його туди, де він зможе відчути запах своєї улюбленої їжі: бульб блакитного листя!$B$BNайближче таке місце — це район «траншеї» в Разорфен-Краулі.  Якщо ви відкриєте ящик біля траншеї, і ваш суслик відчує запах бульб поблизу, він вилізе з ящика й піде за вами.",
        [4] = "КОМАНДНА ПАЛИЦЯ «СНУФФЛЕНОЗ» (tm)$B$BСуслик-снуффленоз — дивовижна тварина.  Вона не тільки викликає любов і прихильність навіть у найсуворішого мешканця рівнин, але й здатна відчути запах закопаного бульби синьолистого рослини на відстані до п’ятдесяти ярдів!$B$BЯкщо ви хочете відправити свого суслика на пошуки бульби, то можете скористатися нашою запатентованою палицею для управління сусликом «Snufflenose» (продається окремо).  $B$BІнструкції — на наступній сторінці...",
        [5] = "Усі наші суслики чудово навчені, і вам достатньо лише помахати командним жезлом, щоб найближчий суслик перейшов у «режим пошуку». Після цього суслик почне нюхати, шукаючи бульбу, і, якщо він її відчує, рушить до неї та викопає її.$B$BЯкщо ви знову помахаєте командною паличкою, поки суслик шукає бульбу, він припинить пошуки та радісно повернеться до вас.$B$BМи впевнені, що ви визнаєте наших сусликів добре навченими, корисними та неймовірно м’якими на дотик учасниками вашої вечірки!",
        [6] = "Нам прикро повідомляти, що компанія Snuff Inc. отримала повідомлення про те, що деякі жадібні мисливці за бульбами не дбають про безпеку своїх милих улюбленців і відправляють їх у темні та небезпечні закутки в пошуках бульб.$B$BМи не схвалюємо таку безвідповідальну поведінку, але, прагнучи забезпечити задоволеність клієнтів, ми додаємо гарантію до кожного проданого суслика, що дозволяє новим власникам повернутися до місця покупки та замінити втрачених улюбленців.$B$BВдалого полювання!",
    },
},

[5917] = {
    en = "Spy's Report",
    T  = "Звіт шпигуна",
    pages = {
        [1] = "--13-й день$B$BПоблизу Терамора посилився рух військ.  Велика кількість людей покинула місто й поспіхом рухається на захід.$B$B$B--14-й день$B$BЗ міста виходить все більше військ.  Я прослідкував за невеликою групою і побачив, як вони зняли форму, щойно опинилися поза межами досяжності стріл з Терамора.  Можливо, це дезертири?$B$B$B--15-й день$B$BСьогодні я підслухав розмову деяких солдатів з Терамора про те, що вартові покидають свої пости.  Мої підозри щодо дезертирів, мабуть, виправдані",
        [2] = "--16-й день$B$BУлег і Таргіл повернулися з місії до доків Терамора.  У порту вони побачили новий корабель: «Кривавий Горобчик».  Корабель прибув із гавані Менетіл в Азероті.$B$B$BЗавтра Улег і Таргіл повернуться до доків і проникнуть на борт корабля.  Вони сподіваються знайти політичні документи, які розкриють відносини між Терамором та Альянсом.",
        [3] = "--17-й день. Улег повернувся з місії.  Йому не вдалося виконати завдання, і Таргіл потрапив у полон.  Я відправив Улега передати цей звіт Назіру. Я залишуся тут.  Я помітив посилення судноплавної активності біля узбережжя Терамора.  Я продовжуватиму спостереження та особисто повідомлятиму про будь-які важливі події.",
    },
},

[5947] = {
    en = "Defias Docket",
    T  = "Справа Дефіаса",
    pages = {
        [1] = "Наш перший план уже провалився! Фісту вдалося змінити графік чергування охоронців у тунелі на той вечір, але через непередбачені дії деяких мешканців Штормовію наша ціль встигла втекти з місця події, перш ніж ми змогли його захопити. Проте ми передбачили такі непередбачені обставини. План № 2 було запущено, і він уже був у повному розпалі, коли в Штормовії спрацювала наша засідка.",
        [2] = "План № 2 настільки ж простий, але вимагатиме від нас більше терпіння. Нашому інформатору в Менетілі вже заплатили за його зусилля, і він блискуче впорався із завданням. У нас не повинно виникнути жодних проблем із тим, щоб знайти нашу ціль і захопити її, щойно ми відпливемо.",
        [3] = "Очікуйте, що атака відбудеться за кілька миль від місця призначення. Саме там наші «союзники» будуть чекати в засідці. Я не впевнений, чому нас змусили укласти союз із цими істотами, але не можу позбутися відчуття, що нас самих примушують до цього. Зрештою, це не матиме значення. З ціллю під нашим контролем ми будемо на шляху до того, щоб повернути Штормовій у наших рук від тих, хто його в нас вкрав!",
    },
},

[5948] = {
    en = "Letter to Jorgen",
    T  = "Лист до Йоргена",
    pages = {
        [1] = "Йорген,$B$BМої побоювання справдилися, і вони вчинили так, як я ніколи не вважав за можливе. Я ніколи не думав, що вони підійдуть так близько, але вони це зробили.$B$BБудь ласка, допоможіть тому, хто приніс цю записку, і надішліть її ЙОМУ. Чесно кажучи, я думаю, що він нам допоможе, зважаючи на серйозність цієї справи. Якби це була будь-яка інша загроза, він, мабуть, і далі ігнорував би нас та проблеми нашого прекрасного міста.$B$BДякую тобі, старий рибалко. Як завжди, я у боргу перед тобою.$B$BТвій друг,$B$BДеЛаві",
    },
},

[5998] = {
    en = "Stormpike's Request",
    T  = "Прохання Стормпайка",
    pages = {
        [1] = "Майстре Лонгбірд,$B$BЯк вам відомо, ми, члени клану «Штормпайк», маємо око на досконалість, тож якість ваших щитів для нас не є таємницею.$B$Тому я хотів би замовити у вас такий щит.  На наступній сторінці я надав технічні характеристики:",
        [2] = "-Ідеально кругла, довжиною від кулака до ліктя.$B$B-Штифти вздовж краю.  Срібло.$B$B-Один великий штифт у центрі, що охоплює три ширини пальців.  Срібло.$B$B-Виготовлений з дуба та зміцнений залізом.$B$B-Моє ім’я, Грінгер Стормпайк, вигравіруване на верхньому краю.",
        [3] = "Оплата буде здійснена у звичайному порядку.  І, будь ласка, виплатіть особі, яка передає це прохання, стандартну винагороду за доставку.  Ви можете додати її до вартості щита.$B$B$B$BЗ повагою та щирою вдячністю,$B--Грінгер Стормпайк",
    },
},

[6167] = {
    en = "Neeka's Report",
    T  = "Звіт Ніки",
    pages = {
        [1] = "Хелгрум,$B$BВисловлюю свою повагу тому, хто віддав наказ про створення нашої бази «Каргат» у Пустках. Це ідеальне місце для підготовки наших військ. Суворі погодні умови, небезпечна дика природа, войовничі місцеві жителі та повна відсутність зовнішньої підтримки роблять це місце справжньою кузнею, з якої вийдуть лише найкращі воїни та розвідники.$B$BГарне планування. Молодці.",
        [2] = "Я опишу навколишні землі так, як їх обстежили розвідники Каргата:$B$B-Червоні, скелясті пагорби та сухі рівнини, що майже не дають можливості для життя.$B-Пекуче сонце та сильні вітри.$B-Жодних озер чи струмків. Навіть розкиданих калюж немає. Щоб знайти воду, мешканці мусять копати глибокі, мулисті колодязі або висмоктувати мізерну вологу з рідкісних кактусів чи колючих бур’янів.$B$BКоротко кажучи: спекотне, важке життя.",
        [3] = "Бедленди кишать ворогами. Огри бродять по розпеченому піску, влаштовуючи засідки на необережних мандрівників. Карлики з Даркірона мешкають у казармах на схід від Каргата і воюють зі своїми світлошкірими родичами в Лох-Модані, що на півночі. Жорстокі, примітивні звірі, яких називають трогами, ховаються в будь-якому куточку тіні, який їм трапляється, і запекло його захищають.$B$BА на сході Пусток, у ущелині Летлор, мешкають дракони. Ми не знаємо, скільки їх і яких розмірів, оскільки розвідники, які наближаються занадто близько, ніколи не повертаються.",
        [4] = "Навіть не варто говорити, що ми — ті, хто стоїть на варті в Каргаті, — цілком задоволені своїм призначенням. Ми залишаємося витривалими тут, бо якщо ми ослабнемо — то загинемо.$B$BІ я б не хотів, щоб було інакше.$B$BНіка Кров’яний Шрам$BГоловний розвідник, Каргат",
    },
},

[6283] = {
    en = "The Book of Ur",
    T  = "«Книга Ура»",
    pages = {
        [1] = "Земля Азерота приховує безліч чудес.  Флора, фауна, культури та магія — все це рясніє на її поверхні.  Дійсно, допитливі люди знайдуть у цьому світі безмежне розмаїття.  Достатньо лише придивитися.$B$BАле якщо придивитися достатньо уважно, відкриваються вікна у цілком нові світи, і кожен із них приховує свої власні дива.$B$BТак само, як і свої власні жахи.",
        [2] = "Саме в цьому полягає мета моєї книги: скласти перелік цих істот, цих потойбічних демонів, які прагнуть знищити наші землі, щоб мандрівники, які натраплять на них, знали, з чим їм доведеться зіткнутися.$B$BТож якщо ви вважаєте себе захисником Азерота, читайте далі.  І пізнайте свого ворога.$B$B-Ур$BMаг з Даларана",
        [3] = "Тварина, про яку я пишу, — це ворген.$B$BСтаровинні сільські перекази, можливо, натякають на цих істот, адже яка дитина селянина не чула оповідей про звіроподібних вовколюдів, що крадуться лісами та болотами за межами її села?$B$BІ в таких оповідях може критися правда — можливо, це попередження про воргенів, замасковані під міфи, щоб налякати нас.",
        [4] = "Але перш ніж відкинути такі оповіді, дозвольте мені запевнити читача: воргени існують насправді. Можливо, вони не з нашого світу, але між їхнім світом і нашим існують проходи, і могутня магія здатна перенести їх сюди.$B$BТакі заклинання краще не вимовляти, адже куди б не ступали воргени, вони несуть із собою жах і кровопролиття.",
        [5] = "Воргена можна впізнати за його схожістю з вовками нашого світу.  Поглянувши на воргена, легко помітити, наскільки його груба шерсть, загострені вуха та довга морда нагадують вовків, яких ми знаємо.$B$BАле ви так само швидко помітите й відмінності:  це грубе хутро оточує потужне двоноге тіло з довгими іклами та кігтями, схожими на кинджали.  А за його виттям ховається злоба, якої немає в жодній природній тварині.",
        [6] = "Батьківщина воргенів — це темне місце, місце кошмарів. Якщо в тому світі й існують куточки, безпечні від проклятих воргенів, то мої дослідження не виявили жодного такого притулку.$B$BА якщо врахувати жорстокість і злобу воргенів, то, ймовірно, таких притулків і не існує.$B$BПрипускається, що воргени задоволені тим, що залишаються у своєму світі, адже, хоча деякі з них володіють потужною магією, вони не робили жодних спроб самостійно дістатися до Азероту.$B$BІ в цьому нам пощастило.",
        [7] = "Як уже згадувалося вище, деякі воргени володіють містичними мистецтвами, а їхня магія пов’язана з темрявою та розтлінням.$B$BПрокляття та надприродні отрути — звичайне явище, тож майте на увазі: тим, хто зіткнеться з воргенськими магами, слід озброїтися захистом проти тіні.",
        [8] = "Я сподіваюся, що жоден чарівник з Даларана не буде шукати воргенів, навіть якщо це робиться з чистим сумлінням. Адже з цими звірами неможливо укласти жодного союзу, дізнатися жодних таємниць — від них не може бути ніякої користі.$B$BЇх краще залишити у їхньому світі. Адже якщо їх знайдуть у нашому світі й не знищать, то нас чекає страшна небезпека...",
    },
},

[6304] = {
    en = "Damp Diary Page (Day 4)",
    T  = "Сторінка щоденника про вологість (4-й день)",
    pages = {
        [1] = "Щоденник — 4-й день. Я вже 4 дні застряг на острові, залишившись наодинці зі своїми думками.  Банани досить смачні, але як же довго доводиться підніматися, щоб до них дістатися.  Коли я не займаюся пошуком їжі або не захищаюся від періодичних дощів, усі мої думки зосереджені на порятунку. Я б не мав стільки надії, якби не коробки з папером і пляшки, які винесло на берег разом зі мною.  Тепер я сміюся, згадуючи, скільки часу я провів на тому кораблі, проклинаючи долю за те, що мені довелося пливти з цілою купою алхіміків і писарів.",
    },
},

[6305] = {
    en = "Damp Diary Page (Day 87)",
    T  = "Сторінка щоденника «Волога» (87-й день)",
    pages = {
        [1] = "Ці місяці дали мені час поміркувати, позбутися старих переконань і упереджень. Альянс? Орда? Добро? Зло? Значення цих слів, колись таких чітких, тепер розмиваються, коли мій погляд блукає по безмежному морю.$B$BТепер я знаю, що має значення. Банани переслідують мене.$B$BСидячи високо на своєму дереві, вони дивляться на мене з холодною злобою. А останній, який я спробував з’їсти, ледь не викликав у мене блювоту! Я майже чув, як він кричав, коли я розтрощив його, наполовину розкушеного, об морські скелі.$B$BЦе війна, і я її виграю.",
    },
},

[6306] = {
    en = "Damp Diary Page (Day 512)",
    T  = "Сторінка щоденника «Волога» (512-й день)",
    pages = {
        [1] = "Щоденник — День 512 Банани почали розмовляти зі мною, і я дізнався багато нового про їхню культуру. Я припинив безглузде руйнування їхніх осель та поїдання молодняку. Як мало я тоді знав про ту велику цивілізацію, яку руйнував. З іншої теми: здається, у мене закінчуються пляшки та папір.  Коли я вперше побачив ті величезні стоси паперу, що винесло на берег, я думав, що вони будуть невичерпними.  Горе мені, мій щоденник незабаром доведеться закінчити.",
    },
},

[6488] = {
    en = "Simple Tablet",
    T  = "Простий планшет",
    pages = {
        [1] = "Ага, друже. Віднеси цей лист Франгу в Долину Випробувань. Він зазвичай перебуває біля «Лігва», де виховує молодих воїнів, готуючи їх до боїв за Орду.$B$BЙому потрібні такі хитрі воїни, як ти, щоб показати оркам, як битися не лише за допомогою м’язів. Ти швидший і розумніший за більшість, але не хвалися цим — орки не люблять образ. Вони — хороші союзники, і, можливо, вони теж навчать тебе чомусь новому.$B$B-Тар'сере",
    },
},

[6842] = {
    en = "Furen's Instructions",
    T  = "Вказівки Фурена",
    pages = {
        [1] = "На наступних сторінках ти знайдеш перелік матеріалів, необхідних для виготовлення вогнезахисного обладунку.  Удачі тобі, воїне.$B$B$B — Фурен Довгобородий",
        [2] = "Обпалені ікла павуків:$B$BРуда інцендициту, яку видобувають у печері поблизу скелі Телген, обпалила павуків, що мешкають там.$B$BОтрута в їхніх іклах закипає і вступає в реакцію з самими іклами, утворюючи надзвичайно міцну речовину.",
        [3] = "Обвуглені роги:$B$BПодібно до обвуглених іклів павука, обвуглені роги хімери, що мешкає в Обвугленій долині в горах Стоунталон на Калімдорі, мають дуже цінну властивість. $B$BЯкщо їх розточити до плоского стану та належним чином обробити, вони стають надзвичайно стійкими до фізичних навантажень.",
        [4] = "Оцинкований ріг:$B$BМіцність рідкісного оцинкованого рогу є основою всього комплекту обладунків, який я збираюся створити, тому його теж потрібно дістати.$B$BЙого можна отримати від рідкісної матріархи хімери в Обпаленій долині.",
        [5] = "Флакон з флогістоном:$B$BНа останньому етапі створення обладунків знадобиться надзвичайно гаряча кузня. Щоб досягти необхідного рівня нагрівання, мені знадобиться флакон з флогістоном.$B$BЄдиним відомим виробником цієї речовини є легендарний квілбоар Ругуг, і він не віддасть її без бою. Ругуг мешкає в глибинах Разорфен-Краула на півдні Пусток.",
    },
},

[6846] = {
    en = "Defias Script",
    T  = "Сценарій «Дефіас»",
    pages = {
        [1] = "План введено в дію. Візьміть колись величний бастіон віри — «Варту героїв» — за наш базовий табір, і ми почнемо перекидати до вас підкріплення з Вестфолла, щойно ви повідомите, що все належним чином підготовлено. Ця місцевість практично забута жителями та воїнами Штормовію, тож має стати ідеальною відправною точкою для наших атак. Дефіас поверне Штормовій! Чекаю на вашу відповідь.",
    },
},

[6847] = {
    en = "Dark Iron Script",
    T  = "«Сценарій «Темне залізо»»",
    pages = {
        [1] = "Брудних трогів так легко обдурити. Їхня ненависть до нашого народу значно полегшує завдання керувати ними та використовувати їх як пішаків. Мене дивує, що взагалі вдалося укласти будь-який союз, але наш народ становить набагато більшу загрозу для їхнього існування... принаймні поки що.$B$BПроте після початку атак обидві сторони будуть ослаблені й вразливі до нашого наступу. Займіть поселення на південь від озера Гельмс-Бед і чекайте на подальші вказівки.$B$BЗалізна Кузня стане нашою.",
    },
},

[6929] = {
    en = "Bath'rah's Parchment",
    T  = "Пергамент Бат'ри",
    pages = {
        [1] = "Нижче ви знайдете все необхідне для мого заклинання, щоб викликати великого Циклоніана. Нехай удача супроводжує вас.$B$B--Бат’ра, Спостерігач за Вітром",
        [2] = "Ліфрут:$B$BЙого можна зібрати в дикій природі або здобути від Звірів Вітервайну на болотах Дастволлоу.  Його сила знадобиться, щоб притягнути життєву сутність циклоніанців у цей світ.",
        [3] = "Бивні «Кровоскалів»:$B$BБивні тролів «Кровоскалів» із Долини Странглторн мають рідкісну властивість.  Злобність «Кровоскалів» зосереджена в їхніх бивнях, і якщо їх подрібнити в порошок, їхні огидні сили можуть бути вивільнені.",
        [4] = "Есенція вигнанця:$B$BЦю есенцію можна отримати шляхом злиття трьох амулетів елементальних вигнанців з Аратських височин.  Зберіть «Громовий», «Палаючий» та «Хвилястий» амулети у елементалів, а потім покладіть по вісім кожного з них у мій казан.  $B$BЗ цих амулетів утвориться есенція вигнанця.",
    },
},

[6996] = {
    en = "Jordan's Weapon Notes",
    T  = "Примітки щодо зброї Йорданії",
    pages = {
        [1] = "$N,$BПерш ніж продовжувати, дозвольте мені ще раз подякувати вам за все, що ви зробили для мене та моєї дружини. Ви врятували їй життя, і за це я завдячую вам набагато більше, ніж міг би віддячити навіть за сто життів. Вона для мене — все. Якби вона померла... ну, я навіть не знаю, що б я зробив.$B$BОсь список речей, які вам знадобляться, щоб відновити сили, якщо я маю викувати для вас священну зброю. Я розмістив їх у порядку від найлегшого до найважчого — сподіваюся, це полегшить вам завдання.",
        [2] = "Якісний дуб «білий камінь» — до того, як їх захопили, у шахтах під Мунбруком у Вестфолі було багато цієї деревини; її використовували для виготовлення деяких найважливіших решіток та інструментів завдяки її стійкості до високих температур і тиску.$B$BЇї доставляли туди після перевезення з-за океану. Це рідкісна деревина, яка є достатньо міцною для виготовлення вашої зброї. Якщо в шахтах ще щось від неї залишилося, то її, мабуть, мають гобліни-різьбярі.",
        [3] = "Очищена руда — У Телсамарі живе гном на ім’я Бейлор Стоунхенд, коваль, у якого я деякий час навчався. Він виготовляє дуже особливий сплав, який, на мою думку, ідеально підійде для твоєї зброї. Я чекав на поставку цього сплаву, поки був у Айронфорджі, але досі не отримав від нього жодних звісток.$B$BЗнайди його та дізнайся, що сталося з вантажем. А якщо його вже немає в Лох-Модані, я хоча б дізнався, що сталося з моїм старим вчителем.",
        [4] = "Очищена руда — У Телсамарі живе гном на ім’я Бейлор Стоунхенд, коваль, у якого я деякий час навчався. Він виготовляє дуже особливий сплав, який, на мою думку, ідеально підійде для твоєї зброї. Я чекав на поставку цього сплаву, поки був у Айронфорджі, але досі не отримав від нього жодних звісток.$B$BЗнайди його та дізнайся, що сталося з вантажем. А якщо його вже немає в Лох-Модані, я хоча б дізнався, що сталося з моїм старим вчителем.",
        [5] = "Ковальський молот — До настання Чуми та зради Артаса я мешкав у містечку під назвою Пайрвуд, що лежало в глибині прекрасного лісу Сільверпайн. Ліс уже далеко не такий прекрасний, як колись, а фортеця, де я опанував таємниці сталі, вже давно перетворилася на гниле й огидне місце, заповнене істотами неймовірного зла.$B$BКоли ми з дружиною втекли з того, що тепер називають фортецею Тіньовий Ікло, ми залишили там деякі зі своїх найцінніших речей.",
        [6] = "Серед них — ковальський молоток, який мені подарував батько. У молодості я сумнівався в цьому, але він завжди казав мені, що молоток зачарований, і це останній спогад про нього, який у мене залишився, перш ніж його вбив «Скорб».$B$BПринеси мені мій молоток, $N, щоб я міг використати його як осередок своєї пристрасті. Якщо він справді зачарований, то це тільки допоможе нам обом.$B$BЯ залишив його у стайнях на головному дворі фортеці. Якщо тільки ті істоти там не взялися самі за ковальство, то, сподіваюся, він досі там лежить.",
        [7] = "Самоцвіт Кор — З того, що мені розповідали, деякі чарівники використовують ці самоцвіти для накопичення енергії своїх заклинань, що робить їх ще більш смертоносними. Нічний ельф, якому я колись допоміг, — Тундріс Віндвівер, — зможе розповісти тобі більше, оскільки ти будеш говорити від мого імені. Я вважаю, що одну з енергій, накопичених у цьому самоцвіті, можна використати для створення вашої зброї.$B$BКоли ми востаннє розмовляли, Тундріс перебував в Аубердіні — містечку, розташованому в глибині Темного Берега, спотвореного лісу, що розкинувся вздовж узбережжя під тінню батьківщини нічних ельфів.",
    },
},

