[7668] = {
    en = "Bloodstained Journal",
    T  = "Заплямований кров’ю щоденник",
    pages = {
        [1] = "(Через плями можна розібрати лише окремі уривки щоденника.)$B$Булдаман, 3-й день$B$Я не можу повірити, яким дурнем я був.  Потрапити в засідку підступних гномів із Тіньової Кузні — це витівка новачка.  Мої рани загоюються повільно; безсумнівно, мене отруїли.  Я відчуваю, як з мене витікає сила.  Проте я мушу вийти на розвідку...$B$B...що ще гірше, намисто, яке гном виготовив для мене, розбилося!  Три найбільші самоцвіти, вставлені в нього, загубилися.  Я мушу їх знайти; без них намисто не має сили...",
        [2] = "Улдаман, 4-й день$B$B... перша підказка з’явилася в глибинах Улдамана, коли один із найлютіших трогів, яких я коли-небудь бачив, розмахував великим сапфіром — таким, що, як я гадаю, ідеально підійде до намиста.  Я випадково почув, як один із гномів з Тіньової Кузні згадав ім’я цієї потвори: Грімлок. Однак загін охоронців, який має цей брутал Грімлок...",
        [3] = "Улдаман, 5-й день$B$B...трогг, забравши топаз у своїх убитих «побратимів», увійшов у бічну печеру біля входу до зали...$B$B...швидко поклав топаз у велику, помітну урну в глибині зали...$B$B...з усіх можливих істот — гноми!  До того ж аж троє.  Зараз вони забарикадувалися від трогів.  Звернутися до них означало б закликати їх на самогубство, бо в моєму ослабленому стані мене б просто змели огидні троги.  Однак, щойно я дізнаюся про третій самоцвіт, я...",
        [4] = "Улдаман, 6-й день$B$B... Я страшенно голодний. У мене закінчилися запаси, і зараз навіть запліснявілий хліб здався б мені справжнім бенкетом. Я на власні очі бачив, як голова трога перетворилася на соковитий стейк прямо переді мною...",
        [5] = "Улдаман, 7-й день$B$B... останній шанс виправити свої помилки.  Я вважаю, що рубін знаходиться в останній укріпленій зоні, яку карлики утримують проти трогів.  Їхні бої, безсумнівно, за дорогоцінні камені та інші артефакти з цього місця, точаться безперервно.  Цілком у дусі тих мерзенних гномів — сховати його десь саме там.  У будь-якому разі, я мушу щось робити.  Можливо, найкращим варіантом буде шалений ривок на поверхню...",
    },
},

