[9575] = {
    en = "Glyphic Tablet",
    T  = "Гліфічна табличка",
    pages = {
        [1] = "Ласкаво просимо до свого пробудження, друже. Таємниці магії — у твоїх руках, якщо ти будеш достатньо сильним, щоб їх утримати.$B$BТи знайдеш Май’а, коли будеш готовий. Вона навчить тебе багато чого про магію та заклинання, які тобі знадобляться, щоб знищити тих, хто протистоїть тобі.$B$BMай’а перебуває поблизу Лігва у Долині Випробувань. Прийди, знайди її — і ти станеш сильним. Тоді ти покажеш іншим магам, як магія підкоряється твоїй волі… а не навпаки.",
    },
},

[9576] = {
    en = "Tainted Letter",
    T  = "Зражений лист",
    pages = {
        [1] = "Занадто часто такі люди, як послідовники Святого Світла, залякують тих, хто цікавиться справжньою силою, змушуючи їх думати, що вони не можуть досліджувати жодну форму таємних знань — адже не все, що походить з-поза меж цього світу, є злом. Не всі сутності прагнуть панувати над іншими чи підкорювати їх. Якщо ви достатньо сильні, ці самі сутності можуть стати вашими послідовниками.$B$BПро це я хотіла б поговорити з вами докладніше. Знайдіть мене на кладовищі праворуч від абатства.$B$B— Друзілла Ла Саль, наставниця чаклунів",
    },
},

[9577] = {
    en = "Tainted Memorandum",
    T  = "Скомпрометований меморандум",
    pages = {
        [1] = "УВАГА:$B$BЗберігайте мовчання! Не оглядайтеся навколо! Хтось може спостерігати за вами саме в цю мить.$B$BМене звати Аламар Грімм, $N. Я навчаю тих, хто прагне здобути знання та більшу силу з... інших світів. Мене попросили таємно зв’язатися з вами та повідомити, що я можу надалі навчати вас справжній магії.$B$BКоли зможете, завітайте до мене в глибині Анвілмара.$B$B— Аламар Грімм, наставник чаклунів",
    },
},

[9578] = {
    en = "Tainted Scroll",
    T  = "Зіпсований сувій",
    pages = {
        [1] = "Яке жахливе становище, у якому ми опинилися, чи не так, $N? Нас переслідує Огидний Принц. Нас вигнали й знехтували наші власні близькі. Завдяки прекрасній Сильвані ми нарешті здобули власну волю, але що це нам тепер дає? Раби іншого господаря — це все одно раби, принаймні я так вважаю.$B$BАле що, якби ми самі стали господарями? Так, ти розумієш, про що я, чи не так?$B$BМи ще більше відокремлені від решти Забутих, $N. І саме тому ми мусимо поговорити далі. Знайдіть мене в церкві в Дескнелі.",
    },
},

[9579] = {
    en = "Tainted Parchment",
    T  = "Зіпсований пергамент",
    pages = {
        [1] = "Я пишу це повідомлення найпотужнішими чорнилами, які тільки можу створити, $N. Воно миттєво накладе прокляття на будь-кого, хто наважиться прочитати його, крім тебе. Я настільки могутній. Я за бажанням викликаю демонів із Викрученого Потойбіччя. Я мучу своїх ворогів уві сні та на полі бою. І тепер ти теж побачив силу мого шляху. Мої брати задоволені цим.$B$BЗнайди мене в глибинах Лігва, щойно зорієнтуєшся. Я хотів би поговорити з тобою про важливі справи.$B$B-Нарток, наставник чаклунів",
    },
},

[9580] = {
    en = "Verdant Sigil",
    T  = "Зелений Сигіл",
    pages = {
        [1] = "Коли до мене дійшла звістка, що ти готовий, я негайно надіслав цей символ. Усі друїди Сенаріуса відчувають велике задоволення, бачачи, як зростає наша чисельність. Здається, навіть духи стали сильнішими завдяки нашій посиленій присутності. З часом і за умови певної терплячості, сподіваємося, наша сила повернеться до колишньої величі. Знайди мене біля вершини Алдрасілу, коли будеш готовий. Я буду твоїм провідником, доки ти перебуватимеш у Тіньовій Долині.$B$B- Мардант Стронгоук, інструктор друїдів",
    },
},

[9581] = {
    en = "Verdant Note",
    T  = "«Зелена нота»",
    pages = {
        [1] = "Минулої ночі у моїх снах до мене з’явилися духи. Вони розповіли мені про твій прихід і про те, що моїм завданням буде допомогти тобі. За той короткий час, що ми проведемо разом, нам потрібно обговорити багато чого — про природу, духів, Матір-Землю і навіть нічних ельфів. Але я залишу ці уроки на час твого приїзду і зроблю все, що в моїх силах, аби ти був готовий до випробувань, що чекають на тебе.$B$BНехай мудрість веде тебе. Я чекатиму.$B$B— Гарт Міструнер, наставник друїдів",
    },
},

