[10789] = {
    en = "Manual of Engineering Disciplines",
    T  = "Посібник з інженерних дисциплін",
    pages = {
        [1] = "Інженерні дисципліни$B$BХоча можна сперечатися щодо того, яка раса першою започаткувала інженерну науку в Азероті, майже ніхто не заперечує, що в наш час її головними прихильниками є гноми та гобліни.  Їхня спільна відданість інженерії не тільки стала рушійною силою фантастичних винаходів у цій, мабуть, чарівній «Епосі винаходів», але й підживила їхню запеклу расову суперництво.  Ніде це не проявляється так яскраво, як у їхніх розбіжних інженерних дисциплінах.",
        [2] = "Гномська інженерія$B$BГноми як раса, як правило, досягають видатних успіхів у розробці предметів, призначених для впливу на навколишній світ та управління ним. Хоча вони й мають поверхневі знання про вибухові речовини та зброю, гномська інженерія зосереджується на предметах, які, в прямому сенсі, покликані зробити життя простішим і доступнішим.  Це дисципліна теоретичних можливостей, що втілюються в реальність завдяки гномському ноу-хау.  Однак деякі можливості так і залишаються нереалізованими.",
        [3] = "Інженерія гоблінів$B$BЯк раса, яка майже в кожному конфлікті залишається нейтральною, гобліни доклали чималих зусиль, щоб перетворити науку на джерело прибутку. Вони активно використовують практичні аспекти інженерії, про що свідчать їхні радикальні розробки у сфері вибухових речовин, вогнепальної зброї та механізмів.  Гоблінська інженерія виявляє лише побічний інтерес до інженерної теорії; їхні винаходи зазвичай не страждають від того, що не працюють, а навпаки — працюють занадто добре.  Це, безперечно, не для людей зі слабкими нервами.",
        [4] = "Вивчення дисциплін$B$BГноми та гобліни настільки ретельно приховують свої знання один від одного, що отримати доступ до обох наборів дисциплін одночасно практично неможливо.  Кожна раса, незалежно від політичних переконань, надає доступ до знань цих дисциплін лише тим, хто погоджується відмовитися від вивчення дисципліни іншої раси. Наприклад, якщо учень вирішить опанувати гномську інженерію, то знання гоблінської інженерії йому ніколи не будуть доступні.",
        [5] = "Остаточні рішення$B$BУ попередньому розділі було підкреслено важливий момент щодо двох інженерних дисциплін, який необхідно ще раз наголосити з освітньою метою.  Рішення присвятити себе одній із цих двох дисциплін означає, що схеми іншої дисципліни не будуть доступні для вивчення. Хоча така остаточність може лякати інженера-нефахівця, досвідчений фахівець розуміє, що гноми та гобліни ревно охороняють свої таємниці; деякі знання завжди кращі за їхню повну відсутність.",
        [6] = "Цитати$B$B\"Хочеш дізнатися про гоблінську інженерію?  Спробуй запитати про це одного з їхніх найкращих і найталановитіших інженерів — здається, його звати «Наббі Стампфінгерс».  Хочеш знати, чому його так назвали?  ОТО й є гоблінська інженерія.\"$B— Рінго Трагедікшн, інженер-гном$B$B\"Кажіть про нас, гоблінів, що завгодно, але одне я вам скажу: У НАС Є ВИБУХОВІ РЕЧОВИНИ!\"$B— Яз Нітроспорк, гоблін-бомбардир",
        [7] = "Ще цитати!$B$B«Знаєте те відчуття, яке виникає, коли ви закінчуєте створювати щось і вперше вмикаєте це, щоб відчути силу та радість винаходу, коли ваш пристрій оживає?  Гноми цього не відчувають.\"$B-- Нікс Спрокетспринг, головний гоблін-інженер Гаджетзана$B$B\"Інженерія — це перетворення фантазії на щось фантастичне!\"$B-- Ровіс Маккранкенспанк, гном-винахідник",
    },
},

[10832] = {
    en = "Fel Tracker Owner's Manual",
    T  = "Інструкція з експлуатації Fel Tracker",
    pages = {
        [1] = "Викликання звіра:$B$BЩоб викликати «Слідопита-фелхаунда», вам потрібно використати надану «Фел-кулю».$B$BПримітки:$B$BВикликаний «Слідопит-фелхаунд» залишатиметься в цьому світі лише протягом тридцяти хвилин.$B$BПрикликаний «Фельхаунд-слідопит» допомагатиме вам лише у пошуку ашарських утворень.$B$BПрикликаний «Фельхаунд-слідопит» НЕ БУДЕ робити наступне: виконувати трюки, атакувати що-небудь, допомагати кому-небудь, танцювати, знищувати арканічних істот.$B$BНаступна сторінка, будь ласка...",
        [2] = "«Керування звіром»:$B$BСлідошукачі-фелхаунди реагують лише на звірячі рики. Щоб ваш слідошукач-фелхаунд почав вистежувати ашарські формування, ви повинні енергійно рикнути на нього! (Виберіть «Слідопита-фелхаунда» як ціль і введіть /roar).$B$BКоли «Слідопит-фелхаунд» знайде формування, він кинеться до нього, майже не зважаючи на істот, що його оточують. Хоча вам не потрібно захищати «Слідопита-фелхаунда», бажано залишатися поруч, щоб не втратити його з поля зору.",
        [3] = "Утилізація звіра:$B$BЧерез тридцять хвилин звір повернеться до свого дому в Нетері.$B$BПримітка:$B$BУ запалі боротьби звір МОЖЕ збігти зі скелі або впасти з гори. Не сумуйте за втратою Фелхаунда-слідопита — замість цього викличте іншого.",
    },
},

[10839] = {
