[11482] = {
    en = "Crystal Pylon User's Manual",
    T  = "Посібник користувача «Crystal Pylon»",
    pages = {
        [1] = "<HTML>$B<BODY>$B<H1 align=\"center\">$BІНСТРУКЦІЯ З ЕКСПЛУАТАЦІЇ CRYSTAL PYLON$B</H1>$B<BR/>$B<P align=\"center\"> \"Посібник зі збору та використання енергетичних кристалів кратера Ун’Горо\" </P>$B<BR/>$B<BR/>$B<P align=\"left\">Розділ 1: Північний пілон </P>$B<BR/>$B<P align=\"left\">Розділ 2: Східний пілон </P>$B<BR/>$B<P align=\"left\">Розділ 3: Західний пілон </P>$B<BR/>$B</BODY>$B</HTML>",
        [2] = "<HTML>$B<BODY>$B<H1 align=\"center\">$BРозділ 1: ПІВНІЧНИЙ ПІЛОН$B</H1>$B<BR/>$B<BR/>$B<IMG src=\"Interface\\Pictures\\11482_crystals_mini_north\" align=\"left\"/>$B<P align=\"right\">Північна<BR/>$BPілон приймає<BR/>$Bжовті, червоні,<BR/>$Bта зелені<BR/>$Bкристали.</P>$B<BR/>$B<BR/>$B<BR/>$B<BR/>$B<P align=\"left\">Пілон зосереджується на енергії, яку можна створити, використовуючи жовті кристали як основне джерело енергії.</P>$B</BODY>$B</HTML>",
        [3] = "<HTML>$B<BODY>$B<H1 align=\"center\">$BКомбінації північних кристалів$B</H1>$B<BR/>$B<P align=\"left\">Існують два можливі ефекти: один завдає шкоди, а інший — нейтралізує її. </P>$B<BR/>$B<P align=\"left\">КРИСТАЛЬНИЙ ЗАРЯД: Потрібні червоні та жовті кристали. <BR/>Це спричинить великий вибух.</P>$B<BR/>$B<P align=\"left\">КРИСТАЛЬНЕ ВІДНОВЛЕННЯ: Потрібні жовті та зелені кристали. <BR/>Це надасть вам цілющу ауру.$B</P>$B</BODY>$B</HTML>",
        [4] = "<HTML>$B<BODY>$B<H1 align=\"center\">$BДІАГРАМА ТАБЛИЦІ ПІВНІЧНОГО ПІЛОНА$B</H1>$B<BR/>$B<IMG src=\"Interface\\Pictures\\11482_crystals_north\"/>$B</BODY>$B</HTML>",
        [5] = "<HTML>$B<BODY>$B<H1 align=\"center\">$BРозділ 2: СХІДНИЙ ПІЛОН$B</H1>$B<BR/>$B<BR/>$B<IMG src=\"Interface\\Pictures\\11482_crystals_mini_east\" align=\"left\"/>$B<P align=\"right\">Східний<BR/>$BPілон приймає<BR/>$Bсині, жовті<BR/>$Bта зелені<BR/>$Bкристали.</P>$B<BR/>$B<BR/>$B<BR/>$B<BR/>$B<P align=\"left\">Пілон зосереджується на енергії, яку можна створити, використовуючи сині кристали як основне джерело енергії.</P>$B</BODY>$B</HTML>",
        [6] = "<HTML>$B<BODY>$B<H1 align=\"center\">$BКомбінації східних кристалів$B</H1>$B<BR/>$B<P align=\"left\">Існує два можливі ефекти: один надає бонус до духу, а інший створює захисний щит, що завдає шкоди.</P>$B<BR/>$B<P align=\"left\">КРИСТАЛЬНА СИЛА: Потрібні сині та зелені кристали.<BR/>Це забезпечить вам підвищення духу.</P>$B<BR/>$B<P align=\"left\">КРИСТАЛЬНА ВЕЖА: Потрібні сині та жовті кристали.<BR/>Це створить щит, який завдає шкоди нападникам.$B</P>$B</BODY>$B</HTML>",
        [7] = "<HTML>$B<BODY>$B<H1 align=\"center\">$BСХЕМА СТОЛУ «EASTERN PYLON»$B</H1>$B<BR/>$B<IMG src=\"Interface\\Pictures\\11482_crystals_east\"/>$B</BODY>$B</HTML>",
        [8] = "<HTML>$B<BODY>$B<H1 align=\"center\">$BРозділ 3: ЗАХІДНИЙ ПІЛОН$B</H1>$B<BR/>$B<BR/>$B<IMG src=\"Interface\\Pictures\\11482_crystals_mini_west\" align=\"left\"/>$B<P align=\"right\">Західний<BR/>$BPілон приймає<BR/>$Bчервоні, зелені<BR/>$Bта сині<BR/>$Bкристали.</P>$B<BR/>$B<BR/>$B<BR/>$B<BR/>$B<P align=\"left\">Пілон зосереджується на енергії, яку можна створити, використовуючи червоні кристали як основне джерело енергії.</P>$B</BODY>$B</HTML>",
        [9] = "<HTML>$B<BODY>$B<H1 align=\"center\">$BКомбінації західних кристалів$B</H1>$B<BR/>$B<P align=\"left\">Існує два можливі ефекти: один підвищує ваш захист від шкоди, а інший послаблює захист ворога.</P>$B<BR/>$B<P align=\"left\">КРИСТАЛЬНИЙ ЗАХИСТ: Потрібні червоні та зелені кристали.<BR/>Це підвищить ваш рівень броні.</P>$B<BR/>$B<P align=\"left\">КРИСТАЛЬНИЙ УРОЖАЙ: Потрібні сині та червоні кристали.<BR/>Це може знизити броню певної цілі.$B</P>$B</BODY>$B</HTML>",
        [10] = "<HTML>$B<BODY>$B<H1 align=\"center\">$BСхема західної опори$B</H1>$B<BR/>$B<IMG src=\"Interface\\Pictures\\11482_crystals_west\"/>$B</BODY>$B</HTML>",
    },
},

[11727] = {
    en = "Goodsteel Ledger",
    T  = "Реєстр Goodsteel",
    pages = {
        [1] = "Вітаю вас, мандрівники!$B$BI, я — Крінкл Гудстіл, і мені потрібні ті, хто готовий ризикнути, аби виконати деякі з моїх найважчих завдань. З огляду на мої численні обов’язки та обсяг роботи, який я взяв на себе, я гарантую, що кожен, хто наважиться виконати цей список завдань і повернути мені все в цілості, отримає щедру винагороду. $B$BСписок міститься на наступних сторінках...",
        [2] = "Ноги з твердого кристалу — $B$BПавуки «Гласвеб» з Ущелини Палаючого Вогню створені з неймовірного матеріалу, схожого на кристал. Їхні ноги, якщо вони не пошкоджені під час вбивства, стають чудовим провідником у деяких інженерних експериментах моїх супутників.$B$BМені знадобиться кілька таких екземплярів для випробувань. Оскільки павуки мають вісім ніг, це не повинно становити проблеми для відважного воїна чи досвідченого мага.",
        [3] = "Запізніла посилка —$B$BЯ найняв людину, яку вважав надійним пілотом, щоб той привіз мені посилку з Терамора. Виявляється, я помилився. І хоча пілот вижив і зміг розповісти про те, що сталося, він залишив свій цепелін разом з усім вантажем, аби врятувати власну шкуру.$B$BЩо ж, мені потрібно повернути цю посилку. З того, що розповів мені Бізіл, він розбився трохи на захід від затоки в Болоті Дастволлоу. Це сталося одразу після того, як він перетнув пагорби вздовж берега.$B$BХм... він так і не сказав мені, що саме спричинило аварію...",
        [4] = "«Збалансований фламберг» від Гудстіла — $B$BНарешті я хочу представити одну зі своїх найкращих ковальських робіт на сьогодні. Цей фламберг був неймовірним мечем, який я подарував тому, кого вважав дуже шанованим і великим воїном. Ну, його розгромив мурлок на ім’я Джарквей? Чи щось таке. $B$BЦе сталося, коли він подорожував узбережжям Болота Скорботи й вирішив атакувати цю істоту. Йому не вдалося, і, судячи з усього, він втік, але не забув залишити зброю, щоб цей мурлок міг її забрати.",
        [5] = "Знайди для мене ці предмети та повернися з ними всіма, а також із цією бухгалтерською книгою, до Гаджетзана, і я винагороджу тебе.",
    },
},

