    pages = {
        [1] = "Привіт, Фелнок!$B$BМоє навчання в Палаючих степах просувається чудово. І я дуже вдячний $N за всю $ghis:her; допомогу!  Ось що мені потрібно, щоб продовжувати:$B$BA сталева котушка «бампер-бітцель»$BA льодовий гайковий ключ 17-го калібру$B12 фунтів качиного пір’я$BA баночка того клею, який ти робиш$B$BДуже дякую, Фелноку, і коли ми знову побачимося, нагадай мені, щоб я не клав вугілля в твої чоботи!$B$B-Тінкі",
