[12730] = {
    en = "Warosh's Scroll",
    T  = "Свиток Вароша",
    pages = {
        [1] = "О, я проклятий!  Колись я був великим магом-огром з клану Спірстоун, але кинув виклик Уроку Доумхаулу, і той викрав мою магію та прокляв мене.  Тепер я змушений блукати коридорами Хордемара у вигляді цієї жалюгідної істоти!$B$BДопоможіть мені!  Зіткніться з Уроком і поверніть мені мою магію!  Це буде нелегко, адже Урок ховається в тінях, і його можна викликати лише шляхом великого випробування.$B$BЦим випробуванням стане смерть його найнадійнішого помічника, верховного лорда Омока.$B$BЧитай далі, і ти все зрозумієш.",
        [2] = "Верховний лорд Омокк править Каменями Духів, але робить це завдяки магії Урока.  Урок зачарував Омока заклинанням, здатним вбити будь-якого огра, який кине йому виклик.  Він неодноразово застосовував це заклинання і зберігає черепи своїх жертв у купі в місці сили, розташованому над покоями Омока.$B$BСаме туди вам і слід вирушити, щоб зіткнутися з Уроком.",
        [3] = "Знайдіть грубо оброблений спис у таборах Скаршильдів. Вони часто складають їх біля своїх спальних килимків, неподалік від входу до володінь огра Спірстоуна.$B$BКоли ви знайдете спис, прорвіться до верховного лорда Омока.  Вбийте його та насадіть його голову на піку.$B$BТоді ви будете готові до справжнього випробування.",
        [4] = "Відправляйся до місця сили, що знаходиться над володіннями Спірстоуна, за тунелями Скіттервеб.  У цьому місці нагромаджені черепи ворогів і суперників Урока. Саме сюди ти повинен вбити спис із головою Омока!$B$BКоли голова опиниться на місці, Урок неодмінно з’явиться… але спершу він надішле на тебе своїх поплічників.  Знищте їх, і з часом сам Урок буде викликаний.$B$BВбийте Урока та поверніть мою магію.  Коли я відновлю свої сили, я винагороджу вас.",
        [5] = "Удачі тобі.  А ось підказка, яка може стати в нагоді у твоїх сутичках із посіпаками Урока:$B$BЗаклинання, яке Омокк використовує проти огрів — те, що вбиває їх на місці, — може зберегти свою силу навіть після того, як ти вб’єш Омокка.  Під час бою з поплічниками Урока задійте силу, що міститься в голові Омока — якщо пощастить, Омок знищить поплічників Урока!$B$BЯка іронія.",
    },
},

[12765] = {
