    T  = "Таємна записка № 1",
    pages = {
        [1] = "Агашам,$B$BНаші плани потрібно будь-що-будь тримати в таємниці! Якщо інші племена тауренів дізнаються про нашу приналежність, це призведе до катастрофи.$B$BPідпис,$B$BПередвісник Елм",
    },
},

[12766] = {
    en = "Secret Note #2",
    T  = "Таємна записка № 2",
    pages = {
        [1] = "Агашам,$b$bОб’єднавши сили, ми станемо могутнішими, ніж усі племена тауренів разом узяті! Однак ми вимагаємо від вас повної покори. Пам’ятайте: ваш народ отримає нагороду лише після того, як наші плани втіляться в життя!$b$bПідпис,$b$bПередвісник Рекс",
    },
},

[12768] = {
