    T  = "Таємна записка № 3",
    pages = {
        [1] = "Агашам,$b$bНаші агенти з Лордаерона незабаром зустрінуться з вашими делегатами. Ми повідомимо вас, щойно знайдемо відповідне місце для проведення нашої зустрічі на вищому рівні.$b$bПідпис,$b$bПередвісник Гракус",
    },
},

[12900] = {
    en = "Annals of Darrowshire",
    T  = "Хроніки Дарроуширу",
    pages = {
        [1] = "«Літопис Дарроуширу»$b$bДарроушир, названий на честь озера Дарроумір, що розташоване на заході від нього, — це село, затиснуте в південних передгір’ях Лордаерону. Відоме своїми скромними, але працьовитими мешканцями, Дарроушир залишалося на задньому плані історії Лордаерону аж до Другої війни.$b$bПід час тієї війни з’явилися герої. І загинули герої.",
        [2] = "Битва за Дарроушир$b$bБитва за Дарроушир відбулася в розпал Другої війни, коли війська Плетіння спустошували Лордаерон. Дарроушир був відрізаний від основних сил Альянсу, але місто підкріплювали рота солдатів, загін паладинів «Срібної Руки» та відважна група місцевої міліції на чолі з капітаном Джозефом Редпатом.",
        [3] = "Перші атаки «Покарання» на Дарроушир були нечастими. Невеликі групи мародерствуючих скелетів і трупів блукали на околицях села, але їх відбивали.$b$bОднак «Пораза» не злякалася наполегливості захисників і відповіла тим самим: незабаром після першої хвилі атак з’явилася друга. Гул-чемпіони, слуги володаря гулів Хоргуса, з криками зривалися з пагорбів і вступали в бій з обложеними захисниками Дарроуширу.",
        [4] = "Захисники втратили сили, але на зміну їм прийшли паладини — послідовники «Срібної Руки». Їхній ватажок, Давіл Крокфорд, був уродженцем Дарроуширу. Дізнавшись про майбутній напад, він привів своїх послідовників до села, і разом із захисниками вони стримали слуг Хоргуса.$b$bКоли сам Хоргус вступив у бій, він зіткнувся з Давілом. Вони билися протягом багатьох хвилин, і зрештою Давіл взяв гору, але отримав смертельне поранення й помер незабаром після того, як переміг володаря гулів.",
        [5] = "Битва тривала, і капітан Редпат хоробро очолював свою міліцію. І, можливо, перемога була б за ними, якби капітана не спокусив лицар смерті Мардук Чорний.$b$bУ самому розпалі бою Мардук під’їхав до Редпата і за допомогою чорної магії вирвав з нього душу, перетворивши її на злу тінь хороброго капітана.",
        [6] = "Зіпсований капітан Редпат потім поширив свою злу скверну серед захисників Дарроушира, які зрадили своїх союзників і винищили їх. Потім вони обернулися проти міста Дарроушир і вбили всіх, хто ховався у своїх будинках.$b$bРешта армії Пошесті разом із спотвореним духом капітана Редпата покинула розорене селище Дарроушир і вторглася до Лордаерону, додавши ще більше болю та смерті до Другої війни.",
    },
},

[13158] = {
    en = "Words of the High Chief",
    T  = "Слова Верховного вождя",
    pages = {
        [1] = "Нападники... з усіх боків.$B$BЦе видно по їхніх очах. Тімбермоу — зло. Вороги.$B$BТреба захистити плем’я. Треба захистити Вінтерфолл. Треба вигнати загарбників з нашої землі.",
        [2] = "Сніг, що засліплює...$B$BТреба захистити плем'я. Зробити їх сильними. Бути сильним.$B$BНе знаю...",
        [3] = "Огняна вода.$B$BЗробіть ще. Ще огняної води.$B$BOгняна вода робить Вінтерфол сильним. Переможемо наших ворогів.$B$BУ Вінтерфола немає союзників. Вінтерфол сильний. Має велику силу.",
        [4] = "Більше. Потрібно більше...$B$BВінтерфолл... не... слабкий...",
    },
},

[13202] = {
    en = "Extended Annals of Darrowshire",
    T  = "Розширені літописи Дарроуширу",
    pages = {
        [1] = "«Літопис Дарроуширу»$B$BДарроушир, названий на честь озера Дарроумір, що розташоване на заході від нього, — це село, затиснуте в південних передгір’ях Лордаерону.  Відоме своїми скромними, але працьовитими мешканцями, Дарроушир залишалося на задньому плані історії Лордаерону аж до Другої війни.$B$BПід час тієї війни з’явилися герої.  І загинули герої.",
        [2] = "Битва за Дарроушир$B$BБитва за Дарроушир відбулася в розпал Другої війни, коли війська Плетіння лютували на території Лордаерона.  Дарроушир був відрізаний від основної частини військ Альянсу, але місто підкріплювали рота солдатів, загін паладинів «Срібної Руки» та відважна група місцевої міліції на чолі з капітаном Джозефом Редпатом.",
        [3] = "Перші напади «Покарання» на Дарроушир були нечастими. Невеликі групи грабіжницьких скелетів і трупів блукали на околицях села і були легко розгромлені.  $B$BАле «Пораза» відчула завзятість захисників і відповіла тим самим: незабаром після першої хвилі атак з’явилася друга.  Гул-чемпіони, слуги володаря гулів Хоргуса, з криками зривалися з пагорбів і вступали в бій з обложеними захисниками Дарроуширу.",
        [4] = "Захисники втратили сили, але на зміну їм прийшли паладини — послідовники «Срібної Руки». Їхній ватажок, Давіл Крокфорд, був уродженцем Дарроуширу.  Дізнавшись про майбутній напад, він привів своїх послідовників до села, і разом із захисниками вони стримали слуг Хоргуса.$B$BКоли сам Хоргус вступив у бій, він зіткнувся з Давілом.  Вони билися протягом багатьох хвилин, і зрештою Давіл взяв гору, але отримав смертельне поранення й помер незабаром після того, як переміг володаря гулів.",
        [5] = "Битва тривала, і капітан Редпат хоробро очолював свою ополченську дружину.  І, можливо, перемога була б за ними, якби капітана не спокусив лицар смерті Мардук Чорний.$B$BУ самому розпалі бою Мардук під’їхав до Редпата і за допомогою чорної магії вирвав з нього душу, перетворивши її на злу тінь хороброго капітана.",
        [6] = "Зіпсований капітан Редпат потім поширив свою злу скверну серед захисників Дарроушира, які зрадили своїх союзників і винищили їх.  Потім вони обернулися проти міста Дарроушир і вбили всіх, хто ховався у своїх домівках.$B$BРешта армії Пошесті разом із спотвореним духом капітана Редпата покинула розорене селище Дарроушир і вторглася до Лордаерону, додавши ще більше болю та смерті до Другої війни.",
        [7] = "Доля Хоргуса Руйнівника$B$BХоргус Руйнівник загинув у битві під Дарроуширом.  Але зло, що таїлося в ньому, не зникло повністю.  Переможні війська Плетіння забрали його череп з поля битви під Дарроуширом, несучи його з собою, щоб сіяти жах серед живих, з якими їм доводилося стикатися.$B$BЧерез кілька днів загін Плетіння, який володів головою, був розгромлений паладинами «Срібної Руки».  Голову Хоргуса кинули в озеро Блеквуд.",
        [8] = "Доля Чорного Мардука$B$BMардук пережив Другу війну, принісши велику смерть і страждання своїм огидним мечем, усіяним рунами. Хоча Мардук досі живий, його меч було втрачено в битві поблизу Корінського переходу.  Капітан-карлик розбив меч об свій зачарований щит, змусивши Мардука втекти з поля бою та забезпечивши перемогу Альянсу.$B$BMеч Мардука занурився в землю й спотворив її, виївши в ній ущелину, яка тепер відома як «Шрам Інфектіса».",
        [9] = "Доля Давіла Лайтфорджа$B$BDавіл Лайтфордж загинув у битві за Дарроушир, але його хоробрість надихала Альянс протягом усієї війни.$B$BЙого книгу — лібрам паладина — було знайдено військами «Скарлетного хрестового походу».  Зараз вона зберігається в ратуші міста Хартглен, яке контролюється «Скарлетним хрестовим походом», і її часто читають хрестоносці, прагнучи черпати силу з прикладів Давіла.",
        [10] = "Доля Джозефа Редпата$B$BДжозеф Редпат загинув під час битви за Дарроушир.  Його душа була спотворена й прийняла нову форму, і ця істота сіяла велике зло в Лордаероні.$B$BУ місцевості «В’янення Гаррона», на схід від Андорхала, спотворений Редпат був остаточно розгромлений військами Альянсу.  Його щит досі лежить біля сараю зараженої ферми, а слуги Плетіння й досі тягнуться до пам’яті про його зло.",
        [11] = "Доля Карліна Редпата$B$BBрат капітана Джозефа Редпата, Карлін загинув під час битви при Дарроуширі.  Але, незважаючи на тяжкі поранення, він залишився живим.$B$BЧерез кілька днів після битви агенти «Срібного Світанку» знайшли Карліна, що блукав, знесилений спрагою та лихоманкою, поблизу Корінського Переходу.  Вони перев'язали йому рани та доставили до каплиці «Надії Світла».$B$BВдячний за їхню милосердність, Карлін приєднався до лав «Срібного Світанку» і тепер веде битву за помсту проти Плеті.",
    },
},

[13507] = {
    en = "Cliffwatcher Longhorn Report",
    T  = "Звіт «Cliffwatcher Longhorn»",
    pages = {
        [1] = "Натака, у «Тисячі Голках» все гаразд. Кентаври — це лише дрібна неприємність… Іноді нападають, але це не становить серйозної загрози. Однак, схоже, з’явилися чутки про об’єднання кланів кентаврів.$B$BМи завжди замислювалися над загрозою, яку може становити об’єднана безжальна раса, така як кентаври…Я намагаюся не зациклюватися на таких думках, як ти знаєш... ніщо не може проникнути крізь ту чисту ненависть, яку вони відчувають... навіть один до одного.$B$B-Кліфвотчер Лонгхорн",
    },
},

