[15847] = {
    en = "Quel'Thalas Registry",
    T  = "Реєстр Кве'Таласа",
    pages = {
        [1] = "Дата запису: Невідома$B$BNім: Натанос Марріс, людський лорд-рейнджер Лордаерону.$B$BЗапис:$B$BВідзначено незгоду Каель'таса Сонстрайдера щодо мого рішення прийняти Натаноса Марріса до ордену. Слід також зазначити, що Натанос — хоч і є людиною — є одним із найталановитіших рейнджерів, яких мені коли-небудь випадало навчати.$B$B(продовження)",
        [2] = "Протягом тисячоліть ми ізолювали себе від сторонніх. Я буду першим серед нас, хто визнає, що в минулому були допущені помилки. Люди ніколи не мали стикатися з магією. Я не заперечую цього, але не збираюся прирікати нас на таке усамітнене існування через промахи наших попередників. Співіснування квельдореїв та інших рас цього світу може принести багато користі. Ми мусимо проявляти терпимість.$B$B(продовження)",
        [3] = "Отже, саме цими словами я відхиляю прохання Кела щодо Натаноса Марріса. Він виявиться безцінним союзником. Запам’ятайте мої слова.$B$BПідпис,$B$BSільванас Віндранер$BRічник-генерал Срібного Місяця$B",
    },
},

[15998] = {
    en = "Lewis' Note",
    T  = "Примітка Льюїса",
    pages = {
