[17735] = {
    en = "The Feast of Winter Veil",
    T  = "Свято Зимової завіси",
    pages = {
        [1] = "Свято Зимової завіси$B$BУ багатьох культурах Азерота пізні пори року вважаються часом змін.  Зокрема, гноми та таурени сприймають легенду про наближення Зимової завіси — коли земля вкривається снігом, що знаменує початок періоду відродження — як привід для святкування.  Хоча розуміння легенд, спільних для рас Азерота, не надто відрізняється, способи їх вшанування настільки ж різноманітні, як і самі раси.",
        [2] = "Легенда про Великого Батька Зиму$B$BКажуть, що термін «Зимова завіса» походить від назви надприродної істоти, яку в багатьох культурах називають Великим Батьком Зимою.  Коли він мандрував землею наприкінці сезонів, сама зима ставала його хвилястим плащем.  У його слід за землею простягався сніговий покрив, і тому кажуть, що Великий Батько Зима накидав на землю свою зимову завісу.  Хоча деякі частини Азероту й можуть бути вкриті снігом, це дає землі час для відродження та оновлення.",
        [3] = "Гноми$B$BЗахоплені дослідженням свого походження, гноми вирішили відзначати цю пору року на честь самого Великого Батька Зими. Вони вважають його уособленням одного з древніх Азерота — титанів.  Хоча вони й стверджують, що в тій чи іншій мірі походять від цих містичних істот, вони вважають свою засніжену батьківщину Дун-Морог найкращим прикладом благословень Великого Батька Зими.",
        [4] = "Таурени$B$BТаурени та їхнє шаманське розуміння зими, а також їхнє недавнє залучення до друїдських практик, добре вписуються в легенду про Зимову Завісу.  Вони зосереджуються майже виключно на аспектах відродження, залишаючи поклоніння легендам тим расам, які (на їхню думку) менш гармонійно співіснують із природою речей. Багато тауренів вважають цей час ідеальним для того, щоб подякувати за благословення їхньої нової батьківщини в Мулгорі.",
        [5] = "Бенкет$B$BІдея влаштовувати бенкети в цю пору року бере свій початок із самої легенди. Кажуть, що коли Великий Батько Зима мандрував Азеротом, приносячи з собою зиму, він дарував щедрі дари тим, хто радо вітав його прихід.  Таким чином, традиція бенкетів під час Зимової завіси об’єднувала громади, які ділилися тим, що мали.  Зазвичай цей перехід зустрічали одним днем веселощів та бенкетів, очікуючи на відродження землі.",
        [6] = "Сучасні традиції$B$BІнші культури почали сприймати Свято Зимової Завіси як час великого святкування, хоча й не за тими традиціями, на яких ґрунтується легенда.  Звичаї, які часто не пов’язані ні з чим іншим, окрім як із нагодою для святкування та обміну подарунками, увійшли до сучасних традицій відзначення цього сезону. Навіть образ Великого Батька Зими іноді використовується, але скоріше як передвісник комерційної вигоди, а не як надприродний титан.",
    },
},

[17781] = {
    en = "The Pariah's Instructions",
    T  = "Настанови Парії",
    pages = {
        [1] = "Глибоко в Долині Списів розташований священний храм Мараудон. І якби цього було недостатньо, ви швидко зрозумієте, чому я попросив не-кентавра допомогти мені у моїй скруті.$B$BTам, одразу за дверима, за якими можуть пересуватися лише духи та наші найсвятіші жерці й жриці, перебуває той, кого називають Безіменним Пророком. Він є найвищим авторитетом у духовних справах серед усіх племен і одним із найстаріших серед усіх племен.",
        [2] = "Пророк наділений великою силою і спілкується з духами наших предків. Але він — дурень! Він навіть не уявляє, якою справжньою силою володіє. На ньому — Амулет Духів — саме з нього він черпає більшу частину своєї сили.$Я дізнався, що Амулет наділений великою силою, але він неповний.",
        [3] = "В амулеті бракує п’яти самоцвітів. І якщо б ці самоцвіти було знайдено та вставлено назад у символ, його сила значно перевищила б ту, що він має зараз. Я знайшов ці п’ять самоцвітів, але мені потрібна допомога такого майстра, як ти, щоб зібрати їх. Вбити Безіменного Пророка — це, безперечно, єресь, так само як і пограбувати його труп, але те, про що я попрошу тебе далі, засудило б будь-якого кентавра навіть за саму думку про це.",
        [4] = "У печерах Мараудона блукають духи наших перших ханів. Перші діти нашої Матері та Батька, а також наші найвидатніші вожді — це Гелк, Колк, Магра, Мараудос і Венг. Кожен із цих духів зберігає один із зниклих самоцвітів.",
        [5] = "Використай силу «Амулета духів», щоб змусити їх проявитися, і забери у них самоцвіти! Потім поклади самоцвіти в «Амулет духів» і поверни його мені. Як тільки я отримаю «Амулет єдності», я стану достатньо могутнім, щоб реорганізувати племена, і ми нарешті зможемо стати такими, якими нас хотіли бачити наші предки!",
    },
},

