        [3] = "<HTML>$B<BODY>$B<H1 align=\"center\">ЗВАННЯ ОФІЦЕРІВ АЛЬЯНСУ</H1><BR/>$B<P align=\"center\">Частина 2</P>$B<IMG src=\"Interface\\PvPRankBadges\\PvPRank09\" align=\"left\"/><BR/>$B<P align=\"right\">Лицар-чемпіон</P><BR/><BR/>$B<IMG src=\"Interface\\PvPRankBadges\\PvPRank08\" align=\"left\"/><BR/>$B<P align=\"right\">Лицар-капітан</P><BR/><BR/>$B<IMG src=\"Interface\\PvPRankBadges\\PvPRank07\" align=\"left\"/><BR/>$B<P align=\"right\">Лицар-лейтенант</P><BR/><BR/>$B<IMG src=\"Interface\\PvPRankBadges\\PvPRank06\" align=\"left\"/><BR/>$B<P align=\"right\">Лицар</P><BR/><BR/>$B</BODY>$B</HTML>",
