        [5] = "<HTML>$B<BODY>$B<H1 align=\"center\">ЗВАННЯ ОФІЦЕРІВ ОРДИ</H1><BR/>$B<P align=\"center\">Частина 1</P>$B<IMG src=\"Interface\\PvPRankBadges\\PvPRank14\" align=\"left\"/><BR/>$B<P align=\"right\">Верховний воєначальник</P><BR/><BR/>$B<IMG src=\"Interface\\PvPRankBadges\\PvPRank13\" align=\"left\"/><BR/>$B<P align=\"right\">Воєначальник</P><BR/><BR/>$B<IMG src=\"Interface\\PvPRankBadges\\PvPRank12\" align=\"left\"/><BR/>$B<P align=\"right\">Генерал</P><BR/><BR/>$B<IMG src=\"Interface\\PvPRankBadges\\PvPRank11\" align=\"left\"/><BR/>$B<P align=\"right\">Генерал-лейтенант</P><BR/><BR/>$B<IMG src=\"Interface\\PvPRankBadges\\PvPRank10\" align=\"left\"/><BR/>$B<P align=\"right\">Чемпіон</P><BR/><BR/>$B</BODY>$B</HTML>",
