        [7] = "<HTML>$B<BODY>$B<H1 align=\"center\">Ранги рядового складу Орди</H1><BR/>$B<IMG src=\"Interface\\PvPRankBadges\\PvPRank05\" align=\"left\"/><BR/>$B<P align=\"right\">Старший сержант</P><BR/><BR/>$B<IMG src=\"Interface\\PvPRankBadges\\PvPRank04\" align=\"left\"/><BR/>$B<P align=\"right\">Старший сержант</P><BR/><BR/>$B<IMG src=\"Interface\\PvPRankBadges\\PvPRank03\" align=\"left\"/><BR/>$B<P align=\"right\">Сержант</P><BR/><BR/>$B<IMG src=\"Interface\\PvPRankBadges\\PvPRank02\" align=\"left\"/><BR/>$B<P align=\"right\">Рядовий</P><BR/><BR/>$B<IMG src=\"Interface\\PvPRankBadges\\PvPRank01\" align=\"left\"/><BR/>$B<P align=\"right\">Розвідник</P><BR/><BR/>$B</BODY>$B</HTML>",
