[18675] = {
    en = "Military Ranks of the Horde & Alliance",
    T  = "Військові звання Орди та Альянсу",
    pages = {
        [1] = "<HTML>$B<BODY>$B<H1 align=\"center\">ВІЙСЬКОВІ ЗВАННЯ ОРДИ ТА АЛЬЯНСУ</H1>$B<BR/>$B<BR/>$B<IMG src=\"Interface\\PvPRankBadges\\PvPRankHorde\" align=\"left\"/>$B<BR/>$B<P align=\"right\">Тром'ка!  У цій</P>$B<P align=\"right\">книзі ви знайдете</P>$B<P align=\"right\">багато переліків</P>$B<P align=\"right\">військових звань</P>$B<P align=\"right\">Орди та</P>$B<P align=\"right\">кволого Альянсу.</P>$B<P align=\"right\">Спочатку йтиметься про</P>$B<P align=\"right\">Орду, потім про Альянс,</P>$B<P align=\"right\">і для кожного з них наведено переліки офіцерських та рядових звань.  Як і годиться, найсильніші вказані нагорі, а слабші — нижче них.</P>$B</BODY>$B</HTML>",
        [2] = "<HTML>$B<BODY>$B<H1 align=\"center\">ЗВАННЯ ОФІЦЕРІВ ОРДИ</H1><BR/>$B<P align=\"center\">Частина 1</P>$B<IMG src=\"Interface\\PvPRankBadges\\PvPRank14\" align=\"left\"/><BR/>$B<P align=\"right\">Верховний воєначальник</P><BR/><BR/>$B<IMG src=\"Interface\\PvPRankBadges\\PvPRank13\" align=\"left\"/><BR/>$B<P align=\"right\">Воєначальник</P><BR/><BR/>$B<IMG src=\"Interface\\PvPRankBadges\\PvPRank12\" align=\"left\"/><BR/>$B<P align=\"right\">Генерал</P><BR/><BR/>$B<IMG src=\"Interface\\PvPRankBadges\\PvPRank11\" align=\"left\"/><BR/>$B<P align=\"right\">Генерал-лейтенант</P><BR/><BR/>$B<IMG src=\"Interface\\PvPRankBadges\\PvPRank10\" align=\"left\"/><BR/>$B<P align=\"right\">Чемпіон</P><BR/><BR/>$B</BODY>$B</HTML>",
