[18708] = {
    en = "Petrified Bark",
    T  = "Окаменіла кора",
    pages = {
        [1] = "Симона-спокусниця:$B$BВи знайдете Симону, яка псує Кратер Ун'Горо. Не дайте себе обдурити її маскуванням. Наближайтеся до неї обережно і киньте їй виклик на бій.",
        [2] = "Клінфран Божевільний:$B$BКлінфран блукає Палаючими степами. Наближайтеся до нього з обережністю і змусьте його показати свою справжню подобу.",
        [3] = "Соленор-Вбивця:$B$BУ посушливому краю Сілітус причаївся демонічний звір — Соленор-Вбивця. Безсумнівно, він переодягнений, але, безперечно, становить небезпеку. Наблизьтеся до нього і змусьте його прийняти справжню подобу.",
        [4] = "Арторіус, Носій загибелі:$B$BАрторіус приносить розпад і загибель усьому, до чого торкається у Вінтерспрингу. Знайдіть його та вбийте.",
        [5] = "Майте на увазі, мисливцю: з цими демонами треба битися на їхніх умовах. Якщо вони відчують, що не перевершують вас, то втечуть.$B$BЙДІТЬ САМІ.",
    },
},

[18818] = {
    en = "Mor'zul's Instructions",
    T  = "Вказівки Мор'зула",
    pages = {
        [1] = "Щоб приборкати страхітливого коня, вам потрібно виконати три дії:$B$BСтворити Коло Великого Прикликання.$B$BУсередині Кола відкрити портал до Ксорота і витягнути через нього страхітливого коня.$B$BПеремогти страхітливого коня, а потім підкорити його дух.$B$BНа наступних сторінках детально описано, як виконати кожен із цих кроків. Це буде нелегко, але ти вже довів, що здатний на багато що. Я впевнений, що завдяки зосередженості та майстерності жахливий кінь стане твоїм.$B$BЧитай далі,$B-Мор'зул Кровоносець",
        [2] = "Ритуальні приналежності$B$BПерш ніж приступити до виконання завдання, вам необхідно підготувати такі магічні приналежності:$B$BГорщик Джіві$BA Чорний магнітний камінь$BКсиротійські гліфи$B$BМій слуга Горзекі надасть вам їх за певну плату. Не намагайтеся виконувати жодного етапу ритуалу, не маючи всіх цих предметів. Кожен із них є необхідним.$B$BНа наступних сторінках я опишу, як слід використовувати кожен із цих предметів.",
        [3] = "Коло Великого Зв'язування$B$BA Коло Великого Зв'язування необхідно створити в місці, де магія особливо сильна. Таке місце знаходиться глибоко в руїнах Елдре'Таласа, які також називають Дайр-Маул. В Елдре'Таласі ув'язнено істоту великої сили, Іммол'тара; саме на п'єдесталі його в'язниці ви повинні провести ритуал для створення Кола.$B$BПробийтеся до п'єдесталу, а потім випустіть Джі'іві з його глечика.",
        [4] = "Дзвін, Колесо та Свічка$B$BПісля звільнення Джіві він розмістить Дзвін, Колесо та Свічку, і з’явиться коло. Це початок ритуалу. Ви повинні бути пильними; згадані вище предмети проводять величезні потоки енергії і схильні до виходу з ладу. Коли це трапиться, ви повинні швидко використати свій Чорний магнітний камінь, щоб перезапустити їх, перш ніж весь ритуал зазнає невдачі.$B$BЯкщо всі три предмети вийшли з ладу до того, як ви зможете їх перезапустити, то ваш ритуал закінчується, і вам доведеться починати його заново.",
        [5] = "Окрім того, що дзвін, колесо та свічка спрямовують енергію ритуалу, вони також мають власні унікальні властивості.$B$BДзвін Детмури, коли дзвенить, наділяє чаклунів у колі силою та енергією.$B$BКолесо Чорного Походу, обертаючись, захищає тих, хто перебуває в колі, від небезпеки.$B$BSвічка Судного дня, горіючи, направляє надприродну енергію на ворогів, які входять у коло.$B$BЗавдяки цим благословенням дуже важливо підтримувати дію всіх цих предметів протягом усього ритуалу.",
        [6] = "Також слід зазначити, що «Чорний магніт», який використовується для перезапуску «Дзвону», «Колеса» або «Свічки» у разі їхньої несправності, потребує осколків душі. Кожного разу, коли ви перезапускаєте ритуальний предмет за допомогою магніту, витрачається один із ваших осколків душі, тому перед початком ритуалу переконайтеся, що у вас є їхній значний запас.",
        [7] = "Завершення ритуалу$B$BВи можете відстежувати свій прогрес за допомогою магічних рун, розташованих по краю кола. Коли з’являться дев’ять рун, ритуал буде завершено, і ви побачите, як енергія піднімається з щойно наділеного силою кола.$B$BПісля цього ви зможете закликати ксоротські гліфи, відкрити портал у Ксорот і витягнути крізь нього страхітливого коня.$B$BПереможіть страхітливого коня та звільніть його дух. Вступите в сутичку з духом — він буде підкорений, а ви отримаєте в нагороду таємницю його виклику.",
    },
},

[19483] = {
    en = "Peeling the Onion",
    T  = "«Розбираючи цибулину»",
    pages = {
        [1] = "«Розкриваючи таємниці»: Посібник із розгрому «Штормпіка» — автор: Дрек’Тар. На цих сторінках ви знайдете багатий масив знань про бойові тактики та політику. Освічений воїн — це той, хто спирається на досвід. Нехай ця книга стане вашим провідником у битві за Долину Альтерака.",
        [2] = "Розділ 1 — Лінія фронту Розгром армії «Штормпайк» дуже нагадує чищення цибулі. Щоб дістатися до серцевини, спочатку треба зняти зовнішні шари. Передня лінія, що складається переважно з альпіністів «Штормпайка» та вартових Альянсу, пов’язана з бункером капітана. Саме капітан Балінда Стоунхарт надає цим підрозділам сили та забезпечує підкріплення, коли лінія оборони опиняється в облозі. Знешкодьте капітана — і сили передньої лінії розсиплються.",
        [3] = "Розділ 2 — Близнюкові вежі Не помиліться: Ванндар Штормпайк — хитрий супротивник і аж ніяк не дурень. Після прориву лінії фронту необхідно ще знищити другорядні оборонні об’єкти. Це Близнюкові вежі Стоунхарт та Айсвінг, які керують Стражами Штормпайка за межами Дун-Балдара та патрулями Штормпайка.",
        [4] = "Будь обережним, солдате, адже обидві ці вежі добре укріплені й перебувають під командуванням одного з елітних командирів Ванндара. Якщо твої війська прорвуть укріплення, переконайся, що командира, який перебуває всередині, було… знешкоджено. Це також стане частиною операції з ліквідації «Штормпайка».",
        [5] = "Розділ 3 — Чотири командири Третій шар «цибулини» Штормпайка складається з чотирьох командирів. У цьому плані Ванндар наслідував наші славетні оборонні споруди «Морозних вовків». Звісно, він скаже вам зовсім інше… Але я відволікся. Чотири командири керують рухом «Стражів Штормпайка», які запекло захищають Дун-Балдар. Знешкодьте їх усіх — і «Стражі Штормпайка» впадуть. Тоді залишиться зняти лише один шар.",
        [6] = "Розділ 4 — Бункери Дун-Балдар. Як ви, безсумнівно, помітили, оборонні лінії «Штормпайк» створені для того, щоб запобігти знищенню всієї армії одним потужним ударом. Перш ніж ви запитаєте: так, саме так розставлені наші власні сили, і ні, я не змінюватиму нашу оборонну структуру. Вони нас скопіювали, тож чому ми маємо щось змінювати?",
        [7] = "На чому я зупинився? Так, отже, бункери Дун-Балдара (які розташовані в Дун-Балдарі) контролюють «Захисників Штормпайка» — найнадійніші та елітні охоронні підрозділи Ванндара. Зруйнуйте ці дві вежі, і підкріплення, відправлене на допомогу Ванндару, перестане існувати.",
        [8] = "Епілог. Зробивши все це, ви опинитеся перед самою серцевиною цибулини: солодким ядром. Ванндар Штормпайк залишиться беззахисним і самотнім. Правила військової поведінки вимагають, щоб ми запропонували йому здатися, перш ніж приступити до страти. Не забудьте згадати про цю пропозицію, коли побачите його... а потім вбийте його.",
    },
},

[19484] = {
    en = "The Frostwolf Artichoke",
    T  = "Артишок «Фроствулф»",
    pages = {
        [1] = "«Артишок Фростволфів»: Оповідання про славу Штормпайка$B — Автор: Ванндар Штормпайк$B$BЩо таке «Фростволфи»? Відповідь проста: «Фростволфи» — це дикуни, які намагаються зупинити наш суверенний імперіалістичний порив.$B$BПодібно до артишоку, «Морозні вовки» мають колючий, захищений набір оборонних механізмів, і, як і у артишоку, коли зовнішній шар знято, оголюється серцевина, готова до вживання з вишуканим часниковим соусом.$B$BСмакота!",
        [2] = "Розділ 1 — Лінія фронту$B$BLінія фронту оборонних позицій «Морозних вовків» складається з воїнів «Морозних вовків». Воїни висуваються на передову з фортеці капітана Галвангара — гарнізону «Крижана кров». Найефективніший спосіб прорвати цей рівень оборони — знищити гарнізон «Крижана кров».$B$BОточіть фортецю та знищіть капітана Галвангара. Після цього передова лінія оборони впаде.",
        [3] = "Розділ 2 — Айсблад і Тауер-Пойнт$B$BПісля знищення першого шару відкриється другий шар «артишоку». Знищення веж «Морозних вовків», розташованих поблизу лінії фронту, паралізує діяльність легіонерів та патрулів, що заполонили тил.$B$BВежі добре укріплені, у кожній з них перебуває один з елітних командирів Дрек'Тара. Їх необхідно вбити. Це прискорить руйнування оборонних споруд «Морозних вовків».",
        [4] = "Розділ 3 — Чотири командири$B $BЯкщо ви дотримувалися порад цього посібника, то на цей момент двоє командирів Дрек'Тара вже мертві. Гарна робота, солдате! Їхня рішучість уже слабшає. Тепер ти повинен завершити знищення ланцюга командування, вбивши двох командирів, що залишилися.$B$BКоли всі чотири командири будуть вбиті, легіонери «Морозних вовків», які охороняють фортецю «Морозних вовків», розбіжаться — залишившись без командування. Вони — легка здобич!",
        [5] = "Розділ 4 — Східна та Західна вежі Морозних Вовків$B$BТепер між вами та перемогою стоїть лише один рівень; найнадійніші та найпотужніші бойові підрозділи Дрек'Тара — Стражі Морозного Вовка.$B$BСтражі Морозного Вовка висуваються з взводів, що перебувають у резерві в східній та західній вежах Морозного Вовка. Зруйнуйте ці вежі, і ви побачите, як решта Стражів Морозного Вовка втече з ганьбою.",
        [6] = "Епілог$B$B\"Змастіть серце артишоку часниковим маслом і майонезом. Доповніть страву витриманим, міцним елем.\"$B$BДрек'Тар тепер стоїть сам, а поруч із ним — його дві дворняги. Захопіть притулок «Фроствольф», щоб полегшити собі битву та знищити Дрек'Тара. Коли генерал загине, ця земля нарешті перейде до свого законного власника — «Штормпайка».",
    },
},

