[20405] = {
    en = "Decoded Tablet Transcription",
    T  = "Розшифрований текст з таблички",
    pages = {
        [1] = "День 1$BНаше паломництво завершилося. Ми нарешті дісталися Сілітуса, де маємо налагодити контакт. Ми прибули з різних куточків світу, щоб об’єднати зусилля в цій грандіозній справі.$B$BУ повітрі витає неймовірне відчуття хвилювання. Завтра ми присвятимо всю свою енергію створенню того, що дозволить нам спілкуватися з НИМИ.$B$BЗавтра ми побудуємо вітровий камінь!",
        [2] = "День 2$BМісцезнаходження «вітряного каменю» є предметом бурхливих дискусій. Навіть наймудріші з нас не можуть з повною впевненістю визначити, де саме розташоване місце, згадане в стародавньому пророцтві.$B$BЯ залишився з первісною північною групою, і час, безсумнівно, доведе нашу правоту. Твердження про те, що енергетичні лінії перетинаються в цьому місці під шкідливими кутами, є безглуздими та наївними.$B$BМи вже з великою швидкістю збираємо необхідні будівельні матеріали.",
        [3] = "15-й день$BНаша наполегливість принесла свої плоди. Ми — перший табір, який завершив будівництво вітрового каменю. Якби ті інші дурні залишилися з нами, ми б виконали це завдання менш ніж за тиждень!$B$BЗавтра ми розпочнемо ритуали, пов’язані з викликом самого барона Казума. Він вимагав бути першим, хто випробує систему, і ми не могли йому суперечити, бо він дуже запальний.$B$BСподіваюся, він буде нами дуже задоволений.",
    },
},

[20415] = {
    en = "The War of the Shifting Sands",
    T  = "Війна мінливих пісків",
    pages = {
        [1] = "З часу «Війни рухомих пісків» минуло майже тисяча років. Саме під час цієї війни, у самому серці пустелі Сілітус, на Фандрала Стагхелма обрушилася велика трагедія та ще більший тягар. Вважається, що саме описані тут події зрештою сформували неприємний характер архідруїда.",
        [2] = "Колись давня розумна раса інсектоїдів, відома як Кіраджі, боролася за панування над значною частиною Калімдора. Саме пихатий імперіаліст Стагхельм та його армія нічних ельфів вступили з Кіраджі у відкриту битву.",
        [3] = "Батько й син запекло боролися, намагаючись стримати наступаючу хвилю рою комахоподібних у Сілітусі. З фортеці Ан’Кірадж, здавалося б, нескінченний потік силітидів продовжував поповнювати ряди військ-загарбників Кірадж. Весь Сілітус перебував у облозі.",
        [4] = "У результаті рішення, про яке Стагхельм згодом пошкодує, молодшому Стагхельму, Валстанну, було наказано захищати форпост нічних ельфів — Село Південного Вітру. На жаль, того дня Валстанн загинув, а Село Південного Вітру впало під натиском військ Ан’Кіраджа.",
        [5] = "Незважаючи на все це і з важким серцем, спраглий помсти Фандрал Стагхельм продовжував рухатися вперед. Поразка в Сілітусі могла призвести до величезних втрат для нації нічних ельфів і, цілком можливо, для всього світу.$B$BБитва тривала місяцями. Весь Сілітус був захоплений кіраджі. Стагхельм і його армія були відтіснені до Танарісу. Зі знекровленою армією та незліченною кількістю вбитих невинних людей зарозумілість, яка рухала Фандралом Стагхельмом, була повністю знищена.",
        [6] = "Його гордість була повністю розбита. Стагхельм удруге за своє життя відчув те тремтіння в глибині шлунка, яке могло бути викликане лише страхом. Саме в Танарісі Стагхельм підійшов до Анахроноса, нащадка Ноздорму, і благав про допомогу Бронзового Польоту.",
        [7] = "Спочатку Анахронос відмовився втягувати «Бронзовий полк» у справи нижчих рас. Лише після того, як кіраджі зухвало напали на Печери Часу, Анахронос погодився об’єднати сили з нічними ельфами.",
        [8] = "Анахронос незабаром усвідомив, що навіть могутній Бронзовий Політ не здатний стримати натиск військ-загарбників Кіраджі. На кожні п’ятдесят комах, знищених його диханням, сто інших вже чекали, щоб зайняти їхнє місце. Оскільки лінії нічних ельфів слабшали, а загроза відступу ще далі на північ, у дикі землі Фераласу, ставала дедалі реальнішою, Анакронос вирішив, що діти Аспектів повинні бути про це поінформовані.",
        [9] = "Спочатку він звернеться до Драконячого зграї Ісери. На його заклик відгукнеться Мерітра зі Сну, а від неї про це дізнаються Драконячі зграї Алексстрази та Малігоса.",
        [10] = "Дракони збиралися у стратосфері високо над Сілітусом: за тисячі футів над фортецею Ан’Кірадж.$B$BТам був Анакронос, син Ноздорму, Аспекта Часу.$B$BЗі Смарагдового Сну прибувала Мерітра, дочка Ісери, Аспекту Природи.$B$BКаелестраз, син Алексстрази, Аспекту Життя, представляв Червоний Драконячий Політ.$B$BАригос, син Малігоса, Аспекта Магії, представляв Блакитний Драконячий Політ.",
        [11] = "Дракони спостерігали, як з Ан’Кіраджа виривався нескінченний потік силітидів і кіраджі. Їм стало ясно, що жодна сила ніколи не зможе покласти край цій війні. Усередині головного храму чекали десятки тисяч військ кіраджі. З кожною секундою вилуплювалося й готувалося до бою все більше істот, готових вирватися у світ.",
        [12] = "Аригос першим помітив дивні випромінювання. Монолітний храм у південному квадранті Ан’Кіраджа випромінював тьмяну магію, яка не схожа була на те, що вони відчували від Кіраджі. Як би вони не намагалися, нікому не вдалося проникнути глибше в храм, щоб знайти джерело цієї енергії. Лише щось надзвичайно могутнє могло так повністю захистити себе. Можливо... щось, що керує комахами. Щось, що керує навіть кіраджі.",
        [13] = "Дракони розуміли, що їм треба діяти швидко, щоб світ не зазнав чергової грандіозної катастрофи. Після ретельного обговорення було вирішено, що найкращим варіантом буде зупинити армії загарбників безпосередньо у місці їхнього походження або поблизу нього.",
        [14] = "Буде створено могутній бар'єр, що черпатиме силу з сутності як нічних ельфів, так і драконівського полку. Магічний бар'єр, здатний утримати силітидів та їхніх повелителів у стінах Ан'Кіраджа й запобігти майбутнім вторгненням. Сам Ан'Кірадж стане в'язницею.",
    },
},

