[20552] = {
    en = "Decoded Twilight Text",
    T  = "Розшифрований текст «Сутінок»",
    pages = {
        [1] = "Для негайного поширення серед усіх членів «Молота Сутінків».$B$BНижче наведено інформацію щодо використання вітрових каменів для зв’язку з нашими господарями з Ради Безодні.$B$BБудь-яке необґрунтоване використання вітрових каменів каратиметься найболіснішим чином.$B$B—Хранитель Сутінків Хавунт",
        [2] = "Темплари Безодні$B$BЯк новачок, вам дозволено встановлювати контакт із Темпларами Безодні для проведення звичайних ритуалів. Пам’ятайте, що під час використання вітрових каменів завжди слід одягати відповідне вбрання, щоб уникнути активації наших захисних чар.$B$BУ разі виникнення непередбаченої надзвичайної ситуації за відсутності наглядачів вам надається дозвіл на виклик Абісального тамплієра.$B$BДетальнішу інформацію щодо відповідних ритуалів виклику дивіться у випуску «Істинного віруючого» за минулий місяць.",
        [3] = "Герцоги Безодні$B$BЛише аколити, які мають медальйон свого звання, мають право встановлювати контакт із  Герцогами Безодні. Медальйони рангу можуть використовуватися лише тими особами, яким вони були спочатку видані.$B$BЧлени «Молота Сутінків», причетні до несанкціонованого спілкування з Абісальними герцогами або до несанкціонованого використання медальйонів рангу, будуть покарані мною особисто.",
        [4] = "Верховна Рада Володарів Безодні$B$BЛише Володарі Сутінків мають право звертатися до принца Скалдренокса, Верховного маршала Вірлаксіса, барона Казума або лорда Сквола.$B$BНі за яких обставин членам «Молота Сутінків» нижчого рангу не дозволяється ініціювати спілкування з Верховною Радою.  Будь-які сторонні особи, яких викриють у використанні вітрового каменю з цією метою, будуть на місці перетворені на попіл.",
    },
},

[20676] = {
    en = "Decoded Twilight Text",
    T  = "Розшифрований текст «Сутінок»",
    pages = {
        [1] = "«Стан культу», том 92$B$BЗ радістю у серці вітаю вас, мої брати, адже стан нашого культу не міг би бути величнішим. Ми — легіон, і наші цілі дедалі ближче до втілення.$B$BНові рекрути продовжують збиратися. Вони співають хвалу нашим володарям у Темному Березі, схиляються в радісному замилуванні в Палючому Ущелині, обіймають слугу наших господарів, Аку’маї, у Чорноглибинних безоднях. Справді, мої брати й сестри, незабаром рой віруючих покриє весь Азерот!",
    },
},

[20677] = {
    en = "Decoded Twilight Text",
    T  = "Розшифрований текст «Сутінок»",
    pages = {
        [1] = "«Стан культу», том 127$B$BЦе справді щасливий день!  Нас випробували в Сілітусі, і ми витримали випробування!$B$BЗвістки про знищення нашого найпівнічнішого табору можуть похитнути віру невірних, але цю різанину не слід розглядати як трагедію. Ні!",
        [2] = "Пролиття нашої крові одним із членів Вищої ради Безодні — це благословення! Ми маємо заздрити нашим полеглим товаришам, адже їхні душі тепер мешкають у череві найправеднішої звірини!$B$BСлава Старим Богам! Слава їхнім слугам! Слава «Молоту Сутінків»!",
    },
},

[20678] = {
    en = "Decoded Twilight Text",
    T  = "Розшифрований текст «Сутінок»",
    pages = {
        [1] = "«Стан культу», том 233$B$BМожливість знову стукає у двері, мої брати та сестри! «Коло Сенаріона» — огидний культ шанувальників природи — тепер направляє проти нас своїх агентів. Мабуть, вони хочуть завадити нам викликати червоні приваблюючі камені. Ми не можемо цього допустити!$B$BЧервоні камені мають вирішальне значення для наших нових союзників. Ми не повинні дозволити посіпакам «Круга Сенаріона» досягти успіху. Тримайтеся міцно, мої вірні друзі. Тримайтеся міцно!",
    },
},

[20679] = {
    en = "Decoded Twilight Text",
    T  = "Розшифрований текст «Сутінок»",
    pages = {
        [1] = "Звідки ми знаємо, що вони нас люблять?$B$BДехто може замислитися над тим, як Старі Боги та їхні слуги можуть нас любити. Хіба вони не вбивають нас? Хіба вони не завдають болю та страждань усім? Як істоти, настільки схильні до злоби, можуть знати любов у своїх серцях?$B$BНа це питання є проста відповідь. Настільки проста, що її навіть не потрібно вимовляти?",
        [2] = "Віра. Віра — це джерело, з якого на нас ллється радість служіння. Віра зігріватиме нас у найхолодніші ночі Сілітуса. Віра збереже нам прихильність наших Господів, коли настануть Останні Дні.$B$BВіра врятує нас.",
    },
},

