[21130] = {
    en = "Diary of Weavil",
    T  = "Щоденник Вівіла",
    pages = {
        [1] = "Дорогий щоденнику,$B$BСьогодні мій заклятий ворог, Нарайн Сутфансі, спробував обдурити мене, відправивши своїх поплічників, щоб ті зайняли його місце на страті. На ЙОГО страті. Ти можеш у це повірити?$B$BЯ доклав стільки зусиль, щоб придумати цей диявольський план, аби виманити його з тієї проклятої халупи, а він робить таке? Та що там... Занадто злий, щоб продовжувати писати. Повернуся пізніше.",
        [2] = "Дорогий щоденнику,$B$Після останнього запису я у гніві покинув свою схованку. Ой, як же я розлютився! Я вирішив переробити форму своїх підлеглих, щоб вона краще відображала мою тривогу. Мені трохи полегшало, але чогось все ж бракує. Я зараз повернуся...",
        [3] = "Дорогий щоденнику,$B$BОкей, тепер я в порядку. Я побив одного зі своїх підлеглих, поки він не заплакав, як маленька дівчинка.$B$BХм... Тепер мені трохи не по собі. Хвилинку! Чорт забирай, я ж ЗЛИЙ геній! Злий, розумієш? Я так розчарований у собі. Зараз повернуся.",
        [4] = "Дорогий щоденнику,$B$BЯ обійняв його і сказав, щоб він і далі так тримав. Тепер мені краще. Нехай це залишиться між нами, щоденнику.$B$BНа чому я зупинився? Ах так, НАРАЇН! АРГХ!!! Ненавиджу цього хлопця. Адже саме Нараїн зіпсував мені оцінки на кожному іспиті, коли ми ще навчалися в Інституті майстрування Гномерегана.$B$BВони що, хочуть, щоб мене відрахували зі школи? Що стосується мене, то Гномереган отримав те, на що заслуговував!$B$BНа сьогодні все. Спи спокійно, щоденнику!",
        [5] = "Дорогий щоденнику,$B$BI, мабуть, я старію. Я зовсім забув, що розповідав тобі про Нараїна та його обман. У будь-якому разі, я так розлютився, коли замість Нараїна побачив підставну особу, замасковану під нього, що наказав Другому знищити цього дурня!$B$BI сів у свій літальний апарат і почав рвати на шматки його дорогоцінну, дурну, безглузду книжку про драконівську мову. Що за позер? Хто взагалі читає драконівську мову? Я його так ненавиджу!",
        [6] = "Дорогий щоденнику,$B$BВибач, я заснув. Отже, я летів у гніві й викидав розділи тієї дурної книги. Я побачив під собою в Дарквіспері демона й вирішив, що перший розділ утворить магічний паперовий торнадо, який розірве його тіло на мільйон шматочків! Це було так звільняюче. Магія + папір = веселощі.$B$BЦе мене дуже порадувало, тож я вирішив полетіти до Східних Королівств. Моєю першою зупинкою стало Розплавлене Ядро. Нараїн завжди розповідав про це місце! «Розплавлене Ядро те, Рагнарос се...»",
        [7] = "Ну, знаєш що? Якщо йому це так подобається, то, можливо, йому сподобається спробувати зібрати свою книгу до купи, відправившись до Розплавленого Ядра й відродивши розділ із купи попелу! Ха!$B$BПоки я був у тих краях, я подумав, що деяким із тих слинявих техніків у лабораторії старого Віктора Нефаріуса ця драконяча штука може стати в нагоді. Бомби — вперед!",
        [8] = "Це починало перетворюватися на своєрідний вид спорту. Мені справді подобалося розбивати цю кляту книгу на частини!$B$BНаступні кілька частин відпали легко.$B$BАндерсіті — домівка смердючих гнилих трупів і, можливо, найкращого чилі, яке я коли-небудь куштував, — отримало один розділ. Штормовій, столиця Сиру, — іншу. Щоденнику, ти коли-небудь додавав сир із Штормовію до чилі з Підмістя? АЛО? Це мало б тебе насторожити.",
        [9] = "До цього моменту я вже втомився, тож розвернув літальний апарат і попрямував додому, але не без того, щоб зробити ще дві зупинки. Я пролетів повз лорда Каззака та його демонів у «Заплямованій шрамі» (він ненавидить, коли я так роблю) і засунув ще одного в димар Оніксії.$B$BВтомився. Йду спати.",
    },
},

[21142] = {
    en = "From the Desk of Lord Victor Nefarius",
    T  = "З робочого столу лорда Віктора Нефаріуса",
    pages = {
        [1] = "До уваги всіх, кого це може стосуватися,$B$BЯк же я люблю ці ігри, в які ми граємо. $B$BМожу лише припустити, що якщо ви читаєте цей лист, то вам якимось чином — чи то завдяки диву, чи то завдяки божественному втручанню — вдалося перемогти мене. Я знаю, це абсурдно, але в історії цього світу траплялися й дивніші речі.",
        [2] = "Як і у всьому в житті, у цій сумній історії є свій чудовий, срібний промінь надії серед трагедії, хаосу та зла. Хоча ти й убив мене, ти зробив це настільки повільно й безладно, що я встиг написати цей лист ПІСЛЯ того, як знищив твою єдину надію на порятунок цього світу. Подрібнений червоний кристалічний порошок — це все, що залишилося від уламка твого скіпетра.",
        [3] = "Насолоджуйтесь зброєю «Немезіс» та «Штормрейдж», яку ви можете знайти в моїй скарбниці. Повірте мені на слово: я відчуваю велике задоволення від усвідомлення того, що зробив те, чого не зміг зробити мій батько...$B$B$BS З повагою,$B$BLорд Віктор Нефаріус$B\"Нефаріан\"",
    },
},

[21314] = {
    en = "Metzen's Letters and Notes",
    T  = "Листи та нотатки Метцена",
    pages = {
        [1] = "Від імені «Смоківуд Пастерс» ще раз дякуємо за те, що взялися за цю справу. Ми не впевнені, яка саме група утримує Метцена, але розслідування обох варіантів буде гарним початком!$B$BЧас — це гроші, друже, а в цій справі його у нас дуже мало.  Дійте швидко, щоб врятувати заручників, адже не варто недооцінювати можливості цих угруповань.$B$BУ будь-якому разі, на наступних двох сторінках наведені листи з вимогами викупу, які ми отримали.  Удачі...",
        [2] = "Якщо хочеш повернути оленя живим, то поспіши з викупом.  Пірати Південного моря не терплять затримок із виплатами, а ми знаємо, наскільки цінна ця тварина для ВАШОГО виду піратства.$B$BПринесіть суму в 1000 золотих до входу в бухту Загубленого Рігера в Танарісі.  Будь-яка спроба врятувати оленя призведе до того, що Метцену доведеться пройти дуже довгу дорогу з дуже короткої дошки.$B$BЕ-е-е...$B$BПірати Південного моря",
        [3] = "Вашому улюбленому вихованцеві не дуже добре тут, у нестерпній спеці Палючого Ущелини… Вам буде розумніше без зволікання виконати наші вимоги.$B$BВи принесете нам п’ять зіркових рубінів та 700 золотих — покладіть усе в один простий пакунок без будь-яких позначок.  Залиште пакунок біля воріт Перевалу Кам'яної Кузні протягом тижня.$B$BЯкщо ви не виконаєте наші вимоги, Метцен стане головною стравою на традиційному бенкеті темнозалізних гномів з нагоди Зимової Завіси.$B$BMммм... олені...",
        [4] = "Швидше за орлів мчали його коні,$B$BІ він свистів, кричав і кликав їх по імені;$B$B«Ну ж бо, Мерсер! ну ж, Чілтоне! ну ж, Джордане й Каплане!$B$BВперед, Наглі! вперед, Пардо! вперед, Гудмане й Метцені!$B$BНа верхівку ганку! на верхівку стіни!$B$BТепер мчіть! мчіть! мчіть усі!\"$B$B",
    },
},

[22344] = {
    en = "Brazier of Invocation: User's Manual",
    T  = "«Жаровня заклинань»: Посібник користувача",
    pages = {
        [1] = "«КОЧІГ ДЛЯ ЗАКЛИКАННЯ»: ІНСТРУКЦІЯ З ЕКСПЛУАТАЦІЇ$B$BДе знайти місця, що переслідують привиди$B$BВСТУП$B$BНа цих сторінках наведено місця перебування занепалих і зіпсованих духів та душ, причетних до «Інциденту з амулетом» лорда Валталака. Хоча ви вже врятували цих моїх колишніх супутників, я припускаю, що огидні відгомони зла, яке колись спотворило їхні душі, досі витають у цих місцях, де блукають привиди. Такою була злісна сила духу лорда Валталака.$B$BКрім того, жаровню можна використовувати для виклику лорда Валталака, хоча, як і раніше, при цьому слід дотримуватися надзвичайної обережності.",
        [2] = "ВСТУП, продовження...$B$BСам жаровня працює так само, як і «Жаровня, що кличе». Просто розмістіть його в межах дії будь-якого з п’яти місць, де блукають привиди, і він викличе духів померлих.$B$BДо речі, оскільки я знаю, що вам буде цікаво це дізнатися, «Прапор провокації» можна використовувати подібним чином на арені в Глибинах Чорної Скелі. Не забудьте провчити Телдрена та його посіпак від мого імені щоразу, коли у вас випаде така нагода, коли ви там будете.$B$BПродовжуйте читати, якщо бажаєте отримати більше інформації.",
        [3] = "ІСАЛІЕН$B$BЖриця Місяця з народу нічних ельфів$B$BКоли Ісаліен вирішила покинути загін, вона зробила це з наміром здійснити паломництво до Діре-Маула — занепалого прадавнього міста нічних ельфів, яке колись називалося Елдре’Талас. Там досі стоїть бібліотека величезних знань — святилище, яке невеликій групі нічних ельфів вдалося вберегти від руйнування. Вона була рішуче налаштована знайти відповіді як щодо свого походження, так і, можливо, щодо уламків амулета. Варто зазначити, що вона також була доброю подругою Фалріна Трешшепера.",
        [4] = "ІСАЛІЕН, продовження...$B$BНа жаль, коли вона разом зі своїм супутником-гіпогрифом Емпіреаном в’їжджала до міста, на них напав Алззін Дикий Творець та його поплічники. Там вона впала, щоб більше ніколи не підвестися. Можливо, це й на краще, що Ісаліен так і не розкрила жодних інших таємниць злої магії, яку лорд Валталак застосував, щоб утримати частину своєї сутності в амулеті.$B$BВідкрита зала, де мешкає Альзін, є одним із таких місць, де блукають привиди.",
        [5] = "МОР ГРЕЙХУФ$B$BДруїд-таурен і перший, хто загинув$B$BMор Грейхуф завжди був надійним і вірним товаришем у лавах «Завуальованого меча». На жаль, саме він першим загинув від рук злих поплічників лорда Валталака.$B$BКоли ми тікали від Валталака, нас переслідувала справжня армія його примарних вбивць і переслідувачів. Втеча з Шпиля Чорної Скелі була, м'яко кажучи, хаотичною. На жаль, по дорозі Мор якимось чином втратив рівновагу, хоча я підозрюю, що його штовхнули. У будь-якому разі, він впав у глибини нижньої частини вежі.",
        [6] = "МОР ГРЕЙХУФ, продовження...$B$BПізніше ми дізналися, що Мор насправді вижив після падіння. Але для мого доброго друга щасливого кінця не судилося: його взяли в полон тролі з Тазза’Алаора. Незабаром після цього, коли його катував воєнний магістр Вун, група вбивць Валталака втрутилася й довершила справу.$B$BЯкщо ви хочете викликати відлуння духу Мора Грейхуфа, то камера воєнного магістра Вуна — це місце, де блукають привиди.",
        [7] = "ДЖАРІЕН І СОТОС$B$BБрати і сестри, які прагнули стати членами «Скарлетного хрестового походу»$B$BДжарієн і Сотос були двома з найбільш нетерпимих людей, яких я знав. Проте їхні бойові навички були винятковими, до того ж вони походили з заможної родини, і, мабуть, саме тому Антіон, лідер «Завуальованого меча», тримав їх у своїх лавах.$B$BЗрештою брати й сестри захопилися вченням та філософією «Скарлатового хрестового походу». Вони завжди виявляли певний запал у знищенні будь-яких представників «Покарання», з якими ми стикалися під час наших подорожей, і існували підозри, що їхня родина мала зв’язки з цією організацією.",
        [8] = "ДЖАРІЕН І СОТОС, продовження...$B$BОтож так вони опинилися перед випробуваннями, які повинні пройти ті, хто прагне приєднатися до Хрестового походу. Особливий інтерес для них представляло отримання звання лицаря в лавах походу — це, судячи з усього, вимагало проходження більш складних випробувань. Адже згодом з’ясувалося, що Сотос насправді не пройшов своє останнє випробування. Однак Джарієн не могла з цим змиритися і, відкрито кинувши виклик, наполягала, щоб його прийняли до лав лицарів разом із нею. З того, що нам вдалося з’ясувати, Великий хрестоносець Датрохан вбив їх обох прямо на місці, посеред своїх покоїв.$B$BОтож ще одним із таких місць, що переслідують привиди, є «Багряний трон» у «Скарлатовому бастіоні» в Стратхолмі.",
        [9] = "КОРМОК$B$BДвоголовий огр-некромант$B$BЩо можна сказати про Кормока? Він був двоголовим огро-чарівником, який раніше не був таким вже й поганим. Коли ми вперше взяли його до себе, він був полоненим під час одного завдання, яке ми взяли на себе в Палаючих степах. Однак він виявився незамінним, допомогаючи нам вибратися зі скрутного становища, в яке ми там потрапили, і тому став одним із провідних магів нашої компанії.$B$BДивним у ньому було те, що його дві голови мали абсолютно різний характер. Одна завжди була веселою, хоч і трохи дурнуватою, тоді як інша — хитрою, розважливою, з майже мертвим поглядом. Це було справді трохи моторошно.",
        [10] = "КОРМОК, продовження...$B$BПізніше, під час наших мандрівок, Кормок познайомився з некромантичною стороною магії. На жаль, ця моторошна голова виявила схильність до воскресіння мертвих духів і отримувала від цього збочне задоволення, особливо від виклику вигнаних духів Острова Очищення, щоб вони виконували його накази.$B$BПісля розпаду компанії Кормок вступив до Школомансу, щоб продовжити свою «освіту». Примарним вбивцям було надто легко проникнути до школи, і вони вбили його прямо на очах у його нового наставника, Раса Фроствіспера.$B$BЦе робить кабінет Раса Фроствіспера одним із місць, де блукають привиди, і де можна успішно використати жаровню.",
        [11] = "ЛОРД ВАЛТАЛАК$B$BДраконідський аристократ і колишній генерал Шпиля Чорної Скелі$B$BДо генерала Драккісата був лорд Валталак — драконідський чаклун, що володів величезною силою. Зміна керівництва Шпиля — звичайна справа, і, на наше нещастя, нам судилося взяти участь у черговій зміні влади.$B$BНас найняв гоблін-чарівник-контрабандист із Буті-Бей, Гремнік Різлспранг, щоб викрасти книгу заклинань Валталака. Ми не знаємо, чи хотів він її вивчити, чи продати (а може, й те, й інше), але зараз це вже не має значення. Важливо те, що ми проникли у верхні поверхи Шпиля Чорної Скелі й убили лорда Валталака в його лігві. Ось тоді й почалася справжня веселість.",
        [12] = "ЛОРД ВАЛТАЛАК, продовження...$B$BМи й гадки не мали про глибину магічних знань Валталака в галузі маніпуляції душами, інакше, мабуть, ніколи б не погодилися на це завдання. Але ми все-таки погодилися, і це виявилося останнім завданням, яке ми коли-небудь виконували.$B$BУбивши лорда Валталака й забравши його книгу заклинань, Кормок, мабуть, відчув щось особливе в його амулеті. Він наполягав на тому, щоб забрати його як свою частку здобичі, що швидко переросло у запеклу суперечку, а то й майже бійку, через цю річ. Тоді ми ще не знали, що в амулеті насправді містилася значна частина духу Валталака; ми дізналися про це пізніше, на наше велике незадоволення.",
        [13] = "ЛОРД ВАЛТАЛАК, продовження...$B$BRозбивши амулет на шматки, ми втекли від щойно воскреслого привида Валталака, а також від його армії примарних вбивць. А галас, який ми зчинили, борючись за амулет, розбудив чимало захисників, що залишилися у Шпилі!$B$BМайже всім нам вдалося вибратися з Чорної Скелі, і ми думали, що в безпеці. Але навіть з потойбіччя Валталак посилав на нас своїх поплічників, куди б ми не ховалися. Після тієї місії «Завуальоване Лезо» незабаром розпалося, і тоді ми стали справді легкою здобиччю.$B$BЯк ви, мабуть, знаєте, це робить оселю лорда Валталака — те, що зараз є «Палатою Звіра» у Шпилі Чорної Скелі, — останнім із місць, де бродять привиди.",
    },
},

[22595] = {
    en = "Call to Arms Announcement",
    T  = "Оголошення про мобілізацію",
    pages = {
        [1] = "До всіх працездатних чоловіків і жінок:$B$B«Скорб» повернувся, і ми мусимо відкласти наші суперечки, щоб протистояти цій загрозі. «Срібний Світанок» не відмовить нікому, хто бажає взяти до рук зброю проти загрози «Порази».$B$BТі, хто готовий захищати наші землі, збираються біля каплиці «Надія Світла» у Східних Землях Чуми. Разом ми переможемо.$B$BХранитель Реєстрів$B«Срібний Світанок»",
    },
},

[22930] = {
    en = "A Bloodstained Envelope",
    T  = "Заплямований кров’ю конверт",
    pages = {
        [1] = "Моя Емілі,$B$BКілька днів тому ми згорнули табір у цьому місці, покинутому Світлом, виконуючи наказ Короля повернутися додому. Незважаючи на похмуре оточення, моє серце було легким, бо я знав, що після морозного походу до берега та довгої, виснажливої подорожі я знайду розраду в твоїх обіймах.$B$BСьогодні ми дісталися берега, щоб побачити, що наші кораблі — наш засіб повернення — стали лише обвугленими руїнами; ми не можемо виїхати і не маємо іншого вибору, як просуватися далі вглиб цієї жахливої пустки.$B$BЯ дійшов до самого краю світу, щоб захистити тебе, Емілі... а тепер... Я всім серцем бажаю, щоб я залишився в Лордаероні разом з тобою.$B$BДумки про тебе заповнюють кожну мить мого життя. Ти — моє тепло на цій замерзлій землі, кохана, і ніхто не зможе цього у мене відібрати.$B$BMаксвелл",
    },
},

[22932] = {
    en = "A Torn Letter",
    T  = "Розірваний лист",
    pages = {
        [1] = "Рубен,$B$BЯ пишу цей лист, розуміючи, що ти, можливо, ніколи його не побачиш; просто не можу сидіти склавши руки, слухаючи, як неперервно стукають по стінах Грінхеарта. Нежить оточила наше селище, не припиняючи атак, і нам доручено захищати мешканців, доки не прибуде підкріплення.$B$BПід час останньої атаки я зламав ногу, тож сиджу тут, не приносячи ніякої користі, з мечем біля себе на випадок, якщо в нашій обороні з’явиться пролом. Тут немає місця для пустослів’я… лише звуки бою та смерті. Повітря насичене страхом.$B$BПринц Артас тут, він бореться на передовій разом із воїнами. Якби його тут не було, ми б уже давно впали. Його любов до цієї землі та її народу заразна; я з радістю служу під його командуванням і буду це робити до кінця своїх днів.$B$BБої стають дедалі запеклішими; з переламаною ногою чи без неї, я не можу тут сидіти. Потрібен кожен меч.  Сподіваюся, ці слова знайдуть тебе в щасливіші часи.$B$BТвій друг,$BЛеагрем",
    },
},

[22944] = {
    en = "A Crumpled Missive",
    T  = "Зм'ята листівка",
    pages = {
        [1] = "$b$bГеліана,$b$bя, Варгус, досі живий, попри твої протилежні побажання. Я ненавиджу блукати по селах у цій безглуздій броні.$b$bЗгідно з останніми наказами, ми прямуємо до Андорхала за зерном чи якоюсь іншою нісенітницею. Чому я маю перейматися запасами продовольства саме в Андорхалі? Вся ця ідея перебування в армії — просто смішна.$b$bБудьте впевнені, тітко Геліано, що я повернуся за вашою спадщиною; навіть якщо я отримаю тяжкі поранення й залишуся без їжі, сама лише злість буде гнати мене вперед.$b$bВаргус$b$b",
    },
},

[22945] = {
    en = "A Careworn Note",
    T  = "Застаріла записка",
    pages = {
        [1] = "Найдорожча Амелія,$B$BSьогодні вночі я побачив те, що переслідуватиме мене до кінця днів.$B$BСтратхолм охоплений полум’ям... і ми несемо за це відповідальність.$B$BНаш Принц вивів нас сьогодні вночі на вулиці міста; він наказав нам вриватися в будинки містян і... вбивати їх уві сні. Вони були заражені, стверджував лорд Артас, і їх треба було вбити, перш ніж вони вб’ють нас.$B$BЦе була справжня різанина. Сотні людей безмовно загинули від мечів тих, хто присягав їх захищати. Я більше не міг цього витримати; я втік.$B$BМоже, я й дезертир, але я не міг скоїти таких звірств. У кожному домі я не міг не бачити твоє обличчя або обличчя наших дітей на обличчях жертв, коли вони вмирали. Якщо протистояти цьому означає бути зрадником, то нехай так і буде.$B$BЯ сподіваюся вчасно знайти дорогу до тебе, але дороги небезпечні. Передай нашим дітям мою любов, поки мене немає.$B$BДжеймс",
    },
},

[22946] = {
    en = "A Ragged Page",
    T  = "Пошарпана сторінка",
    pages = {
        [1] = "Самла,$B$BКоли ми слідуємо за нашим володарем Артасом на північ, все далі на північ, моє серце наповнюється тяжкістю. Хоча колись він сяяв Світлом, тепер я відчуваю, як дух молодого паладина потемнішає. Його завзяття затьмарюється задумою, пов’язаною з якимось кошмаром у його душі, який я не можу розгадати...$B$BНезабаром ми висадимося на замерзлих пустках. Хоча багато хто з його воїнів хворіє від холоду та битв із гниліючими чудовиськами, Артас каже нам, що те, чого він шукає у льодах, переламає хід битви.  Але його слова не принесли мені жодного заспокоєння, бо після того, як він їх вимовив... похмура посмішка, що застигла на його скривлених губах, охолодила мене глибше, ніж будь-яка хуртовина.$B$BMолись за нас, Самла, і молись за наш світ,$B$BTоргал",
    },
},

[22948] = {
    en = "A Smudged Document",
    T  = "Забруднений документ",
    pages = {
        [1] = "Дорога Памело,$B$BЗавтра ми дамо бій в Андорхалі, і я боюся, що це буде мій останній лист до тебе, кохана. Нежить не знає втоми, а ми, боюся, лише люди. Ми не зможемо встояти проти них.  Але не турбуйся, бо хоч ми й неминуче загинемо, наша надія залишається міцною. Світло переможе!$B$BІ, моя найдорожча, мені приносить втіху усвідомлення того, що, коли ці темні жахи штурмуватимуть наші стіни й наваляться на нас, мої останні думки не будуть про смерть.  Я думатиму про тебе в моїх обіймах, і нарешті знайду спокій.$B$BКрістоф",
    },
},

[23008] = {
    en = "Sealed Research Report",
    T  = "Закритий звіт про дослідження",
    pages = {
        [1] = "Привіт, $N. Як виявилося, мені вдалося розшукати трохи інформації з тієї записки.$B$BЩодо Джеймса, боюся, я знайшов небагато. Однак мені вдалося дізнатися дещо про родину Амелії.$B$BХоча ані вона, ані її діти не пережили війну, її брат вижив — це чоловік на ім’я Олександр Калдер; ти можеш знайти його в Печері Загублених в Айронфорзі, де він вивчає небезпечну магію Палкого Легіону.$B$BУ неї також була двоюрідна сестра, з якою вона була близька, — жінка, відома зараз як Дезе Сноубейн, яка в Оргримарі пропагує боротьбу за Аратську улоговину.$B$BВам варто відвідати когось із них, коли наступного разу опинитеся в тих краях. Я впевнений, що їм буде цікаво хоча б почути про їхню зниклу Амелію.",
    },
},

[23010] = {
    en = "Sealed Research Report",
    T  = "Закритий дослідницький звіт",
    pages = {
