[21581] = {
    en = "Aftermath of the Second War",
    T  = "Наслідки Другої світової війни",
    pages = {
        [1] = "Руйнівна Друга війна проти орківської орди залишила Альянс Лордаерона в стані шоку та розладу. Кровожерливі орки на чолі з могутнім воєначальником Оргрімом Думомхаммером не лише прорвалися крізь землі Каз-Модана, що належали гномам, а й зруйнували багато центральних провінцій Лордаерона. Неухильні орки навіть встигли спустошити віддалене королівство ельфів Кель'Талас, перш ніж їхнє буйство нарешті було зупинено.",
        [2] = "Армії Альянсу під командуванням сера Андуїна Лотара, Утера Світлоносія та адмірала Дейліна Праудмура відтіснили орків на південь, у зруйновані землі Азерота — першого королівства, яке впало під безжальним натиском орків.$B$B$B$BВійська Альянсу під командуванням сера Лотара зуміли витіснити клани Думхаммера з Лордаерона назад на контрольовані орками землі Азерота. Війська Лотара оточили вулканічну цитадель орків — Шпиль Чорної Скелі — і взяли її в облогу.",
        [3] = "У останній відчайдушній спробі Думхаммер та його заступники здійснили сміливу атаку зі Шпиля і вступили в бій з паладинами Лотара в центрі Палаючих степів. Думхаммер і Лотар зійшлися у титанічній битві, яка залишила обох могутніх бійців побитими й виснаженими. Хоча Думхаммеру й вдалося з невеликим відривом перемогти Лотара, смерть великого героя не мала того ефекту, на який сподівався вождь.",
        [4] = "Тураліон, найнадійніший заступник Лотара, підняв закривавлений щит свого командира й згуртував своїх охоплених горем побратимів для запеклої контратаки. Під пошарпаними прапорами Лордаерона та Азерота війська Тураліона знищили більшу частину решти військ Дуумхаммера у славній, але жахливій битві.",
        [5] = "Знесиленим і розрізненим оркам, що вижили, не залишалося нічого іншого, як втекти до останнього бастіону орків — Темного порталу.$B$B$B$BТураліон та його воїни переслідували решту орків через гниле Болото Скорботи аж до спотворених Зруйнованих Земель, де стояв Темний портал. Саме там, біля підніжжя колосального порталу, розбита орда та загартований Альянс зіткнулися в останній і найкривавішій битві Другої війни.",
        [6] = "Переважені чисельно та збожеволілі від прокляття кровожерливості, орки неминуче зазнали поразки під гнівом Альянсу. Думхаммер потрапив у полон і був доставлений до Лордаерону, а його розгромлені клани були зібрані й відправлені на північ — назад до Лордаерону.",
    },
},

[21582] = {
    en = "Beyond the Dark Portal",
    T  = "За Темним порталом",
    pages = {
        [1] = "Лише через кілька місяців після завершення будівництва Нетергарда енергії Темного порталу злилися й відкрили новий прохід до Дренору. Решта кланів орків під проводом старійшини-шамана Нер'жула знову увірвалися в Азерот. Маючи на меті викрасти низку магічних артефактів, які б посилили силу Нер'жула, орки планували відкрити в Дренорі нові портали, що дозволили б їм назавжди втекти зі свого приреченого червоного світу.",
        [2] = "Переконаний, що Нер'жул готував новий наступ проти Альянсу, король Лордаерона Теренас відправив свої війська до Дренору, щоб раз і назавжди покласти край загрозі з боку орків. Під командуванням Хадгара та генерала Тураліона війська Альянсу вступили в бій з орками на тлі палаючих ландшафтів. Навіть за підтримки ельфійської розвідниці Аллерії, карлика Курдрана та досвідченого воїна Даната Хадгару не вдалося завадити Нер'жулу відкрити портали до інших світів.",
        [3] = "Потужні магічні бурі, спричинені злиттям енергій порталів, почали розривати на шматки спустошений світ. Нер’жул, у супроводі лише своїх найнадійніших слуг, зумів втекти крізь один із порталів, тоді як Хадгар відчайдушно боровся, аби повернути своїх товаришів до Азероту. Усвідомивши, що вони залишаться у пастці на вмираючому світі, Хадгар та його товариші самовіддано вирішили знищити Темний портал, аби Азерот не постраждав від бурхливого руйнування Дренора.",
        [4] = "Судячи з усього, героям вдалося знищити портал і врятувати Азерот — але чи вдалося їм врятуватися від агонії Дренора, ще невідомо.",
    },
},

[21583] = {
    en = "The Kaldorei and the Well of Eternity",
    T  = "Калдорей та Колодязь Вічності",
    pages = {
        [1] = "За десять тисяч років до того, як орки та люди зіткнулися у Першій війні, світ Азерота складався лише з одного величезного континенту, оточеного безмежними бурхливими морями. Цей масив суші, відомий як Калімдор, був домівкою для безлічі різноманітних рас і істот, які всі боролися за виживання серед диких стихів пробуджуваного світу. У центрі темного континенту розташовувалося таємниче озеро, сповнене розжареної енергії.",
        [2] = "Озеро, яке згодом отримало назву «Колодязь Вічності», було справжнім серцем магії та природної сили світу. Черпаючи енергію з нескінченної Великої Темряви за межами світу, Колодязь виступав містичним джерелом, розсилаючи свою потужну енергію по всьому світу, щоб живити життя у всіх його дивовижних формах. Згодом примітивне плем’я нічних гуманоїдів обережно пробралося до берегів цього зачаровуючого, чарівного озера.",
        [3] = "Дикі кочові гуманоїди, приваблені дивною енергією Колодязя, збудували примітивні оселі на його тихих берегах. З часом космічна сила Колодязя вплинула на це дивне плем'я, зробивши його сильним, мудрим і практично безсмертним. Плем'я прийняло назву «Калдорей», що в перекладі з їхньої рідної мови означало «діти зірок». Щоб відсвяткувати зародження свого суспільства, вони звели величні споруди та храми навколо озера.",
        [4] = "Калдорей, або нічні ельфи, як їх згодом стали називати, поклонялися богині Місяця Елуні й вірили, що вдень вона спить у мерехтливих глибинах Колодязя. Перші жерці та провидці нічних ельфів вивчали Колодязь із невгамовною цікавістю, прагнучи осягнути його незбагненні таємниці та силу. У міру розвитку свого суспільства нічні ельфи досліджували простори Калімдору та зустрічали його незліченних мешканців.",
        [5] = "Єдиними істотами, які змушували їх задуматися, були древні й могутні дракони. Хоча ці величезні змієподібні звірі зазвичай вели усамітнене життя, вони робили чимало для захисту відомих земель від потенційних загроз. Нічні ельфи вірили, що дракони вважають себе захисниками світу, і що їх та їхні таємниці краще залишити в спокої.",
        [6] = "Згодом цікавість нічних ельфів привела їх до знайомства та дружби з низкою могутніх істот, серед яких не останнє місце посідав Сенаріус — могутній напівбог пралісів. Великодушний Сенаріус полюбив допитливих нічних ельфів і присвятив чимало часу тому, щоб навчати їх про світ природи. Спокійні калдореї розвинули глибоку прихильність до живих лісів Калімдору й насолоджувалися гармонійною рівновагою природи.",
        [7] = "Проте, у міру того як минали, здавалося б, нескінченні віки, цивілізація нічних ельфів розширювалася як територіально, так і культурно. Їхні храми, дороги та поселення простягалися по всій ширині темного континенту. Азшара, прекрасна й обдарована королева нічних ельфів, збудувала на березі Колодязя величезний, дивовижний палац, у розкішних залах якого мешкали її улюблені слуги.",
        [8] = "Її слуги, яких вона називала «Квель'дорей» або «високородні», виконували кожну її команду з великою відданістю і вважали себе вищими за решту своїх побратимів із нижчих каст. Хоча королеву Азшару однаково любив весь її народ, «високородні» таємно викликали ненависть у заздрісних мас. Поділяючи цікавість жерців до Колодязя Вічності, Азшара наказала освіченим «високородним» з’ясувати його таємниці та розкрити його справжнє призначення у світі.",
        [9] = "Високородні повністю занурилися у свою працю й безперервно вивчали Колодязь. Згодом вони розвинули здатність керувати космічними енергіями Колодязя та контролювати їх. У міру того, як їхні безрозсудні експерименти набирали обертів, високородні виявили, що можуть використовувати свої новонабуті сили для того, щоб за власним бажанням творити або руйнувати. Нещасні високородні натрапили на примітивну магію і тепер були рішуче налаштовані присвятити себе її освоєнню.",
        [10] = "Хоча вони й погоджувалися, що магія є небезпечною за своєю суттю, якщо поводитися з нею безвідповідально, Азшара та її високородні почали практикувати чаклунство з безрозсудною відвагою. Сенаріус та багато з мудрих вчених-нічних ельфів попереджали, що ігри з явно нестабільним мистецтвом магії приведуть лише до лиха. Однак Азшара та її послідовники вперто продовжували розширювати свої швидко зростаючі сили.",
        [11] = "У міру зростання їхніх сил Азшара та вищі ельфи зазнали помітних змін. Гордовита й відсторонена верхівка ставала дедалі байдужішою та жорстокішою до своїх співвітчизників-нічних ельфів. Темна, похмура пелена затулила колись чарівну красу Азшари. Вона почала віддалятися від своїх люблячих підданих і відмовлялася спілкуватися з ким-небудь, окрім своїх довірених жерців з числа високородних.",
        [12] = "Молодий, зухвалий вчений на ім’я Фуріон Штормрейдж, який присвятив значну частину свого часу вивченню впливу Колодязя, почав підозрювати, що жахлива сила розбещує представників вищого роду та його улюблену королеву. Хоча він і не міг уявити собі того зла, що мало настати, він знав, що життя нічних ельфів незабаром зміниться назавжди...",
    },
},

