    T  = "Саргерас і зрада",
    pages = {
        [1] = "З плином часу демонічні сутності проникли у світи Титанів із Викрученого Ефіру, і Пантеон обрав свого найвеличнішого воїна, Саргераса, щоб той став його першою лінією оборони. Саргерас — благородний велетень із розплавленої бронзи — виконував свої обов’язки протягом незліченних тисячоліть, вишукуючи та знищуючи цих демонів, де б він їх не знаходив. Протягом еонів Саргерас зіткнувся з двома могутніми демонічними расами, обидві з яких прагнули здобути владу та панування над фізичним всесвітом.",
        [2] = "Ередари — підступна раса диявольських чаклунів — використовували магію чаклунів, щоб вторгнутися на низку світів і поневолити їх. Місцеві раси цих світів зазнали мутацій під впливом злісних сил ередарів і самі перетворилися на демонів.",
        [3] = "Хоча майже безмежні сили Саргераса були більш ніж достатніми, щоб перемогти огидних ередарів, його глибоко турбувала зіпсованість цих істот і всепоглинаюче зло. Не здатний осягнути таку розпусту, великий Титан почав поринати у похмуру депресію. Незважаючи на своє зростаюче занепокоєння, Саргерас позбавив Всесвіт від чаклунів, ув’язнивши їх у куточку Скрученого Потойбіччя.",
        [4] = "У той час як його розгубленість і страждання лише поглиблювалися, Саргерас був змушений протистояти ще одній групі, яка прагнула порушити порядок, встановлений Титанами: Натрезімам. Ця темна раса вампіричних демонів (також відома як «лорди жаху») завоювала низку населених світів, заволодівши їхніми мешканцями та перетворивши їх на тіні.",
        [5] = "Підступні й інтриганські володарі жаху налаштували цілі народи один проти одного, підбурюючи їх до бездумної ненависті та недовіри. Саргерас легко переміг Натрезімів, але їхнє зіпсуття глибоко вплинуло на нього.",
        [6] = "Коли сумніви та відчай заполонили свідомість Саргераса, він втратив віру не лише у свою місію, а й у бачення Титанів щодо впорядкованого Всесвіту. Зрештою він дійшов висновку, що сама ідея порядку є безглуздям, а хаос і розпуста — єдині абсолюти у цьому темному й самотньому Всесвіті.",
        [7] = "Його побратими-титани намагалися переконати його в помилковості його рішення та вгамувати його бурхливі емоції, але він відкинув їхні більш оптимістичні переконання як егоїстичні ілюзії. Назавжди покинувши їхні ряди, Саргерас вирушив на пошуки свого місця у Всесвіті. Хоча Пантеон сумував через його відхід, титани ніколи не могли передбачити, як далеко зайде їхній загублений брат.",
        [8] = "Коли божевілля Саргераса повністю поглинуло останні залишки його хороброго духу, він переконався, що саме Титани винні в провалі творіння. Зрештою вирішивши знищити їхні творіння по всьому Всесвіту, він намірився сформувати непереможну армію, яка б спалила фізичний Всесвіт.",
        [9] = "Навіть титанічна постать Саргераса спотворилася від розтління, яке охопило його колись благородне серце. З його очей, волосся та бороди вирвався вогонь, а металево-бронзова шкіра розірвалася, відкривши безмежну печінь пекучої ненависті.",
        [10] = "У своєму гніві Саргерас розтрощив в'язниці ередарів та натрезімів і випустив на волю огидних демонів. Ці хитрі істоти схилилися перед величезним гнівом темного Титана й запропонували служити йому всіма можливими злісними способами. З-поміж могутніх ередарів Саргерас обрав двох чемпіонів, щоб вони очолили його демонічну армію руйнування.",
        [11] = "Кіл'яеден Обманщик був обраний для того, щоб відшукати найтемніші раси у Всесвіті та завербувати їх до лав Саргераса. Другий чемпіон, Архімонд Осквернитель, був обраний, щоб очолити величезні армії Саргераса в битві проти всіх, хто міг би чинити опір волі Титана.",
        [12] = "Першим кроком Кіл'яедена стало підкорення вампіричних лордів жаху під свою жахливу владу. Лорди жаху слугували його особистими агентами по всьому Всесвіту, і вони з насолодою вишукували примітивні раси, щоб їхній повелитель міг їх спотворити та привести до свого стада. Першим серед лордів жаху був Тіхондріус Темний. Тіхондріус служив Кіл'ядену як бездоганний воїн і погодився нести палаючу волю Саргераса у всі темні куточки Всесвіту.",
        [13] = "Могутній Архімонд також наділив силою своїх власних агентів. Звернувшись до злісних володарів пекла та їхнього варварського ватажка, Маннорота Руйнівника, Архімонд сподівався створити бойову еліту, яка б знищила все живе у всьому творінні.",
        [14] = "Як тільки Саргерас переконався, що його армії зібрані й готові виконувати кожну його команду, він кинув свої люті війська у безмежну Велику Темряву. Свою армію, що постійно зростала, він назвав «Палаючою Легією». До сьогоднішнього дня залишається невідомим, скільки світів вони поглинули й спалили під час свого нечестивого «Палаючого походу» по всьому Всесвіту.",
    },
},

[175725] = {
    en = "The Old Gods and the Ordering of Azeroth",
    T  = "Старі Боги та Структура Азерота",
    pages = {
        [1] = "Не підозрюючи про місію Саргераса, спрямовану на те, щоб зруйнувати їхні незліченні творіння, Титани продовжували мандрувати від світу до світу, формуючи та упорядковуючи кожну планету на власний розсуд. Під час своєї подорожі вони натрапили на невеликий світ, який його мешканці згодом назвали Азеротом.",
        [2] = "Просуваючись первісним ландшафтом, Титани натрапили на низку ворожих елементальних істот. Ці елементалі, які поклонялися расі незбагненно злих істот, відомих лише як Старі Боги, поклялися відкинути Титанів назад і захистити свій світ від металевого дотику загарбників.",
        [3] = "Пантеон, стурбований схильністю Старих Богів до зла, розпочав війну проти елементалів та їхніх темних повелителів. Арміями Старих Богів командували наймогутніші лейтенанти-елементалі: Рагнарос, Володар Вогню, Теразане, Мати Каменю, Аль'Акір, Володар Вітру, та Нептулон, Мисливець за Припливами.",
        [4] = "Їхні хаотичні сили вирували по всій поверхні світу й зіткнулися з колосальними титанами. Хоча елементалі були настільки могутніми, що це перевищувало людське розуміння, їхні об’єднані сили не змогли зупинити могутніх титанів. Один за одним падали володарі стихій, а їхні сили розсіялися.",
        [5] = "Пантеон зруйнував цитаделі Старих Богів і заковав п’ятьох злих богів у ланцюги глибоко під поверхнею світу. Без сили Старих Богів, яка утримувала їхні розлючені духи у фізичному світі, елементалі були вигнані до безодневого виміру, де вони мали битися один з одним у вічності. З відходом елементалів природа заспокоїлася, і світ занурився у мирну гармонію. Титани побачили, що загроза усунена, і взялися до роботи.",
        [6] = "Титани наділили низку рас силою, щоб ті допомагали їм творити світ. Щоб ті допомагали їм висікати бездонні печери під землею, Титани створили з магічного, живого каменю землян, схожих на гномів. Щоб допомогти їм вичерпати моря та підняти сушу з морського дна, Титани створили величезних, але лагідних морських велетнів. Протягом багатьох століть Титани переміщували та формували землю, аж поки врешті-решт не залишився один досконалий континент.",
        [7] = "У центрі континенту Титани створили озеро, що випромінювало мерехтливу енергію. Це озеро, яке вони назвали «Колодязем Вічності», мало стати джерелом життя для всього світу. Його могутня енергія мала живити основи світу та давати силу життю, щоб воно пустило коріння в родючому ґрунті землі. З часом на прадавньому континенті почали процвітати рослини, дерева, монстри та всілякі істоти.",
        [8] = "Коли в останній день їхньої праці настали сутінки, Титани назвали континент Калімдор: «земля вічного зоряного світла».",
    },
},

[175726] = {
    en = "Charge of the Dragonflights",
    T  = "Атака драконівських зграй",
    pages = {
        [1] = "Переконавшись, що в цьому маленькому світі наведено лад і що їхня робота виконана, Титани приготувалися покинути Азерот. Однак перед тим, як відправитися, вони доручили найвеличнішому виду цього світу завдання охороняти Калімдор, аби жодна сила не загрожувала його досконалому спокою. У ті часи існувало багато драконячих зграй.",
        [2] = "Проте було п’ять зграй, які панували над своїми побратимами. Саме ці п’ять зграй титани обрали, щоб опікуватися молодим світом. Найвеличніші члени Пантеону наділили частину своєї сили лідерам кожного з цих зграй. Ці величні дракони (перелічені нижче) стали відомі як Великі Аспекти, або Драконячі Аспекти.",
        [3] = "Аман'Тул, Верховний Отець Пантеону, наділив величезного бронзового дракона Ноздорму частиною своєї космічної сили. Верховний Отець наділив Ноздорму здатністю охороняти сам час і стежити за вічно обертовими шляхами долі та призначення. Стоїчний і благородний Ноздорму став відомий як «Безчасний».",
        [4] = "Еонар, титанка-покровителька всього живого, передала частину своєї сили червоному левіафану Алекстразі. Відтоді Алексстраза стала відомою як «Зв’язувачка життя» і присвятила себе захисту всіх живих істот у світі. Завдяки своїй надзвичайній мудрості та безмежному співчуттю до всього живого Алексстраза була коронована Драконихою і отримала владу над своїм родом.",
        [5] = "Еонар також наділила молодшу сестру Алексстрази, гнучку зелену драконицю Ісеру, частиною сили Природи. Ісера занурилася у вічний транс, пов'язана з пробудженим Сном Створення. Відома як Мрійниця, вона пильнувала за зростаючими дикими просторами світу зі свого зеленого царства — Смарагдового Сну.",
        [6] = "Норганнон, титан-хранитель знань і великий чарівник, наділив блакитного дракона Малігоса частиною своєї величезної сили. Відтоді Малігос став відомий як «Ткач Заклинань» — охоронець магії та таємних знань.",
        [7] = "Хаз’горот, титан-творець і кузень світу, наділив могутнього чорного дракона Нелтаріона частиною своєї безмежної сили. Великодушний Нелтаріон, якого згодом стали називати Хранителем Землі, отримав владу над землею та глибинами світу. Він уособлював силу світу і був найвідданішим соратником Алексстрази.",
        [8] = "Отримавши такі повноваження, П’ять Аспектів взяли на себе обов’язки захисту світу під час відсутності Титанів. Переконавшись, що дракони готові захищати їхнє творіння, Титани назавжди залишили Азерот. На жаль, це було лише питанням часу, коли Саргерас дізнається про існування новоствореного світу...",
    },
},

[175727] = {
    en = "The War of the Ancients",
    T  = "Війна Стародавніх",
    pages = {
        [1] = "Нерозсудливе використання магії Високородними спричинило поширення енергетичних хвиль, що спірально розходилися від Колодязя Вічності у Велику Темну Незбагненність. Ці потоки енергії були відчуті жахливими чужими розумами. Саргерас — Великий Ворог усього живого, Руйнівник Світів — відчув ці потужні хвилі й був притягнутий до їхнього віддаленого джерела.",
        [2] = "Споглядаючи первісний світ Азерота й відчуваючи безмежну енергію Колодязя Вічності, Саргерас був охоплений ненаситним голодом. Великий темний бог Безіменної Порожнечі вирішив знищити цей молодий світ і привласнити його енергію.",
        [3] = "Саргерас зібрав свою величезну Палаючу Легію й рушив у бік нічого не підозрюючого світу Азерота. Легія складалася з мільйона кричущих демонів, яких вирвали з найвіддаленіших куточків Всесвіту, і ці демони жадали завоювань. Заступники Саргераса — Архімонд Осквернитель та Маннорот Руйнівник — готували своїх пекельних посіпаків до атаки.",
        [4] = "Королева Азшара, охоплена жахливим екстазом своєї магії, стала жертвою незаперечної сили Саргераса і погодилася надати йому доступ до свого світу. Навіть її слуги з роду Високородних піддалися неминучій корупції магії й почали поклонятися Саргерасу як своєму богу. Щоб продемонструвати свою вірність Легіону, Високородні допомогли своїй королеві відкрити величезний, вируючий портал у глибинах Колодязя Вічності.",
        [5] = "Завершивши всі приготування, Саргерас розпочав своє катастрофічне вторгнення в Азерот. Воїни-демони Палкого Легіону увірвалися у світ через Колодязь Вічності й взяли в облогу міста нічних ельфів, що спали. Під проводом Архімонда та Маннорота Легіон навалився на землі Калімдору, залишаючи за собою лише попіл і горе.",
        [6] = "Демонічні чаклуни викликали пекучі пекельні створіння, які, немов пекельні метеорити, врізалися у витончені шпилі храмів Калімдора. Загін палаючих, кровожерливих вбивць, відомих як «Стражі Приречення», просувався полями Калімдора, винищуючи всіх на своєму шляху. Зграї диких демонічних фел-псів безперешкодно спустошували сільську місцевість. Хоча відважні воїни калдореїв кинулися на захист своєї прадавньої батьківщини, їм довелося відступати, дюйм за дюймом, перед люттю наступу Легіону.",
        [7] = "Саме Малфуріону Штормрейджу випало знайти допомогу для свого народу, що опинився в скрутному становищі. Штормрейдж, чий власний брат, Іллідан, практикував магію Високородних, був обурений зростаючою розпустою серед вищих верств суспільства. Переконавши Іллідана відмовитися від своєї небезпечної одержимості, Малфуріон вирушив на пошуки Сенаріуса, щоб зібрати сили опору.",
        [8] = "Прекрасна молода жриця Тиранда погодилася супроводжувати братів в ім'я Елуни. Хоча Малфуріон та Іллідан однаково кохали цю ідеалістичну жрицю, серце Тиранди належало лише Малфуріону. Іллідан обурювався через роман, що зароджувався між його братом і Тирандою, але розумів, що його душевний біль — ніщо порівняно з муками, які завдавала йому магічна залежність.",
        [9] = "Іллідан, який став залежним від енергії магії, що надавала йому силу, з великими зусиллями намагався стримати свою майже непереборну жагу знову скористатися енергією Джерела. Однак завдяки терплячій підтримці Тиранди йому вдалося стриматися і допомогти своєму братові знайти відлюдного напівбога, Сенаріуса.",
        [10] = "Сенаріус, який мешкав у священних Місячних галявинах на далекій горі Гіял, погодився допомогти нічним ельфам, знайшовши древніх драконів і заручившись їхньою підтримкою. Дракони на чолі з великим червоним левіафаном Алекстразою погодилися відправити свої могутні зграї, щоб вступити в бій з демонами та їхніми пекельними повелителями.",
        [11] = "Сенаріус, закликавши духів зачарованих лісів, зібрав армію древніх дереволюдів і повів їх проти Легіону в сміливий наземний наступ. Коли союзники нічних ельфів збіглися до храму Азшари та Колодязя Вічності, розгорілася тотальна війна. Незважаючи на силу своїх нових союзників, Малфуріон та його товариші усвідомили, що Легіон неможливо перемогти лише військовою силою.",
        [12] = "Поки навколо столиці Азшари вирувала титанічна битва, королева, що втратила розум, з нетерпінням чекала на прихід Саргераса. Володар Легіону готувався пройти крізь Колодязь Вічності й увійти до спустошеного світу. Коли його неймовірно величезна тінь наближалася до поверхні Колодязя, Азшара зібрала наймогутніших зі своїх послідовників із числа Високородних. Лише об’єднавши свою магію в одне зосереджене заклинання, вони змогли б створити портал, достатньо великий, щоб Саргерас міг увійти.",
        [13] = "Поки битва вирувала на палаючих полях Калімдору, стався жахливий поворот подій. Подробиці цієї події загубилися в глибинах часу, але відомо, що Нелтаріон, Драконівський Аспект Землі, збожеволів під час вирішального бою проти Палаючого Легіону. Він почав розпадатися на частини, а з його темної шкіри виривалися полум’я та лють. Перейменувавши себе на Смертокрила, палаючий дракон обернувся проти своїх побратимів і вигнав п’ять драконячих полчищ з поля бою.",
        [14] = "Раптова зрада Десвінга мала настільки руйнівні наслідки, що п’ять драконівських полків так і не змогли повністю оговтатися. Поранена й приголомшена Алекстраза та інші благородні дракони були змушені покинути своїх смертних союзників. Малфуріон та його товариші, які тепер опинилися в безнадійній чисельній меншості, ледь вижили під час наступного наступу.",
        [15] = "Мальфуріон, переконаний, що Колодязь Вічності є пуповиною, яка пов’язує демонів із фізичним світом, наполягав на тому, що його слід знищити. Його товариші, знаючи, що Колодязь є джерелом їхнього безсмертя та сил, були жахнуті цією необачною ідеєю. Проте Тиранда побачила мудрість у теорії Малфуріона, тож вона переконала Сенаріуса та їхніх товаришів штурмувати храм Азшари й знайти спосіб назавжди закрити Колодязь.",
    },
},

[175729] = {
    en = "Mount Hyjal and Illidan's Gift",
    T  = "Гора Гіжал і «Дар Іллідана»",
    pages = {
        [1] = "Ті нечисленні нічні ельфи, що вижили після жахливого вибуху, зібралися на грубо збитих плотах і повільно рушили до єдиного шматка суші, який було видно на горизонті. Якимось чином, завдяки милості Елуни, Малфуріон, Тиранде та Сенаріус вижили під час Великого Розколу. Втомлені герої домовилися очолити своїх товаришів-виживців і заснувати нову батьківщину для свого народу.",
        [2] = "Подорожуючи в мовчанні, вони оглядали руїни свого світу й усвідомлювали, що саме їхні пристрасті спричинили руйнування, яке оточувало їх з усіх боків. Хоча Саргерас і його Легіон були вирвані зі світу внаслідок знищення Джерела, Малфуріон та його супутники залишилися, щоб замислитися над жахливою ціною перемоги.",
        [3] = "Багато представників Високородних все ж пережили катаклізм без жодних ушкоджень. Разом з іншими нічними ельфами вони дісталися берегів нової землі. Хоча Малфуріон з підозрою ставився до мотивів Високородних, він був упевнений, що без енергії Джерела вони не зможуть заподіяти ніякої реальної шкоди.",
        [4] = "Коли втомлена громада нічних ельфів висадилася на берегах нової землі, вони виявили, що священна гора Гіжал пережила катастрофу. Прагнучи облаштувати для себе нову домівку, Малфуріон та нічні ельфи піднялися схилами Гіжала й дісталися його обвіваної вітрами вершини. Спускаючись у лісисту улоговину, що затишно вклалася між величезними вершинами гори, вони натрапили на невелике, спокійне озеро. На їхній жах, вони виявили, що води озера були отруєні магією.",
        [5] = "Іллідан, який також пережив Великий Розкол, дістався до вершини Гіялу набагато раніше, ніж Малфуріон і нічні ельфи. У своєму божевільному прагненні зберегти потоки магії у світі Іллідан вилив у гірське озеро свої флакони, що містили дорогоцінні води з Колодязя Вічності.",
        [6] = "Потужна енергія Колодязя швидко розпалилася й злилася в новий Колодязь Вічності. Радісний Іллідан, вважаючи, що новий Колодязь — це дар для майбутніх поколінь, був шокований, коли Малфуріон вистежив його. Малфуріон пояснив своєму братові, що магія за своєю суттю хаотична і що її використання неминуче призведе до повсюдного розбещення та конфліктів. Проте Іллідан відмовився відмовитися від своїх магічних сил.",
        [7] = "Добре усвідомлюючи, до чого зрештою призведуть безжальні інтриги Іллідана, Малфуріон вирішив раз і назавжди розправитися зі своїм братом, охопленим жадобою влади. За допомогою Сенаріуса Малфуріон ув'язнив Іллідана у величезній підземній могильній в'язниці, де той мав залишатися скутим ланцюгами й безсилим до кінця часів. Щоб гарантувати утримання брата, Малфуріон наділив молоду наглядачку, Маєв Тіньоспів, повноваженнями особистого тюремника Іллідана.",
        [8] = "Побоюючись, що знищення нового Колодязя може спричинити ще більшу катастрофу, нічні ельфи вирішили залишити його в спокої. Однак Малфуріон оголосив, що вони ніколи більше не будуть займатися магією. Під пильним наглядом Сенаріуса вони почали вивчати стародавнє мистецтво друїдизму, яке дозволило б їм зцілити спустошену землю та відродити свої улюблені ліси біля підніжжя гори Гіжал.",
    },
},

[175730] = {
    en = "The World Tree and the Emerald Dream",
    T  = "Світове Дерево та Смарагдова Мрія",
    pages = {
        [1] = "Протягом багатьох років нічні ельфи невтомно працювали над тим, щоб відновити те, що вдалося врятувати зі своєї прадавньої батьківщини. Залишивши зруйновані храми та дороги на милість заростей, вони збудували свої нові оселі серед зелених дерев і затінених пагорбів біля підніжжя Гіялу. Згодом дракони, які вижили після Великого Розколу, вийшли зі своїх таємних притулків.",
        [2] = "Алексстраза Червона, Ісера Зелена та Ноздорму Бронзовий спустилися на тихі галявини друїдів і оглянули плоди праці нічних ельфів. Мальфуріон, який став архідруїдом з величезною силою, привітав могутніх драконів і розповів їм про створення нового Джерела Вічності.",
        [3] = "Великі дракони були стривожені, почувши цю похмуру новину, і припустили, що доки Колодязь існує, Легіон може одного дня повернутися й знову напасти на світ. Малфуріон та троє драконів уклали угоду, щоб захистити Колодязь і гарантувати, що агенти Палаючого Легіону ніколи не зможуть повернутися у цей світ.",
        [4] = "Алексстраза, Пов’язувачка Життя, поклала єдиний зачарований жолудь у саме серце Колодязя Вічності. Жолудь, активований могутніми чарівними водами, ожив і перетворився на колосальне дерево. Коріння могутнього дерева проросло з вод Колодязя, а його зелена крона, здавалося, торкалася самого неба.",
        [5] = "Це величезне дерево мало стати вічним символом єдності нічних ельфів із природою, а його життєдайна енергія з часом поширилася б, зцілюючи решту світу. Нічні ельфи дали своєму Світовому Дереву нову назву — Нордрасіл, що в перекладі з їхньої рідної мови означало «корона небес».",
        [6] = "Ноздорму, Вічний, наклав закляття на Світове Дерево, щоб гарантувати: доки стоїть це велетенське дерево, нічні ельфи ніколи не старітимуть і не стануть жертвами хвороб чи недуг.",
        [7] = "Ісера, Мрійниця, також наклала закляття на Світове Дерево, пов’язавши його зі своїм власним царством — ефірним виміром, відомим як Смарагдова Мрія. Смарагдова Мрія — величезний, постійно мінливий світ духів — існувала за межами фізичного світу. З Мрії Ісера регулювала припливи й відпливи природи та еволюційний шлях самого світу.",
        [8] = "Друїди нічних ельфів, включаючи самого Малфуріона, були пов’язані зі Сном через Світове Дерево. У рамках цього містичного пакту друїди погодилися спати століттями, щоб їхні душі могли мандрувати нескінченними стежками Снівних шляхів Ісери. Хоча друїди сумували через те, що їм доведеться втратити стільки років свого життя на зимову сплячку, вони самовіддано погодилися дотримуватися угоди з Ісерою.",
    },
},

[175731] = {
    en = "Exile of the High Elves",
    T  = "Вигнання високих ельфів",
    pages = {
        [1] = "З плином століть нове суспільство нічних ельфів зміцніло й поширилося по всьому молодому лісі, який вони стали називати Ешенвелем. Багато істот і видів, які були численними до Великого Розколу, таких як фурболги та квілбоари, знову з’явилися на цій землі й процвітали тут. Під доброзичливим керівництвом друїдів нічні ельфи насолоджувалися епохою безпрецедентного миру та спокою під зорями.",
        [2] = "Однак багато хто з тих, хто вижив із числа Високородних, почав відчувати неспокій. Як і Іллідан до них, вони стали жертвами відчаю, що виник внаслідок втрати їхньої заповітної магії. Їх спокушала можливість черпати енергію з Колодязя Вічності та насолоджуватися своїми магічними практиками. Дат'Ремар, зухвалий і відвертий лідер Високородних, почав публічно висміювати друїдів, називаючи їх боягузами за те, що вони відмовлялися користуватися магією, яка, за його словами, належала їм по праву.",
        [3] = "Мальфуріон та друїди відкинули аргументи Дат’Ремара й попередили Високородних, що будь-яке використання магії каратиметься смертю. У зухвалій і фатальній спробі переконати друїдів скасувати цей закон Дат’Ремар та його послідовники наслали на Ешенвейл жахливу магічну бурю.",
        [4] = "Друїди не наважилися стратити таку велику кількість своїх родичів, тож вирішили вигнати з своїх земель цих необачних Високородних. Дат’Ремар та його послідовники, раді, що нарешті позбулися своїх консервативних родичів, сіли на борт кількох спеціально побудованих кораблів і вирушили в море. Хоча ніхто з них не знав, що чекає на них за водами бурхливого Маелстрому, вони прагнули заснувати власну батьківщину, де могли б безкарно практикувати свою омріяну магію.",
        [5] = "Високородні, або Квель'дорей, як назвала їх Азшара в давні часи, зрештою висадилися на східних землях, які люди назвали Лордаероном. Вони планували збудувати власне магічне королівство — Квель'Талас — і відмовитися від заповідей нічних ельфів щодо поклоніння Місяцю та нічного способу життя. Відтоді вони назавжди поклонялися Сонцю і стали відомі лише як високі ельфи.",
    },
},

[175732] = {
    en = "The Sentinels and the Long Vigil",
    T  = "«Вартові» та «Довге чування»",
    pages = {
        [1] = "Після від'їзду своїх норовливих кузенів нічні ельфи знову зосередили свою увагу на охороні своєї зачарованої батьківщини. Друїди, відчуваючи, що час їхньої зимової сплячки наближається, готувалися заснути, залишивши своїх близьких і родини.",
        [2] = "Тиранде, яка стала Верховною жрицею Елуни, попросила свого коханого, Малфуріона, не залишати її заради «Смарагдового Сну» Ісери. Але Малфуріон, зобов’язаний честю увійти в мінливі «Шляхи Сну», попрощався з жрицею і присягнувся, що вони ніколи не розлучаться, доки залишатимуться вірними своєму коханню.",
        [3] = "Залишившись наодинці, щоб захистити Калімдор від небезпек нового світу, Тиранде зібрала потужний бойовий загін із своїх сестер-нічних ельфів. Безстрашні, високопідготовлені войовниці, які присвятили себе захисту Калімдора, стали відомі як «Вартові». Хоча вони воліли самостійно патрулювати тінисті ліси Ешенвеля, у них було чимало союзників, до яких вони могли звернутися у разі небезпеки.",
        [4] = "Напівбог Сенаріус залишився неподалік, у Місячних гаях гори Гіжал. Його сини, відомі як «Хранителі Гаю», пильно стежили за нічними ельфами та регулярно допомагали Вартовим підтримувати мир на цій землі. Навіть сором’язливі дочки Сенаріуса, дріади, дедалі частіше з’являлися на відкритому просторі.",
        [5] = "Забезпечення правопорядку в Ешенвейлі повністю поглинало Тиранду, але без Малфуріона поруч вона не відчувала справжньої радості. З плином довгих століть, поки друїди спали, її побоювання щодо другого вторгнення демонів лише зростали. Вона не могла позбутися тривожного відчуття, що Палка Легіон, можливо, досі десь там, за Великою Темрявою неба, готує свою помсту нічним ельфам і світу Азероту.",
    },
},

[175733] = {
    en = "The Founding of Quel'Thalas",
    T  = "Заснування Квель-Таласа",
    pages = {
        [1] = "Вищі ельфи на чолі з Датом’Ремаром залишили Калімдор позаду й кинули виклик бурям Маелстрому. Їхні флоти блукали серед руїн світу протягом багатьох довгих років, і під час своїх мандрів вони відкривали таємниці та загублені королівства. Дат'Ремар, який взяв собі ім'я Санстрайдер (або «той, хто крокує у світлі дня»), шукав місця зі значною силою лей-ліній, щоб збудувати там нову батьківщину для свого народу.",
        [2] = "Його флот нарешті висадився на берегах королівства, яке згодом люди назвуть Лордаероном. Просуваючись углиб країни, високі ельфи заснували поселення серед тихих гаїв Тірісфал. Через кілька років багато хто з них почав божеволіти. Існувала гіпотеза, що під цією конкретною частиною світу дрімало щось зле, але ці чутки так і не знайшли підтвердження. Вищі ельфи згорнули свій табір і рушили на північ, до іншої землі, багатої на енергію лей-ліній.",
        [3] = "Коли високі ельфи перетинали суворі гірські землі Лордаерона, їхня подорож ставала дедалі небезпечнішою. Оскільки вони фактично були відрізані від життєдайної енергії Колодязя Вічності, багато хто з них захворів через морозний клімат або помер від голоду. Однак найтривожнішою зміною стало те, що вони більше не були безсмертними й не мали імунітету до стихій.",
        [4] = "Вони також дещо зменшилися у зрості, а їхня шкіра втратила характерний фіолетовий відтінок. Незважаючи на всі труднощі, вони зустріли безліч дивовижних істот, яких раніше в Калімдорі ніхто не бачив. Вони також натрапили на племена первісних людей, які полювали в стародавніх лісових масивах. Однак найстрашнішою загрозою для них стали ненажерливі й хитрі лісові тролі Зул'Амана.",
        [5] = "Ці тролі з моховою шкірою могли відрощувати втрачені кінцівки та зцілювати тяжкі фізичні поранення, але виявилися варварською й злою расою. Імперія Амані простягалася майже на всю територію північного Лордаерону, і тролі запекло боролися, щоб не допустити небажаних чужинців до своїх кордонів. Ельфи відчували глибоку ненависть до жорстоких тролів і вбивали їх на місці, щойно їх зустрічали.",
        [6] = "Через багато довгих років високі ельфи нарешті знайшли землю, що нагадувала Калімдор. Глибоко в північних лісах континенту вони заснували королівство Кель'Талас і пообіцяли створити могутню імперію, яка за розмірами перевершила б імперію їхніх родичів-калдореїв. На жаль, незабаром вони дізналися, що Квель-Талас було засновано на місці стародавнього міста тролів, яке ті й досі вважали священним. Майже одразу тролі почали масово нападати на ельфійські поселення.",
        [7] = "Уперті ельфи, не бажаючи відмовлятися від своєї нової землі, використали магію, яку вони почерпнули з Колодязя Вічності, і стримали напад диких тролів. Під керівництвом Дат’Ремара їм вдалося перемогти загони Амані, які переважали їх у десять разів. Деякі ельфи, пам’ятаючи про давні застереження калдореїв, вважали, що використання магії може привернути увагу вигнаного Палаючого Легіону.",
        [8] = "Тому вони вирішили приховати свої землі за захисним бар'єром, який все ж давав би їм змогу застосовувати свої чари. Вони спорудили низку монолітних рунічних каменів у різних точках навколо Кель'Таласа, які позначали межі магічного бар'єру. Рунічні камені не тільки приховували магію ельфів від позавимірних загроз, а й допомагали відлякувати забобонні загони тролів.",
        [9] = "З плином часу Кель'Талас перетворився на блискучий пам'ятник зусиллям та магічній майстерності високих ельфів. Його чудові палаци були зведені в тому ж архітектурному стилі, що й стародавні зали Калімдору, проте вони гармонійно вписувалися в природний рельєф місцевості. Квель-Талас став тією сяючою перлиною, про створення якої так мріяли ельфи.",
        [10] = "Конвокація Срібного Місяця була заснована як правляча влада над Квель'Таласом, хоча династія Сонцекроків зберігала певну частку політичної влади. Конвокація, до складу якої входили сім найвидатніших лордів високих ельфів, дбала про безпеку ельфійських земель та народу. Оточені своїм захисним бар'єром, високі ельфи не зважали на давні застереження калдореїв і продовжували безсоромно використовувати магію майже в усіх сферах свого життя.",
        [11] = "Протягом майже чотирьох тисяч років високі ельфи жили мирно у відокремленому та безпечному своєму королівстві. Проте мстивих тролів не так легко було перемогти. Вони плели інтриги та підступи в глибинах лісів і чекали, поки їхні бойові загони поповняться. Зрештою, могутня армія тролів вирвалася з тінистих лісів і вкотре взяла в облогу сяючі шпилі Кель'Таласа.",
    },
},

[175734] = {
    en = "Arathor and the Troll Wars",
    T  = "Аратор і війни з тролями",
    pages = {
        [1] = "Поки високі ельфи боролися за своє життя проти запеклого наступу тролів, розрізнені кочові люди Лордаерона вели боротьбу за укріплення своїх племінних земель. Племена раннього людства нападали одне на одного, майже не зважаючи на расове єднання чи честь.",
        [2] = "Проте одне плем'я, відоме як араті, усвідомило, що тролі стають занадто серйозною загрозою, щоб її ігнорувати. Араті прагнули об'єднати всі племена під своєю владою, щоб створити єдиний фронт проти воєнних загонів тролів.",
        [3] = "Протягом шести років хитрі араті перехитрили та перемогли супротивників у боях. Після кожної перемоги араті пропонували підкореним народам мир і рівність; таким чином вони завоювали лояльність тих, кого перемогли. Зрештою до племені араті увійшли численні різнорідні племена, а чисельність його війська значно зросла.",
        [4] = "Впевнені в тому, що зможуть дати відсіч загонам тролів або навіть відлюдним ельфам, якщо це буде потрібно, воєначальники Араті вирішили збудувати могутнє фортечне місто в південних регіонах Лордаерона. Місто-держава, яке отримало назву Стром, стало столицею нації Араті — Аратора. У міру процвітання Аратора люди з усіх куточків величезного континенту прямували на південь, шукаючи захисту та безпеки у Стромі.",
        [5] = "Об’єднавшись під одним прапором, племена людей сформували міцну, оптимістичну культуру. Торадін, король Аратора, знав, що таємничі ельфи з північних земель перебували під постійною облогою тролів, але відмовився ризикувати безпекою свого народу заради захисту відлюдних чужинців. Минуло багато місяців, поки з півночі доносилися чутки про нібито поразку ельфів. Лише коли втомлені посланці з Квель-Таласа дісталися Строма, Торадін усвідомив, наскільки великою насправді була загроза з боку тролів.",
        [6] = "Ельфи повідомили Торадіну, що армії тролів були величезними і що, знищивши Квель-Талас, тролі рушать на південні землі. Зневірені ельфи, які гостро потребували військової допомоги, поспішно погодилися навчити обраних людей користуватися магією в обмін на їхню допомогу у боротьбі з воєнними загонами.",
        [7] = "Торадін, який не довіряв жодній магії, погодився допомогти ельфам лише з необхідності. Майже одразу ж ельфійські чарівники прибули до Аратора й почали навчати групу людей мистецтву магії.",
        [8] = "Ельфи виявили, що, хоча люди від природи незграбні у поводженні з магією, вони мають вражаючу природну схильність до неї. Сотні людей навчили основам магічних таємниць ельфів: не більше, ніж було абсолютно необхідно для боротьби з тролями. Переконавшись, що їхні людські учні готові допомогти у боротьбі, ельфи залишили Стром і вирушили на північ разом із могутніми військами короля Торадіна.",
        [9] = "Об’єднані армії ельфів і людей зіткнулися з переважаючими військами тролів біля підніжжя Альтеракських гір. Битва тривала багато днів, але незламні війська Аратора не втомилися й не поступилися ні на крок перед натиском тролів. Ельфійські лорди вирішили, що настав час обрушити на ворога всю міць своєї магії.",
        [10] = "Сто людських магів та безліч ельфійських чаклунів викликали гнів небес і спалили армії тролів. Вогні стихій не дали тролям відновити свої рани та спалили їхні змучені тіла зсередини.",
        [11] = "Коли армії тролів розпалися й спробували втекти, війська Торадіна наздогнали їх і винищили до останнього солдата. Тролі так і не змогли повністю оговтатися від цієї поразки, і в історії більше ніколи не трапилося, щоб тролі знову об’єдналися в єдину націю. Переконавшись, що Квель-Талас врятовано від знищення, ельфи дали обітницю вірності та дружби нації Аратор та династії її короля, Торадіна. Люди та ельфи підтримуватимуть мирні стосунки протягом багатьох століть. $B$B",
    },
},

[175735] = {
    en = "The Guardians of Tirisfal",
    T  = "Охоронці Тірісфала",
    pages = {
        [1] = "Оскільки на північних землях не залишилося тролів, ельфи Кель'Таласа зосередили свої зусилля на відновленні своєї славетної батьківщини. Переможні війська Аратора повернулися додому — на південні землі Строма.",
        [2] = "Людське суспільство Аратора зростало й процвітало, проте Торадін, побоюючись, що його королівство розпадеться, якщо воно надто розшириться, наполягав на тому, що Стром є центром Араторської імперії. Після багатьох мирних років зростання та торгівлі могутній Торадін помер від старості, залишивши молодому поколінню Аратора свободу розширювати імперію за межі земель Строма.",
        [3] = "Перші сто магів, яких ельфи навчали мистецтву магії, розширили свої здібності та набагато глибше вивчили містичні дисципліни створення заклинань. Ці маги, спочатку обрані за їхню сильну волю та благородний дух, завжди практикували магію з обережністю та відповідальністю; однак вони передали свої таємниці та сили новому поколінню, яке не мало уявлення ні про суворість війни, ні про необхідність самообмеження.",
        [4] = "Ці молоді чарівники почали займатися магією заради особистої вигоди, а не з почуття відповідальності перед своїми ближніми.",
        [5] = "У міру того як імперія зростала й поширювалася на нові землі, молоді чарівники також розійшлися по південних краях. Використовуючи свої містичні сили, чарівники захищали своїх побратимів від диких істот цих земель і дали змогу звести нові міста-держави посеред дикої природи. Однак у міру зростання своїх сил маги ставали дедалі зарозумілішими й ізольовувалися від решти суспільства.",
        [6] = "Друге араторіанське місто-держава — Даларан — було засноване на землях на північ від Строма. Багато початківців-чарівників залишили за собою обмежуючі межі Строма й вирушили до Даларана, де сподівалися використовувати свої нові сили з більшою свободою. Ці чарівники застосували свої вміння, щоб звести зачаровані шпилі Даларана, і з насолодою віддавалися своїм науковим дослідженням.",
        [7] = "Жителі Даларана терпимо ставилися до діяльності магів і розбудували процвітаючу економіку під захистом своїх захисників, що володіли магією. Однак у міру того, як дедалі більше магів займалися своїм ремеслом, тканина реальності навколо Даларана почала слабшати й розриватися.",
        [8] = "Зловісні агенти Палкого Легіону, яких було вигнано після руйнування Колодязя Вічності, були знову заманені у цей світ через необережне чаклунство магів Даларана. Хоча ці відносно слабкі демони не з’явилися великими силами, вони все ж посіяли значну плутанину та хаос на вулицях Даларана.",
        [9] = "Більшість цих зіткнень із демонами були поодинокими випадками, і правлячі магократи робили все можливе, щоб приховати такі події від громадськості. Наймогутніших магів відправляли на полювання за невловимими демонами, але вони часто виявлялися безнадійно слабшими за поодиноких агентів могутнього Легіону.",
        [10] = "Через кілька місяців забобонне селянство почало підозрювати, що їхні чаклунські правителі приховують від них щось жахливе. Чутки про революцію почали ширитися вулицями Даларана, а параноїдальні мешканці ставили під сумнів мотиви та дії магів, яких колись так шанували. Магократи, побоюючись, що селяни повстануть і що Стром вживе проти них заходів, звернулися до єдиної групи, яка, на їхню думку, могла зрозуміти їхню особливу проблему: до ельфів.",
        [11] = "Дізнавшись від магократів про демонічну активність у Даларані, ельфи негайно відправили своїх наймогутніших чарівників на землі людей. Ельфійські чарівники дослідили енергетичні потоки в Даларані та склали докладні звіти про всю демонічну активність, яку їм вдалося зафіксувати. Вони дійшли висновку, що, хоча у світі на волі перебувало лише кілька демонів, сама Легіон залишатиметься серйозною загрозою доти, доки люди продовжуватимуть користуватися силами магії.",
        [12] = "Рада Срібного Місяця, яка правила ельфами Квель-Таласа, уклала таємний союз із магократами — володарями Даларана. Ельфи розповіли магократам про історію стародавнього Калімдору та Палкого Легіону — історію, яка й досі загрожувала світу. Вони поінформували людей, що доки вони користуватимуться магією, їм доведеться захищати своїх громадян від злісних агентів Легіону.",
        [13] = "Магократи запропонували ідею наділити повноваженнями єдиного смертного чемпіона, який би використовував свої сили для ведення нескінченної таємної війни проти Легіону. Було наголошено, що більшість людства ніколи не повинна дізнатися про Стражів чи загрозу з боку Легіону, щоб уникнути масових заворушень, спричинених страхом і параноєю. Ельфи погодилися з цією пропозицією та заснували таємне товариство, яке мало стежити за вибором Охоронця та допомагати стримувати поширення хаосу у світі.",
        [14] = "Товариство проводило свої таємні зібрання в затінених Полях Тірісфал, де високі ельфи вперше оселилися в Лордаероні. Тому вони назвали цю таємну секту «Стражами Тірісфала». Смертні воїни, яких було обрано Стражами, були наділені неймовірною силою як ельфійської, так і людської магії. Хоча одночасно міг існувати лише один Страж, вони володіли настільки величезною силою, що могли самотужки відбивати атаки агентів Легіону, де б ті не з’являлися у світі.",
        [15] = "Сила Хранителя була настільки великою, що лише Рада Тірісфала мала право обирати потенційних наступників на посаду Хранителя. Щоразу, коли Хранитель ставав занадто старим або втомлювався від таємної війни проти хаосу, Рада обирала нового захисника й у контрольованих умовах офіційно передавала силу Хранителя своєму новому представнику.",
        [16] = "З плином поколінь Стражі захищали людство від невидимої загрози з боку Палкого Легіону на землях Аратора та Квель'Таласа. Аратор розростався й процвітав, а використання магії поширювалося по всій імперії. Тим часом Стражі пильно стежили за ознаками демонічної активності.",
    },
},

[175736] = {
    en = "Ironforge - the Awakening of the Dwarves",
    T  = "Айронфордж — Пробудження гномів",
    pages = {
        [1] = "У давні часи, після того як титани покинули Азерот, їхні діти, відомі як «земні», продовжували формувати й охороняти найпотаємніші куточки світу. «Земні» майже не цікавилися справами рас, що мешкали на поверхні, і прагнули лише досліджувати темні глибини землі.",
        [2] = "Коли світ був розірваний на частини внаслідок вибуху Колодязя Вічності, це глибоко позначилося на землянах. Охоплені болем самої землі, земляни втратили значну частину своєї ідентичності й замкнулися в кам’яних палатах, де вони були вперше створені. Улдаман, Улдум, Улдуар... так називалися стародавні міста Титанів, де земляні вперше набули форми та обрисів. Поховані глибоко під землею, земляні спочивали в мирі майже вісім тисяч років.",
        [3] = "Хоча достеменно невідомо, що саме їх розбудило, земляні, ув’язнені в Улдамані, зрештою прокинулися від самонакладеного сну. Ці земляні виявили, що під час своєї сплячки вони суттєво змінилися. Їхня скеляста шкіра пом’якшала й стала гладенькою, а їхні сили над каменем і землею ослабли. Вони перетворилися на смертних істот.",
        [4] = "Називаючи себе гномами, останні з «земних» покинули зали Улдамана й вирушили у світ, що пробуджувався. Ще перебуваючи під впливом відчуття безпеки та дивовиж глибин, вони заснували величезне королівство під найвищою горою цієї землі.",
        [5] = "Вони назвали свою землю Хаз-Модан, або «Гора Хаза», на честь титана-творця Хаз’горота. Збудувавши вівтар на честь свого титанського батька, гноми створили могутню кузню в самому серці гори. Тож місто, що виросло навколо кузні, відтоді й донині називається Айронфордж.",
        [6] = "Гноми, які від природи захоплювалися обробкою дорогоцінних каменів та гірських порід, вирушили в навколишні гори, щоб добувати багатства та дорогоцінні мінерали. Задоволені своєю працею під землею, гноми залишалися ізольованими від подій, що відбувалися у їхніх сусідів, які мешкали на поверхні.",
    },
},

[175737] = {
    en = "The Seven Kingdoms",
    T  = "Сім Королівств",
    pages = {
        [1] = "Стром і надалі залишався центральним осередком Аратора, але, як і у випадку з Далараном, по всьому континенту Лордаерон виникло багато нових міст-держав. Гілнеас, Альтерак і Кул-Тирас були першими міськими державами, що виникли, і хоча кожна з них мала власні звичаї та систему торгівлі, всі вони визнавали об’єднуючу владу Строма.",
        [2] = "Під пильним наглядом Ордену Тірісфала Даларан став головним центром освіти для магів у всій країні. Магократи, які правили Далараном, заснували Кірін-Тор — спеціалізовану секту, на яку було покладено завдання каталогізувати та досліджувати кожне заклинання, артефакт і магічний предмет, відомі людству на той час.",
        [3] = "Гілнеас та Альтерак стали відданими прихильниками Строма і створили могутні армії, які досліджували гірські південні землі Хаз-Модана. Саме в цей період люди вперше зустрілися з древньою расою гномів і відвідали їхнє підземне місто-печеру Айронфордж. Люди та гноми поділилися багатьма секретами ковальства та інженерії, а також виявили спільну пристрасть до битв і розповіді історій.",
        [4] = "Місто-держава Кул-Тирас, засноване на великому острові на південь від Лордаерона, розбудувало процвітаючу економіку, що ґрунтувалася на рибальстві та судноплавстві. Згодом Кул-Тирас створив могутній флот торгових суден, які курсували по всьому відомому світу в пошуках екзотичних товарів для торгівлі та продажу. Однак навіть тоді, коли економіка Аратора процвітала, її найміцніші елементи почали розпадатися.",
        [5] = "Згодом лорди Строма вирішили перенести свої маєтки до родючих північних земель Лордаерона й покинути посушливі землі півдня. Спадкоємці короля Торадіна, останні нащадки роду Араті, стверджували, що Стром не слід покидати, чим викликали невдоволення більшості мешканців, які також прагнули виїхати.",
        [6] = "Лорди Строма, прагнучи знайти чистоту та просвітлення на дикому півночі, вирішили залишити своє стародавнє місто. Далеко на північ від Даларана лорди Строма збудували нове місто-державу, яке назвали Лордаерон. Весь континент отримав свою назву на честь цього міста-держави. Лордаерон став меккою для релігійних мандрівників та всіх, хто шукав внутрішнього спокою й безпеки.",
        [7] = "Нащадки Араті, що залишилися в руїнах стародавнього Строма, вирішили вирушити на південь, повз скелясті гори Хаз-Модана. Їхня подорож нарешті завершилася після багатьох довгих сезонів, і вони оселилися в північній частині континенту, який вони назвали Азеротом. У родючій долині вони заснували королівство Штормовій, яке швидко перетворилося на самостійну державу, здатну забезпечувати себе всім необхідним.",
        [8] = "Ті нечисленні воїни, що залишилися у Стромі, вирішили залишитися й охороняти стародавні стіни свого міста. Стром уже не був центром імперії, але перетворився на нову державу під назвою Стромгард. Хоча кожне з міст-держав процвітало самостійно, імперія Аратор фактично розпалася. У міру того як кожна нація розвивала власні звичаї та вірування, вони дедалі більше віддалялися одна від одної. Мрія короля Торадіна про об’єднане людство зрештою зникла.",
    },
},

[175738] = {
    en = "Aegwynn and the Dragon Hunt",
    T  = "Егвінн і полювання на драконів",
    pages = {
        [1] = "Поки політичні інтриги та суперечки між сімома людськими націями то набирали сили, то вщухали, династія Хранителів незмінно пильнувала, не даючи хаосу взяти гору. За ці роки було багато Хранителів, але лише один з них у будь-який конкретний момент часу володів магічною силою Тірісфала. Одна з останніх Хранительниць тієї епохи прославилася як могутня войовниця, що боролася проти темряви.",
        [2] = "Егвінн, запальна дівчина-людина, заслужила визнання Ордену й отримала звання Охоронниці. Егвінн енергійно працювала над тим, щоб вистежувати й знищувати демонів, де б вона їх не знаходила, але часто ставила під сумнів авторитет Ради Тірісфала, в якій домінували чоловіки.",
        [3] = "Вона вважала, що стародавні ельфи та літні чоловіки, які очолювали раду, були надто консервативними у своїх поглядах і не мали достатньої далекоглядності, щоб остаточно покласти край конфлікту з хаосом. Втрачаючи терпіння від тривалих обговорень і дебатів, вона прагнула довести свою гідність перед колегами та начальством, і тому в вирішальних ситуаціях часто віддавала перевагу відвазі, а не мудрості.",
        [4] = "У міру того, як її володіння космічною силою Тірісфала зростало, Егвінн дізналася про існування низки могутніх демонів, які бродили по крижаному північному континенті Нортренд. Відправившись на далеку північ, Егвінн простежила слід демонів аж до гір. Там вона виявила, що демони полювали на одне з останніх вцілілих драконячих стад і висмоктували з цих древніх істот їхню вроджену магію.",
        [5] = "Могутні дракони, які втекли від невпинного наступу людських суспільств, виявилися не в змозі протистояти темній магії Легіону. Егвінн зіткнулася з демонами і, за допомогою благородних драконів, знищила їх. Однак, коли останнього демона було вигнано зі світу смертних, на півночі розігралася величезна буря.",
        [6] = "На небі над Нортрендом з’явилося величезне темне обличчя. Саргерас, король демонів і володар Палкого Легіону, з'явився перед Егвінн, випромінюючи пекельну енергію. Він повідомив молодій Охоронниці, що час Тірісфала добігає кінця і що світ незабаром схилиться перед натиском Легіону.",
        [7] = "Горда Егвінн, вважаючи себе рівною загрозливому богу, спрямувала свої сили проти аватара Саргераса. З дивовижною легкістю Егвінн обрушила на володаря демонів свої сили й зуміла знищити його фізичну оболонку. Побоюючись, що дух Саргераса може залишитися, Егвінн замкнула зруйновану оболонку його тіла в одній із стародавніх зал Калімдора, які були скинуті на дно моря під час обвалу Колодязя Вічності.",
        [8] = "Егвінн ніколи не дізналася б, що вчинила саме так, як і планував Саргерас. Вона мимоволі вирішила долю світу смертних, адже Саргерас у момент своєї фізичної смерті переніс свій дух у ослаблене тіло Егвінн. Не знаючи про це, молода Хранителька не підозрювала, що Саргерас ще довгі роки залишатиметься прихованим у найтемніших глибинах її душі.",
    },
},

[175739] = {
    en = "War of the Three Hammers",
    T  = "Війна трьох молотів",
    pages = {
        [1] = "Гноми з гори Айронфордж жили в мирі протягом багатьох довгих століть. Однак їхнє суспільство стало занадто великим для меж їхніх гірських міст. Хоча могутній Верховний король Модімус Анвілмар правив усіма гномами справедливо й мудро, у гномському суспільстві виникли три впливові угруповання.",
        [2] = "Клан Бронзобородих, очолюваний таном Мадораном Бронзобородим, підтримував тісні зв’язки з Верховним королем і виступав традиційним захисником гори Айронфордж. Клан Диких Молотів, очолюваний таном Хардросом Диким Молотом, населяв передгір'я та скелі навколо підніжжя гори й прагнув здобути більший контроль у місті.",
        [3] = "Третьою фракцією був клан Темного Заліза, яким керував чародій-тан Тауріссан. Темні Залізні ховалися в найглибших тінях під горою й плели змови як проти своїх родичів із клану Бронзобородих, так і проти клану Диких Молотів.",
        [4] = "Певний час між трьома фракціями зберігався хиткий мир, але напруга спалахнула, коли Верховний король Анвілмар помер від старості. Три правлячі клани вступили у війну за контроль над самим Айронфорджем. Громадянська війна карликів вирувала під землею протягом багатьох років. Зрештою Бронзобороди, які мали найбільшу постійну армію, вигнали Темних Залізних та Диких Молотів з-під гори.",
        [5] = "Хардрос та його воїни з племені Диких Молотів вирушили на північ через захисні ворота Дун-Алгаза і заснували власне королівство на віддаленій вершині Грім-Батол. Там Дикі Молоти процвітали й відновили свої скарби. Тауріссану та його Темним Залізним пощастило не так. Принижені й розлючені поразкою, вони поклялися помститися Айронфоргу. Повівши свій народ далеко на південь, Тауріссан заснував місто (яке назвав на свою честь) у мальовничих горах Червоногір'я.",
        [6] = "Процвітання та плин років майже не пом’якшили ненависть Темнозалізних до своїх родичів. Тауріссан та його дружина-чарівниця Модгуд розпочали двофронтовий наступ проти Айронфорджа та Грім-Батола. Темнозалізні були рішуче налаштовані привласнити собі весь Каз-Модан.",
        [7] = "Армії Темного Заліза обрушилися на твердині своїх родичів і ледь не захопили обидва королівства. Однак Мадоран Бронзобородий зрештою привів свій клан до вирішальної перемоги над магічною армією Тауріссана. Тауріссан та його слуги втекли назад у безпеку свого міста, не підозрюючи про події, що розгорталися в Грім-Батолі, де армія Модгуда зазнала не меншої поразки у бою проти Хардроса та його воїнів Диких Молотів.",
        [8] = "Зустрічаючись віч-на-віч із ворожими воїнами, Модгуд використовувала свої сили, щоб вселити страх у їхні серця. Тіні рухалися за її наказом, а темні істоти виповзали з глибин землі, щоб переслідувати Вайлдхаммерів у їхніх власних залах. Зрештою Модгуд прорвалася крізь ворота й взяла в облогу саму фортецю. Вайлдхаммери відчайдушно билися, а сам Хардрос продирався крізь бурхливу юрбу, щоб убити королеву-чаклунку.",
        [9] = "Втративши свою королеву, Темні Залізні втекли перед гнівом Диких Молотів. Вони кинулися на південь, до твердині свого короля, але там зіткнулися з військами Айронфорджа, які прибули на допомогу Грім-Батолу. Опинившись у тиску між двома арміями, рештки військ Темних Залізних були повністю знищені.",
        [10] = "Об'єднані війська Айронфорджа та Грім-Батола потім повернули на південь, маючи намір раз і назавжди знищити Тауріссана та його «Темних Залізних». Вони ще не встигли далеко відійти, як лють Тауріссана спричинила заклинання катастрофічних масштабів. Прагнучи прикликати надприродного слугу, який забезпечив би йому перемогу, Тауріссан звернувся до древніх сил, що спали в надрах світу. На його подив — і, зрештою, на його загибель — істота, що з’явилася, виявилася жахливішою за будь-який кошмар, який він міг собі уявити.",
        [11] = "Рагнарос, Володар Вогню, безсмертний повелитель усіх вогняних елементалів, був вигнаний Титанами ще в давні часи, коли світ тільки зароджувався. Тепер, звільнений завдяки заклику Тауріссана, Рагнарос знову прорвався на світ. Апокаліптичне відродження Рагнароса в Азероті розтрощило Гори Червоного хребта й створило бурхливий вулкан у самому центрі руйнувань.",
        [12] = "Вулкан, відомий як Гора Чорної Скелі, межував з Палючим Ущелиною на півночі та Палючими Степами на півдні. Хоча Тауріссан загинув від рук сил, яких він сам випустив на волю, його брати, що вижили, зрештою були поневолені Рагнаросом та його елементалями. Вони й донині перебувають у глибинах Чорної Скелі.",
        [13] = "Побачивши жахливі руйнування та пожежі, що поширювалися по південних горах, король Мадоран і король Хардрос зупинили свої війська й поспішно повернули назад до своїх королівств, не бажаючи стикатися з грізним гнівом Рагнароса.",
        [14] = "Бронзобороди повернулися до Айронфорджа й відбудували своє славетне місто. Дикі Молоти також повернулися додому, у Грім-Батол. Однак смерть Модгуда залишила зловісну пляму на гірській фортеці, і Дикі Молоти визнали її непридатною для проживання.",
        [15] = "У їхніх серцях панувала гіркота через втрату улюбленої батьківщини. Король Бронзобородий запропонував Диким Молотам місце для проживання в межах Айронфорджа, але ті рішуче відмовилися. Хардрос повів свій народ на північ, у напрямку земель Лордаерону. Оселившись у пишних лісах Замежжя, Дикі Молоти збудували місто Пік Орлиного Гнізда, де вони стали ближчими до природи й навіть зблизилися з могутніми грифонами цієї місцевості.",
        [16] = "Прагнучи зберегти відносини та торгівлю зі своїми родичами, гноми з Айронфорджа збудували дві величезні арки — Тандольський міст — щоб з’єднати Хаз-Модан і Лордаерон. Завдяки взаємній торгівлі обидва королівства процвітали. Після смерті Мадорана та Хардроса їхні сини спільно замовили дві величні статуї на честь своїх батьків.",
        [17] = "Ці дві статуї мали стояти на сторожі переходу до південних земель, які перетворилися на вулканічну місцевість внаслідок палючої присутності Рагнароса. Вони слугували як попередженням для всіх, хто наважиться напасти на королівства гномів, так і нагадуванням про те, яку ціну заплатили Темні Залізні за свої злочини.",
        [18] = "Протягом кількох років обидва королівства підтримували тісні зв’язки, але «Дикі Молоти» сильно змінилися під впливом жахіть, які вони пережили в Грім-Батолі. Вони почали жити на поверхні, на схилах Піку Ері, замість того, щоб вибудовувати величезне королівство всередині гори. Ідеологічні розбіжності між двома кланами карликів, що залишилися, зрештою призвели до їхнього розставання.",
    },
},

[175740] = {
    en = "The Last Guardian",
    T  = "«Останній охоронець»",
    pages = {
        [1] = "Охоронниця Егвінн з роками стала все могутнішою і, використовуючи енергію Тірісфала, значно продовжила своє життя. Наївно вірячи, що вона остаточно перемогла Саргераса, вона продовжувала захищати світ від поплічників короля демонів майже дев'ятсот років. Однак Рада Тірісфала врешті-решт постановила, що її правління добігло кінця.",
        [2] = "Рада наказала Егвінн повернутися до Даларана, щоб вони могли обрати нового спадкоємця сили Хранителя. Однак Егвінн, яка завжди ставилася до Ради з недовірою, вирішила обрати спадкоємця самостійно.",
        [3] = "Горда Егвінн планувала народити сина, якому вона передала б свою силу. Вона не мала наміру дозволити Ордену Тірісфала маніпулювати її наступником так само, як вони намагалися маніпулювати нею. Подорожуючи до південної країни Азерота, Егвінн знайшла ідеального чоловіка, який мав стати батьком її сина: вправного людського мага на ім’я Ніелас Аран.",
        [4] = "Аран був придворним чарівником і радником короля Азерота. Егвінн спокусила чарівника і зачала від нього сина. Природна схильність Ніеласа до магії глибоко вкоренилася в ще ненароджену дитину і визначила ті трагічні кроки, які дитина згодом зробить. У дитину також була вкладена сила Тірісфала, проте вона мала пробудитися лише тоді, коли він досягне фізичної зрілості.",
        [5] = "Минув час, і Егвінн народила сина у відокремленому гаї. Назвавши хлопчика Медів, що в перекладі з мови високих ельфів означає «хранитель таємниць», Егвінн вірила, що він виросте і стане наступним Хранителем. На жаль, злісний дух Саргераса, що ховався в ній, опанував беззахисну дитину ще тоді, коли вона перебувала в її лоні. Егвінн навіть не підозрювала, що наймолодший Хранитель світу вже опинився під владою свого найбільшого ворога.",
        [6] = "Переконавшись, що її дитина здорова й ціла, Егвінн привезла маленького Медівха до двору Азерота й залишила його там, щоб його виховували його смертний батько та його народ. Потім вона вирушила в дику місцевість і готувалася перейти в той потойбічний світ, який на неї чекав. Медів виріс сильним хлопчиком і не мав уявлення про потенційну силу свого тирісфальського спадку.",
        [7] = "Саргерас чекав слушного моменту, поки сила юнака не проявилася. До того часу, як Медів досяг підліткового віку, він став дуже популярним в Азероті завдяки своїм магічним здібностям і часто вирушав у пригоди зі своїми двома друзями: Ллейном, принцом Азерота, та Андуїном Лотаром, одним із останніх нащадків роду Араті. Ці троє хлопців постійно влаштовували витівки по всьому королівству, але прості люди їх дуже любили.",
        [8] = "Коли Медіву виповнилося чотирнадцять років, космічна сила, що таїлася в ньому, пробудилася й зіткнулася з всепроникним духом Саргераса, який причаївся в його душі. Медіву впав у кататонічний стан, який тривав багато років.",
        [9] = "Прокинувшись із коми, він виявив, що став дорослим, а його друзі Ллейн та Андуїн стали регентами Азерота. Хоча він і прагнув використати свої неймовірні новонабуті сили для захисту землі, яку вважав своєю батьківщиною, темний дух Саргераса спотворив його думки та емоції, спрямувавши їх на підступну мету.",
        [10] = "Саргерас насолоджувався темним серцем Медівха, бо знав, що його плани щодо другого вторгнення у світ наближаються до завершення і що останній Хранитель світу допоможе втілити їх у життя.",
    },
},

[175741] = {
    en = "Kil'jaeden and the Shadow Pact",
    T  = "Кіл'яеден і Пакту Тіней",
    pages = {
        [1] = "Приблизно в той час, коли Медів народився на Азероті, Кіл'яеден-Ошуканець сидів у Скрученому Ефірі серед своїх послідовників, занурившись у роздуми. Цей хитрий володар демонів, виконуючи наказ свого господаря Саргераса, готував друге вторгнення Палаючого Легіону на Азерот.",
        [2] = "Цього разу він не допустить жодних помилок. Кіл'яеден дійшов висновку, що йому потрібні нові сили, аби послабити оборону Азерота ще до того, як Легіон ступить на землю цього світу. Якщо смертні раси, такі як нічні ельфи та дракони, будуть змушені боротися з новою загрозою, вони стануть надто слабкими, щоб чинити будь-який реальний опір, коли Легіон розпочне справжнє вторгнення.",
        [3] = "Саме в цей час Кіл'яеден відкрив для себе пишний світ Дренора, що мирно плавав у Великій Темній Позамежності. Дренор, де мешкали орки, що дотримувалися шаманізму та жили кланами, а також миролюбні драені, був настільки ж ідилічним, наскільки й безмежним.",
        [4] = "Шляхетні клани орків блукали по відкритих преріях і полювали заради розваги, тоді як допитливі драені будували примітивні міста серед височенних скель і вершин цього світу. Кіл’яеден знав, що мешканці Дренору мають великий потенціал для служіння Палкому Легіону, якщо їх правильно виховати.",
        [5] = "З цих двох рас Кіл'яеден побачив, що войовничі орки були більш вразливими до спотворення Легіону. Він зачарував старшого шамана орків, Нер'жула, майже так само, як колись у давні часи Саргерас підкорив собі королеву Азшару. Використовуючи хитрого шамана як посередника, демон поширив жагу до бою та дикунство серед кланів орків.",
        [6] = "Незабаром духовна раса перетворилася на кровожерливий народ. Тоді Кіл'яеден закликав Нер'жула та його народ зробити останній крок: повністю віддатися прагненню смерті та війни. Однак старий шаман, відчуваючи, що його народ назавжди стане рабом ненависті, якимось чином опирався наказу демона.",
        [7] = "Розчарований опором Нер'жула, Кіл'яеден почав шукати іншого орка, який би віддав свій народ у руки Легіону. Хитрий володар демонів нарешті знайшов того, хто був готовий стати його послідовником, — амбітного учня Нер'жула, Гул'дана. Кіл'яеден пообіцяв Гул'дану незмірну силу в обмін на його беззаперечну покірність.",
        [8] = "Молодий орк став завзятим послідовником демонічної магії й перетворився на наймогутнішого смертного чаклуна в історії. Він навчав інших молодих орків таємним мистецтвам і прагнув викорінити шаманські традиції орків. Гул’дан відкрив своїм побратимам новий вид магії — жахливу нову силу, що тхнула загибеллю.",
        [9] = "Кіл'яеден, прагнучи зміцнити свою владу над орками, допоміг Гул'дану заснувати «Раду Тіней» — таємну секту, яка маніпулювала кланами та поширювала використання магії чаклунів по всьому Дренору. У міру того як дедалі більше орків починали користуватися магією чаклунів, мальовничі поля та струмки Дренора почали чорніти й зникати. З часом безкрайні прерії, які орки вважали своєю батьківщиною протягом багатьох поколінь, засохли, залишивши після себе лише червону безплідну землю. Енергія демонів повільно вбивала цей світ.",
    },
},

[175742] = {
    en = "Rise of the Horde",
    T  = "Піднесення Орди",
    pages = {
        [1] = "Під таємним контролем Гул'дана та його Ради Тіней орки ставали дедалі агресивнішими. Вони споруджували величезні арени, де орки відточували свої воїнські навички у випробуваннях, що супроводжувалися боями та смертю. У цей період декілька вождів кланів виступили проти зростаючої розбещеності своєї раси.",
        [2] = "Один із таких вождів, Дуротан із клану Морозних Вовків, застерігав орків від того, щоб вони не піддалися ненависті та люті. Однак його слова залишилися непочутими, оскільки на перший план вийшли більш впливові вожді, такі як Гром Пекельний Крик із клану Воєнних Пісень, які стали провідниками нової ери воєн та панування.",
        [3] = "Кіл'яеден знав, що клани орків майже готові, але йому потрібно було переконатися в їхній беззаперечній відданості. Таємно він доручив Раді Тіней викликати Маннорота Руйнівника — живе втілення руйнування та люті. Гул'дан скликав вождів кланів і переконав їх, що, випивши бурхливу кров Маннорота, вони стануть абсолютно непереможними.",
        [4] = "Під проводом Грома Пекельного Крику всі вожді кланів, крім Дуротана, випили напій і тим самим прирекли себе на долю рабів Палкого Легіону. Наділені гнівом Маннорота, вожді несвідомо поширили це поневолення на своїх нічого не підозрюючих побратимів.",
        [5] = "Охоплені прокляттям цієї нової жаги до крові, орки прагнули виплеснути свою лють на всіх, хто стояв на їхньому шляху. Відчувши, що час настав, Гул'дан об'єднав ворогуючі клани в єдину, непереможну Орду.",
        [6] = "Однак, розуміючи, що різні вожді, такі як Пекельний Крик та Оргрім Руйнівний Молот, будуть змагатися за загальне панування, Гул’дан поставив маріонеткового вождя, щоб той керував цією новою Ордою. Чорна Рука Руйнівник, особливо розбещений і жорстокий воєначальник орків, був обраний маріонеткою Гул'дана. Під командуванням Чорної Руки Орда вирушила, щоб випробувати свої сили у битві проти наївних драені.",
        [7] = "Протягом кількох місяців Орда знищила майже всіх драені, що мешкали на Дренорі. Лише поодиноким вцілілим вдалося уникнути страхітливого гніву орків. Окрилений перемогою, Гул’дан насолоджувався силою та могутністю Орди. Проте він розумів, що без ворогів, з якими можна було б битися, Орда з’їсть сама себе у нескінченних внутрішніх чварах, нестримний її апетит до славетної різанини.",
        [8] = "Кіл'яеден знав, що Орда нарешті готова. Орки стали найпотужнішою зброєю Палаючого Легіону. Хитрий демон поділився своїми знаннями зі своїм господарем, який з нетерпінням чекав на цю мить, і Саргерас погодився, що час його помсти нарешті настав.",
    },
},

[175745] = {
    en = "The Dark Portal and the Fall of Stormwind",
    T  = "«Темний портал» і падіння Штормовію",
    pages = {
        [1] = "Поки Кіл'яеден готував Орду до вторгнення в Азерот, Медів продовжував боротися за свою душу проти Саргераса. Король Лейн, благородний монарх Штормовію, почав з обережністю ставитися до темряви, яка, здавалося, заплямовувала душу його колишнього друга.",
        [2] = "Король Ллейн поділився своїми побоюваннями з Андуїном Лотаром, останнім нащадком роду Араті, якого він призначив своїм військовим заступником. Проте жоден із них не міг уявити, що повільне занурення Медівха у божевілля спричинить ті жахи, що мали статися.",
        [3] = "В якості останнього стимулу Саргерас пообіцяв наділити Гул'дана великою силою, якщо той погодиться очолити Орду в поході на Азерот. Через Медівха Саргерас повідомив чаклуну, що той зможе стати живим богом, якщо знайде підводну гробницю, куди майже тисячу років тому охоронниця Егвінн поховала покалічене тіло Саргераса.",
        [4] = "Гул'дан погодився і вирішив, що, як тільки мешканці Азерота будуть розгромлені, він знайде легендарну гробницю й отримає свою нагороду. Переконавшись, що Орда слугуватиме його цілям, Саргерас наказав розпочати вторгнення.",
        [5] = "Спільними зусиллями Медів та чаклуни Ради Тіней відкрили міжвимірні ворота, відомі як Темний портал. Цей портал з'єднав Азерот і Дренор, і був достатньо великим, щоб через нього могли пройти цілі армії. Гул'дан відправив через портал розвідників-орків, щоб ті оглянули землі, які їм належало завоювати. Розвідники, що повернулися, запевнили Раду Тіней, що світ Азерота готовий до завоювання.",
        [6] = "Все ще переконаний, що розбещення Гул'дана знищить його народ, Дуротан знову виступив проти чаклунів. Хоробрий воїн стверджував, що чаклуни руйнують чистоту духу орків і що це безрозсудне вторгнення стане для них загибеллю. Гул'дан, не маючи змоги ризикнути вбити такого популярного героя, був змушений вигнати Дуротана та його клан «Морозних вовків» у найвіддаленіші куточки цього нового світу.",
        [7] = "Після того як вигнані «Морозні Вовки» увірвалися крізь портал, за ними послідували лише кілька кланів орків. Ці орки швидко розгорнули оперативну базу в Чорному Болоті — темній і болотистій місцевості, що розташована далеко на схід від королівства Штормовій. Коли орки почали розходитися й досліджувати нові землі, вони одразу ж вступили в конфлікт із людськими захисниками Штормовію. $B$B",
        [8] = "Хоча ці сутички зазвичай швидко закінчувалися, вони добре проілюстрували слабкі та сильні сторони обох ворогуючих видів. Ллейн і Лотар так і не змогли зібрати точні дані про чисельність орків і могли лише здогадуватися, з якими силами їм доведеться мати справу.",
        [9] = "Через кілька років більша частина орківської Орди переправилася до Азероту, і Гул’дан вирішив, що настав час для головного удару по людству. Орда кинула всі свої сили на нічого не підозрююче королівство Штормовій.",
        [10] = "Поки війська Азерота та Орди зіштовхувалися на території королівства, внутрішні конфлікти почали даватися взнаки в обох арміях. Король Лейн, який вважав, що звіроподібні орки не здатні завоювати Азерот, з презирством тримався на своїй позиції у столиці — Штормовій. Однак сер Лотар переконався, що битву слід перенести безпосередньо на територію ворога, і йому довелося обирати між своїми переконаннями та вірністю королю.",
        [11] = "Вирішивши довіритися своїм інстинктам, Лотар штурмував вежу-фортецю Медівха — Каразан — за допомогою молодого учня чарівника, Хадгара. Хадгару та Лотару вдалося перемогти одержимого Хранителя, якого вони визнали джерелом конфлікту.",
        [12] = "Знищивши тіло Медівха, Лотар і молодий учень мимоволі вигнали дух Саргераса в безодню. Як наслідок, чистий і доброчесний дух Медівха також отримав можливість продовжувати існувати... і блукати астральним планом ще багато років.",
        [13] = "Хоча Медів був переможений, Орда продовжувала домінувати над захисниками Штормовію. У міру наближення перемоги Орди Оргрім Думхаммер, один із найвидатніших вождів орків, почав усвідомлювати, наскільки глибоко розбещення поширилося серед кланів з часів їхнього перебування в Дренорі.",
        [14] = "Його давній товариш, Дуротан, повернувся з вигнання і вкотре попередив його про зраду Гул'дана. У відповідь вбивці Гул'дана швидко розправилися з Дуротаном та його родиною, залишивши в живих лише його немовля-сина. Думхаммер не знав, що немовля-сина Дуротана знайшов людський офіцер Еделас Блекмур і взяв його в рабство. $B$B$B$BЦей орк-немовля одного дня стане найвеличнішим вождем, якого коли-небудь знав його народ.",
        [15] = "Обурений смертю Дуротана, Оргрім вирішив звільнити Орду від демонічного спотворення і зрештою став вождем Орди, вбивши спотворену маріонетку Гул'дана — Чорну Руку. Під його рішучим керівництвом невблаганна Орда нарешті взяла в облогу фортецю Штормовій.",
        [16] = "Король Лейн сильно недооцінив міць Орди і безпорадно спостерігав, як його королівство падало під натиском зеленошкірих загарбників. Зрештою короля Лейна вбила одна з найкращих вбивць Ради Тіней — напіворк Гарона.",
        [17] = "Лотар та його воїни, повертаючись додому з Каразана, сподівалися зупинити кровопролиття та врятувати свою колись славну батьківщину. Натомість вони повернулися занадто пізно й знайшли своє улюблене королівство в димних руїнах. Орківська Орда продовжувала спустошувати околиці й привласнювала собі навколишні землі. Змушені ховатися, Лотар і його товариші склали сувору присягу повернути свою батьківщину за будь-яку ціну.",
    },
},

[175746] = {
    en = "The Alliance of Lordaeron",
    T  = "Альянс Лордаерона",
    pages = {
        [1] = "Лорд Лотар зібрав залишки армій Азерота після їхньої поразки біля фортеці Штормовій, а потім організував масовий перехід через море до північного королівства Лордаерон. Переконані, що, якщо не чинити опору, Орда переможе все людство, лідери семи людських націй зібралися на нараду й домовилися об’єднатися в організацію, яка згодом стала відомою як Альянс Лордаерону.",
        [2] = "Вперше за майже три тисячі років розрізнені народи Аратора знову об’єдналися під спільним прапором. Лорд Лотар, призначений Верховним головнокомандувачем військ Альянсу, готував свої війська до наступу Орди.",
        [3] = "За підтримки своїх заступників — Утера Світлоносія, адмірала Дейліна Праудмура та Тураліона — Лотар зміг переконати й напівлюдські раси Лордаерона в існуванні насувається загрози. Альянсу вдалося заручитися підтримкою стоїчних гномів з Айронфорджа та невеликої кількості високих ельфів з Кель'Таласа.",
        [4] = "Ельфи, очолювані на той час Анастеріаном Сонцекроком, в основному не виявляли інтересу до майбутнього конфлікту. Однак вони були зобов’язані допомогти Лотару, оскільки він був останнім нащадком роду Араті, який у давні часи надавав допомогу ельфам.",
        [5] = "Орда, яку тепер очолював вождь Думхаммер, привела огрів зі свого рідного світу Дренора та приєднала до своїх лав знедолених лісових тролів Амані. Розпочавши масштабну кампанію з метою захоплення королівства карликів Хаз-Модан та південних околиць Лордаерону, Орда без особливих зусиль знищила всіх супротивників.",
        [6] = "Епічні битви Другої війни варіювалися від масштабних морських сутичок до грандіозних повітряних боїв. Якимось чином Орда відшукала могутній артефакт, відомий як «Душа Демона», і використала його, щоб поневолити древню Королеву Драконів, Алексстразу. Погрожуючи знищити її дорогоцінні яйця, Орда змусила Алекстразу відправити своїх дорослих дітей на війну. Благородні червоні дракони були змушені битися за Орду — і вони билися.",
        [7] = "Війна вирувала на континентах Хаз-Модан, Лордаерон та на самому Азероті. У рамках своєї північної кампанії Орді вдалося спалити прикордонні землі Квель-Таласа, тим самим забезпечивши остаточну прихильність ельфів до справи Альянсу. Великі міста та селища Лордаерону були зрівняні з землею та спустошені внаслідок конфлікту. Незважаючи на відсутність підкріплення та перевагу супротивника, Лотару та його союзникам вдалося стримати напад ворогів.",
        [8] = "Однак у останні дні Другої війни, коли перемога Орди над Альянсом здавалася майже гарантованою, між двома наймогутнішими орками Азерота спалахнула жахлива ворожнеча. Поки Думхаммер готував свій останній штурм столиці Лордаерона — штурм, який би знищив останні залишки Альянсу, — Гул'дан та його послідовники покинули свої позиції й вирушили в море.",
        [9] = "Збентежений Думхаммер, втративши майже половину своїх бойових сил внаслідок зради Гул'дана, був змушений відступити й відмовитися від свого найбільшого шансу на перемогу над Альянсом.",
        [10] = "Жадібний до влади Гул'дан, одержимий ідеєю здобути божественність, вирушив у відчайдушний пошук підводної гробниці Саргераса, яка, на його думку, приховувала таємниці абсолютної влади. Вже прирекши своїх побратимів-орків на рабство у «Палаючому Легіоні», Гул'дан анітрохи не зважав на свій нібито обов'язок перед Думхаммером.",
        [11] = "За підтримки кланів «Бурерозбивачів» та «Молота Сутінків» Гул’дану вдалося підняти Гробницю Саргераса з морського дна. Однак, коли він відкрив стародавню, затоплену гробницю, там на нього чекали лише божевільні демони.",
        [12] = "Прагнучи покарати непокірних орків за їхню згубну зраду, Думхаммер відправив свої війська, щоб вбити Гул'дана та повернути зрадників у лоно спільноти. За свою необачність Гул'дан був розірваний на шматки божевільними демонами, яких він сам випустив на волю. Втративши свого ватажка, клани зрадників швидко зазнали поразки від розлючених легіонів Думхаммера.",
        [13] = "Хоча повстання було придушене, Орда не змогла відшкодувати ті жахливі втрати, яких зазнала. Зрада Гул'дана дала Альянсу не лише надію, а й час, щоб перегрупуватися та завдати удару у відповідь.",
        [14] = "Лорд Лотар, побачивши, що Орда розпадається зсередини, зібрав останні сили та відтіснив Дуумхаммера на південь, назад у зруйновану серцевину Штормовію. Там війська Альянсу заблокували відступаючу Орду в вулканічній фортеці Шпиль Чорної Скелі. Хоча лорд Лотар загинув у бою біля підніжжя Шпиля, його заступник, Тураліон, в останню мить згуртував війська Альянсу й відкинув Орду назад у безодню Болота Скорботи.",
        [15] = "Військам Тураліона вдалося знищити Темний портал — містичний прохід, що з'єднував орків із їхнім рідним світом Дренором. Відрізана від підкріплень і роздроблена внутрішніми суперечками, Орда зрештою розпалася і впала під натиском Альянсу.",
        [16] = "Розрізнені клани орків були швидко зібрані й поміщені в охоронювані табори для інтернованих. Хоча здавалося, що Орда була остаточно розгромлена, дехто все ще дуже скептично ставився до того, що мир триватиме довго. Хадгар, який на той час вже був досить відомим архімагом, переконав верховне командування Альянсу збудувати фортецю Нетергард, яка б охороняла руїни Темного порталу та гарантувала, що подальших вторгнень із Дренору не буде.",
    },
},

[175747] = {
    en = "The Invasion of Draenor",
    T  = "Вторгнення на Дренор",
    pages = {
        [1] = "Коли вогонь Другої війни згас, Альянс вжив рішучих заходів для стримування загрози з боку орків. У південній частині Лордаерона було збудовано низку великих таборів для інтернованих, призначених для утримання полонених орків. Ці табори, які охоронялися як паладинами, так і досвідченими солдатами Альянсу, виявилися надзвичайно ефективними.",
        [2] = "Хоча полонені орки були напружені й прагнули знову вступити в бій, різні наглядачі табору, що базувалися в старій тюремній фортеці Дурнхолд, забезпечували спокій і підтримували видимість суворого порядку.",
        [3] = "Однак у пекельному світі Дренора нова армія орків готувалася завдати удару по нічого не підозрюючому Альянсу. Нер'жул, колишній наставник Гул'дана, об'єднав під своїм темним прапором клани орків, що вціліли. За підтримки клану Тіньомісяця старий шаман планував відкрити на Дренорі низку порталів, які б привели Орду до нових, незайманих світів.",
        [4] = "Щоб забезпечити енергією свої нові портали, йому знадобилася низка зачарованих артефактів з Азероту. Щоб їх роздобути, Нер'жул знову відкрив Темний портал і відправив своїх ненаситних слуг у напад крізь нього.",
        [5] = "Нова Орда на чолі з досвідченими вождями, такими як Гром Пекельний Крик та Кілрог Мертве Око (з клану «Кривава Ущелина»), застала зненацька оборонні сили Альянсу та пронеслася руйнівним шквалом по сільській місцевості. Під точним командуванням Нер'жула орки швидко зібрали необхідні їм артефакти й втекли назад у безпеку Дренора.",
        [6] = "Король Лордаерона Теренас, переконаний у тому, що орки готують нове вторгнення в Азерот, скликав своїх найнадійніших соратників. Він наказав генералу Тураліону та архімагу Хадгару очолити експедицію через Темний портал, щоб раз і назавжди покласти край загрозі з боку орків. Війська Тураліона та Хадгара увійшли до Дренору й неодноразово вступали в сутички з кланами Нер'жула на спустошеному Півострові Пекельного Вогню.",
        [7] = "Навіть за допомогою високої ельфійки Аллерії Віндранер, карлика Курдрана Вайлдхаммера та досвідченого воїна Даната Троллбейна Хадгару не вдалося завадити Нер'жулу відкрити свої портали в інші світи.",
        [8] = "Нер'жул нарешті відкрив свої портали в інші світи, але не передбачив, яку жахливу ціну йому доведеться за це заплатити. Гігантська енергія порталів почала розривати саму тканину Дренору. Поки війська Тураліона відчайдушно боролися, щоб повернутися додому, в Азерот, світ Дренору почав руйнуватися. Гром Пекельний Крик і Кілрог Мертве Око, усвідомивши, що божевільні плани Нер'жула приречуть на загибель усю їхню расу, зібрали решту орків і втекли до відносної безпеки Азерота.",
        [9] = "На Дренорі Тураліон і Хадгар вирішили піти на крайню жертву — знищити Темний Портал зі свого боку. Хоча це коштувало їм життя, а також життя їхніх товаришів, вони розуміли, що це єдиний спосіб забезпечити виживання Азерота. Навіть коли Пекельний Крик і Мертве Око у відчайдушній спробі здобути свободу прорубували собі шлях крізь ряди людей, Темний Портал вибухнув за їхніми спинами. Для них, як і для решти орків на Азероті, дороги назад уже не було.",
        [10] = "Нер'жул та його вірний клан Тіньового Місяця пройшли крізь найбільший із щойно створених порталів, коли потужні вулканічні виверження почали розривати континенти Дренора на шматки. Палаючі моря піднялися й бурхливо прокотилися по розтрощеному ландшафту, а змучений світ зрештою був поглинений грандіозним, апокаліптичним вибухом.",
    },
},

[175748] = {
    en = "The Birth of the Lich King",
    T  = "Народження Короля Ліча",
    pages = {
        [1] = "Нер'жул та його послідовники увійшли до «Викрученого Потойбіччя» — ефірного виміру, що з'єднує всі світи, розкидані по Великій Темній Далечі. На жаль, там на них чекали Кіл'яеден та його демонічні слуги. Кіл'яеден, який поклявся помститися Нер'жулу за його гордовитий опір, повільно розривав тіло старого шамана на шматки, один за одним.",
        [2] = "Кіл'яеден зберіг дух шамана живим і неушкодженим, через що Нер'жул болісно усвідомлював жахливе розчленування свого тіла. Хоча Нер'жул благав демона звільнити його дух і дарувати йому смерть, демон похмуро відповів, що Кровний пакт, який вони уклали давно, досі залишається чинним, і що Нер'жул ще має виконувати своє призначення.",
        [3] = "Невдача орків у спробі завоювати світ для Палаючого Легіону змусила Кіл'яедена створити нове військо, щоб посіяти хаос у королівствах Азерота. Не можна було допустити, щоб це нове військо стало жертвою тих самих дріб'язкових суперечок і внутрішніх конфліктів, які роздирали Орду. Вона мала бути безжальною та цілеспрямованою у виконанні своєї місії. Цього разу Кіл'яеден не міг собі дозволити провалитися.",
        [4] = "Утримуючи дух Нер'жула в безпорадному стані стазису, Кіл'яеден дав йому останній шанс — служити Легіону або зазнати вічних мук. І знову Нер'жул необачно погодився на угоду з демоном. Дух Нер'жула було поміщено у спеціально виготовлений блок криги, твердої як алмаз, зібраної з найвіддаленіших куточків Звивистого Потойбіччя.",
        [5] = "Ув’язнений у замерзлій бочці, Нер’жул відчув, як його свідомість розширилася в десять тисяч разів. Змінений хаотичними силами демона, Нер’жул перетворився на примарну істоту з незбагненною силою. У ту мить орк, відомого як Нер’жул, був назавжди знищений, і народився Король Ліч.",
        [6] = "Вірні Нер'жулу лицарі смерті та послідовники Тіньового Місяця також зазнали перетворення під впливом хаотичної енергії демона. Злі чаклуни були розірвані на шматки й перетворені на скелетних лічів. Демони подбали про те, щоб навіть після смерті послідовники Нер'жула беззаперечно служили йому.",
        [7] = "Коли настав відповідний час, Кіл'яеден пояснив місію, заради якої він створив Короля Ліча. Нер'жул мав поширити по Азероту чуму смерті та жаху, яка назавжди знищила б людську цивілізацію. Усі, хто загине від цієї страшної чуми, повстануть як неживі, а їхні душі назавжди будуть підпорядковані залізній волі Нер'жула.",
        [8] = "Кіл'яеден пообіцяв, що якщо Нер'жул виконає його темну місію — знищити людство на землі, — він буде звільнений від прокляття й отримає нове, здорове тіло, в якому зможе жити.",
        [9] = "Хоча Нер'жул був поступливим і, здавалося, прагнув виконати свою роль, Кіл'яеден залишався скептичним щодо відданості своєї маріонетки. Утримання Короля Ліча безтілесним і ув'язненим у кришталевій бочці гарантувало його слухняність у короткостроковій перспективі, але демон розумів, що йому доведеться пильно стежити за ним. З цією метою Кіл'яеден закликав свою елітну демонічну гвардію — вампіричних лордів жаху — стежити за Нер'жулом і гарантувати, що той виконає своє жахливе завдання.",
        [10] = "Тіхондріус, наймогутніший і найхитріший із жахливих лордів, з ентузіазмом сприйняв цей виклик; його зачарувала жорстокість чуми та безмежний потенціал Ліча-Короля до геноциду.",
    },
},

[175749] = {
    en = "Icecrown and the Frozen Throne",
    T  = "«Крижана Корона» та «Замерзлий Трон»",
    pages = {
        [1] = "Кіл'яеден відкинув крижану труну Нер'жула назад у світ Азерота. Затверділий кристал промчав по нічному небу й врізався в безлюдний арктичний континент Нортренд, занурившись глибоко в льодовик Лідової Корони. Замерзлий кристал, деформований і пошрамований внаслідок бурхливого падіння, став схожим на трон, і незабаром у ньому прокинувся мстивий дух Нер'жула.",
        [2] = "З глибин «Замерзлого Трону» Нер'жул почав простягати свою безмежну свідомість і проникати в розуми корінних мешканців Нортренда. Не докладаючи особливих зусиль, він поневолив розуми багатьох місцевих істот, зокрема льодових тролів та лютих вендіго, і втягнув їхніх злісних побратимів у свою дедалі більшу тінь. Його психічні сили виявилися майже безмежними, і він використав їх, щоб створити невелику армію, яку розмістив у звивистих лабіринтах Льодової Корони.",
        [3] = "Поки Король Ліч вдосконалював свої здібності під пильним наглядом лордів жаху, він виявив віддалене людське поселення на околиці безкрайньої Драконової Пустки. З примхи Нер'жул вирішив випробувати свої сили на нічого не підозрюючих людях.",
        [4] = "Нер'жул випустив чуму нежиті — що зародилася в глибинах Замерзлого Трону — на арктичну пустку. Керуючи чумою лише силою своєї волі, він спрямував її прямо на людське селище. За три дні всі мешканці поселення загинули, але незабаром після цього мертві селяни почали повставати як зомбі. Нер'жул відчував їхні душі та думки так, ніби це були його власні.",
        [5] = "Бурхлива какофонія в його свідомості робила Нер'жула ще могутнішим, ніби їхні душі давали йому таке необхідне живлення. Він виявив, що керувати діями зомбі та спрямовувати їх на будь-яку мету, яку він забажає, — це дитяча забавка.",
        [6] = "Протягом наступних місяців Нер'жул продовжував експериментувати зі своєю чумою нежиті, підкорюючи всіх людських мешканців Нортренда. Бачачи, як його армія нежиті щодня зростає, він розумів, що наближається час справжнього випробування.",
    },
},

[175750] = {
    en = "The Battle of Grim Batol",
    T  = "Битва за Грім-Батол",
    pages = {
        [1] = "Тим часом на розтерзаних війною землях півдня розрізнені залишки Орди боролися за саме виживання. Хоча Грому Пекельному Крику та його клану «Військова Пісня» вдалося уникнути полону, Дед-Ай та його клан «Кривава Ущелина» були затримані й поміщені в табори інтернування в Лордаероні. Незважаючи на ці кровопролитні повстання, наглядачі таборів незабаром відновили контроль над своїми брутальними підопічними.",
        [2] = "Однак, про що Альянс не знав, великі сили орків все ще вільно бродили північними пустками Хаз-Модана. Клан «Драконопаща», очолюваний сумнозвісним чаклуном Некросом, використовував стародавній артефакт, відомий як «Душа Демона», щоб контролювати Королеву Драконів Алекстразу та її драконячий полк. Тримаючи Королеву драконів у заручниках, Некрос створив таємну армію в покинутій — а за деякими словами, проклятій — фортеці «Грім-Батол», що належала клану Диких Молотів.",
        [3] = "Плануючи кинути свої війська та могутніх червоних драконів на Альянс, Некрос сподівався возз’єднати Орду та продовжити завоювання Азерота. Його задум не здійснився: невеликій групі борців опору на чолі з людським магом Роніном вдалося знищити «Душу демона» та звільнити Королеву драконів від влади Некроса.",
        [4] = "У своєму гніві дракони Алексстрази рознесли Грім-Батол на шматки та спалили більшу частину клану «Драконяча Паща». Грандіозні плани Некроса щодо возз’єднання розвалилися, коли війська Альянсу зібрали решту вцілілих орків і відправили їх до підготовлених таборів для інтернованих. Поразка клану «Драконяча Паща» ознаменувала кінець Орди та кінець несамовитої кровожерливості орків.",
    },
},

[175751] = {
    en = "Lethargy of the Orcs",
    T  = "Апатія орків",
    pages = {
        [1] = "Минали місяці, і все більше полонених орків затримували та розміщували в таборах для інтернованих. Коли табори почали переповнюватися, Альянс був змушений спорудити нові табори на рівнинах на південь від Альтеракських гір. Щоб належним чином утримувати та забезпечувати зростаючу кількість таборів, король Теренас ввів новий податок для країн Альянсу.",
        [2] = "Цей податок, а також посилення політичної напруженості через прикордонні суперечки, спричинили масові заворушення. Здавалося, що крихкий союз, який об’єднав людські народи в найважчі часи, може розпастися в будь-яку мить.",
        [3] = "На тлі політичних потрясінь багато наглядачів таборів почали помічати тривожні зміни в поведінці своїх орків-полонених. Згодом спроби орків втекти з таборів або навіть вступити в сутички між собою стали значно рідшими. Орки ставали дедалі більш відстороненими та апатичними.",
        [4] = "Хоча в це й важко було повірити, орки — які колись вважалися найагресивнішою расою, яку коли-небудь бачили в Азероті, — повністю втратили волю до боротьби. Ця дивна апатія спантеличувала лідерів Альянсу й продовжувала згубно позначатися на орках, що стрімко слабшали.",
        [5] = "Дехто припускав, що причиною цієї незрозумілої апатії стала якась дивна хвороба, якою можуть заразитися лише орки. Однак архімаг Антонідас із Даларана висунув іншу гіпотезу. Досліджуючи ті нечисленні відомості про історію орків, які йому вдалося знайти, Антонідас дізнався, що орки протягом багатьох поколінь перебували під руйнівним впливом демонічної сили.",
        [6] = "Він припустив, що орки були спотворені цими силами ще до свого першого вторгнення в Азерот. Очевидно, демони отруїли кров орків, і в результаті ці звірі отримали надприродно підвищену силу, витривалість та агресивність.",
        [7] = "Антонідас висунув гіпотезу, що загальна апатія орків насправді не була хворобою, а наслідком відходу їхньої раси від нестабільної магії чаклунів, яка зробила їх грізними, спраглими крові воїнами.",
        [8] = "Хоча симптоми були очевидними, Антонідас не зміг знайти ліків від того стану, в якому перебували орки. До того ж багато його колег-магів, а також кілька впливових лідерів Альянсу стверджували, що пошук ліків для орків буде необачним кроком. Замислившись над загадковим станом орків, Антонідас дійшов висновку, що ліки для них мають бути духовними.",
    },
},

[175752] = {
    en = "The New Horde",
    T  = "Нова Орда",
    pages = {
        [1] = "Головний наглядач таборів інтернування, Еделас Блекмур, стежив за полоненими орками зі своєї тюремної фортеці Дурнхолд. Один орк особливо привертав його увагу: це був сирота-немовля, якого він знайшов майже вісімнадцять років тому. Блекмур виховав юного орка як улюбленого раба й назвав його Тралом. Блекмур навчав орка тактиці, філософії та бойовим мистецтвам. Трала навіть готували на гладіатора. Увесь цей час корумпований наглядач прагнув перетворити орка на зброю.",
        [2] = "Незважаючи на суворі умови виховання, юний Трал виріс сильним і кмітливим орком, і в глибині душі він розумів, що життя раба — не для нього. Дорослішаючи, він дізнався про свій народ — орків, яких ніколи не бачив: після поразки більшість із них потрапила до таборів для інтернованих. Ходили чутки, що Дуумхаммер, вождь орків, втік із Лордаерону й переховувався. Лише один розбійницький клан досі діяв таємно, намагаючись уникнути пильного ока Альянсу.",
        [3] = "Кмітливий, але недосвідчений Трал вирішив втекти з фортеці Блекмура й вирушив на пошуки своїх одноплемінників. Під час своїх мандрів Трал відвідав табори інтернованих і виявив, що його колись могутня раса стала дивно пригніченою та апатичною. Не знайшовши тих гордих воїнів, на яких сподівався, Трал вирушив на пошуки останнього непереможеного вождя орків — Грома Пекельного Крику.",
        [4] = "Незважаючи на те, що його постійно переслідували люди, Пекельний Крик все ж зберігав незламну волю Орди до боротьби. Маючи за єдину підтримку лише свій відданий клан «Воєнна Пісня», Пекельний Крик продовжував вести підпільну війну проти гноблення свого пригнобленого народу. На жаль, Геллскрім так і не зміг знайти спосіб вивести полонених орків із їхнього заціпеніння. Вразливий Трал, натхненний ідеалізмом Геллскріма, розвинув сильну прихильність до Орди та її воїнських традицій.",
        [5] = "У пошуках істини про своє походження Трал вирушив на північ, щоб знайти легендарний клан Морозних Вовків. Трал дізнався, що Гул'дан вигнав «Морозних вовків» на початку Першої війни. Він також з'ясував, що є сином і спадкоємцем героя орків Дуротана — справжнього вождя «Морозних вовків», якого вбили в дикій місцевості майже двадцять років тому.",
        [6] = "Під керівництвом шанованого шамана Дрек'Тара Трал вивчав стародавню шаманську культуру свого народу, яка була забута за часів злого панування Гул'дана. Згодом Трал став могутнім шаманом і зайняв належне йому місце вождя вигнаних «Морозних вовків». Наділений силою самих стихій і сповнений прагненням знайти своє призначення, Трал вирушив, щоб визволити полонені клани та очистити свій народ від демонічного спотворення.",
        [7] = "Під час своїх мандрівок Тралл знайшов старого вождя, Оргріма Думхаммера, який багато років проживав як відлюдник. Думхаммер, що колись був близьким другом батька Тралла, вирішив приєднатися до молодого провидця-орка та допомогти йому звільнити полонені клани. За підтримки багатьох досвідчених вождів Траллу врешті-решт вдалося відродити Орду та надати своєму народу нову духовну ідентичність.",
        [8] = "Щоб символізувати відродження свого народу, Трал повернувся до фортеці Дурнхолд, що належала Блекмуру, і остаточно поклав край планам свого колишнього господаря, взявши в облогу табори інтернованих. Ця перемога далася не без втрат: під час звільнення одного з таборів Думхаммер загинув у бою.",
        [9] = "Трал взяв у руки легендарний бойовий молот «Доомхаммер» і одягнув чорні пластинчасті обладунки, щоб стати новим вождем Орди. Протягом наступних місяців невелика, але непередбачувана Орда Трала спустошила табори інтернованих і зірвала всі спроби Альянсу протистояти його хитрим стратегіям. Заохочений своїм найкращим другом і наставником, Громом Пекельним Криком, Трал докладав усіх зусиль, щоб його народ ніколи більше не став рабами.",
    },
},

[175753] = {
    en = "War of the Spider",
    T  = "Війна павука",
    pages = {
        [1] = "Поки Трал звільняв своїх побратимів у Лордаероні, Нер'жул продовжував зміцнювати свою владу в Нортренді. Над льодовиком «Крижаної Корони» було зведено величну цитадель, яку укомплектовували дедалі чисельніші легіони мерців. Однак, поки Король Ліч поширював свій вплив на ці землі, одна таємнича імперія протистояла його могутності.",
        [2] = "Стародавнє підземне королівство Азжол-Неруб, засноване расою зловісних гуманоїдних павуків, відправило свою елітну гвардію воїнів, щоб атакувати Льодяну Корону та покласти край божевільним намаганням Короля Ліча здобути панування. На превеликий жаль Нер'жула, злі нерубіанці виявилися несприйнятливими не лише до чуми, а й до його телепатичного впливу.",
        [3] = "Нерубійські пани-павуки командували величезними військами та мали підземну мережу, що простягалася майже на половину ширини Нортренда. Їхня тактика «удар і втеча» проти фортець Короля Ліча раз за разом зводила нанівець його спроби їх винищити. Зрештою війна Нер'жула проти нерубіанців була виграна шляхом виснаження. За допомогою зловісних лордів жаху та незліченних воїнів-нежиті Король Ліч вторгся в Азжол-Неруб і обрушив його підземні храми на голови павукових лордів.",
        [4] = "Хоча нерубіанці були імунні до його чуми, дедалі сильніші некромантичні здібності Нер'жула дозволили йому воскресити трупи павукоподібних воїнів і підкорити їх своїй волі. На знак поваги до їхньої витривалості та безстрашності Нер'жул запозичив характерний архітектурний стиль нерубіанців для своїх фортець та споруд.",
        [5] = "Залишившись безсуперечно правити своїм королівством, Король Ліч почав готуватися до своєї справжньої місії у світі. Простягнувши свою безмежну свідомість на землі людей, Король Ліч звернувся до кожної темної душі, яка була готова його вислухати...",
    },
},

[175754] = {
    en = "Kel'Thuzad and the Forming of the Scourge",
    T  = "Кел'Тузад і утворення Плетіння",
    pages = {
        [1] = "По всьому світу було кілька могутніх особистостей, які почули телепатичний заклик Короля Ліча з Нортренда. Найвидатнішим серед них був архімаг Даларана, Кел'Тузад, який був одним із найстарших членів Кірін-Тор — правлячої ради Даларана. Протягом багатьох років його вважали бунтарем через його наполегливість у вивченні забороненого мистецтва некромантії.",
        [2] = "Прагнучи дізнатися все, що тільки можна, про магічний світ та його таємничі дива, він відчував розчарування через те, що вважав застарілими та позбавленими уяви принципами своїх однолітків. Почувши могутнє закликання з Нортренда, архімаг спрямував усю свою неабияку волю на спілкування з таємничим голосом. Переконаний, що Кірін-Тор надто боязкий, щоб опанувати силу та знання, притаманні темним мистецтвам, він змирився з тим, що навчиться усього, чого зможе, від надзвичайно могутнього Короля Ліча.",
        [3] = "Залишивши позаду своє багатство та престижне політичне становище, Кел’Тузад відвернувся від шляхів Кірін-Тор і назавжди покинув Даларан. Під впливом наполегливого голосу Короля Ліча, що лунав у його свідомості, він продав свої величезні володіння та сховав свої статки. Подорожуючи самотньо багато ліг як по суші, так і по морю, він нарешті дістався до замерзлих берегів Нортренда.",
        [4] = "Маючи намір дістатися до Льодової Корони та запропонувати свої послуги Королю Лічу, архімаг пройшов крізь спустошені, розтрощені війною руїни Азжол-Неруба. Кел'Тузад на власні очі побачив масштаби та жорстокість сили Нер'жула. Він почав усвідомлювати, що союз із таємничим Королем Лічів може виявитися як мудрим, так і потенційно вигідним кроком.",
        [5] = "Після довгих місяців мандрів суворими арктичними пустками Кел'Тузад нарешті дістався до темного льодовика Ледяної Корони. Він сміливо наблизився до темної цитаделі Нер'жула й був вражений, коли неживі вартові мовчки пропустили його, ніби його вже чекали.",
        [6] = "Кел'Тузад спустився вглиб холодної землі й дістався до самого дна льодовика. Там, у безмежній печері з льоду й тіней, він впав ниць перед Замерзлим Троном і приніс свою душу в жертву темному володареві мертвих.",
        [7] = "Король Ліч був задоволений своїм новим підлеглим. Він пообіцяв Кель'Тузаду безсмертя та велику силу в обмін на його вірність і слухняність. Спраглий темних знань і влади, Кель'Тузад прийняв своє перше велике завдання: вирушити у світ людей і заснувати нову релігію, прихильники якої поклонялися б Королю Лічу як богу.",
        [8] = "Щоб допомогти архімагу виконати його місію, Нер’жул залишив Кель’Тузаду його людську сутність. Старому, але все ще харизматичному чарівнику було доручено за допомогою своїх здібностей до ілюзій та переконання заспокоїти пригноблені, позбавлені прав маси Лордаерону, вселивши в них довіру та віру. Потім, привернувши їхню увагу, він мав запропонувати їм нове бачення того, яким могло б бути суспільство, — та нового лідера, якого вони могли б назвати своїм королем.",
        [9] = "Кел’Тузад повернувся до Лордаерона під виглядом іншої особи, і протягом трьох років, використовуючи свій статок та інтелект, зібрав таємне братство однодумців — чоловіків і жінок. Братство, яке він назвав «Культом Проклятих», обіцяло своїм послідовникам соціальну рівність та вічне життя в Азероті в обмін на їхню службу та покірність Нер'жулу.",
        [10] = "З плином місяців Кел’Тузад знайшов серед втомлених, перевантажених роботою трудівників Лордаерона чимало охочих добровольців для свого нового культу. Кел'Тузаду було напрочуд легко досягти своєї мети: а саме перетворити віру громадян у Святе Світло на віру в темну тінь Нер'жула. У міру того як «Культ Проклятих» набирав чисельності та впливу, Кел'Тузад дбав про те, щоб приховати його діяльність від влади Лордаерону.",
        [11] = "З огляду на успіхи Кел'Тузада в Лордаероні, Король Ліч завершив останні приготування до свого наступу на людську цивілізацію. Вклавши свою енергію чуми в низку переносних артефактів, званих «казанами чуми», Нер'жул наказав Кель'Тузаду перевезти ці казани до Лордаерону, де їх мали сховати в різних селах, контрольованих культом.",
        [12] = "Котли, охоронювані відданими послідовниками культу, мали б тоді стати джерелами чуми, розносячи її по нічого не підозрюючих сільських місцевостях та містах північного Лордаерону.",
        [13] = "План Короля Ліча спрацював бездоганно. Багато північних сіл Лордаерона були заражені майже миттєво. Так само, як і в Нортренді, жителі, які заразилися чумою, помирали й воскресали як слухняні раби Короля Ліча.",
        [14] = "Послідовники Кель'Тузада прагнули загинути, щоб потім воскреснути й знову служити своєму темному володареві. Вони раділи перспективі безсмертя через нежить. У міру поширення чуми на північних землях з'являлося дедалі більше диких зомбі. Кел'Тузад, споглядаючи на зростаюче військо Короля Ліча, назвав його «Покаранням», адже незабаром воно рушить до воріт Лордаерона й винищить людство з лиця землі.",
    },
},

[175756] = {
    en = "The Scourge of Lordaeron",
    T  = "Пошесть Лордаерона",
    pages = {
        [1] = "Після багатомісячної підготовки Кел'Тузад та його «Культ Проклятих» нарешті завдали першого удару, наславши на Лордаерон чуму нежиті. Утер та його товариші-паладини вирушили досліджувати заражені регіони в надії знайти спосіб зупинити чуму. Незважаючи на їхні зусилля, чума продовжувала поширюватися й загрожувала розірвати Альянс на шматки.",
        [2] = "Коли лави нежиті прокотилися по Лордаерону, єдиний син Теренаса, принц Артас, взявся за боротьбу проти Плети. Артасу вдалося вбити Кел'Тузада, але, незважаючи на це, ряди нежиті поповнювалися кожним воїном, який гинув, захищаючи землю. Розчарований і збентежений, здавалося б, непереможним ворогом, Артас вдавався до дедалі радикальніших заходів, аби перемогти їх. Зрештою товариші Артаса попередили його, що він втрачає зв'язок зі своєю людськістю.",
        [3] = "Страх і рішучість Артаса в кінцевому підсумку стали причиною його загибелі. Він відстежив джерело чуми аж до Нортренда, маючи намір назавжди покласти край цій загрозі. Натомість принц Артас зрештою став жертвою неймовірної сили Короля Ліча. Вірячи, що це врятує його народ, Артас взяв у руки проклятий рунічний меч «Морозний Скорбот».",
        [4] = "Хоча меч і наділив його незбагненною силою, він також викрав його душу та перетворив його на наймогутнішого з рицарів смерті Короля Ліча. Позбавлений душі та розгубивши розум, Артас очолив Пошесть у війні проти власного королівства. Зрештою Артас вбив власного батька, короля Теренаса, і підкорив Лордаерон залізною рукою Короля Ліча.",
    },
},

[175757] = {
    en = "Sunwell - The Fall of Quel'Thalas",
    T  = "«Санвелл» — Падіння Квель-Таласа",
    pages = {
        [1] = "Хоча він і переміг усіх, кого тепер вважав своїми ворогами, Артаса все ще переслідував привид Кел’Тузада. Привид сказав Артасу, що його потрібно воскресити для наступного етапу плану Короля Ліча. Щоб воскресити його, Артасу потрібно було доставити останки Кель'Тузада до містичного Сонцеджерела, прихованого у вічному королівстві високих ельфів — Кель'Таласі.",
        [2] = "Артас і його «Покарання» вторглися в Кель'Талас і взяли в облогу руйнуючіся оборонні споруди ельфів. Сильвана Віндранер, генерал-рейнджер Срібного Місяця, вела відважну боротьбу, але Артас зрештою знищив армію високих ельфів і прорвався до Сонцеджерела. У жорстокому прояві своєї влади він навіть воскресив повалене тіло Сильвани як банші, приреченої на вічне нежиття на службі у завойовника Кель'Таласа.",
        [3] = "Зрештою, Артас занурив останки Кел'Тузада у святі води Сонцеджерела. Хоча цей вчинок забруднив могутні води Вічності, Кел'Тузад відродився як чаклунський ліч. Відродившись як набагато могутніша істота, Кел'Тузад пояснив наступний етап плану Короля Лічів.",
        [4] = "До того часу, як Артас і його армія мертвих повернули на південь, у Квель-Таласі не залишилося жодного живого ельфа. Славетна батьківщина високих ельфів, яка існувала понад дев’ять тисяч років, перестала існувати.",
    },
},

[175758] = {
    en = "Archimonde's Return and the Flight to Kalimdor",
    T  = "Повернення Архімонда та втеча до Калімдору",
    pages = {
        [1] = "Як тільки Кел'Тузад знову став цілим, Артас повів Плеть на південь, до Даларана. Там ліч здобув могутню книгу заклинань Медівха і використав її, щоб повернути Архімонда у цей світ. З цього моменту сам Архімонд розпочав остаточне вторгнення Легіону. Навіть чарівники Кірін-Тор не змогли завадити військам Артаса викрасти книгу Медівха, і незабаром Кель'Тузад отримав усе необхідне для виконання свого заклинання.",
        [2] = "Через десять тисяч років могутній демон Архімонд та його військо знову з'явилися у світі Азерота. Однак Даларан не був їхньою кінцевою метою. За наказом самого Кіл'яедена Архімонд та його демони пішли слідом за неживим Плетью до Калімдору, маючи на меті знищити Нордрасіл — Світове Дерево.",
        [3] = "Посеред цього хаосу з’явився самотній таємничий пророк, щоб дати смертним расам настанови. Цим пророком виявився ніхто інший, як Медів, останній Страж, який дивом повернувся з Потойбіччя, щоб спокутувати свої минулі гріхи. Медів розповів Орді та Альянсу про небезпеки, що на них чекають, і закликав їх об’єднатися.",
        [4] = "Зневірені багатовіковою ненавистю, орки та люди не хотіли про це й чути. Медіву довелося мати справу з кожною расою окремо, використовуючи пророцтва та хитрощі, щоб провести їх через море до легендарної землі Калімдор. Незабаром орки та люди натрапили на цивілізацію калдорей, що довгий час залишалася прихованою.",
        [5] = "Орки на чолі з Тралом зазнали низки невдач під час своєї подорожі через Пустощі Калімдору. Хоча вони й подружилися з Кейрном Кровавим Копитом та його могутніми воїнами-тауренами, багато орків почали піддаватися демонічній жадобі крові, яка мучила їх роками. Найвидатніший заступник Тралла, Гром Пекельний Крик, навіть зрадив Орду, піддавшись своїм найнижчим інстинктам.",
        [6] = "Коли Пекельний Крик та його вірні воїни з племені «Воєнна Пісня» пробиралися лісами Попелястої Долини, вони зіткнулися з древніми Стражами нічних ельфів. Впевнений, що орки знову повернулися до свого войовничого способу життя, напівбог Сенаріус виступив, щоб відкинути Пекельного Крика та його орків. Проте Геллскрім та його орки, охоплені надприродною ненавистю та люттю, зуміли вбити Сенаріуса та спотворити стародавні ліси.",
        [7] = "Зрештою, Пекельний Крик відновив свою честь, допомогаючи Тралу перемогти Маннорота — повелителя демонів, який першим наклав на орків прокляття, передаючи їм у спадок ненависть і лють. Зі смертю Маннорота кровне прокляття орків нарешті було знято.",
        [8] = "Поки Медів намагався переконати орків і людей у необхідності союзу, нічні ельфи вели боротьбу з Легіоном, використовуючи свої таємні методи. Тиранде Шепот Вітру, безсмертна Верховна Жриця Вартових нічних ельфів, відчайдушно боролася, щоб не дати демонам і нежиті заполонити ліси Ашенвейлу. Тиранде усвідомила, що їй потрібна допомога, тож вона вирушила, щоб розбудити друїдів нічних ельфів з їхнього тисячолітнього сну.",
        [9] = "Звернувшись до свого давнього коханого, Малфуріона Штормрейджа, Тиранде вдалося зміцнити свої оборонні позиції та відкинути Легіон. За допомогою Малфуріона сама Природа піднялася, щоб розгромити Легіон та його союзників із «Покарання».",
        [10] = "Під час пошуків інших друїдів, що перебували в стані сплячки, Малфуріон знайшов стародавню могильну в’язницю, в якій він ув’язнив свого брата Іллідана. Переконана, що Іллідан допоможе їм у боротьбі проти Легіону, Тиранде звільнила його. Хоча Іллідан і допомагав їм деякий час, зрештою він втік, щоб переслідувати власні інтереси.",
        [11] = "Нічні ельфи зібралися з силами й з суворою рішучістю кинулися в бій проти Палаючого Легіону. Легіон ніколи не втрачав прагнення заволодіти Колодязем Вічності, який здавна був джерелом сили Світового Дерева і водночас серцем королівства нічних ельфів. Якби їхній запланований штурм Дерева увінчався успіхом, демони буквально розірвали б світ на шматки.",
    },
},

[175759] = {
    en = "The Betrayer Ascendant",
    T  = "«Зрадник, що піднімається»",
    pages = {
        [1] = "Під час вторгнення Легіону в Попелясту долину Іллідан був звільнений зі своєї могильної в'язниці після десяти тисяч років ув'язнення. Хоча він і намагався заспокоїти своїх товаришів, незабаром він знову прийняв свою справжню подобу й поглинув енергію могутнього артефакту чаклуна, відомого як «Череп Гул'дана».",
        [2] = "У результаті Іллідан набув демонічних рис і значно збільшив свою силу. Він також отримав деякі давні спогади Гул'дана — зокрема, ті, що стосувалися Гробниці Саргераса, підземелля на острові, де, за чутками, зберігаються останки Темного Титана Саргераса.",
        [3] = "Сповнений сили й знову вільний мандрувати світом, Іллідан вирушив на пошуки свого місця у великому плані всесвіту. Однак Кіл'яеден зіткнувся з Ілліданом і зробив йому пропозицію, від якої той не міг відмовитися. Кіл'яеден був розлючений поразкою Архімонда на горі Гіжал, але у нього були важливіші турботи, ніж помста.",
        [4] = "Відчувши, що його творіння — Король Ліч — стає надто могутнім, щоб його можна було контролювати, Кіл'яеден наказав Іллідану знищити Нер'жула та раз і назавжди покласти край неживому Плечу. Натомість Іллідан мав отримати незрівнянну силу та посісти гідне місце серед решти володарів Палаючого Легіону.",
        [5] = "Іллідан погодився й одразу ж вирушив знищити Замерзлий Трон — крижану кришталеву скриню, в якій перебував дух Короля Ліча. Іллідан знав, що для знищення Замерзлого Трону йому знадобиться могутній артефакт. Використовуючи знання, отримані зі спогадів Гул'дана, Іллідан вирішив відшукати Гробницю Саргераса й заволодіти останками Темного Титана.",
        [6] = "Він зажадав від Високородних погашення давніх боргів і виманив змієподібних нагів із їхніх темних підводних лігвищ. Під проводом хитрої чаклунки леді Вашдж наги допомогли Іллідану дістатися до Розбитих островів, де, за чутками, мала знаходитися гробниця Саргераса.",
        [7] = "Коли Іллідан вирушив у дорогу разом із нагами, на його слід виступила Стражниця Маєв Тіньоспівачка. Маєв була тюремницею Іллідана протягом десяти тисяч років і з нетерпінням чекала на можливість знову його схопити. Однак Іллідан перехитрив Маєв та її Спостерігачів і, попри їхні зусилля, зумів заволодіти Оком Саргераса. Отримавши у своє розпорядження могутнє Око, Іллідан вирушив до колишнього міста чарівників — Даларана.",
        [8] = "Отримавши підкріплення від міських ліній енергії лей, Іллідан використав «Око», щоб накласти руйнівне закляття на цитадель Ліча-Короля — «Крижану Корону» — у далекому Нортренді. Атака Іллідана зруйнувала оборонні споруди Ліча-Короля та прорвала саму «покрівлю світу». У вирішальний момент руйнівне заклинання Іллідана було зупинено, коли його брат Малфуріон та жриця Тиранде прибули на допомогу Маєв.",
        [9] = "Розуміючи, що Кіл'яеден не буде задоволений тим, що йому не вдалося знищити Замерзлий Трон, Іллідан втік до безплідного виміру, відомого як Замежжя: останніх залишків Дренора, колишньої батьківщини орків. Там він планував уникнути гніву Кіл'яедена та обміркувати свої подальші дії.",
        [10] = "Після того як їм вдалося зупинити Іллідана, Малфуріон і Тиранде повернулися додому, в Ліс Ешенвейл, щоб піклуватися про свій народ. Однак Маєв не збиралася так легко здаватися і поїхала за Ілліданом до Замежжя, рішуче налаштована притягнути його до відповідальності.",
    },
},

[175760] = {
    en = "Rise of the Blood Elves",
    T  = "Піднесення Кровних ельфів",
    pages = {
        [1] = "На той час нежить «Плети» фактично перетворила Лордаерон і Квель'Талас на отруйні Землі Чуми. Залишилося лише кілька осередків сил опору Альянсу. Одну з таких груп, що складалася переважно з високих ельфів, очолював останній представник династії Сонцекроків — принц Каель'тас.",
        [2] = "Каел, який сам був досвідченим чарівником, почав з обережністю ставитися до Альянсу, що втрачав свої позиції. Вищі ельфи сумували за втраченою батьківщиною і вирішили називати себе кров’яними ельфами на честь свого загиблого народу. Однак, намагаючись стримати Пошесть, вони зазнавали великих страждань через те, що були відрізані від Сонцеджерела, яке надавало їм силу.",
        [3] = "У відчайдушних спробах знайти ліки від расової залежності свого народу від магії Каель вчинив немислиме: він визнав походження свого народу від Високородних і приєднався до Іллідана та його нагів у надії знайти нове джерело магічної сили, яким можна було б живитися. Решта командирів Альянсу засудили кровних ельфів як зрадників і назавжди вигнали їх.",
        [4] = "Не маючи куди більше йти, Кель та його кровні ельфи послідували за леді Вашдж до Замежжя, щоб допомогти протистояти наглядачці Маєв, яка знову захопила Іллідана. Об’єднавши сили нага та кровних ельфів, їм вдалося перемогти Маєв і визволити Іллідана з її полону. Оселившись у Замежжя, Іллідан зібрав свої війська для другого удару по Королю Лічу та його фортеці Ледяної Корони.",
    },
},

[175761] = {
    en = "Civil War in the Plaguelands",
    T  = "Громадянська війна в Землях Чуми",
    pages = {
        [1] = "Нер'жул, Король Ліч, знав, що його час добігає кінця. Ув'язнений у Замерзлому Троні, він підозрював, що Кіл'яеден надішле своїх агентів, щоб знищити його. Збитки, завдані заклинанням Іллідана, спричинили тріщину в Замерзлому Троні; отже, Король Ліч щодня втрачав свою силу. У відчайдушній спробі врятуватися він покликав до себе свого наймогутнішого смертного слугу — лицаря смерті, принца Артаса.",
        [2] = "Хоча його сили були виснажені слабкістю Короля Ліча, Артас брав участь у громадянській війні в Лордаероні. Половина діючих військ нежиті, очолюваних банші Сильваною Віндранер, влаштувала переворот, щоб захопити владу над імперією нежиті. Артас, якого покликав Король Ліч, був змушений залишити «Поражу» під керівництвом свого заступника, Кель'Тузада, оскільки війна набирала обертів по всій території Заражених земель.",
        [3] = "Зрештою, Сильвана та її повстанці-нежить (відомі як «Покинуті») захопили зруйновану столицю Лордаерона. Збудувавши власний бастіон під руїнами міста, Покинуті поклялися перемогти Плеть та вигнати Кел’Тузада й його поплічників з цих земель.",
        [4] = "Ослаблений, але рішуче налаштований врятувати свого господаря, Артас дістався до Нортренда, де на нього вже чекали наги Іллідана та кровні ельфи. Разом зі своїми союзниками-нерубіанцями він вступив у гонку з військами Іллідана, щоб дістатися до льодовика Крижаної Корони та захистити Замерзлий Трон.",
    },
},

[175762] = {
    en = "The Lich King Triumphant",
    T  = "Тріумф Короля Ліча",
    pages = {
        [1] = "Незважаючи на те, що він був ослаблений, Артас зрештою перехитрив Іллідана й першим дістався до Замерзлого Трону. За допомогою свого рунічного меча «Морозний Смертельник» Артас розбив крижану в’язницю Короля Ліча й тим самим звільнив зачаровані шолом і нагрудник Нер’жула.",
        [2] = "Артас надів на голову неймовірно могутній шолом і став новим Королем Лічем. Душі Нер'жула й Артаса злилися в одне могутнє істота, саме так, як це завжди планував Нер'жул. Іллідан та його війська були змушені з ганьбою втекти назад до Замежжя, тоді як Артас став одним із наймогутніших істот, яких коли-небудь знав цей світ.",
        [3] = "Наразі Артас, новий і безсмертний Король Ліч, перебуває в Нортренді; ходять чутки, що він відновлює цитадель Лідової Корони. Його довірений заступник, Кел’Тузад, командує Покаранням у Землях Чуми. Сильвана та її повстанці з числа Покинутих утримують лише Ліси Тірісфал — невелику частину королівства, розтерзаного війною.",
    },
},

[175763] = {
    en = "Old Hatreds - The Colonization of Kalimdor",
    T  = "«Старі ворожнечі» — Колонізація Калімдора",
    pages = {
        [1] = "Хоча перемога була за ними, смертні раси опинилися у світі, розтрощеному війною. «Плеть» та «Палаючий Легіон» практично знищили цивілізації Лордаерона і майже завершили цю справу в Калімдорі. Попереду було відновлення лісів, примирення з минулим та відновлення рідних земель. Війна глибоко поранила кожну расу, але вони самовіддано об’єдналися, щоб спробувати почати все з нуля, розпочавши з непевного перемир’я між Альянсом та Ордою.",
        [2] = "Тралл привів орків на континент Калімдор, де вони за допомогою своїх братів-тауренів заснували нову батьківщину. Назвавши свою нову землю Дуротар на честь вбитого батька Тралла, орки оселилися там, щоб відродити своє колись славетне суспільство.",
        [3] = "Тепер, коли прокляття демонів було знято, Орда перетворилася з войовничої нестримної сили на більш вільну коаліцію, націлену на виживання та процвітання, а не на завоювання. За підтримки благородних тауренів та хитрих тролів з племені Темного Списа Тралл і його орки з надією очікували на нову еру миру на своїй землі.",
        [4] = "Решта військ Альянсу під командуванням Джейни Праудмур оселилася на півдні Калімдору. Біля східного узбережжя Болота Пил'яної Ями вони збудували міцне портове місто Терамор. Там люди та їхні союзники-гноми намагалися вижити на землі, яка завжди була їм ворожою. Хоча захисники Дуротара й Терамора дотримувалися непевного перемир'я між собою, крихкий колоніальний спокій не міг тривати вічно.",
        [5] = "Мир між орками та людьми був порушений прибуттям величезного флоту Альянсу до Калімдору. Могутній флот під командуванням великого адмірала Дейліна Праудмура (батька Джейни) покинув Лордаерон ще до того, як Артас знищив королівство. Пропливши багато виснажливих місяців, адмірал Праудмур шукав будь-яких вцілілих членів Альянсу, яких тільки міг знайти.",
        [6] = "Армада Праудмура становила серйозну загрозу стабільності регіону. Як видатний герой Другої війни, батько Джейни був затятим ворогом Орди і був рішуче налаштований знищити Дуротар, перш ніж орки зможуть закріпитися на цій землі.",
        [7] = "Великий адмірал змусив Джейну прийняти жахливе рішення: або підтримати його в битві проти орків і зрадити своїх нових союзників, або битися проти власного батька, щоб зберегти крихкий мир, якого Альянс і Орда нарешті досягли. Після довгих роздумів Джейна обрала друге і допомогла Тралу перемогти свого збожеволілого батька.",
