[175854] = {
    en = "The Twin Empires",
    T  = "Дві імперії",
    pages = {
        [1] = "Приблизно 16 000 років тому (задовго до того, як нічні ельфи нерозважливо накликали на себе гнів Палаючого Легіону) тролі панували над значною частиною Калімдору (який тоді був єдиним континентом). Існували дві імперії тролів — Імперія Гурубаші в південно-східних джунглях та Імперія Амані в центральних лісових масивах.",
        [2] = "На далекій півночі (у регіоні, який нині відомий як Нортренд) мешкали менші племена. Ці племена заснували невелику державу під назвою Гундрак, але так і не досягли таких розмірів та процвітання, як південні імперії.",
        [3] = "Імперії Гурубаші та Амані не відчували одна до одної особливої симпатії, але рідко воювали між собою. У той час їхнім найбільшим спільним ворогом була третя імперія — цивілізація Аз’Акір. Акіри — це розумні інсектоїди, які панували на землях далекого заходу. Ці кмітливі інсектоїди були великими експансіоністами й неймовірно злісними. Акіри були одержимі ідеєю знищення всього не-комашиного життя на полях Калімдору.",
        [4] = "Тролі вели з ними боротьбу протягом багатьох тисяч років, але так і не змогли здобути справжню перемогу над акірами. Зрештою, завдяки наполегливості тролів, королівство акірів розпалося навпіл, а його мешканці розбіглися до окремих колоній у найвіддаленіших північних і південних регіонах континенту.",
        [5] = "З’явилися два міські держави акірі — Азжол-Неруб у північних пустках та Ан’Кірадж у південній пустелі. Хоча тролі підозрювали, що під Калімдором існують й інші колонії акірі, їхнє існування так і не було підтверджено.",
        [6] = "Після того як інсектоїди були вигнані у вигнання, дві імперії тролів повернулися до звичного укладу життя. Незважаючи на свою велику перемогу, жодна з цих цивілізацій не розширилася значно далі своїх початкових кордонів. Проте стародавні тексти згадують про невелику групу тролів, яка відокремилася від Імперії Амані та заснувала власну колонію в самому серці Темного континенту.",
        [7] = "Саме там ці відважні першопрохідці відкрили космічне «Колодязь Вічності», яке перетворило їх на істот, наділених неймовірною силою. Деякі легенди стверджують, що ці авантюрні тролі були першими нічними ельфами, хоча ця теорія так і не була доведена.",
    },
},

[175855] = {
    en = "Empires' Fall",
    T  = "Падіння імперій",
    pages = {
        [1] = "Незважаючи на їхнє таємниче походження, очевидно, що нічні ельфи прийшли до влади незабаром після відкриття Колодязя Вічності. Незважаючи на спроби тролів завадити їм розширювати свої території, нічні ельфи збудували могутню імперію, яка стрімко поширювалася по первісному Калімдору. Володіючи грізною магією, про яку забобонні тролі навіть не могли мріяти, нічні ельфи без особливих зусиль зробили те, чого ніколи не змогли досягти злі акіри: повалили дві наймогутніші імперії світу.",
        [2] = "Нічні ельфи систематично руйнували оборонні споруди та ланцюги постачання тролів. Тролі, не маючи можливості протистояти руйнівній магії ельфів, не витримали натиску. Нічні ельфи виявилися не менш хитрими й кровожерливими, ніж дикі тролі, — чим накликали на себе вічну ненависть і презирство цієї раси. Імперії Гурубаші та Амані розпалися всього за кілька коротких років.",
        [3] = "Зрештою, нічні ельфи були спалені тим самим магічним вогнем, яким вони намагалися керувати. Їхнє безрозсудне використання магії привернуло до цього світу демонічну «Палаючу Легію». Демони знищили значну частину цивілізації нічних ельфів. Хоча немає жодних записів, які б вказували на те, що Легіон атакував будь-яку з цивілізацій тролів, цілком імовірно, що битви відбувалися по всьому континенту.",
        [4] = "Наприкінці цього жахливого конфлікту — відомого як «Війна Стародавніх» — «Колодязь Вічності» зазнав внутрішнього вибуху. Утворена в результаті цього ударна хвиля розтрощила великий масив суші Калімдору. Центр континенту опинився під водою, залишивши після себе лише невелику групу роздроблених окремих континентів.",
        [5] = "Таким чином, значні території імперій Амані та Гурубаші досі існують на землях сучасних Квель'Таласа та Странглторна (відповідно). Королівства Аз'Акір — Аз'ол-Неруб та Ан'Кірадж — також збереглися на території сучасних Нортренда та Танаріса (відповідно). Обидві цивілізації тролів відступили від величезних руйнувань первісного світу, який вони знали. Непохитні тролі відбудували свої зруйновані міста й взялися відновлювати частину своєї колишньої могутності.",
    },
},

[175856] = {
    en = "Wrath of Soulflayer",
    T  = "Гнів Душорозривача",
    pages = {
        [1] = "Довгі століття, що настали після Великого Розколу світу, були важкими для раси тролів. Голод і терор були звичним явищем у роздроблених королівствах. Тролі Гурубаші, доведені до відчаю, звернулися по допомогу до древніх містичних сил. Хоча обидва королівства тролів поділяли спільну віру у великий пантеон первісних богів, Гурубаші потрапили під владу найтемнішого з них.",
        [2] = "Хаккар Душоріз, підлий і кровожерливий дух, почув заклик тролів і вирішив допомогти їм. Хаккар відкрив гурубаші свої таємниці крові та допоміг їм поширити свою цивілізацію на більшу частину Долини Странглторн та на деякі острови Південних морів. Хоча він і надав їм велику силу, Хаккар прагнув дедалі більшої винагороди за свої зусилля.",
        [3] = "Кровожерливий бог вимагав, щоб йому щодня приносили в жертву душі. Він мріяв про те, щоб отримати доступ до фізичного світу, аби змогти пожирати кров усіх смертних істот. Згодом гурубаші усвідомили, з якою істотою вони мали справу, — і повстали проти нього. Найсильніші племена повстали проти Хаккара та його вірних жерців — Атал'аї.",
        [4] = "Про жахливу війну, що спалахнула між послідовниками Хаккара та рештою племен Гурубаші, згадують лише пошепки. Імперія, що тільки-но починала формуватися, була розтрощена магією, яку випустили на волю розлючений бог та його бунтівні діти. Саме тоді, коли битва здавалася безнадійною, тролям вдалося знищити аватара Хаккара й вигнати його зі світу.",
        [5] = "Навіть його жерці Атал'аї зрештою були вигнані зі столиці Зул'Гуруб і змушені виживати в незвіданих болотистих землях на півночі. У тих похмурих болотах вони збудували величний храм на честь свого поваленого бога — Атал'Хаккара — де могли й надалі виконувати справу свого повелителя...",
        [6] = "Решта племен Гурубаші розійшлися в різні боки після того, як велика громадянська війна перетворила їхні землі на руїни. Племена «Розколювач Черепів», «Кривава Скальп» та «Темне Спис» вирушили, щоб заволодіти власними землями у безмежних джунглях Странглторна. Хоча над розбитою імперією запанував хиткий мир, дехто говорив про пророцтво, згідно з яким Хаккар одного дня відродиться у цьому світі — і того дня він поглине його цілком.",
    },
},

