    },
},

[179909] = {
    en = "Rock of Durotan",
    T  = "Скеля Дуротана",
    pages = {
        [1] = "<HTML>$B<BODY>$B<BR/>$B<BR/>$B<P align=\"left\">Тут спочиває Дуротан — перший вождь клану Морозних Вовків і батько нашого шанованого вождя Тралла.  Він був найхоробрішим із нашого роду — зрадженим тими, хто прагнув поневолити наш народ. Дуротан віддав своє життя, щоб ми здобули свободу. Ми вшановуємо його — і спадщину, яку він передав нам через свого сина.</P>$B<BR/>$B<P align=\"left\">Дрек'Тар, Далекоглядний з клану Морозних Вовків </P>$B</BODY>$B</HTML>",
    },
},

[180367] = {
    en = "Altar of Zanza",
    T  = "Вівтар Занзи",
    pages = {
        [1] = "Ми звертаємося до тебе, Занза із Зулдазара.$B$BBлагослови тих, хто просить твоєї допомоги, Лоа Занза. Благослови тих, хто бажає стати союзниками народу Зандалара.$B$B$BДопоможи нам у цей скрутний час. Допоможи нам, Лоа. Надай нам силу, щоб знищити наших ворогів. Надай нам силу, щоб ще раз перемогти Бога Крові.",
    },
},

