[181475] = {
    en = "Monument of Remembrance",
    T  = "Пам'ятник пам'яті",
    pages = {
        [1] = "На згадку про Верховного головнокомандувача союзних військ, Андуїна Лотара: людину, яка готова була пожертвувати всім заради захисту свого короля, свого народу, своєї батьківщини...$B$BНехай наші вороги знають наші імена. Нехай наші союзники вшановують нашу пам’ять. Ми — Сини Лотара. $B$B— Генерал Тураліон",
    },
},

[181573] = {
    en = "Jar of ashes",
    T  = "Банка з попелом",
    pages = {
        [1] = "Ось банка з попелом. Це попіл мого розсудку, моєї пристрасті та моєї енергії. Усе це було повністю знищено самими собою. Нехай усі, хто дивиться на ці спустошені землі Пекельного вогню, пам’ятають про цього занепалого раба. Він пролив кров за Альянс і приніс себе в жертву за Орду, лише щоб зрештою збожеволіти від рук злих і бездушних істот, які поглинули те, що було для нього найдорожчим. Нехай, насолоджуючись плодами його праці, вони зазнають його гніву. Можливо, не в цьому світі, але в кожному наступному. Це моя заява, моя урочиста клятва та моя вічна обіцянка. Я помщуся за свої страждання.",
    },
},

[181895] = {
    en = "Trans-dimensional Ship Repair for Simpletons",
    T  = "Міжвимірний ремонт кораблів для недоумків",
    pages = {
        [1] = "P.S. — Наш великий магістр отримав відповідь з Замежжя щодо запитання Тралла. Відповідь, без жодних сумнівів, — так.",
    },
},

[182203] = {
    en = "The Green Hills of Stranglethorn",
    T  = "Зелені пагорби Стренглторна",
    pages = {
        [1] = "<HTML>$B<BODY>$B<BR/>$B<BR/>$B<H1 align=\"center\">ЗЕЛЕНІ ПАГОРБИ СТРАНГЛТОРНА</H1>$B<BR/>$B<H3 align=\"center\">автор: Хемет Несінгварі</H3>$B</BODY>$B</HTML>",
        [2] = "Наш перший день пройшов так добре, як і слід було очікувати від першого дня. Більшу частину часу ми присвятили підготовці до облаштування базового табору. Я знайшов ідеальне місце біля притоки прісноводної річки. Судячи зі старих, занедбаних причалів поблизу, це місце колись було заселене. Щодо його перших мешканців, то про це може розповісти лише час.",
        [3] = "Для цієї експедиції я зібрав Аджека Руака та сера С. Дж. Ерлгадіна, а також мого вірного слугу Барніла Стоунпота. Я воював пліч-о-пліч з батьком Аджек у багатьох битвах на захист Альянсу. Бачити, як вона виросла, — це щось особливе. Її батько добре навчив її володінню зброєю. Її вправність у стрільбі з лука змушує мене замислитися, чи не тече в її жилах ельфійська кров.",
        [4] = "Сер С. Дж. Ерлгадін походить із людської аристократії. Його батько, граф Ерлгадін, славився своєю щедрістю. Саме граф доклав зусиль для поліпшення умов праці членів Гільдії каменярів під час відновлення Штормовію після Другої Великої війни.",
        [5] = "У наступні роки, після того як Штормовій зрадив Гільдію каменярів, сер Ерлгадін став з гіркотою ставитися до ролі дворян у Королівстві. Він більше не бажав обіймати посаду, яку родовід його батька забезпечив йому в Палаті дворян.$B$BАле я відволікся від теми. Мета цієї розповіді — не стати політичним трактатом чи біографією. Це розповідь про мої пригоди під час полювання на велику дичину серед зелених пагорбів Странглторна....",
        [6] = "Ми прокинулися разом із сонцем. Барніл почав готувати сніданок. Я помітив, що Аджек була дещо розсіяна. Похід цього дня мав бути довгим, а полювання наблизило б нас до небезпеки. Відсутність зосередженості могла легко призвести до несподіваної халепи. Проте Аджек, здавалося, не могла відвести погляду від Барніла, який стояв на березі річки й ополіскував свою польову посуд.",
        [7] = "Якраз коли я збирався запитати Аджек, чому вона не цікавиться стратегією сьогоднішнього полювання, вона потягнулася до свого колчана, витягла стрілу й випустила її прямо в бік бідолашного Барніла. Але Аджек стріляла не в Барніла. Бо коли Барніл відступив убік, роззявивши рота, на поверхню сплив великий річковий кроколіск, у якого стріла Аджек ідеально влучила між двома великими очима.",
        [8] = "Ми вирушили на захід, крізь густі зарості заплутаних джунглів. Рухаючись повільними, обережними кроками, ми пробиралися крізь густе листя у пошуках здобичі. Ранок минув у розчарованій тиші. У Долині нічого не ворушилося, навіть вітерець не подув. До полудня учасники експедиції стали нетерплячими. Барніл уже не крокував обережними кроками хижака, що вистежує здобич. Натомість він незграбно тупотів стежкою, часто гучно наступаючи на сухе листя чи повалені гілки.",
        [9] = "Під час однієї з таких помилок Ерлгадін важко поклав руку на плече Барніла. Аджек і я кинули побіжний погляд, припускаючи, що чоловік просто робить Барнілу вкрай необхідне зауваження за його необережність. Однак Ерлгадін повільно кивнув головою у бік поваленого дерева, що лежало неподалік. На нас дивилися дві пронизливі чорні очі, розташовані трохи вище рота, повного гострих, як бритва, іклів.",
        [10] = "Звір виявився самцем тигра зі Странглторна. Не встиг я навіть зарядити гвинтівку, як Ерлгадін підняв арбалет і вистрілив у звіра. Стріла не влучила в ціль, але важко поранила звіра в лівий бік. Тигр зробив марну спробу втекти, але його рана була занадто серйозною. Звір ще кілька трагічних секунд спотикався, поки Барніл не довершив його, кинувши сокиру.",
        [11] = "Ця вполювання викликало святковий настрій серед учасників експедиції. Барніл налив медовухи, щоб усі могли насолодитися нею. Але наше святкування тривало недовго. Коли ми готували труп до транспортування назад до базового табору, нас усіх застало зненацька жахливе гарчання. За все своє життя я ніколи не чув нічого настільки моторошного.",
        [12] = "На скелястому обриві вгорі, на тлі заходу сонця, я розгледів найбільшого хижого кота, якого коли-небудь бачив. Мені вдалося випустити одну невмілу серію пострілів зі своєї рушниці, але кіт не поступився. Він ще раз заричав, цього разу голосніше, ніж попереднього разу, і зник.$B$BМи зібрали свої речі й урочисто вирушили назад до табору.",
        [13] = "Я пообіцяв учасникам експедиції, що наступного дня ми будемо полювати на пантер, оскільки їхнє хутро користується великим попитом по всьому Азероту. І це цілком логічно, адже всі працездатні мисливці, трапери та торговці хутром віддають свої життя так відважно в ім’я Альянсу.",
        [14] = "Аджек і сер Ерлгадін дуже хотіли навчитися ефективно полювати з гномівською гвинтівкою. Я попросив цих двох людей залишити свою примітивну зброю для стрільби на великі відстані в базовому таборі. Барніл і я оснастили їх найкращою вогнепальною зброєю з Айронфорджа.",
        [15] = "Цього дня ми вирушили на південь, слідуючи за свіжими слідами пантери. Незабаром ми дісталися до ущелини, через яку пролягав величезний мост із мотузок. Побачивши це диво інженерної думки, я не міг не згадати описи цього краю, зроблені Бранном. Так часто вважалося, що місцеві тролі — це примітивна й неосвічена раса, проте, споглядаючи майстерну роботу над мостом, я зміг оцінити той талант, завдяки якому тролі-будівельники подолали, здавалося б, неможливе завдання.",
        [16] = "Незабаром Аджек вистежив пантеру на південному заході. Ми йшли тихо, тримаючи зброю напоготові, в очікуванні здобичі. Тріск гілочок із сусіднього гаю одразу привернув нашу увагу. Там щось було. Одного суворого погляду на Барніла вистачило, щоб передати мої думки. Барніл повільно опустив свою гвинтівку. Ця здобич була не для нас; вона була для наших людських супутників. Незліченна кількість пантер загинула під нашими димлячими стволами. Ця здобич буде для людей.",
        [17] = "І Аджек, і сер Ерлгадін стояли, тримаючи зброю на мушці, спрямовану на густу зарость біля підніжжя колихаючихся дерев. Полуденне сонце палюче припікало нас. Повільна цівка поту стікала з скроні Ерлгадіна, коли він відтягнув запобіжник. Звуком клацання густа рослинність розступилася, і велика чорна пантера — прекрасний екземпляр — вискочила на рівнину.",
        [18] = "Люди націлили зброю на пантеру, яка бігла вздовж краю лісосмуги. Стволи їхніх рушниць рухалися ідеально паралельно один одному. Барніл кинув на мене наполегливий погляд, але я похитав головою. Це полювання було для Людей, а не для Барніла чи для мене. Ерлгадін вистрілив гучним пострілом, але повністю промахнувся повз пантеру. Мабуть, він не був готовий до сильної віддачі від пострілу.",
        [19] = "Його рушниця різко відкинулася назад у його руках. Ствол змахнув убік і опинився під гвинтівкою Аджек. Саме в цей момент Аджек натиснула на спусковий гачок. Гвинтівка, приціл якої тепер незграбно був спрямований у бік лісосмуги, пролунала гучним пострілом. З крони з криком вилетіла зграя птахів, розлетівшись у всі боки. З дерева піднявся стовп диму. Ми з подивом спостерігали, як величезна гілка впала прямо на пантеру, що тікала, зламавши їй спину",
        [20] = "З кожним тижнем наші запаси шкур пантер і тигрів ставали все більшими. Я вирішив, що настав час експедиції перенести свою увагу на нове випробування: хижих птахів.$B$BЛюди, хоча й цінували навчання, яке ми з Барнілом їм надавали, вирішили утриматися від полювання з вогнепальною зброєю. Аджек набагато впевненіше почувався з добре натягнутим луком, а сер Ерлгадін ніколи не залишав табору без свого міцного арбалета.",
        [21] = "Ми вирушили з першими променями світанку, прямуючи на південь повз руїни Ткаші. Барніл висловив побоювання, що ми можемо натрапити на представників племені «Криваві скальпи». Я нагадав Барнілу, що «Криваві скальпи» більше зацікавлені у знищенні свого племінного ворога — «Розколювачів черепів». Зрозуміло, що це анітрохи не заспокоїло Барніла. У мене ж, однак, була заряджена рушниця, сумка, повна пороху, та троє вправних мисливців, що розвіювали будь-які побоювання щодо ворожої засідки.",
        [22] = "Я стояв на полі бою перед грізним Інферналом, коли армія Палаючого Легіону наступала з усіх боків. Недисциплінована зграя тролів здається такою ж нешкідливою, як заєць у пагорбах Дун-Морога.$B$BМи без пригод минули Руїни Ткаші, на велике полегшення Барніла. Наша група рушила на захід, у бік Великого моря, оминаючи руїни Зул’Кунди, що лежали трохи південніше. Піднімаючись на високі морські скелі, ми помітили нашого першого раптора.",
        [23] = "Звір навіть не помітив нашої присутності. Насправді, єдиним привітанням, яке він отримав від експедиції, була куля між очей.$B$BСер Ерлгадін вигукнув сердечне «ура», а Аджек кивнув мені головою, висловлюючи щире схвалення. Я перерив свій рюкзак у пошуках люльки, сподіваючись насолодитися святковою куренням. Барніл почав метушитися вгору по схилу, щоб дістати тушу Раптора. Я дивився на вбиту тварину з тим задоволенням, яке супроводжує кожне велике полювання.",
        [24] = "Але я не міг довго насолоджуватися славою перемоги. Адже коли я перевів погляд на горизонт, на вершині пагорба, прямо над бідним Барнілом, з’явилося кілька силуетів.$B$B*Тікай, Барніле!* — крикнув я. Аджек, сер Ерлгадін і я випустили шквал куль, стріл і болтів у бік Барніла та переслідувачів-хижаків. У цій метушні одному з нас вдалося вбити одного з них.",
        [25] = "Наших поспішно випущених пострілів вистачило, щоб дати Барнілу можливість втекти. Барніл з галасом збіг униз з пагорба й знову приєднався до нашої групи. Ми кинулися в джунглі; зграя лютих рапторів «Лаштейл» стежила за кожним нашим рухом. $B$BТепер мисливці стали здобиччю.",
        [26] = "Я повів загін у бік моря, сподіваючись, що берегова лінія стане для нас притулком від рапторів. У поспіху ми занадто далеко відхилилися на північ, опинившись на небезпечно високому піднесенні. Ми припустилися помилки. Це моя провина. Ми зупинилися впритул до стрімкої скелі, а раптори були всього за кілька кроків від нас.",
        [27] = "Я повільно рушив уперед, піднявши зброю. Я привів цих хоробрих мисливців на смерть. Я загину, захищаючи їх. Раптори «Хвостохвіст» — особливо люті, відомі своєю невгамовною жадобою крові. Їх було набагато більше, ніж нас. Але хай мене чорт забере, якщо я дозволю їм убити мене та моїх товаришів, не проливши спочатку трохи їхньої крові.",
        [28] = "Аджек і сер Ерлгадін приготували зброю, ставши по обидва боки від мене, спиною до моря. Барніл зітхнув з відчаєм і витягнув сокиру. «Лаштейли» вже майже наздогнали нас. Їхній рівномірний крок сповільнився. Тепер вони підкрадалися до своєї здобичі, бо знали, що загнали нас у пастку.",
        [29] = "І тоді сталося щось дивовижне. З боку до нас долинув чіткий і жахливий рик великого білого тигра. Незважаючи на свою чисельність, «Раптори» обернулися й розбіглися в усі боки. Ми побачили лише короткий білий спалах, коли тигр промчав повз нас і накинувся на одного з рапторів. Накази давати не було потреби. Усі четверо членів нашої групи зрозуміли, що настав час тікати.",
        [30] = "Ми мчали назад до базового табору, не зменшуючи швидкості. Пізніше тієї ночі ми тихо сиділи біля багаття, розуміючи, що наші життя врятував дивний поворот долі. Такі ось ризики мисливця на велику дичину. Ми граємо з долею, підкорюючи її. Проте кожен із нас рано чи пізно зіткнеться з її гострими, як бритва, зубами. Цей карлик просто радий, що той момент не настав на зелених пагорбах Странглторна.$B$B--Кінець--",
    },
},

[41130] = {
    en = "Leather Letter",
    T  = "Шкіряний лист",
    pages = {
        [1] = "Я чув, що ти нарешті покинув своє нудне життя і вирішив служити справі Альянсу. Хто б міг подумати, що ти візьмеш арбалет і назвеш себе мисливцем? Це точно нагадує мені про дні, коли я вперше розпочав свою подорож.$b$bТобі знадобиться належне керівництво та тверда рука! Ти знайдеш мене в абатстві, а потім у стайнях; будь готовий.$b$bСтарий Джона",
